  function wdLayerControl(map,opts={}){ const C=L.Control.extend({options:{position:'topright'},onAdd(){ const d=L.DomUtil.create('div','wd-layer-ctl'); d.innerHTML=wdLayerToolbar('is-compact'); L.DomEvent.disableClickPropagation(d); L.DomEvent.disableScrollPropagation(d); return d; }}); const c=new C(); map.addControl(c); return wdMapLayers(map,c.getContainer(),opts); }
