      const fit=()=>{ try{ const z=map.getBoundsZoom(L.latLngBounds([[-58,-180],[78,180]]),false); const minZ=Math.max(1,Math.floor(z*4)/4); map.setMinZoom(minZ); if(map.getZoom()<minZ) map.setZoom(minZ,{animate:false}); }catch(e){} };
