  const VT_GUIDE_ART=[
    '<svg viewBox="0 0 160 96" aria-hidden="true"><rect x="2" y="2" width="156" height="92" rx="8" fill="#fff" stroke="#cfdde1"/><rect x="2" y="2" width="156" height="14" rx="8" fill="#eef3f5"/><circle cx="24" cy="40" r="10" fill="var(--vt-brand,#076898)"/><path d="M24 35v10M19 40h10" stroke="#fff" stroke-width="2.4" stroke-linecap="round"/><rect x="42" y="26" width="104" height="54" rx="6" fill="#f4f8f9" stroke="#cfdde1"/><rect x="50" y="34" width="70" height="7" rx="3" fill="#e1eaed"/><rect x="48" y="47" width="92" height="12" rx="4" fill="#fff" stroke="var(--vt-brand,#076898)" stroke-width="1.6"/><text x="56" y="56" font-size="8" font-family="monospace" fill="var(--vt-brand,#076898)">&lt;/&gt; HTML</text><rect x="50" y="65" width="60" height="7" rx="3" fill="#e1eaed"/></svg>',
    '<svg viewBox="0 0 160 96" aria-hidden="true"><rect x="2" y="2" width="156" height="92" rx="8" fill="#fff" stroke="#cfdde1"/><rect x="2" y="2" width="156" height="14" rx="8" fill="#eef3f5"/><rect x="14" y="26" width="132" height="50" rx="6" fill="#0f2b3a"/><text x="22" y="44" font-size="8" font-family="monospace" fill="#9fe3ee">&lt;script src=…&gt;</text><text x="22" y="58" font-size="8" font-family="monospace" fill="#9fe3ee">&lt;a data-worldives…&gt;</text><rect x="104" y="64" width="34" height="8" rx="4" fill="var(--vt-brand,#076898)"/></svg>',
    '<svg viewBox="0 0 160 96" aria-hidden="true"><rect x="2" y="2" width="156" height="92" rx="8" fill="#fff" stroke="#cfdde1"/><rect x="2" y="2" width="156" height="14" rx="8" fill="#eef3f5"/><rect x="104" y="5" width="46" height="8" rx="4" fill="var(--vt-brand,#076898)"/><rect x="14" y="26" width="80" height="8" rx="3" fill="#cfdde1"/><rect x="14" y="40" width="110" height="5" rx="2.5" fill="#e1eaed"/><rect x="14" y="56" width="46" height="16" rx="8" fill="var(--vt-brand,#076898)"/><rect x="23" y="62" width="28" height="4" rx="2" fill="#fff"/><path d="M128 30l10 10 18-20" stroke="#16a34a" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>'];
  const VT_GUIDES=[['wordpress','WordPress',['En la página donde quieres el botón, pulsa «+» y añade un bloque «HTML personalizado».','Pega el código.','Pulsa «Actualizar».']],
    ['wix','Wix',['En el editor: «Añadir elementos» → «Insertar código» → «Código integrado».','Pega el código.','Publica la web.']],
    ['squarespace','Squarespace',['Edita la página y pulsa «Añadir bloque» → «Código».','Pega el código.','Guarda los cambios.']]];
  async function renderSellOnline(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml, tr=translateString;
    mount.innerHTML=`<div class="pl-loading">${wdIcon('globe',22)} Cargando…</div>`;
    let v, keys={items:[]}, hooks={items:[],deliveries:[],events:[]}, ical={url:null}, imports={items:[]}, mine=null;
    try{ v=await api('/api/provider/vender'); }catch(err){ mount.innerHTML=`<div class="notice error">${esc(err.message)}</div>`; return; }
    const isCenter=state.me?.user?.role==='center';
    [keys,hooks,ical,imports]=await Promise.all([api('/api/provider/api-keys').catch(()=>keys),api('/api/provider/webhooks').catch(()=>hooks),api('/api/provider/ical').catch(()=>ical),api('/api/provider/ical-imports').catch(()=>imports)]);
    if(isCenter) mine=await api('/api/me/ical').catch(()=>null);
    const ui=renderSellOnline.ui||(renderSellOnline.ui={fmt:'boton',service:'',type:'',what:'all',guide:'wordpress',dev:false});
    if(ui.what==='service'&&!ui.service&&v.services[0]) ui.service=String(v.services[0].id);
    const snippet=()=>{ const extra=(ui.what==='service'&&ui.service?` data-servicio="${ui.service}"`:'')+(ui.what==='type'&&ui.type?` data-tipo="${ui.type}"`:''); return v.snippets[ui.fmt].replace(/data-centro="([^"]+)"/,`data-centro="$1"${extra}`); };
    // v50.58 (reserva exprés, parte 6): the preview is always in test mode (nothing is booked or charged).
    const preview=()=>`/w/${encodeURIComponent(v.slug)}?f=${ui.fmt}${ui.what==='service'&&ui.service?'&servicio='+ui.service:''}${ui.what==='type'&&ui.type?'&tipo='+encodeURIComponent(ui.type):''}&prueba=1`;
    const types=[...new Set(v.services.map(s=>s.type).filter(Boolean))];
    if(ui.what==='type'&&!ui.type&&types[0]) ui.type=types[0];
    const typeLabel=t=>SERVICE_TYPES.find(x=>x.value===t)?.label||t;
    const planNote=!v.plan.widget?`<div class="notice warning">${wdIcon('info',16)} ${esc(tr('El botón de reservas para tu web está incluido en los planes «Motor de reservas» y «Pro». Con la ficha gratuita, tu web enseña «Solicitar información».'))} <a href="#/mi-plan">${esc(tr('Ver planes'))}</a></div>`:'';
    const m=v.month||{web:0,link:0};
    const count=`<p class="vt-count">${wdIcon('users',18)} <span>${esc(tr(m.web===1?'Este mes te ha reservado 1 persona desde tu web':'Este mes te han reservado {n} personas desde tu web')).replace(/(\d+|1) (persona|personas)/,'<b>$&</b>').replace('{n}',`<b>${m.web}</b>`)}${m.link?` <small>${esc(tr(m.link===1?'y 1 desde tu enlace de reservas':'y {n} desde tu enlace de reservas').replace('{n}',m.link))}</small>`:''}</span></p>`;
    const choice=(name,val,on,title,sub,extra='')=>`<label class="vt-choice ${on?'is-on':''}"><input type="radio" name="${name}" value="${val}" ${on?'checked':''}><span class="vt-choice-body"><b>${esc(tr(title))}</b>${sub?`<small>${esc(tr(sub))}</small>`:''}${extra}</span></label>`;
    const look=(k,title,sub)=>`<label class="vt-look ${ui.fmt===k?'is-on':''}" data-fmt="${k}"><input type="radio" name="vt-fmt" value="${k}" ${ui.fmt===k?'checked':''}><span class="vt-art">${VT_ART[k]}</span><b>${esc(tr(title))}</b><small>${esc(tr(sub))}</small></label>`;
    const checkBox=c=>!c?'':c.ok?`<div class="notice success vt-check-ok"><strong>${esc(tr('✔ Tu botón está funcionando'))}</strong>${c.authorized?` <span>${esc(tr('Hemos autorizado {web} para que funcione.').replace('{web}',c.authorized))}</span>`:''}</div>`
      :`<div class="notice warning vt-check-no"><strong>${esc(tr('Aún no lo encontramos'))}</strong>${c.hint?` <span>${esc(tr(c.hint))}</span>`:''}</div>`;
    const last=v.check?{ok:v.check.ok,hint:v.check.ok?'':'La última vez no lo encontramos. Si ya lo has pegado, vuelve a probar.'}:null;
    mount.innerHTML=`<div class="cb-module vt-wrap" style="--vt-brand:${esc(v.color||'#076898')}">
      <div class="cb-module-head"><div><p class="eyebrow">${esc(tr('RESERVAS DESDE TU WEB E INSTAGRAM'))}</p><h2>${esc(tr('Que te reserven desde tu web, Instagram o WhatsApp'))}</h2><p>${esc(tr('Las reservas entran solas en tu planning y salen de las mismas plazas que en WORLDIVES.'))}</p></div></div>
      ${count}${planNote}
      <section class="vt-card vt-easy"><div class="vt-easy-main"><p class="eyebrow">${esc(tr('LO MÁS FÁCIL · TAMBIÉN SIN WEB'))}</p><h3>${esc(tr('Tu enlace de reservas'))}</h3>
          <p>${esc(tr('Ponlo en tu Instagram, en Google Maps o mándalo por WhatsApp.'))}</p>
          <code class="vt-link vt-big" translate="no">${esc(v.page)}</code>
          <div class="vt-row"><button type="button" class="btn btn-primary" id="vt-link-copy">${wdIcon('link',15)} ${esc(tr('Copiar'))}</button><a class="btn" id="vt-wa" href="${esc(v.whatsapp)}" target="_blank" rel="noopener">${wdIcon('whatsapp',15)} ${esc(tr('Compartir en WhatsApp'))}</a><a class="btn" id="vt-qr-dl" href="${esc(v.qr.png)}?descargar=1" download>${wdIcon('qr',15)} ${esc(tr('Descargar QR'))}</a><a class="btn btn-ghost" href="${esc(v.page)}" target="_blank" rel="noopener">${esc(tr('Abrir'))}</a></div></div>
        <img class="vt-easy-qr" src="${esc(v.qr.svg)}" alt="${esc(tr('QR de tu enlace de reservas'))}" width="128" height="128"></section>
      <section class="vt-card vt-step" id="vt-step1"><h3><span class="vt-num">1</span> ${esc(tr('¿Qué quieres que reserven?'))}</h3>
        <div class="vt-choices">${choice('vt-what','all',ui.what==='all','Todo tu catálogo','Todos tus servicios a la venta.')}
          ${v.services.length?choice('vt-what','service',ui.what==='service','Un servicio concreto','',`<select id="vt-svc" aria-label="${esc(tr('Servicio'))}">${v.services.map(s=>`<option value="${s.id}" ${String(ui.service)===String(s.id)?'selected':''}>${esc(s.title)}</option>`).join('')}</select>`):''}
          ${types.length>1?choice('vt-what','type',ui.what==='type','Un tipo','Por ejemplo, solo los cursos o solo las inmersiones.',`<select id="vt-type" aria-label="${esc(tr('Tipo'))}">${types.map(t=>`<option value="${esc(t)}" ${ui.type===t?'selected':''}>${esc(tr(typeLabel(t)))}</option>`).join('')}</select>`):''}</div></section>
      <section class="vt-card vt-step" id="vt-step2"><h3><span class="vt-num">2</span> ${esc(tr('¿Cómo quieres que se vea?'))}</h3>
        <div class="vt-choices vt-looks">${look('boton','Un botón «Reservar»','Abre la reserva encima de tu página.')}${look('calendario','Un calendario','Las fechas libres, dentro de tu página.')}${look('lista','Una lista de próximas salidas','Tus salidas y servicios, dentro de tu página.')}</div>
        <p class="vt-help vt-brand">${v.logo?`<img src="${esc(v.logo)}" alt="" width="28" height="28">`:''}<span class="vt-swatch" aria-hidden="true"></span> ${esc(tr('El color y el logo salen solos de tu perfil.'))}</p>
        <div class="vt-previews"><figure class="vt-phone"><figcaption>${wdIcon('user',14)} ${esc(tr('Móvil'))}</figcaption><iframe class="vt-frame" id="vt-frame" title="${esc(tr('Vista previa en el móvil'))}" src="${esc(preview())}" loading="lazy"></iframe></figure>
          <figure class="vt-desk"><figcaption>${wdIcon('globe',14)} ${esc(tr('Ordenador'))}</figcaption><iframe class="vt-frame" title="${esc(tr('Vista previa en el ordenador'))}" src="${esc(preview())}" loading="lazy"></iframe></figure></div>
        <div class="vt-row"><a class="btn" id="vt-try" href="${esc(v.page)}?prueba=1${ui.what==='service'&&ui.service?'&servicio='+ui.service:''}" target="_blank" rel="noopener">${wdIcon('eye',14)} ${esc(tr('Probar como cliente'))}</a><small>${esc(tr('Modo de prueba: no se reserva ni se cobra nada.'))}</small></div></section>
      <section class="vt-card vt-step" id="vt-step3"><h3><span class="vt-num">3</span> ${esc(tr('Ponlo en tu web'))}</h3>
        <p class="vt-lead">${esc(tr('Pega este código en tu web donde quieras que aparezca el botón.'))}</p>
        <pre class="vt-code" id="vt-code" translate="no">${esc(snippet())}</pre>
        <div class="vt-row"><button type="button" class="btn btn-primary" id="vt-copy">${esc(tr('Copiar código'))}</button><button type="button" class="btn" id="vt-mail">${wdIcon('mail',15)} ${esc(tr('Enviar las instrucciones a mi informático'))}</button></div>
        <div class="vt-guides"><div class="vt-tabs" role="tablist">${VT_GUIDES.map(([k,l])=>`<button type="button" role="tab" class="vt-tab" data-guide="${k}" aria-selected="${ui.guide===k}">${esc(l)}</button>`).join('')}</div>
          ${VT_GUIDES.map(([k,l,steps])=>`<ol class="vt-guide" data-guide-pane="${k}" ${ui.guide===k?'':'hidden'} aria-label="${esc(l)}">${steps.map((t,i)=>`<li><figure class="vt-gart">${VT_GUIDE_ART[i]}</figure><p><b>${i+1}.</b> ${esc(tr(t))}</p></li>`).join('')}</ol>`).join('')}
          <p class="vt-help">${esc(tr('¿Otra plataforma? Si deja pegar HTML, funciona igual. Si no, usa tu enlace de reservas de arriba.'))}</p></div></section>
      <section class="vt-card vt-step" id="vt-step4"><h3><span class="vt-num">4</span> ${esc(tr('Comprueba que funciona'))}</h3>
        <p>${esc(tr('Escribe la dirección de tu web y la miramos por ti. Si el botón está, autorizamos tu web para que funcione.'))}</p>
        <form class="vt-row vt-check" id="vt-check-form" novalidate><label class="sr-only" for="vt-check-url">${esc(tr('La dirección de tu web'))}</label><input id="vt-check-url" inputmode="url" autocomplete="url" placeholder="buceomarazul.com" translate="no" maxlength="300" value="${esc(v.check?.url||'')}"><button type="submit" class="btn btn-primary" id="vt-check">${esc(tr('Comprobar'))}</button></form>
        <div id="vt-check-out" aria-live="polite">${checkBox(last)}</div></section>
      <details class="vt-card vt-dev" id="vt-dev" ${ui.dev?'open':''}><summary><span><b>${esc(tr('Para programadores'))}</b><small>${esc(tr('API y claves, avisos automáticos (webhooks), dominios autorizados, color e idioma, calendario iCal y enlaces directos.'))}</small></span></summary>
      <section class="vt-sub"><h4>${esc(tr('Dominios autorizados, color e idioma'))}</h4>
        <p>${esc(tr('El botón solo funciona en tus dominios. «Comprobar» los añade solo; aquí puedes añadir o quitar a mano.'))}</p>
        <div class="svc-field"><label for="vt-domains">${esc(tr('Dominios de tu web (uno por línea)'))}</label><textarea id="vt-domains" rows="3" placeholder="buceomarazul.com&#10;*.buceomarazul.com" translate="no">${esc((v.domains||[]).join('\n'))}</textarea>
          <small>${esc(tr('Escribe solo el dominio: «buceomarazul.com» vale también para «www.buceomarazul.com»; «*.buceomarazul.com» vale para sus subdominios.'))}${v.local_domains?' '+esc(tr('En el entorno de pruebas también vale «localhost:8101».')):''}</small></div>
        <div class="svc-form-row svc-form-row-2"><div class="svc-field"><label for="vt-color">${esc(tr('Color de tu marca'))}</label><input id="vt-color" type="color" value="${esc(v.color||'#076898')}"></div>
          <div class="svc-field"><label for="vt-lang">${esc(tr('Idioma del botón'))}</label><select id="vt-lang"><option value="">${esc(tr('Automático (el del visitante)'))}</option>${v.langs.map(l=>`<option value="${l}" ${v.lang===l?'selected':''}>${esc(WD_LANG_NAMES[l]||l)}</option>`).join('')}</select></div></div>
        <button type="button" class="btn btn-primary" id="vt-save">${esc(tr('Guardar'))}</button></section>
      <section class="vt-sub"><h4>${esc(tr('Dirección de tu página de reservas'))}</h4>
        <div class="svc-field"><label for="vt-slug">${esc(tr('Dirección'))}</label><div class="vt-row"><span class="vt-prefix">${esc(location.origin)}/c/</span><input id="vt-slug" value="${esc(v.slug)}" maxlength="60" pattern="[a-z0-9-]{3,60}"><button type="button" class="btn" id="vt-slug-save">${esc(tr('Cambiar'))}</button></div><small>${esc(tr('Si la cambias, los enlaces y QR antiguos dejan de funcionar.'))}</small></div>
        <div class="vt-row"><a class="btn" href="${esc(v.qr.svg)}?descargar=1">${esc(tr('Descargar SVG'))}</a> <a class="btn" href="${esc(v.qr.png)}?descargar=1">${esc(tr('Descargar PNG'))}</a></div></section>
      <section class="vt-sub"><h4>${esc(tr('Enlace directo a un servicio, una fecha, una hora y las personas'))}</h4>
        <p class="vt-help">${esc(tr('Con la fecha y la hora, la reserva se abre directamente en «Tus datos».'))}</p>
        <div class="svc-form-row svc-form-row-2"><div class="svc-field"><label for="vt-ls">${esc(tr('Servicio'))}</label><select id="vt-ls">${v.services.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></div><div class="svc-field"><label for="vt-ld">${esc(tr('Fecha (opcional)'))}</label><input id="vt-ld" type="date"></div></div>
        <div class="svc-form-row svc-form-row-2"><div class="svc-field"><label for="vt-lt">${esc(tr('Hora (opcional)'))}</label><input id="vt-lt" type="time"></div><div class="svc-field"><label for="vt-lp">${esc(tr('Personas (opcional)'))}</label><input id="vt-lp" type="number" min="1" max="20" inputmode="numeric"></div></div>
        <div class="vt-row"><code class="vt-link" id="vt-direct" translate="no"></code><button type="button" class="btn" id="vt-direct-copy">${esc(tr('Copiar'))}</button><a class="btn" id="vt-direct-qr" href="#" target="_blank" rel="noopener">QR</a></div></section>
      <section class="vt-sub" id="vt-api"><h4>${esc(tr('API para tu web o tu programa de reservas'))}</h4>
        ${v.plan.api?'':`<div class="notice warning">${esc(tr('La API está incluida en «Motor de reservas» y «Pro».'))}</div>`}
        <p>${esc(tr('Consulta servicios y plazas en tiempo real, crea y cancela reservas. Documentación: docs/api/ del paquete.'))}</p>
        <table class="vt-table"><thead><tr><th>Nombre</th><th>Empieza por</th><th>Permiso</th><th>Último uso</th><th></th></tr></thead><tbody>${(keys.items||[]).map(k=>`<tr class="${k.revoked_at?'is-off':''}"><td>${esc(k.name||'')}</td><td><code>${esc(k.prefix)}…</code></td><td>${k.scope==='write'?'Lectura y escritura':'Solo lectura'}</td><td>${k.revoked_at?'Revocada':esc(k.last_used_at?wdDeadline(k.last_used_at):'Nunca')}</td><td>${k.revoked_at?'':`<button type="button" class="btn btn-small" data-revoke="${k.id}">Revocar</button>`}</td></tr>`).join('')||'<tr><td colspan="5">Todavía no tienes claves.</td></tr>'}</tbody></table>
        <div class="vt-row"><input id="vt-key-name" placeholder="Nombre (p. ej. «Mi web»)" maxlength="80"><select id="vt-key-scope"><option value="read">Solo lectura</option><option value="write">Lectura y escritura</option></select><button type="button" class="btn btn-primary" id="vt-key-new">Crear clave</button></div>
        <div id="vt-key-out"></div>
      </section>
      <section class="vt-sub" id="vt-hooks"><h4>Avisos automáticos a tu servidor (webhooks)</h4>
        <p>Cada vez que una reserva se crea, se confirma, se paga, se cancela o cambia, WORLDIVES avisa a tu servidor con un mensaje firmado. Si tu servidor no contesta, se reintenta durante 24 horas.</p>
        <table class="vt-table"><thead><tr><th>Dirección</th><th>Avisos</th><th>Estado</th><th></th></tr></thead><tbody>${(hooks.items||[]).map(h=>`<tr><td><code>${esc(h.url)}</code></td><td><code translate="no">${esc(h.events.join(', '))}</code></td><td>${h.active?'Activo':'Pausado'}</td><td class="vt-actions"><button type="button" class="btn btn-small" data-hook-test="${h.id}">Probar</button><button type="button" class="btn btn-small" data-hook-toggle="${h.id}" data-on="${h.active?0:1}">${h.active?'Pausar':'Activar'}</button><button type="button" class="btn btn-small" data-hook-secret="${h.id}">Nuevo secreto</button><button type="button" class="btn btn-small" data-hook-del="${h.id}">Quitar</button></td></tr>`).join('')||'<tr><td colspan="4">Sin avisos configurados.</td></tr>'}</tbody></table>
        <div class="svc-field"><label for="vt-hook-url">Dirección https de tu servidor</label><input id="vt-hook-url" placeholder="https://tuweb.com/worldives/avisos" translate="no" maxlength="500"></div>
        <div class="vt-checks">${(hooks.events||[]).map(e=>`<label><input type="checkbox" class="vt-hook-ev" value="${e}" checked> <code translate="no">${e}</code></label>`).join('')}</div>
        <button type="button" class="btn btn-primary" id="vt-hook-new">Añadir aviso</button><div id="vt-hook-out"></div>
        <h4>Registro de envíos</h4>
        <table class="vt-table vt-log"><thead><tr><th>Cuándo</th><th>Aviso</th><th>Reserva</th><th>Resultado</th><th>Intentos</th><th></th></tr></thead><tbody>${(hooks.deliveries||[]).slice(0,30).map(x=>`<tr><td>${esc(wdDeadline(x.created_at))}</td><td><code translate="no">${esc(x.event)}</code></td><td>${x.booking_id?'WOD-'+String(x.booking_id).padStart(6,'0'):'—'}</td><td>${x.status==='delivered'?`<span class="pl-tag good">Entregado (${x.last_status})</span>`:x.status==='failed'?`<span class="pl-tag bad">Falló: ${esc(x.last_error||'')}</span>`:`<span class="pl-tag warn">${x.attempts?'Reintento pendiente':'En cola'}</span>`}</td><td>${x.attempts}</td><td>${x.status==='failed'?`<button type="button" class="btn btn-small" data-retry="${x.id}" data-ep="${x.endpoint_id}">Reintentar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">Todavía no se ha enviado ningún aviso.</td></tr>'}</tbody></table>
      </section>
      <section class="vt-sub" id="vt-ical"><h4>Calendario (iCal)</h4>
        <p><b>Exportar:</b> suscríbete desde Google Calendar, Apple o Outlook. Refleja las reservas de todos los canales; cada calendario decide cada cuánto lo vuelve a leer.</p>
        ${ical.url?`<div class="vt-row"><code class="vt-link">${esc(ical.url)}</code><button type="button" class="btn" data-copy="${esc(ical.url)}">Copiar</button></div>`:'<button type="button" class="btn" id="vt-ical-new">Crear mi enlace de calendario</button>'}
        ${mine?.url?`<p class="vt-help">Tu calendario personal (tus cursos y las salidas que guías): <code>${esc(mine.url)}</code> <button type="button" class="btn btn-small" data-copy="${esc(mine.url)}">Copiar</button></p>`:''}
        <p><b>Importar:</b> otro sistema (un portal, tu programa anterior, tus vacaciones) bloquea plazas o días aquí. <span class="pl-tag warn">${esc(imports.note||'No es instantáneo: se lee cada 15 minutos.')}</span></p>
        <table class="vt-table"><thead><tr><th>Nombre</th><th>Bloquea</th><th>Última lectura</th><th>Eventos</th><th></th></tr></thead><tbody>${(imports.items||[]).map(i=>`<tr><td>${esc(i.name||'')}</td><td>${esc((v.services.find(s=>s.id===i.service_id)||{}).title||'Mis días')}</td><td>${i.last_sync_at?esc(wdDeadline(i.last_sync_at)):'—'} ${i.last_status==='error'?`<span class="pl-tag bad">${esc(i.last_error||'error')}</span>`:i.last_error?`<span class="pl-tag warn">${esc(i.last_error)}</span>`:''}</td><td>${i.events||0}</td><td class="vt-actions"><button type="button" class="btn btn-small" data-imp-sync="${i.id}">Leer ahora</button><button type="button" class="btn btn-small" data-imp-del="${i.id}">Quitar</button></td></tr>`).join('')||'<tr><td colspan="5">Sin calendarios importados.</td></tr>'}</tbody></table>
        <div class="svc-form-row svc-form-row-2"><div class="svc-field"><label for="vt-imp-url">Dirección del calendario (https:// o webcal://)</label><input id="vt-imp-url" maxlength="500"></div><div class="svc-field"><label for="vt-imp-svc">Bloquea</label><select id="vt-imp-svc">${isCenter?'':'<option value="">Mis días (agenda)</option>'}${v.services.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></div></div>
        <div class="vt-row"><input id="vt-imp-name" placeholder="Nombre" maxlength="80"><button type="button" class="btn btn-primary" id="vt-imp-new">Importar</button></div>
        <p class="vt-help">Gestores de canales (channel managers): pendiente de decisión. Mientras tanto, la API y el iCal sirven para conectarlos.</p>
      </section>
      </details>
    </div>`;
    const reload=()=>renderSellOnline(mountId);
    const show=(id,html)=>{ const o=$('#'+id,mount); if(o) o.innerHTML=html; };
    translateTree(mount);
    $('#vt-dev',mount).addEventListener('toggle',e=>{ ui.dev=e.currentTarget.open; });
    $$('input[name="vt-what"]',mount).forEach(i=>i.onchange=()=>{ ui.what=i.value; reload(); });
    $('#vt-svc',mount)?.addEventListener('change',e=>{ ui.service=e.target.value; ui.what='service'; reload(); });
    $('#vt-type',mount)?.addEventListener('change',e=>{ ui.type=e.target.value; ui.what='type'; reload(); });
    $$('input[name="vt-fmt"]',mount).forEach(i=>i.onchange=()=>{ ui.fmt=i.value; reload(); });
    $$('.vt-tab[data-guide]',mount).forEach(b=>b.onclick=()=>{ ui.guide=b.dataset.guide; $$('.vt-tab[data-guide]',mount).forEach(x=>x.setAttribute('aria-selected',String(x===b))); $$('[data-guide-pane]',mount).forEach(p=>p.hidden=p.dataset.guidePane!==ui.guide); });
    $('#vt-copy',mount).onclick=()=>wdCopyText(snippet());
    $('#vt-link-copy',mount).onclick=()=>wdCopyText(v.page);
    $$('[data-copy]',mount).forEach(b=>b.onclick=()=>wdCopyText(b.dataset.copy));
    $('#vt-check-form',mount).onsubmit=async e=>{ e.preventDefault(); const btn=$('#vt-check',mount), url=$('#vt-check-url',mount).value.trim();
      if(!url){ toast(tr('Escribe la dirección de tu web, por ejemplo buceomarazul.com.')); return; }
      btn.disabled=true; show('vt-check-out',`<p class="wd-loading">${esc(tr('Mirando tu web…'))}</p>`);
      try{ const r=await postJSON('/api/provider/vender/check',{url}); show('vt-check-out',checkBox(r)); translateTree($('#vt-check-out',mount)); if(r.ok&&r.domains) $('#vt-domains',mount).value=r.domains.join('\n'); }
      catch(err){ show('vt-check-out',`<div class="notice error">${esc(err.message)}</div>`); }
      btn.disabled=false; };
    $('#vt-mail',mount).onclick=()=>{
      const {el,close}=wdOpenModal({id:'vt-mail-m',size:'sm',title:esc(tr('Enviar las instrucciones a mi informático')),subtitle:esc(tr('Le mandamos el código y la guía de 3 pasos. Si contesta, el correo te llega a ti.')),
        body:`<form id="vt-mail-form" novalidate><div class="field"><label for="vt-mail-to">${esc(tr('Su correo'))}</label><input id="vt-mail-to" type="email" autocomplete="off" placeholder="nombre@empresa.com" maxlength="160" required></div>
          <div class="field"><label for="vt-mail-name">${esc(tr('Su nombre (opcional)'))}</label><input id="vt-mail-name" maxlength="80"></div>
          <div class="field"><label for="vt-mail-note">${esc(tr('Mensaje (opcional)'))}</label><textarea id="vt-mail-note" rows="2" maxlength="300" placeholder="${esc(tr('Ej.: ponlo en la página de inicio, debajo de las fotos.'))}"></textarea></div>
          <p class="wz-hint">${esc(tr('Va el código de lo que has elegido en los pasos 1 y 2.'))}</p></form>`,
        footer:`<button type="button" class="btn" data-modal-close>${esc(tr('Cancelar'))}</button><button type="button" class="btn btn-primary" id="vt-mail-send">${esc(tr('Enviar'))}</button>`});
      translateTree(el);
      $('#vt-mail-send',el).onclick=async e=>{ const btn=e.currentTarget; btn.disabled=true;
        try{ const r=await postJSON('/api/provider/vender/instructions',{email:$('#vt-mail-to',el).value.trim(),name:$('#vt-mail-name',el).value.trim(),note:$('#vt-mail-note',el).value.trim(),
            fmt:ui.fmt,service:ui.what==='service'?ui.service:'',type:ui.what==='type'?ui.type:''});
          close(); toast(tr('Enviado a {email}.').replace('{email}',r.sent_to)); }
        catch(err){ toast(err.message); btn.disabled=false; } };
    };
    $('#vt-save',mount).onclick=async()=>{ try{ await postJSON('/api/provider/vender',{domains:$('#vt-domains',mount).value,color:$('#vt-color',mount).value,lang:$('#vt-lang',mount).value}); toast(tr('Guardado.')); reload(); }catch(err){ toast(err.message); } };
    $('#vt-slug-save',mount).onclick=async()=>{ try{ await postJSON('/api/provider/vender',{slug:$('#vt-slug',mount).value.trim()}); toast(tr('Dirección cambiada.')); reload(); }catch(err){ toast(err.message); } };
    const direct=()=>{ const s=$('#vt-ls',mount).value, dte=$('#vt-ld',mount).value, hr=$('#vt-lt',mount).value, pp=+$('#vt-lp',mount).value||0;
      const q=`servicio=${s}${dte?'&fecha='+dte:''}${dte&&hr?'&hora='+hr:''}${pp>0&&pp<=20?'&personas='+pp:''}`;
      const u=`${v.page}?${q}`; $('#vt-direct',mount).textContent=u; $('#vt-direct-qr',mount).href=`${v.qr.svg}?${q}&descargar=1`; return u; };
    if(v.services.length){ direct(); ['#vt-ls','#vt-ld','#vt-lt','#vt-lp'].forEach(id=>{ $(id,mount).onchange=direct; $(id,mount).oninput=direct; }); $('#vt-direct-copy',mount).onclick=()=>wdCopyText(direct()); }
    $('#vt-key-new',mount).onclick=async()=>{ try{ const r=await postJSON('/api/provider/api-keys',{action:'create',name:$('#vt-key-name',mount).value,scope:$('#vt-key-scope',mount).value});
      show('vt-key-out',`<div class="notice warning"><b>Copia tu clave ahora: no se vuelve a enseñar.</b><div class="vt-row"><code class="vt-link">${esc(r.key)}</code><button type="button" class="btn" id="vt-key-copy">Copiar</button></div><button type="button" class="btn btn-small" id="vt-key-done">Ya la he guardado</button></div>`);
      $('#vt-key-copy',mount).onclick=()=>wdCopyText(r.key); $('#vt-key-done',mount).onclick=reload; }catch(err){ toast(err.message); } };
    $$('[data-revoke]',mount).forEach(b=>b.onclick=async()=>{ if(!confirm('¿Revocar esta clave? Lo que la use dejará de funcionar al momento.')) return; try{ await postJSON('/api/provider/api-keys',{action:'revoke',id:+b.dataset.revoke}); reload(); }catch(err){ toast(err.message); } });
    $('#vt-hook-new',mount).onclick=async()=>{ try{ const r=await postJSON('/api/provider/webhooks',{action:'create',url:$('#vt-hook-url',mount).value.trim(),events:$$('.vt-hook-ev:checked',mount).map(x=>x.value)});
      show('vt-hook-out',`<div class="notice warning"><b>Guarda el secreto: sirve para comprobar la firma y no se vuelve a enseñar.</b><div class="vt-row"><code class="vt-link">${esc(r.secret)}</code><button type="button" class="btn" id="vt-sec-copy">Copiar</button></div><button type="button" class="btn btn-small" id="vt-sec-done">Ya lo he guardado</button></div>`);
      $('#vt-sec-copy',mount).onclick=()=>wdCopyText(r.secret); $('#vt-sec-done',mount).onclick=reload; }catch(err){ toast(err.message); } };
    const hook=async(body,msg)=>{ try{ const r=await postJSON('/api/provider/webhooks',body); if(r.secret){ show('vt-hook-out',`<div class="notice warning"><b>Nuevo secreto (cópialo ahora):</b> <code>${esc(r.secret)}</code></div>`); return; } toast(msg); reload(); }catch(err){ toast(err.message); } };
    $$('[data-hook-test]',mount).forEach(b=>b.onclick=()=>hook({action:'test',id:+b.dataset.hookTest},'Aviso de prueba en cola: lo verás en el registro en unos segundos.'));
    $$('[data-hook-toggle]',mount).forEach(b=>b.onclick=()=>hook({action:'toggle',id:+b.dataset.hookToggle,active:b.dataset.on==='1'},'Hecho.'));
    $$('[data-hook-secret]',mount).forEach(b=>b.onclick=()=>{ if(confirm('¿Cambiar el secreto? Tendrás que poner el nuevo en tu servidor.')) hook({action:'secret',id:+b.dataset.hookSecret}); });
    $$('[data-hook-del]',mount).forEach(b=>b.onclick=()=>{ if(confirm('¿Quitar este aviso?')) hook({action:'delete',id:+b.dataset.hookDel},'Aviso quitado.'); });
    $$('[data-retry]',mount).forEach(b=>b.onclick=()=>hook({action:'retry',id:+b.dataset.ep,delivery_id:+b.dataset.retry},'Se reintentará en unos segundos.'));
    $('#vt-ical-new',mount)?.addEventListener('click',async()=>{ try{ await postJSON('/api/provider/ical/regenerate',{}); reload(); }catch(err){ toast(err.message); } });
    $('#vt-imp-new',mount).onclick=async()=>{ try{ const r=await postJSON('/api/provider/ical-imports',{action:'create',url:$('#vt-imp-url',mount).value.trim(),name:$('#vt-imp-name',mount).value,service_id:+$('#vt-imp-svc',mount).value||null});
      toast(r.sync?.ok?`Leído: ${r.sync.events} eventos, ${r.sync.added} bloqueos.`:'Guardado. No se ha podido leer todavía: lo intentaremos cada 15 minutos.'); reload(); }catch(err){ toast(err.message); } };
    $$('[data-imp-sync]',mount).forEach(b=>b.onclick=async()=>{ try{ const r=await postJSON('/api/provider/ical-imports',{action:'sync',id:+b.dataset.impSync}); toast(r.ok?`Leído: ${r.events} eventos.`:r.error); reload(); }catch(err){ toast(err.message); } });
    $$('[data-imp-del]',mount).forEach(b=>b.onclick=async()=>{ if(!confirm('¿Quitar este calendario? Se liberan las plazas y días que bloqueaba.')) return; try{ await postJSON('/api/provider/ical-imports',{action:'delete',id:+b.dataset.impDel}); reload(); }catch(err){ toast(err.message); } });
  }

  // «Ventas por canal» (Parte H): bookings and amount of each channel, month by month.
  async function renderSalesByChannel(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    const ui=renderSalesByChannel.ui||(renderSalesByChannel.ui={year:new Date().getFullYear()});
    let d; try{ d=await api('/api/provider/ventas-canal?year='+ui.year); }catch(err){ mount.innerHTML=`<div class="notice error">${esc(err.message)}</div>`; return; }
    const used=d.channels.filter(c=>d.totals[c.key].bookings);
    const cols=used.length?used:d.channels.slice(0,1);
    mount.innerHTML=`<div class="cb-module vt-wrap"><div class="cb-module-head"><div><p class="eyebrow">INFORME</p><h2>Ventas por canal</h2><p>${esc(d.note)}</p></div>
      <div class="vt-row"><button type="button" class="btn btn-small" data-y="${ui.year-1}">‹ ${ui.year-1}</button><b>${ui.year}</b><button type="button" class="btn btn-small" data-y="${ui.year+1}">${ui.year+1} ›</button><button type="button" class="btn btn-small" data-vc-ex="xlsx">${wdIcon('download',14)} Excel</button><button type="button" class="btn btn-small" data-vc-ex="csv">CSV</button></div></div><p class="wd-export-msg" data-vc-msg role="status" hidden></p>
      <div class="vt-bars">${cols.map(c=>{ const t=d.totals[c.key]; const max=Math.max(1,...cols.map(x=>d.totals[x.key].bookings)); return `<div class="vt-bar"><span>${esc(c.label)}</span><i style="width:${Math.round(t.bookings/max*100)}%"></i><b>${t.bookings} ${t.bookings===1?'reserva':'reservas'} · ${wdMoney(t.amount)}</b></div>`; }).join('')}</div>
      <p class="vt-help">En cada casilla: número de reservas · importe.</p>
      <div class="vt-scroll"><table class="vt-table"><thead><tr><th>Mes</th>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${d.months.map(m=>{ const tot=cols.reduce((a,c)=>[a[0]+m.by[c.key].bookings,a[1]+m.by[c.key].amount],[0,0]);
        return `<tr><td>${esc(plMonthLabel(m.month))}</td>${cols.map(c=>`<td>${m.by[c.key].bookings?`${m.by[c.key].bookings} · ${wdMoney(m.by[c.key].amount)}`:'—'}</td>`).join('')}<td>${tot[0]?`<b>${tot[0]} · ${wdMoney(tot[1])}</b>`:'—'}</td></tr>`; }).join('')}</tbody></table></div></div>`;
    $$('[data-y]',mount).forEach(b=>b.onclick=()=>{ ui.year=+b.dataset.y; renderSalesByChannel(mountId); });
    $$('[data-vc-ex]',mount).forEach(btn=>btn.onclick=()=>wdDownloadExport('ventas_canal',new URLSearchParams({formato:btn.dataset.vcEx,periodo:'personalizado',desde:`${ui.year}-01-01`,hasta:`${ui.year}-12-31`}),btn,$('[data-vc-msg]',mount)));
  }

  // Instant notice of every new booking, whatever the channel (Parte H): the panel asks every 20 seconds.
  function wdStartFeed(){
    if(wdStartFeed.timer) return; let last=null;
    const tick=async()=>{ if(!document.querySelector('.center-backoffice')){ clearInterval(wdStartFeed.timer); wdStartFeed.timer=0; return; }
      try{ const r=await api('/api/provider/feed'+(last===null?'':'?after='+last)); if(last!==null&&r.items?.length){ r.items.filter(x=>x.event==='booking.created'&&x.channel!=='manual').forEach(x=>toast(`Nueva reserva · ${WD_CH[x.channel]||'WORLDIVES'} · ${x.service_title||''} ${x.booking_date?wdDay(x.booking_date):''}${x.booking_time?' '+x.booking_time:''} · ${x.fullname||''}`));
        const bd=document.querySelector('.cb-nav[data-cbtab="bookings"] b'); if(bd&&r.items.some(x=>x.event==='booking.created')) bd.textContent=String((+bd.textContent||0)+r.items.filter(x=>x.event==='booking.created'&&x.status==='requested').length); }
        last=r.last??last??0; }catch{ /* no permission or offline: try again later */ } };
    tick(); wdStartFeed.timer=setInterval(tick,20000);
  }

  // v50.56 · Parte F: spots kept for a group, an agency or a hotel (no customer), out of the same inventory.
  function openSpotBlock(slotId,free,onSaved){
    const {el,close}=wdOpenModal({id:'spot-block',title:'Bloquear plazas sin cliente',subtitle:'Para un grupo, una agencia o un hotel. Ningún canal podrá venderlas hasta que las liberes.',
      body:`<form id="sb-form" class="svc-form" novalidate><div class="svc-form-row svc-form-row-2"><div class="svc-field"><label for="sb-qty">Plazas</label><input id="sb-qty" type="number" min="1" max="${free}" value="1" required><small>${free} libres en esta salida.</small></div>
        <div class="svc-field"><label for="sb-label">Para quién (texto libre)</label><input id="sb-label" maxlength="160" placeholder="Hotel Sol · grupo de 4"></div></div></form>`,
      footer:`<button type="button" class="btn" data-modal-close>Cancelar</button><button type="submit" form="sb-form" class="btn btn-primary">Bloquear</button>`});
    el.querySelector('#sb-form').onsubmit=async e=>{ e.preventDefault(); const btn=el.querySelector('button[type=submit]'); btn.disabled=true;
      try{ await postJSON('/api/provider/spot-blocks',{action:'create',slot_id:slotId,qty:+el.querySelector('#sb-qty').value,label:el.querySelector('#sb-label').value}); close(); toast('Plazas bloqueadas.'); onSaved?.(); }
      catch(err){ toast(err.message); btn.disabled=false; } };
  }

  async function centerIntegrationView(){
    const d=await api('/api/center/integration'); const i=d.integration; const base=`${location.origin}/api/integrations/bookings`;
    return `<div class="cb-module"><div class="cb-module-head"><div><p class="eyebrow">CONECTIVIDAD</p><h2>Web, API y sincronización</h2><p>Conecta el motor de reservas de la web del centro para que las reservas entren directamente en este planning.</p></div><span class="status ${i?.enabled?'good':'warn'}">${i?.enabled?'● Integración activa':'● Sin configurar'}</span></div><div class="cb-integration-grid"><section class="cb-panel"><h3>Motor de reservas de tu web</h3><p>La web puede enviar cada reserva a WORLDIVES con una referencia externa. Se evita la duplicación y la salida mantiene las plazas centralizadas.</p><div class="cb-code"><strong>POST</strong> ${escapeHtml(base)}<br><small>Header: X-WORLDIVES-API-Key</small></div><div class="cb-api-fields"><div><span>Endpoint</span><code>${escapeHtml(base)}</code></div><div><span>Identificador</span><code>external_ref</code></div><div><span>Sincronización</span><code>Reserva → Planning → plazas</code></div></div><button class="btn btn-primary" id="cb-new-api-key">${i?'Regenerar API Key':'Generar API Key'}</button><div id="cb-api-result"></div></section><section class="cb-panel"><h3>Calendarios</h3><p>Las salidas gestionadas en WORLDIVES pueden consultarse desde el calendario operativo del centro. La conexión con calendarios externos se mantiene separada del motor de reservas.</p><div class="cb-checklist"><div>✓ Disponibilidad por salida</div><div>✓ Plazas actualizadas</div><div>✓ Referencia externa de reserva</div><div>✓ Estado centralizado</div></div></section></div></div>`;
  }

  // ---------------------------------------------------------------------------
  // Planning del centro (v50.26): cualquier mes, pasado o futuro, con resumen por día
  // ---------------------------------------------------------------------------
  const PL_WEEK=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
  const plMonthLabel=m=>wdCap(new Date(+m.slice(0,4),+m.slice(5,7)-1,1).toLocaleDateString(wdLocale(),{month:'long',year:'numeric'}));
  const plShortMonth=m=>new Date(+m.slice(0,4),+m.slice(5,7)-1,1).toLocaleDateString(wdLocale(),{month:'short'}).replace('.','');
  const plIso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const plEndTime=(t,min)=>{ if(!min||!/^\d{1,2}:\d{2}/.test(t||'')) return ''; const [h,m]=t.split(':').map(Number); const x=h*60+m+Number(min); if(x>=24*60) return ''; return `${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`; };
  const plFree=sl=>Math.max(Number(sl.spots_total||0)-Number(sl.taken||0),0);
  const plActive=b=>!['cancelled','rejected','expired'].includes(b.status);
  const PL_STATUS={pending:['Pendiente','warn'],confirmed:['Confirmada','good'],completed:['Completada','good'],cancelled:['Cancelada','bad'],rejected:['Rechazada','bad']};
  const PL_PAY={paid:['Pagado','good'],required:['Pago pendiente','warn'],pending:['Pago en curso','warn'],at_center:['Paga en el centro','muted'],not_required:['Sin cobro','muted'],refunded:['Devuelto','muted'],review:['Pago en revisión','warn']};

  async function renderCenterPlanning(mountId,{center,onManage,canBook=true}={}){
    const mount=document.getElementById(mountId); if(!mount) return;
    const ui=renderCenterPlanning.ui||(renderCenterPlanning.ui={month:'',view:(window.innerWidth<720?'list':'month')});
    if(!ui.month) ui.month=plIso(new Date()).slice(0,7);
    const esc=escapeHtml;
    mount.innerHTML=`<div class="pl-wrap"><div class="pl-loading">${wdIcon('calendar',22)} Cargando el planning…</div></div>`;
    let d; try{ d=await api('/api/center/planning?month='+encodeURIComponent(ui.month)); }catch(err){ mount.innerHTML=`<div class="svc-empty"><h3>No se ha podido cargar el planning</h3><p>${esc(err.message)}</p><button type="button" class="btn" id="pl-retry">Reintentar</button></div>`; $('#pl-retry',mount).onclick=()=>renderCenterPlanning(mountId,{center,onManage,canBook}); return; }
    if(!mount.isConnected) return;
    ui.month=d.month;
    if(ui.channel){ d.slots.forEach(sl=>{ sl.bookings=sl.bookings.filter(b=>b.placeholder||wdChannel(b)===ui.channel); }); d.other=(d.other||[]).filter(b=>wdChannel(b)===ui.channel); }   // v50.56: one channel only
    const today=d.today, cur=today.slice(0,7);
    const phase=d.month<cur?['Historial','past']:d.month>cur?['Previsión','future']:['Mes en curso','now'];
    // v50.58 (3.3): a course edition is a block of several days: it is on each of its days, with its session (morning,
    // afternoon or full day); its places and its divers count once, on the first day.
    const byDay={}; d.slots.forEach(sl=>{ const ds=(sl.days||[]).length>1?sl.days:null;
      if(!ds){ (byDay[sl.slot_date]??={slots:[],other:[]}).slots.push(sl); return; }
      ds.forEach(x=>(byDay[x.date]??={slots:[],other:[]}).slots.push({...sl,_day:x,_of:ds.length,_cont:x.n>1})); });
    (d.other||[]).forEach(b=>(byDay[b.booking_date]??={slots:[],other:[]}).other.push(b));
    (d.course_sessions||[]).forEach(c=>((byDay[c.date]??={slots:[],other:[]}).courses??=[]).push(c));   // v50.58 (3.5): «Crear una sesión nueva»
    const csChip=c=>`<span class="pl-chip is-course" style="--c:#7c3aed" title="${esc(translateString('Sesión de curso'))}"><b>${esc(c.start)}</b><em>${esc(c.course)} · ${esc(c.label)}</em><small>${c.students}</small></span>`;
    const csCard=c=>`<article class="pl-slot is-course" style="--c:#7c3aed"><div class="pl-slot-head"><span class="pl-time">${esc(c.start)}<small>– ${esc(c.end)}</small></span><div class="pl-slot-title"><strong>${esc(translateString('Sesión de curso'))} · ${esc(c.course)}</strong><small>${esc(c.label)}${c.instructor?` · ${esc(translateString('con {who}').replace('{who}',c.instructor))}`:''}${c.boat?` · ${esc(translateString('Barco'))} ${esc(c.boat)}`:''}</small></div><span class="pl-tag ${c.done?'good':''}">${esc(translateString(c.done?'Hecha':c.students===1?'1 alumno':'{n} alumnos').replace('{n}',c.students))}</span></div>
      <ul class="pl-people">${c.bookings.map(id=>`<li><button type="button" class="pl-person" data-booking="${id}"><span class="pl-avatar">${wdIcon('curso',13)}</span><span class="pl-pname">${esc(translateString('Ver la reserva'))} WOD-${String(id).padStart(6,'0')}</span></button></li>`).join('')}</ul></article>`;
    const plPart={full:'Día completo',am:'Mañana',pm:'Tarde'};
    const plDayTag=sl=>sl._day?translateString('Día {n} de {t}').replace('{n}',sl._day.n).replace('{t}',sl._of)+' · '+translateString(plPart[sl._day.part]||''):'';
    const dayFig=day=>{ const x=byDay[day]||{slots:[],other:[]}, real=x.slots.filter(s=>!s._cont); const offered=real.reduce((n,s)=>n+Number(s.spots_total||0),0), taken=real.reduce((n,s)=>n+Number(s.taken||0),0);
      const bks=[...real.flatMap(s=>s.bookings),...x.other].filter(plActive); return {slots:x.slots,other:x.other,courses:x.courses||[],offered,taken,free:Math.max(offered-taken,0),divers:bks.reduce((n,b)=>n+Number(b.participants||1),0),revenue:bks.reduce((n,b)=>n+Number(b.price||0),0),bookings:bks.length}; };
    const st=d.stats, pv=d.prev_stats;
    const delta=(a,b,money)=>{ if(!b&&!a) return ''; if(!b) return '<span class="pl-delta up">nuevo</span>'; const p=Math.round((a-b)/b*100); if(!p) return '<span class="pl-delta">= que el mes anterior</span>'; return `<span class="pl-delta ${p>0?'up':'down'}">${p>0?'▲':'▼'} ${Math.abs(p)}% vs ${esc(plShortMonth(d.prev))}</span>`; };
    const kpi=(label,value,sub,extra='')=>`<div class="pl-kpi"><span>${label}</span><strong>${value}</strong>${sub?`<small>${sub}</small>`:''}${extra}</div>`;
    const occBar=(taken,offered)=>{ const p=offered?Math.min(100,Math.round(taken/offered*100)):0; return `<span class="pl-occ ${p>=100?'is-full':p>=70?'is-high':p>=35?'is-mid':''}"><i style="width:${p}%"></i></span>`; };
    const maxTrend=Math.max(1,...d.trend.map(t=>Math.max(t.offered,t.divers)));
    const trend=d.trend.map(t=>{ const off=Math.round(t.offered/maxTrend*100), tk=Math.round(Math.max(t.taken,t.divers)/maxTrend*100);
      return `<button type="button" class="pl-tbar ${t.month===d.month?'is-current':''} ${t.month>cur?'is-future':''} ${t.month===cur?'is-now':''}" data-month="${t.month}" title="${esc(plMonthLabel(t.month))}: ${t.slots} salidas · ${t.taken} de ${t.offered} plazas ocupadas · ${t.bookings} reservas · ${wdMoney(t.revenue)}"><span class="pl-tbar-col"><i class="off" style="height:${off}%"></i><i class="tk" style="height:${tk}%"></i></span><small>${esc(plShortMonth(t.month))}</small><b>${t.divers||''}</b></button>`; }).join('');
    // Calendar grid
    const [Y,M]=[+d.month.slice(0,4),+d.month.slice(5,7)-1]; const first=new Date(Y,M,1), days=new Date(Y,M+1,0).getDate(), lead=(first.getDay()+6)%7;
    let cells=''; for(let i=0;i<lead;i++) cells+='<div class="pl-cell is-blank" aria-hidden="true"></div>';
    for(let day=1;day<=days;day++){ const iso=plIso(new Date(Y,M,day)); const f=dayFig(iso); const n=f.slots.length+f.other.length+f.courses.length;
      const chips=f.courses.slice(0,3).map(csChip).join('')+f.slots.slice(0,Math.max(0,3-f.courses.length)).map(sl=>`<span class="pl-chip ${sl.status==='closed'?'is-closed':''} ${sl._day?'is-multi':''} ${sl._cont?'is-cont':''}" style="--c:${esc(sl.service_color||'#2563eb')}" ${sl._day?`title="${esc(plDayTag(sl))}"`:''}><b>${esc(sl._day?sl._day.hours[0]:sl.slot_time)}</b><em>${esc(sl.service_title)}</em><small>${sl._day?esc(`${sl._day.n}/${sl._of}`):`${sl.taken}/${sl.spots_total}`}</small></span>`).join('')+(f.other.length&&f.slots.length<3?`<span class="pl-chip is-loose" style="--c:#64748b"><em>${f.other.length} ${f.other.length===1?'reserva':'reservas'} sin salida</em></span>`:'');
      const more=n>3?`<span class="pl-more">+${n-3} más</span>`:'';
      cells+=`<button type="button" class="pl-cell ${iso===today?'is-today':''} ${iso<today?'is-past':''} ${n?'has-events':''}" data-day="${iso}" aria-label="${esc(wdLongDay(iso))}${n?`: ${f.slots.length} salidas, ${f.divers} buceadores`:''}">
        <span class="pl-cell-top"><span class="pl-num">${day}</span>${f.divers?`<span class="pl-divers" title="Buceadores">${wdIcon('users',12)}${f.divers}</span>`:''}</span>
        <span class="pl-chips">${chips}${more}</span>
        ${f.offered?`<span class="pl-cell-foot">${occBar(f.taken,f.offered)}<small>${f.free?`${f.free} libres`:'Completo'}</small></span>`:''}
        ${n?`<span class="pl-dots">${f.slots.slice(0,5).map(s=>`<i style="background:${esc(s.service_color||'#2563eb')}"></i>`).join('')}</span>`:''}
      </button>`; }
    // List view
    const listDays=Object.keys(byDay).sort();
    const list=listDays.map(day=>{ const f=dayFig(day); return `<section class="pl-lday ${day<today?'is-past':''} ${day===today?'is-today':''}"><button type="button" class="pl-lday-head" data-day="${day}"><span class="pl-ldate"><b>${new Date(+day.slice(0,4),+day.slice(5,7)-1,+day.slice(8,10)).getDate()}</b><small>${esc(wdDay(day).split(' ')[0].replace(',',''))}</small></span><span class="pl-lsum"><strong>${esc(wdLongDay(day))}</strong><small>${f.slots.length} ${f.slots.length===1?'salida':'salidas'} · ${f.divers} buceadores${f.offered?` · ${f.free} plazas libres`:''}</small></span>${f.offered?occBar(f.taken,f.offered):''}<span class="pl-lgo">›</span></button></section>`; }).join('');
    const legend=[...new Map(d.slots.map(s=>[s.service_title,s.service_color||'#2563eb'])).entries()].slice(0,10);
    const monthOpts=[]; for(let i=-24;i<=18;i++){ const x=new Date(+cur.slice(0,4),+cur.slice(5,7)-1+i,1); const m=plIso(x).slice(0,7); monthOpts.push(`<option value="${m}" ${m===d.month?'selected':''}>${esc(plMonthLabel(m))}</option>`); }
    mount.innerHTML=`<div class="pl-wrap pl-phase-${phase[1]}">
      <header class="pl-head">
        <div class="pl-title"><p class="eyebrow">Agenda operativa</p><h2>Planning</h2></div>
        <div class="pl-nav" role="group" aria-label="Mes">
          <button type="button" class="pl-arrow" data-go="${d.prev}" aria-label="Mes anterior">‹</button>
          <label class="pl-month"><span class="sr-only">Elegir mes</span><select id="pl-month">${monthOpts.join('')}</select><strong>${esc(plMonthLabel(d.month))}</strong></label>
          <button type="button" class="pl-arrow" data-go="${d.next}" aria-label="Mes siguiente">›</button>
          ${d.month!==cur?`<button type="button" class="btn pl-today" data-go="${cur}">Hoy</button>`:''}
        </div>
        <div class="pl-actions"><label class="pl-chf"><span class="sr-only">Canal</span><select id="pl-channel"><option value="">Todos los canales</option>${Object.entries(WD_CH).map(([k,l])=>`<option value="${k}" ${ui.channel===k?'selected':''}>${esc(l)}</option>`).join('')}</select></label><div class="pl-views" role="tablist"><button type="button" data-view="month" aria-pressed="${ui.view==='month'}">Mes</button><button type="button" data-view="list" aria-pressed="${ui.view==='list'}">Lista</button></div>${canBook?'<button type="button" class="btn btn-primary pl-new">+ Reserva</button>':''}</div>
      </header>
      <section class="pl-summary">
        <div class="pl-phase"><span class="pl-badge ${phase[1]}">${phase[0]}</span><p>${phase[1]==='past'?'Así fue este mes.':phase[1]==='future'?'Lo que ya está reservado para este mes.':'Cómo va el mes hasta ahora, incluidas las salidas que quedan.'}</p></div>
        <div class="pl-kpis">
          ${kpi('Salidas',st.slots,`${st.offered} plazas ofrecidas`,delta(st.slots,pv.slots))}
          ${kpi('Ocupación',st.offered?st.occupancy+'%':'—',`${st.taken} de ${st.offered} plazas`,occBar(st.taken,st.offered))}
          ${kpi('Reservas',st.bookings,`${st.divers} buceadores${st.pending?` · ${st.pending} por confirmar`:''}`,delta(st.bookings,pv.bookings))}
          ${kpi(phase[1]==='past'?'Ingresos':'Ingresos previstos',wdMoney(st.revenue),`${wdMoney(st.paid)} cobrado${st.cancelled?` · ${st.cancelled} canceladas`:''}`,delta(st.revenue,pv.revenue))}
          ${kpi('Plazas libres',st.free,phase[1]==='past'?'sin vender':'para vender',phase[1]!=='past'&&st.free?'<button type="button" class="pl-kpi-link pl-month-poster">Crear cartel</button>':'')}
        </div>
        <div class="pl-trend" aria-label="Últimos y próximos meses"><div class="pl-trend-head"><span>Tendencia</span><small><i class="off"></i>Plazas ofrecidas <i class="tk"></i>Ocupadas · cifra: buceadores</small></div><div class="pl-trend-bars">${trend}</div></div>
      </section>
      <div id="pl-course-pending"></div>
      <div class="pl-body" data-view="${ui.view}">
        <div class="pl-cal"><div class="pl-week">${PL_WEEK.map(w=>`<span>${w}</span>`).join('')}</div><div class="pl-grid">${cells}</div></div>
        <div class="pl-list">${list||`<div class="svc-empty svc-empty-small"><span class="svc-empty-icon">${wdIcon('calendar',26)}</span><p>No hay salidas ni reservas en ${esc(plMonthLabel(d.month).toLowerCase())}.</p></div>`}</div>
      </div>
      ${legend.length?`<div class="pl-legend">${legend.map(([t,c])=>`<span><i style="background:${esc(c)}"></i>${esc(t)}</span>`).join('')}</div>`:''}
    </div>`;
    mountCoursePending($('#pl-course-pending',mount));   // v50.58 (3.5)
    const go=m=>{ ui.month=m; closePop(); renderCenterPlanning(mountId,{center,onManage,canBook}); };
    $$('[data-go]',mount).forEach(b=>b.onclick=()=>go(b.dataset.go));
    $('#pl-month',mount).onchange=e=>go(e.target.value);
    $('#pl-channel',mount).onchange=e=>{ ui.channel=e.target.value; go(d.month); };
    $$('.pl-tbar',mount).forEach(b=>b.onclick=()=>go(b.dataset.month));
    $$('.pl-views button',mount).forEach(b=>b.onclick=()=>{ ui.view=b.dataset.view; $('.pl-body',mount).dataset.view=ui.view; $$('.pl-views button',mount).forEach(x=>x.setAttribute('aria-pressed',String(x===b))); closePop(); });
    const reload=()=>renderCenterPlanning(mountId,{center,onManage,canBook});
    $('.pl-new',mount)&&($('.pl-new',mount).onclick=()=>openManualBooking({date:d.month===cur?today:`${d.month}-01`,onSaved:reload}));
    $('.pl-month-poster',mount)?.addEventListener('click',()=>{ const up=d.slots.filter(s=>s.slot_date>=today&&s.status!=='closed'&&plFree(s)>0); if(!up.length){toast('No quedan salidas con plazas libres este mes.');return;} openPosterStudio({center,slots:up.slice(0,6)}); });
    $$('.pl-cell.has-events,.pl-cell[data-day],.pl-lday-head',mount).forEach(c=>c.onclick=()=>openDay(c.dataset.day,c));
    // ---- Bocadillo del día
    function closePop(){ document.getElementById('pl-pop')?.remove(); document.removeEventListener('keydown',onKey); $$('.pl-cell.is-open',mount).forEach(x=>x.classList.remove('is-open')); }
    function onKey(e){ if(e.key==='Escape') closePop(); }
    function openDay(day,anchor){
      closePop(); const f=dayFig(day); const past=day<today;
      anchor.classList.add('is-open');
      const slotCard=sl=>{ const free=plFree(sl), end=sl._day?sl._day.hours[1]:plEndTime(sl.slot_time,sl.duration_minutes), act=sl.bookings.filter(plActive), gone=sl.bookings.length-act.length;
        const stTag=sl.cancelled_at?'<span class="pl-tag bad">Cancelada</span>':sl.status==='closed'?'<span class="pl-tag bad">Cerrada</span>':free<=0?'<span class="pl-tag good">Completa</span>':`<span class="pl-tag ${free<=2?'warn':''}">${free} ${free===1?'plaza libre':'plazas libres'}</span>`;
        return `<article class="pl-slot" style="--c:${esc(sl.service_color||'#2563eb')}">
          <div class="pl-slot-head"><span class="pl-time">${esc(sl._day?sl._day.hours[0]:sl.slot_time)}${end?`<small>– ${end}</small>`:''}</span><div class="pl-slot-title"><strong>${esc(sl.service_title)}</strong><small>${sl._day?`<b class="pl-dayof">${esc(plDayTag(sl))}</b> · `:''}${esc(sl.points.map(p=>p.name).join(' · ')||translateString('Punto a elegir'))}</small></div>${stTag}</div>
          <div class="pl-slot-occ">${occBar(sl.taken,sl.spots_total)}<small>${sl.taken} de ${sl.spots_total} plazas ocupadas</small></div>
          ${act.length?`<ul class="pl-people">${act.map(b=>b.placeholder?`<li><span class="pl-person is-placeholder" title="Un buceador está pagando estas plazas. Si no completa el pago en unos minutos, se liberan solas."><span class="pl-avatar">…</span><span class="pl-pname">${esc(b.status_label||'Pago en curso')}${Number(b.participants)>1?` <em>×${b.participants}</em>`:''}</span></span></li>`:`<li><button type="button" class="pl-person" data-booking="${b.id}"><span class="pl-avatar">${esc(initials(b.fullname||'?'))}</span><span class="pl-pname">${esc(b.fullname||'Cliente')}${Number(b.participants)>1?` <em>×${b.participants}</em>`:''}</span><span class="pl-tag pl-ch ch-${esc(wdChannel(b))}" title="Canal">${esc(WD_CH[wdChannel(b)])}</span>${b.insurance?`<span class="pl-tag pl-ins" title="${esc(INS_BOOKING_LABEL[b.insurance.status]||'Seguro de buceo')}"><span aria-hidden="true">${b.insurance.icon}</span> <span>Seguro</span></span>`:''}${PL_PAY[b.payment_status]?`<span class="pl-tag ${PL_PAY[b.payment_status][1]}">${PL_PAY[b.payment_status][0]}</span>`:''}${(b.status==='requested'||b.status==='pending')?'<span class="pl-tag warn">Solicitud</span>':b.status==='accepted_pending_payment'?'<span class="pl-tag warn">Aceptada · pendiente de pago</span>':''}</button></li>`).join('')}</ul>`:'<p class="pl-nobody">Todavía sin reservas.</p>'}
          ${gone?`<p class="pl-gone">${gone} ${gone===1?'reserva cancelada':'reservas canceladas'}</p>`:''}
          ${(sl.blocks||[]).map(bl=>bl.source==='course'?`<p class="pl-block is-course">${wdIcon('curso',13)} ${esc(bl.label||translateString('Sesión de curso'))}</p>`:`<p class="pl-block">${wdIcon('lock',13)} ${bl.qty} ${bl.qty===1?'plaza bloqueada':'plazas bloqueadas'} · ${esc(bl.label||'Sin nombre')}${!past?` <button type="button" class="pl-unblock" data-block="${bl.id}">Liberar</button>`:''}</p>`).join('')}
          <div class="pl-slot-actions">${!past&&!sl._cont&&sl.status!=='closed'&&free>0?`${canBook?`<button type="button" class="btn pl-add" data-slot="${sl.id}" data-service="${sl.service_id}">+ Reserva</button>`:''}<button type="button" class="btn pl-blockspots" data-slot="${sl.id}" data-free="${free}">Bloquear plazas</button><button type="button" class="btn pl-poster" data-slot="${sl.id}">${wdIcon('image',15)} Crear cartel</button>`:''}${act.some(b=>!b.placeholder)?`<a class="btn pl-manifest" href="#/manifiesto?slot=${sl.id}">${wdIcon('users',15)} Manifiesto</a>`:''}${!past&&!sl.cancelled_at&&canBook?`<button type="button" class="btn pl-change" data-slot="${sl.id}">Cambio de hora o punto</button><button type="button" class="btn pl-cancel" data-slot="${sl.id}">Cancelar salida y avisar a todos</button>`:''}<button type="button" class="btn pl-manage">Gestionar</button></div>
        </article>`; };
      const loose=f.other.filter(plActive);
      const html=`<div class="pl-pop" id="pl-pop" role="dialog" aria-label="${esc(wdLongDay(day))}">
        <header class="pl-pop-head"><div><p class="eyebrow">${past?'Historial':day===today?'Hoy':'Agenda'}</p><h3>${esc(wdLongDay(day))}</h3></div><button type="button" class="pl-pop-x" aria-label="Cerrar">×</button></header>
        <div class="pl-pop-sum"><span><b>${f.slots.length}</b> ${f.slots.length===1?'salida':'salidas'}</span><span><b>${f.divers}</b> buceadores</span>${f.offered?`<span><b>${f.free}</b> plazas libres</span>`:''}<span><b>${wdMoney(f.revenue)}</b></span></div>
        <div class="pl-pop-body">${f.courses.map(csCard).join('')}${f.slots.map(slotCard).join('')}
          ${loose.length?`<article class="pl-slot" style="--c:#64748b"><div class="pl-slot-head"><span class="pl-time">—</span><div class="pl-slot-title"><strong>Reservas sin salida programada</strong><small>Alquileres o reservas con hora libre</small></div></div><ul class="pl-people">${loose.map(b=>`<li><button type="button" class="pl-person" data-booking="${b.id}"><span class="pl-avatar">${esc(initials(b.fullname||'?'))}</span><span class="pl-pname">${esc(b.fullname||'Cliente')}${Number(b.participants)>1?` <em>×${b.participants}</em>`:''}<small>${esc([b.booking_time,b.service_title].filter(Boolean).join(' · '))}</small></span>${PL_PAY[b.payment_status]?`<span class="pl-tag ${PL_PAY[b.payment_status][1]}">${PL_PAY[b.payment_status][0]}</span>`:''}</button></li>`).join('')}</ul></article>`:''}
          ${!f.slots.length&&!loose.length&&!f.courses.length?`<div class="pl-pop-empty">${past?'Este día no hubo actividad.':'No hay salidas este día.'}</div>`:''}
        </div>
        <footer class="pl-pop-foot">${(day===today||day===plIso(new Date(Date.now()+864e5)))&&f.slots.some(sl=>sl.bookings.some(b=>!b.placeholder&&plActive(b)))?`<a class="btn" href="#/barco?fecha=${day}">${wdIcon('check',15)} Check-in en el barco</a>`:''}${!past&&canBook?`<button type="button" class="btn pl-day-add">+ Reserva este día</button>`:''}${!past&&f.slots.some(s=>s.status!=='closed'&&plFree(s)>0)?`<button type="button" class="btn btn-primary pl-day-poster">${wdIcon('image',15)} Cartel del día</button>`:''}</footer>
      </div>`;
      document.body.insertAdjacentHTML('beforeend',html);
      const pop=document.getElementById('pl-pop');
      // Position: next to the day on wide screens, as a bottom sheet on phones.
      if(window.innerWidth>=760){ const r=anchor.getBoundingClientRect(), w=Math.min(420,window.innerWidth-32); pop.style.width=w+'px';
        let left=r.right+12; if(left+w>window.innerWidth-16) left=r.left-w-12; if(left<16) left=Math.max(16,Math.min(window.innerWidth-w-16,r.left+r.width/2-w/2));
        const h=Math.min(pop.offsetHeight,window.innerHeight-32); let top=r.top+r.height/2-h/2; top=Math.max(16,Math.min(window.innerHeight-h-16,top));
        pop.style.left=left+'px'; pop.style.top=top+'px'; pop.classList.add('is-float'); }
      else pop.classList.add('is-sheet');
      document.addEventListener('keydown',onKey);
      const outside=e=>{ if(!document.getElementById('pl-pop')){document.removeEventListener('mousedown',outside,true);return;} if(!pop.contains(e.target)&&!e.target.closest('.pl-cell,.pl-lday-head')){ closePop(); document.removeEventListener('mousedown',outside,true);} };
      document.addEventListener('mousedown',outside,true);
      window.addEventListener('hashchange',closePop,{once:true});
      pop.querySelector('.pl-pop-x').onclick=closePop;
      pop.querySelector('.pl-pop-x').focus({preventScroll:true});
      $$('.pl-person',pop).forEach(b=>b.onclick=()=>{ closePop(); wdGo('#/reserva?id='+b.dataset.booking); });
      $$('.pl-add',pop).forEach(b=>b.onclick=()=>{ closePop(); openManualBooking({serviceId:+b.dataset.service,slotId:+b.dataset.slot,onSaved:reload}); });
      $$('.pl-poster',pop).forEach(b=>b.onclick=()=>{ const sl=f.slots.find(x=>String(x.id)===b.dataset.slot); closePop(); if(sl) openPosterStudio({center,slots:[sl]}); });
      $$('.pl-blockspots',pop).forEach(b=>b.onclick=()=>{ closePop(); openSpotBlock(+b.dataset.slot,+b.dataset.free,reload); });
      $$('.pl-unblock',pop).forEach(b=>b.onclick=async()=>{ if(!confirm('¿Liberar estas plazas? Se podrán vender al momento en todos los canales.')) return; try{ await postJSON('/api/provider/spot-blocks',{action:'release',id:+b.dataset.block}); closePop(); toast('Plazas liberadas.'); reload(); }catch(err){ toast(err.message); } });
      $$('.pl-manage',pop).forEach(b=>b.onclick=()=>{ closePop(); onManage?.(); });
      $$('.pl-cancel',pop).forEach(b=>b.onclick=()=>{ closePop(); openSlotNotice(+b.dataset.slot,'slot_cancelled',reload); });
      $$('.pl-change',pop).forEach(b=>b.onclick=()=>{ closePop(); openSlotNotice(+b.dataset.slot,'slot_changed',reload); });
      pop.querySelector('.pl-day-add')?.addEventListener('click',()=>{ closePop(); openManualBooking({date:day,onSaved:reload}); });
      pop.querySelector('.pl-day-poster')?.addEventListener('click',()=>{ closePop(); openPosterStudio({center,slots:f.slots.filter(s=>s.status!=='closed'&&plFree(s)>0)}); });
    }
  }

  // ---------------------------------------------------------------------------
  // Generador de carteles para redes sociales (v50.27): 6 plantillas
  // ---------------------------------------------------------------------------
  const POSTER_FORMATS={post:{w:1080,h:1350,label:'Publicación',hint:'4:5 · Instagram y Facebook'},story:{w:1080,h:1920,label:'Historia',hint:'9:16 · Stories, Reels y WhatsApp'},square:{w:1080,h:1080,label:'Cuadrado',hint:'1:1'}};
  const posterLoadImg=src=>new Promise(res=>{ if(!src) return res(null); const im=new Image(); if(/^https?:/i.test(src)&&!src.startsWith(location.origin)) im.crossOrigin='anonymous'; im.onload=()=>res(im); im.onerror=()=>res(null); im.src=src; });
  let posterFontsReady=null;
  function loadPosterFonts(){
    if(posterFontsReady) return posterFontsReady;
    const list=[['WDPDisplay','InterDisplay-Black',{weight:'900'}],['WDPDisplay','InterDisplay-BlackItalic',{weight:'900',style:'italic'}],['WDPSans','Inter-ExtraBold',{weight:'800'}],['WDPSans','Inter-SemiBold',{weight:'600'}],['WDPSans','Inter-Regular',{weight:'400'}]];
    // v50.33: Polish letters come from the latin-ext subset of the same font (OFL). Cyrillic retired with Russian (v50.46).
    const EXT={'latin-ext':'U+0100-02AF,U+0304,U+0308,U+0329,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF'};
    const WEIGHT={'InterDisplay-Black':'900','InterDisplay-BlackItalic':'900-italic','Inter-ExtraBold':'800','Inter-SemiBold':'600','Inter-Regular':'400'};
    list.slice().forEach(([fam,file,d])=>Object.keys(EXT).forEach(sub=>list.push([fam,`Inter-${sub}-${WEIGHT[file]}`,{...d,unicodeRange:EXT[sub]},'woff2'])));
    posterFontsReady=Promise.all(list.map(([fam,file,d,fmt='woff'])=>{ try{ const f=new FontFace(fam,`url(/fuentes/${file.toLowerCase()}.${fmt}) format("${fmt}")`,d); return f.load().then(x=>document.fonts.add(x)).catch(()=>null); }catch{ return null; } }));
    return posterFontsReady;
  }
  // Drawing kit shared by every template
  const PK={
    disp:(s,it)=>`${it?'italic ':''}900 ${Math.round(s)}px WDPDisplay, "Arial Black", Impact, sans-serif`,
    sans:(s,w=600)=>`${w} ${Math.round(s)}px WDPSans, "Segoe UI", Roboto, system-ui, sans-serif`,
    serif:(s,w=400,it)=>`${it?'italic ':''}${w} ${Math.round(s)}px Georgia, "Times New Roman", serif`,
    rr(ctx,x,y,w,h,r){ r=Math.min(r,w/2,h/2); ctx.beginPath(); ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath(); },
    cover(ctx,img,x,y,w,h,fy=.5){ const s=Math.max(w/img.width,h/img.height), iw=img.width*s, ih=img.height*s; ctx.drawImage(img,x+(w-iw)/2,y+(h-ih)*fy,iw,ih); },
    wrap(ctx,text,maxW){ const words=String(text||'').split(/\s+/).filter(Boolean); const lines=[]; let line=''; words.forEach(w=>{ const t=line?line+' '+w:w; if(ctx.measureText(t).width>maxW&&line){ lines.push(line); line=w; } else line=t; }); if(line) lines.push(line); return lines; },
    fit(ctx,text,fontFn,start,maxW,min=14){ let s=start; ctx.font=fontFn(s); while(ctx.measureText(text).width>maxW&&s>min){ s-=2; ctx.font=fontFn(s); } return s; },
    block(ctx,text,fontFn,start,maxW,maxLines,min=24){ let s=start, lines; for(;;){ ctx.font=fontFn(s); lines=PK.wrap(ctx,text,maxW); if((lines.length<=maxLines&&lines.every(l=>ctx.measureText(l).width<=maxW))||s<=min) break; s-=4; } return {size:s,lines:lines.slice(0,maxLines)}; },
    ellipsis(ctx,text,maxW){ let t=String(text||''); if(ctx.measureText(t).width<=maxW) return t; while(t.length>1&&ctx.measureText(t+'…').width>maxW) t=t.slice(0,-1); return t.trim()+'…'; },
    spaced(ctx,text,x,y,sp,align='left'){ const chars=[...String(text)]; const w=chars.reduce((n,c)=>n+ctx.measureText(c).width,0)+sp*(chars.length-1); let cx=align==='center'?x-w/2:align==='right'?x-w:x; const a=ctx.textAlign; ctx.textAlign='left'; chars.forEach(c=>{ ctx.fillText(c,cx,y); cx+=ctx.measureText(c).width+sp; }); ctx.textAlign=a; return w; },
    qr(ctx,m,x,y,size,fg='#011C3C',bg='#fff',pad=14,r=18){ if(!m) return; ctx.fillStyle=bg; PK.rr(ctx,x-pad,y-pad,size+pad*2,size+pad*2,r); ctx.fill(); const n=m.length,c=size/n; ctx.fillStyle=fg; m.forEach((row,ri)=>{ for(let k=0;k<n;k++) if(row[k]==='1') ctx.fillRect(x+k*c,y+ri*c,Math.ceil(c),Math.ceil(c)); }); },
    logo(ctx,o,x,y,s,ring='#fff',monoBg='#076898',monoInk='#fff'){ ctx.save(); ctx.beginPath(); ctx.arc(x+s/2,y+s/2,s/2,0,Math.PI*2); ctx.fillStyle=ring; ctx.fill(); ctx.clip();
      if(o.logo){ const k=Math.min((s*.78)/o.logo.width,(s*.78)/o.logo.height); ctx.drawImage(o.logo,x+(s-o.logo.width*k)/2,y+(s-o.logo.height*k)/2,o.logo.width*k,o.logo.height*k); }
      else { ctx.fillStyle=monoBg; ctx.fillRect(x,y,s,s); ctx.fillStyle=monoInk; ctx.font=PK.sans(s*.38,800); ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(initials(o.centerName||'WD'),x+s/2,y+s/2+1); ctx.textBaseline='alphabetic'; ctx.textAlign='left'; }
      ctx.restore(); },
    money:(o,v)=>v?wdMoney(v,o.currency):'',
    free:n=>t(`${n} ${n===1?'plaza':'plazas'}`),
    darken(ctx,W,H,stops){ const g=ctx.createLinearGradient(0,0,0,H); stops.forEach(([p,c])=>g.addColorStop(p,c)); ctx.fillStyle=g; ctx.fillRect(0,0,W,H); },
    noPhoto(ctx,W,H,a,b){ const g=ctx.createLinearGradient(0,0,W,H); g.addColorStop(0,a); g.addColorStop(1,b); ctx.fillStyle=g; ctx.fillRect(0,0,W,H); ctx.save(); ctx.globalAlpha=.10; ctx.strokeStyle='#fff'; ctx.lineWidth=3; for(let i=0;i<14;i++){ ctx.beginPath(); for(let x=0;x<=W;x+=20){ const y=H*.25+i*H*.06+Math.sin(x/90+i)*18; x?ctx.lineTo(x,y):ctx.moveTo(x,y); } ctx.stroke(); } ctx.restore(); }
  };

