  async function drawPoster(canvas,o){
    const F=POSTER_FORMATS[o.format]; const T=POSTER_TEMPLATES[o.template]||POSTER_TEMPLATES.ultima;
    canvas.width=F.w; canvas.height=F.h; const ctx=canvas.getContext('2d');
    const rowsMax=o.format==='square'?3:o.format==='story'?5:4;
    for(const k of [1,.92,.85,.78,.72,.66]){
      for(const rm of [rowsMax,Math.max(1,rowsMax-1),Math.max(1,rowsMax-2)]){
        ctx.save(); ctx.clearRect(0,0,F.w,F.h); ctx.textBaseline='alphabetic'; ctx.textAlign='left'; ctx.shadowBlur=0; ctx.setLineDash([]); ctx.globalAlpha=1; ctx.globalCompositeOperation='source-over';
        let over=false; try{ over=T.draw(ctx,F.w,F.h,{...o,rowsMax:rm},k); }catch(err){ console.error('cartel',err); over=false; }
        ctx.restore();
        if(!over) return;
        if(rm===1) break;
      }
    }
  }

  async function openPosterStudio({center,slots}){
    if(!slots?.length){ toast('No hay salidas con plazas libres para anunciar.'); return; }
    const esc=escapeHtml; center=center||{};
    const day=slots[0].slot_date; const sameDay=slots.every(s=>s.slot_date===day);
    const dLong=x=>wdCap(wdParseDate(x).toLocaleDateString(wdLocale(),{weekday:'long',day:'numeric',month:'long'}));
    const totalFree=slots.reduce((n,s)=>n+plFree(s),0);
    const rel=(()=>{ const t=new Date(); t.setHours(0,0,0,0); const diff=Math.round((wdParseDate(day)-t)/864e5); return diff===0?'hoy':diff===1?'mañana':diff<7?'este '+wdParseDate(day).toLocaleDateString(wdLocale(),{weekday:'long'}):''; })();
    const firstPts=(slots[0].points||[]).map(p=>p.name).slice(0,2).join(' y ');
    const es=currentLanguage()==='es';
    const defaults={headline:sameDay?(totalFree<=3?(es?`¡Últimas plazas${rel?' '+rel:''}!`:t('¡Últimas plazas!')):(es?`¿Te vienes a bucear${rel?' '+rel:''}?`:t('¿Te vienes a bucear?'))):t('Próximas salidas con plazas libres'),
      message:slots.length===1?`${slots[0].service_title}${firstPts?(es?' en ':' · ')+firstPts:''}. ${t('¡Reserva la tuya!')}`:t('Elige tu hora y ven a bucear con nosotros.'),
      badge:t(totalFree<=3?'Últimas plazas':'Plazas libres'), cta:t('Reserva ya en WORLDIVES')};
    const cover=center.cover_url||'', siteHero=media('hero:centros')||'';
    const photoChoices=[cover&&['cover','Portada del centro',cover],siteHero&&['site','Foto de la web',siteHero],['none','Sin foto',''],['upload','Subir una foto…','']].filter(Boolean);
    const o={format:'post',template:'ultima',accent:POSTER_TEMPLATES.ultima.accents[0],photoKey:photoChoices[0][0],showPrice:true,showSpots:true,showQr:true,...defaults};
    const body=`<div class="ps-wrap">
      <div class="ps-stage"><canvas id="ps-canvas" aria-label="Vista previa del cartel"></canvas></div>
      <form class="ps-side" id="ps-form" data-nosubmit>
        <div class="ps-group"><span class="ps-label">Plantilla</span><div class="ps-templates" id="ps-templates">${Object.entries(POSTER_TEMPLATES).map(([k2,t])=>`<button type="button" class="ps-tpl" data-template="${k2}" aria-pressed="${k2===o.template}"><canvas width="216" height="270" aria-hidden="true"></canvas><strong>${esc(t.name)}</strong><small>${esc(t.hint)}</small></button>`).join('')}</div></div>
        <div class="ps-group"><span class="ps-label">Color</span><div class="ps-accents" id="ps-accents"></div></div>
        <div class="ps-group"><span class="ps-label">Formato</span><div class="ps-seg">${Object.entries(POSTER_FORMATS).map(([k2,f])=>`<button type="button" data-format="${k2}" aria-pressed="${k2===o.format}"><strong>${f.label}</strong><small>${f.hint}</small></button>`).join('')}</div></div>
        <label class="ps-group"><span class="ps-label">Foto de fondo</span><select id="ps-photo">${photoChoices.map(([k2,l])=>`<option value="${k2}">${esc(l)}</option>`).join('')}</select><input type="file" id="ps-file" accept="image/jpeg,image/png,image/webp" hidden></label>
        <label class="ps-group"><span class="ps-label">Titular</span><input id="ps-headline" maxlength="60" value="${esc(o.headline)}"></label>
        <label class="ps-group"><span class="ps-label">Texto</span><textarea id="ps-message" rows="2" maxlength="120">${esc(o.message)}</textarea></label>
        <div class="ps-row"><label class="ps-group"><span class="ps-label">Etiqueta</span><input id="ps-badge" maxlength="22" value="${esc(o.badge)}"></label><label class="ps-group"><span class="ps-label">Llamada a la acción</span><input id="ps-cta" maxlength="34" value="${esc(o.cta)}"></label></div>
        <div class="ps-checks"><label><input type="checkbox" id="ps-price" checked> Precio</label><label><input type="checkbox" id="ps-spots" checked> Plazas libres</label><label><input type="checkbox" id="ps-qr" checked> Código QR para reservar</label></div>
        <label class="ps-group"><span class="ps-label">Texto para la publicación <button type="button" class="svc-link" id="ps-copy">Copiar</button></span><textarea id="ps-caption" rows="4"></textarea></label>
      </form></div>`;
    const {el}=wdOpenModal({id:'poster-studio',size:'xl',title:'Crear cartel para redes',subtitle:`${esc(sameDay?dLong(day):'Varias fechas')} · ${slots.length} ${slots.length===1?'salida':'salidas'} con ${totalFree} ${totalFree===1?'plaza libre':'plazas libres'}`,
      body,footer:`<button type="button" class="btn" data-modal-close>Cerrar</button><button type="button" class="btn" id="ps-share" hidden>Compartir</button><button type="button" class="btn btn-primary" id="ps-download">${wdIcon('download',16)} Descargar imagen</button>`});
    const canvas=el.querySelector('#ps-canvas');
    const [logo,qrData]=await Promise.all([posterLoadImg(centerLogo(center)),api(`/api/center/poster-qr?service=${slots.length===1?slots[0].service_id:''}&slot=${slots.length===1?slots[0].id:''}`).catch(()=>null),loadPosterFonts()]);
    const photos={};
    const loadPhoto=async k2=>{ if(k2 in photos) return photos[k2]; const src=(photoChoices.find(x=>x[0]===k2)||[])[2]; photos[k2]=await posterLoadImg(src); return photos[k2]; };
    const place=[center.city,center.country?t(center.country):''].filter(Boolean).join(', ');
    const slotRows=()=>slots.map(s=>{ const end=plEndTime(s.slot_time,s.duration_minutes); return {time:s.slot_time+(end?'–'+end:''),title:s.service_title,sub:[sameDay?'':wdDay(s.slot_date),(s.points||[]).map(p=>p.name).slice(0,2).join(' · ')].filter(Boolean).join(' · '),free:plFree(s),price:s.service_price,currency:s.currency,color:s.service_color}; });
    const dt=wdParseDate(day);
    const dp=sameDay?{wd:dt.toLocaleDateString(wdLocale(),{weekday:'long'}),wdShort:dt.toLocaleDateString(wdLocale(),{weekday:'short'}).replace('.','').toUpperCase(),day:String(dt.getDate()),month:dt.toLocaleDateString(wdLocale(),{month:'long'}),mon:dt.toLocaleDateString(wdLocale(),{month:'short'}).replace('.','').toUpperCase(),year:String(dt.getFullYear())}:null;
    const dateText=sameDay?dLong(day):`Del ${wdDay(slots[0].slot_date)} al ${wdDay(slots[slots.length-1].slot_date)}`;
    const prices=slots.map(s=>Number(s.service_price||0)).filter(Boolean); const minPrice=prices.length?Math.min(...prices):0;
    const caption=()=>{ const lines=[`${o.headline} 🤿`,'',`📅 ${dateText}`,...slotRows().map(s=>`⏰ ${s.time} · ${s.title}${o.showSpots?` — ${t(`${s.free} ${s.free===1?'plaza':'plazas'}`)}`:''}${o.showPrice&&s.price?` · ${wdMoney(s.price,s.currency)}`:''}`),'',o.message,'',`${t('Reserva')}: ${qrData?.url||location.origin}`,center.phone?`📞 ${center.phone}`:'','',`${es?'#buceo ':''}#scubadiving #${String(center.city||'diving').toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g,'')} #worldives`]; return lines.filter((l,i,a)=>!(l===''&&a[i-1]==='')).join('\n').trim(); };
    const data=photo=>({...o,photo,logo,qr:o.showQr?qrData?.matrix:null,centerName:center.name||state.me?.user?.fullname||'',place,phone:center.phone||'',dateText,dp,slots:slotRows(),totalFree,minPrice,currency:slots[0].currency||'EUR'});
    const drawAccents=()=>{ const t=POSTER_TEMPLATES[o.template]; el.querySelector('#ps-accents').innerHTML=t.accents.map(c=>`<button type="button" class="ps-acc" data-accent="${c}" aria-pressed="${c===o.accent}" aria-label="Color ${c}" style="--a:${c}"></button>`).join(''); };
    // Thumbnails of every template, drawn with the real data
    const thumbs=async()=>{ const photo=o.photoKey==='none'?null:await loadPhoto(o.photoKey); const off=document.createElement('canvas');
      for(const b of $$('.ps-tpl',el)){ const key=b.dataset.template; await drawPoster(off,{...data(photo),template:key,format:'post',accent:key===o.template?o.accent:POSTER_TEMPLATES[key].accents[0]}); const c=b.querySelector('canvas'); const cx=c.getContext('2d'); cx.clearRect(0,0,c.width,c.height); cx.drawImage(off,0,0,c.width,c.height); } };
    let seq=0;
    const redraw=async()=>{ const my=++seq; const photo=o.photoKey==='none'?null:await loadPhoto(o.photoKey); if(my!==seq) return;
      await drawPoster(canvas,data(photo));
      const cap=el.querySelector('#ps-caption'); if(!cap.dataset.edited) cap.value=caption(); };
    el.querySelector('#ps-templates').onclick=e=>{ const b=e.target.closest('.ps-tpl'); if(!b) return; o.template=b.dataset.template; o.accent=POSTER_TEMPLATES[o.template].accents[0]; $$('.ps-tpl',el).forEach(x=>x.setAttribute('aria-pressed',String(x===b))); drawAccents(); redraw(); };
    el.querySelector('#ps-accents').onclick=e=>{ const b=e.target.closest('.ps-acc'); if(!b) return; o.accent=b.dataset.accent; drawAccents(); redraw(); };
    $$('[data-format]',el).forEach(b=>b.onclick=()=>{ o.format=b.dataset.format; $$('[data-format]',el).forEach(x=>x.setAttribute('aria-pressed',String(x===b))); redraw(); });
    el.querySelector('#ps-photo').onchange=e=>{ if(e.target.value==='upload'){ el.querySelector('#ps-file').click(); e.target.value=o.photoKey; return; } o.photoKey=e.target.value; redraw(); thumbs(); };
    el.querySelector('#ps-file').onchange=e=>{ const f=e.target.files[0]; if(!f) return; if(f.size>15*1024*1024){toast('La foto pesa demasiado.');return;} const url=URL.createObjectURL(f); posterLoadImg(url).then(im=>{ if(!im){toast('No se ha podido leer esa foto.');return;} photos.mine=im; if(!photoChoices.some(x=>x[0]==='mine')){ photoChoices.splice(photoChoices.length-1,0,['mine','Mi foto','']); const opt=document.createElement('option'); opt.value='mine'; opt.textContent='Mi foto'; el.querySelector('#ps-photo option[value="upload"]').before(opt);} o.photoKey='mine'; el.querySelector('#ps-photo').value='mine'; redraw(); thumbs(); }); };
    let tt; [['#ps-headline','headline'],['#ps-message','message'],['#ps-badge','badge'],['#ps-cta','cta']].forEach(([s,k2])=>{ let t; el.querySelector(s).oninput=e=>{ o[k2]=e.target.value; clearTimeout(t); t=setTimeout(redraw,120); clearTimeout(tt); tt=setTimeout(thumbs,900); }; });
    [['#ps-price','showPrice'],['#ps-spots','showSpots'],['#ps-qr','showQr']].forEach(([s,k2])=>el.querySelector(s).onchange=e=>{ o[k2]=e.target.checked; redraw(); });
    if(!qrData?.matrix){ const q=el.querySelector('#ps-qr'); q.checked=false; q.disabled=true; o.showQr=false; }
    el.querySelector('#ps-caption').oninput=e=>{ e.target.dataset.edited='1'; };
    el.querySelector('#ps-copy').onclick=async()=>{ try{ await navigator.clipboard.writeText(el.querySelector('#ps-caption').value); toast('Texto copiado.'); }catch{ el.querySelector('#ps-caption').select(); toast('Selecciona y copia el texto.'); } };
    const fileName=()=>`cartel-${(center.name||'worldives').toLowerCase().normalize('NFD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}-${day}-${o.template}-${o.format}.png`;
    const blob=()=>new Promise((res,rej)=>{ try{ canvas.toBlob(b=>b?res(b):rej(new Error('No se ha podido crear la imagen.')),'image/png'); }catch(err){ rej(new Error('La foto elegida no se puede usar en el cartel. Prueba con otra.')); } });
    el.querySelector('#ps-download').onclick=async()=>{ try{ const b=await blob(); const a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download=fileName(); document.body.appendChild(a); a.click(); setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},2000); toast('Cartel descargado. Súbelo a Instagram desde tu móvil o el ordenador.'); }catch(err){ toast(err.message); } };
    const share=el.querySelector('#ps-share');
    if(navigator.canShare&&navigator.share){ try{ if(navigator.canShare({files:[new File([new Blob(['x'])],'x.png',{type:'image/png'})]})) share.hidden=false; }catch{} }
    share.onclick=async()=>{ try{ const b=await blob(); const file=new File([b],fileName(),{type:'image/png'}); await navigator.share({files:[file],text:el.querySelector('#ps-caption').value}); }catch(err){ if(err?.name!=='AbortError') toast(err.message||'No se ha podido compartir.'); } };
    drawAccents(); await redraw(); thumbs();
  }
  function centerTariffsView(tariffs,extras,equipment){
    return `<div class="cb-module"><div class="cb-module-head"><div><p class="eyebrow">PRECIOS MAESTROS</p><h2>Tarifas y extras</h2><p>Aquí se cambian los precios de forma centralizada. Al cambiar una tarifa de servicio, se aplica a las <strong>salidas futuras y nuevas reservas</strong>; las reservas ya realizadas conservan el precio que pagó el cliente.</p></div></div>
      <section class="cb-panel"><div class="cb-panel-head"><div><p class="eyebrow">SERVICIOS</p><h3>Tarifas de servicios y salidas</h3><p>Una tarifa maestra por servicio. Los cambios con fecha futura se programan sin alterar las reservas ya realizadas.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Servicio</th><th>Tarifa vigente</th><th>Próxima tarifa</th><th>Color</th><th></th></tr></thead><tbody>${tariffs.map(t=>{const today=new Date().toISOString().slice(0,10);const current=(t.history||[]).filter(h=>String(h.effective_from)<=today)[0];const next=(t.history||[]).filter(h=>String(h.effective_from)>today).sort((a,b)=>String(a.effective_from).localeCompare(String(b.effective_from)))[0];return `<tr><td><strong>${escapeHtml(t.service.title)}</strong><br><small>${escapeHtml(t.service.service_type||'')}</small></td><td><strong>${Number((current?.price ?? t.service.price)||0).toFixed(2)} €</strong><br><small>${current?`Desde ${escapeHtml(current.effective_from)}`:'Precio actual'}</small></td><td>${next?`<strong>${Number(next.price||0).toFixed(2)} €</strong><br><small>Desde ${escapeHtml(next.effective_from)}</small>`:'<span style="color:var(--muted)">Sin cambio programado</span>'}</td><td><span class="service-color-dot" style="display:inline-block;background:${escapeHtml(t.service.color||'#2563eb')}"></span></td><td><button type="button" class="btn tariff-edit" data-service="${t.service.id}">Cambiar precio</button></td></tr>`}).join('')||'<tr><td colspan="5">Todavía no has creado servicios.</td></tr>'}</tbody></table></div></section>
      <section class="cb-panel" style="margin-top:18px"><div class="cb-panel-head"><div><p class="eyebrow">EXTRAS</p><h3>Complementos</h3><p>Instructor extra, reportaje fotográfico, nitrox, traslado, etc.</p></div><button class="btn btn-primary" id="new-center-extra">+ Nuevo extra</button></div><div class="cb-extra-grid">${extras.map(x=>`<article class="cb-panel cb-extra-card"><div><span class="status ${x.active?'good':'warn'}">${x.active?'Activo':'Pausado'}</span><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.description||'')}</p></div><strong>${Number(x.price||0).toFixed(2)} €</strong><div><button class="btn edit-extra" data-id="${x.id}">Editar</button><button class="btn delete-extra" data-id="${x.id}">Eliminar</button></div></article>`).join('')||'<div class="empty">Todavía no hay extras.</div>'}</div></section>
      <section class="cb-panel" style="margin-top:18px"><div class="cb-panel-head"><div><p class="eyebrow">ALQUILER</p><h3>Equipo de alquiler</h3><p>Precio individual de cada artículo disponible.</p></div></div><div id="cb-equipment"></div></section></div>`;
  }
  async function loadCenterTariffs(d){const [t,e,eq]=await Promise.all([api('/api/center/tariffs'),api('/api/center/extras'),api('/api/center-equipment?center_id='+d.user.center_id)]);window.__centerTariffs=t.items;window.__centerExtras=e.items;$('#cb-content').innerHTML=centerTariffsView(t.items,e.items,eq.items);$('#cb-equipment').innerHTML=eq.items.map(x=>`<div class="equipment-admin-row"><div><strong>${escapeHtml(x.label)}</strong></div><input class="center-equipment-price" data-code="${escapeHtml(x.code)}" type="number" min="0" step="0.01" value="${x.price==null?'':x.price}" placeholder="Precio"><span>€</span><button class="btn save-equipment-price" data-code="${escapeHtml(x.code)}">Guardar</button></div>`).join('');
    $$('.save-equipment-price').forEach(btn=>btn.onclick=async()=>{const input=document.querySelector('.center-equipment-price[data-code="'+btn.dataset.code+'"]');await postJSON('/api/center-equipment',{code:btn.dataset.code,price:input.value});toast('Precio de equipo actualizado.');});
    $$('.tariff-edit').forEach(btn=>btn.onclick=()=>centerTariffForm(t.items.find(x=>Number(x.service.id)===Number(btn.dataset.service)),d));
    $('#new-center-extra').onclick=()=>centerExtraForm();$$('.edit-extra').forEach(b=>b.onclick=()=>centerExtraForm(Number(b.dataset.id)));$$('.delete-extra').forEach(b=>b.onclick=async()=>{if(!confirm('¿Eliminar este extra?'))return;await postJSON('/api/center/extras/delete',{id:+b.dataset.id});loadCenterTariffs(d);});
  }
  function centerTariffForm(serviceEntry,d){const svc=serviceEntry.service;const html=`<div class="modal-backdrop" id="tariff-modal"><div class="modal-card"><button class="modal-close" id="tariff-close">×</button><p class="eyebrow">TARIFA MAESTRA</p><h2>${escapeHtml(svc.title)}</h2><p>El cambio afectará automáticamente a las salidas futuras y nuevas reservas desde la fecha indicada.</p><form id="tariff-form" class="form-grid"><div class="field"><label>Nuevo precio (€)</label><input id="tariff-price" type="number" min="0" step="0.01" required value="${Number(svc.price||0)}"></div><div class="field"><label>Aplicar desde</label><input id="tariff-date" type="date" required value="${new Date().toISOString().slice(0,10)}"></div><div class="full form-actions"><button class="btn btn-primary">Actualizar tarifa</button></div></form></div></div>`;document.body.insertAdjacentHTML('beforeend',html);$('#tariff-close').onclick=()=>$('#tariff-modal').remove();$('#tariff-form').onsubmit=async e=>{e.preventDefault();try{await postJSON('/api/center/tariffs/save',{service_id:svc.id,price:+$('#tariff-price').value,effective_from:$('#tariff-date').value});$('#tariff-modal').remove();toast('Tarifa actualizada para futuras operaciones.');loadCenterTariffs(d);}catch(e){toast(e.message)}};}
  function centerExtraForm(id){const existing=window.__centerExtras?.find(x=>x.id===id);const html=`<div class="modal-backdrop" id="extra-modal"><div class="modal-card"><button class="modal-close" id="extra-close">×</button><p class="eyebrow">EXTRA</p><h2>${id?'Editar':'Nuevo'} extra</h2><form id="extra-form" class="form-grid"><div class="field full"><label>Nombre</label><input id="extra-name" required value="${escapeHtml(existing?.name||'')}" placeholder="Instructor extra"></div><div class="field"><label>Precio (€)</label><input id="extra-price" type="number" min="0" step="0.01" required value="${existing?.price??''}"></div><div class="field full"><label>Descripción</label><textarea id="extra-desc">${escapeHtml(existing?.description||'')}</textarea></div><div class="full form-actions"><button class="btn btn-primary">Guardar extra</button></div></form></div></div>`;document.body.insertAdjacentHTML('beforeend',html);$('#extra-close').onclick=()=>$('#extra-modal').remove();$('#extra-form').onsubmit=async e=>{e.preventDefault();await postJSON('/api/center/extras/save',{id:id||0,name:$('#extra-name').value,description:$('#extra-desc').value,price:+$('#extra-price').value,active:1});$('#extra-modal').remove();toast('Extra guardado.');const d=await api('/api/me');loadCenterTariffs(d);};}
  function centerQRManager(center,bookings,services){const slots=[];(services||[]).forEach(s=>(s.slots||[]).forEach(x=>slots.push({...x,service_title:s.title})));return `<div class="cb-module"><div class="cb-module-head"><div><p class="eyebrow">IDENTIFICACIÓN DIGITAL</p><h2>Check-in / QR</h2><p>El centro ya está seleccionado automáticamente: <strong>${escapeHtml(center.name)}</strong>. No puedes crear QR para otro centro.</p></div></div><div class="cb-qr-purpose-grid"><button class="cb-qr-purpose active" data-purpose="center"><strong>🏪 Centro</strong><span>Identificar el centro y hacer check-in</span></button><button class="cb-qr-purpose" data-purpose="diver"><strong>🤿 Buceador</strong><span>Identificar al cliente al llegar</span></button><button class="cb-qr-purpose" data-purpose="dive"><strong>🌊 Inmersión</strong><span>Compartir los datos de una salida con el Log Book</span></button><button class="cb-qr-purpose" data-purpose="booking"><strong>🎫 Reserva</strong><span>Identificar una reserva concreta</span></button></div><form id="center-qr-form" class="cb-panel form-grid" style="margin-top:18px"><input type="hidden" id="center-qr-purpose" value="center"><div class="field full"><label>Nombre del QR</label><input id="center-qr-label" value="Identificación del centro" required></div><div class="field full" id="center-qr-target-wrap" style="display:none"><label id="center-qr-target-label">Elemento</label><select id="center-qr-target"></select></div><div class="full form-actions"><button class="btn btn-primary">Generar QR</button></div></form><div id="center-qr-output" style="margin-top:18px"></div></div>`;}
  function bindCenterQR(center,bookings,services){const slots=[];(services||[]).forEach(s=>(s.slots||[]).forEach(x=>slots.push({...x,service_title:s.title})));const purposeNames={center:'Identificación del centro',diver:'Check-in del buceador',dive:'Inmersión',booking:'Reserva'}; $$('.cb-qr-purpose').forEach(b=>b.onclick=()=>{ $$('.cb-qr-purpose').forEach(x=>x.classList.remove('active'));b.classList.add('active');const p=b.dataset.purpose;$('#center-qr-purpose').value=p;$('#center-qr-label').value=purposeNames[p];const wrap=$('#center-qr-target-wrap'); if(p==='dive'||p==='booking'){wrap.style.display='block';$('#center-qr-target-label').textContent=p==='dive'?'Salida / inmersión':'Reserva';$('#center-qr-target').innerHTML=(p==='dive'?slots.map(x=>`<option value="${x.id}">${escapeHtml(x.slot_date)} · ${escapeHtml(x.slot_time)} · ${escapeHtml(x.service_title)}</option>`):bookings.map(x=>`<option value="${x.id}">#${x.id} · ${escapeHtml(x.booking_date)} · ${escapeHtml(x.service_title||'Reserva')}</option>`)).join('');}else wrap.style.display='none';}); $('#center-qr-form').onsubmit=async e=>{e.preventDefault();const p=$('#center-qr-purpose').value;const r=await postJSON('/api/qr/create',{purpose:p,reference_id:(p==='dive'||p==='booking')?Number($('#center-qr-target').value):null,label:$('#center-qr-label').value});const base=location.origin;$('#center-qr-output').innerHTML=`<div class="qr-box"><p><strong>${escapeHtml($('#center-qr-label').value)}</strong></p><img src="/api/qr/${r.code}" alt="Código QR"><p>${escapeHtml(center.name)} · ${escapeHtml(purposeNames[p])}</p><code>${base}/#/checkin/${r.code}</code><br><button class="btn" type="button" id="center-qr-copy">Copiar enlace</button></div>`;$('#center-qr-copy').onclick=()=>navigator.clipboard?.writeText(`${base}/#/checkin/${r.code}`);toast('QR generado.');};}
  // v50.51: a team profile without «estadisticas» (or a plan without analytics) still opens the panel, with empty figures.
  const centerAnalytics=()=>{ const none=()=>({metrics:{},by_day:[],by_service:[],channels:{}}); return wdCan('estadisticas')?api('/api/center/analytics').catch(none):Promise.resolve(none()); };
  async function renderCenterWorkspace(d){
    // v50.57: each part on its own: one that fails no longer closes the panel (a notice says which, with «Reintentar»).
    const failed=[]; const soft=(p,fallback,label)=>Promise.resolve(p).catch(e=>{ console.error(e); failed.push([label,e?.message||'']); return fallback; });
    const [centerRes,bookingsRes,servicesRes,clientsRes,analyticsRes,expRes]=await Promise.all([soft(api('/api/centers/'+d.user.center_id),{item:{id:d.user.center_id,name:d.center?.name||d.user.center_name||'Tu centro'}},'Ficha del centro'),soft(api('/api/bookings'),{items:[]},'Reservas'),soft(api('/api/provider-services?provider_id='+d.user.id),{items:[]},'Servicios'),wdCan('reservas')?soft(api('/api/center/clients'),{items:[]},'Clientes'):Promise.resolve({items:[]}),centerAnalytics(),api('/api/provider/experiences').catch(()=>({requests:[]}))]);
    const center=centerRes.item||{id:d.user.center_id,name:'Tu centro'}; let bookings=bookingsRes.items; let services=servicesRes.items; let clients=clientsRes.items; let analytics=analyticsRes; analytics.client_count=clients.length; let currentTab='dashboard';
    // Without statistics the «Reservas» badge counts the pending requests from the bookings themselves.
    const pendingOf=list=>list.filter(b=>['requested','pending'].includes(b.status)).length;
    analytics.metrics=Object.assign({pending:pendingOf(bookings)},analytics.metrics,{experience_requests:(expRes.requests||[]).filter(r=>r.status==='requested').length});
    setApp(centerWorkspaceShell(center,analytics.metrics)); proTermsBanner(d.user); const content=$('#cb-content'); wdModerationBanner($('.cb-main')||content); const nav=$$('.cb-nav');
    if(failed.length){ const parts=document.createElement('div'); content.before(parts); wdPartsFailed(parts,failed,()=>route()); }
    const go=tab=>{nav.forEach(n=>n.classList.toggle('active',n.dataset.cbtab===tab)); wdGo('#/admin?tab='+tab);};
    // Bookings and analytics are reloaded after any change made from the panel, so every tab shows fresh data.
    const reloadData=async()=>{try{const [b,an]=await Promise.all([api('/api/bookings'),centerAnalytics()]); bookings=b.items; analytics=an; analytics.client_count=clients.length; analytics.metrics=Object.assign({pending:pendingOf(bookings)},analytics.metrics); const badge=document.querySelector('.cb-nav[data-cbtab="bookings"] b'); if(badge)badge.textContent=analytics.metrics?.pending||0;}catch(e){}};
    // v50.57: a tab that fails shows its error in the content area; the menu and the rest of the panel keep working.
    const loadTab=async (tab,opts={})=>{ try{ await loadTabIn(tab,opts); }catch(e){ console.error(e); content.innerHTML=wdBlockError(e); translateTree(content); content.querySelector('[data-block-retry]').onclick=()=>loadTab(tab,opts); } };
    const loadTabIn=async (tab,opts={})=>{
      // Encargo del 17/10 (1.4): the rental equipment is only in «Servicios y tarifas → Equipo de alquiler»; the old address
      // (#/admin?tab=equipment, favourites and links) opens it there.
      if(tab==='equipment'){ svcUi.tab='equipment'; tab='services'; history.replaceState(null,'','#/admin?tab=services'); }
      nav.forEach(n=>n.classList.toggle('active',n.dataset.cbtab===tab)); currentTab=tab;
      if(opts.view) bkUi.view=opts.view;
      if(tab==='dashboard') await reloadData();
      if(['dashboard','qr'].includes(tab)){try{services=(await api('/api/provider-services?provider_id='+d.user.id)).items;}catch(e){}}
      if(tab==='dashboard'){content.innerHTML=centerDashboardPro(center,analytics,bookings,services);
        // v50.51: shortcuts to a tab this profile does not have (e.g. «Cobrado» → statistics for an instructor) are not shown.
        $$('.cb-go[data-tab]',content).forEach(b=>{ if(!document.querySelector(`.cb-nav[data-cbtab="${b.dataset.tab}"]`)) b.remove(); });}
      else if(tab==='planning'){content.innerHTML='<div id="cb-planning"></div>'; await renderCenterPlanning('cb-planning',{center,onManage:()=>loadTab('services')});}
      else if(tab==='services'){content.innerHTML='<div id="center-services-manager"></div>'; await renderProviderServicesManager(d.user.id,'center','center-services-manager');}
      else if(tab==='bookings'){content.innerHTML='<div id="cb-bookings"></div>'; await renderCenterBookings('cb-bookings',{onChange:reloadData});}
      else if(tab==='clients'){try{clients=(await api('/api/center/clients')).items;}catch(e){} content.innerHTML=centerClientsView(clients); const q=$('#cl-q'); if(q)q.oninput=()=>{const v=q.value.trim().toLowerCase(); $$('.cl-row[data-search]').forEach(r=>{r.hidden=!!v&&!r.dataset.search.includes(v);});};}
      else if(tab==='experiences'){content.innerHTML='<div id="cb-experiences"></div>'; await renderProviderExperiences('cb-experiences','center',{goServices:()=>loadTab('services')});}
      else if(tab==='payments'){content.innerHTML='<div id="cb-payments"></div>'; await renderCenterPayments(d.user.center_id,'cb-payments');}
      else if(tab==='analytics'){content.innerHTML=await centerAnalyticsView(); content.insertAdjacentHTML('afterbegin','<div id="cb-vcanal"></div>'); wdGuard('cb-vcanal',()=>renderSalesByChannel('cb-vcanal')); wdBindExports(content);}
      else if(tab==='vender'||tab==='integration'){content.innerHTML='<div id="cb-vender"></div><details class="vt-legacy"><summary>Conexión antigua: tu sistema envía las reservas que ya tiene (canal «Importada»)</summary><div id="cb-legacy"></div></details>'; await renderSellOnline('cb-vender');
        $('#cb-legacy').innerHTML=await centerIntegrationView(); $('#cb-new-api-key').onclick=async()=>{try{const r=await postJSON('/api/center/integration/regenerate',{});$('#cb-api-result').innerHTML='<div class="notice warning" style="margin-top:14px"><strong>Guarda esta clave ahora.</strong><br><code>'+escapeHtml(r.api_key)+'</code><br><small>Por seguridad WORLDIVES no vuelve a mostrarla completa.</small></div>';}catch(e){toast(e.message)}};}
      else if(tab==='points'){content.innerHTML='<div id="cb-points"></div>'; await renderCenterPointManager(d.user.center_id,'cb-points');}
      else if(tab==='marina'){content.innerHTML='<div id="cb-marina"></div>'; await renderMarinaProposals('cb-marina');}
      else if(tab==='qr'){content.innerHTML=`<div class="pr-tabs" role="tablist"><button type="button" class="pr-tab is-on" data-pt="promos">${wdIcon('gift',16)} Promociones</button><button type="button" class="pr-tab" data-pt="check">${wdIcon('qr',16)} Validar un código</button><button type="button" class="pr-tab" data-pt="checkin">${wdIcon('pin',16)} QR de check-in</button><button type="button" class="pr-tab" data-pt="print">${wdIcon('qr',16)} QR para imprimir</button></div><div id="pr-pane"></div>`;
        const pane=$('#pr-pane'); const showPt=pt=>{ $$('.pr-tab').forEach(b=>b.classList.toggle('is-on',b.dataset.pt===pt)); if(pt==='promos') renderCenterPromos('pr-pane',center); else if(pt==='check') renderPromoChecker('pr-pane'); else if(pt==='print') renderShortLinks('pr-pane','center'); else { pane.innerHTML=centerQRManager(center,bookings,services); bindCenterQR(center,bookings,services); } };
        $$('.pr-tab').forEach(b=>b.onclick=()=>showPt(b.dataset.pt)); showPt(new URLSearchParams(location.hash.split('?')[1]||'').get('pt')||'promos');}
      else if(tab==='center'){content.innerHTML='<div id="cb-showcase"></div>'; await renderCenterShowcaseEditor('cb-showcase',d.user.center_id);}
      else if(tab==='rewards'){content.innerHTML='<div id="cb-rewards"></div>'; await renderRewardsManager('cb-rewards',{centerId:d.user.center_id});}
      else if(tab==='requests'){content.innerHTML='<div id="cb-requests"></div>'; await renderInfoRequests('cb-requests');}
      else if(tab==='stats'){content.innerHTML='<div id="cb-stats"></div>'; await renderProviderStats('cb-stats');}
      else if(tab==='tools'){content.innerHTML='<div id="cb-tools"></div><div id="cb-waiver"></div>'; await renderProviderTools('cb-tools',true); await renderWaiverEditor('cb-waiver');}
      else if(tab==='team'){content.innerHTML='<div id="cb-team"></div>'; await renderTeam('cb-team');}
      else if(tab==='avisos'){content.innerHTML='<div id="cb-avisos"></div>'; await renderNoticesPanel('cb-avisos');}
      else if(tab==='activity'){content.innerHTML='<div id="cb-activity"></div>'; await renderActivity('cb-activity');}
      else if(tab==='logbook'){content.innerHTML='<div id="cb-logbook"></div>'; await renderCenterLogbook('cb-logbook');}
      else if(tab==='fiscal'){content.innerHTML='<div id="cb-fiscal"></div>'; await renderFiscalCard('cb-fiscal');}
      else if(tab==='plan'){content.innerHTML='<div id="cb-plan"></div>'; await renderMyPlan('cb-plan');}
    };
    // v50.49: each person sees the tabs their role allows (the server refuses the rest anyway).
    if((state.me?.member_role||'owner')!=='owner'){ $$('.cb-nav[data-owner]').forEach(n=>n.remove());
      Object.entries({payments:'cobros',integration:'centro',vender:'centro',center:'centro',marina:'centro',analytics:'estadisticas',stats:'estadisticas',clients:'reservas',requests:'reservas'}).forEach(([t,p])=>{ if(!wdCan(p)) $$(`.cb-nav[data-cbtab="${t}"]`).forEach(n=>n.remove()); });
      if(!wdCan('checkin')&&!wdCan('centro')) $$('.cb-nav[data-cbtab="logbook"]').forEach(n=>n.remove()); }
    { const cur=(state.me?.profiles||[]).find(p=>p.active&&p.center_id); if(cur){ $('#cb-content')?.insertAdjacentHTML('beforebegin',`<div class="pl-bar tq-ctx" style="--c:${escapeHtml(cur.color||'#334155')}">${wdIcon('users',16)} <span>Trabajas en</span> <b translate="no">${escapeHtml(cur.label)}</b> <span>como</span> <b>${escapeHtml(cur.role_name||'')}</b>. <button type="button" class="btn-link" id="tq-ctx-back">Volver a mi perfil</button></div>`); $('#tq-ctx-back')?.addEventListener('click',()=>tqSwitch(0,'')); } }
    { const pl=state.me?.plan; if(pl&&pl.status!=='active'){ const host=$('#cb-content'); host?.insertAdjacentHTML('beforebegin',`<div class="pl-bar ${pl.status==='expired'||pl.code==='free'?'is-free':''}">${wdIcon('info',16)} ${pl.status==='trial'?`Prueba gratuita del plan ${escapeHtml(pl.name)} hasta el ${escapeHtml(wdLegalDate(pl.expires_at))}.`:pl.status==='expired'?'Tu plan ha terminado: tu ficha sigue como ficha gratuita y no recibe reservas online nuevas.':'Ficha gratuita: recibes solicitudes de información.'} <a href="#/admin?tab=plan">Mi plan</a></div>`); } }
    nav.forEach(n=>n.onclick=()=>loadTab(n.dataset.cbtab));
    wdPanelBind($('#app'),'centro');
    // v50.47 (B.6): someone who works for several centres changes the centre of this session explicitly.
    $('#cb-switch')?.addEventListener('change',async e=>{ try{ await postJSON('/api/team/switch',{center:+e.target.value}); await loadMe(); wdGo('#/admin'); toast('Ahora trabajas en este centro.'); }catch(err){ toast(err.message); } });
    content.addEventListener('click',async e=>{const g=e.target.closest('.cb-go'); if(g){e.preventDefault();loadTab(g.dataset.tab,{view:g.dataset.view});return;} if(e.target.closest('.db-new-booking')){openManualBooking({onSaved:async()=>{await reloadData(); if(currentTab==='dashboard')loadTab('dashboard');}});return;} const b=e.target.closest('.cb-booking-open'); if(b){wdGo('#/reserva?id='+b.dataset.id);}});
    $('#cb-refresh').onclick=()=>loadTab(currentTab);
    const requested=new URLSearchParams(location.hash.split('?')[1]||'').get('tab'); loadTab(requested && nav.some(n=>n.dataset.cbtab===requested)?requested:'dashboard');
    if(wdCan('reservas')) wdStartFeed();   // v50.56: a notice for every new booking, whatever the channel
  }

  // ---------------------------------------------------------------- v50.54 · Moderación y datos personales (punto 8)
  // The administration edits platform content; a centre's or a freelance's content is only hidden with a reason. The
  // owner is told, corrects it and sends it for review; the administration publishes it again or keeps it hidden.
  const MOD_TYPES={center:'Ficha del centro',freelance:'Perfil profesional',service:'Servicio',experience:'Experiencia'};
  const MOD_STATUS={open:['Oculto: pendiente de corrección','warn'],resubmitted:['Enviado a revisión','info'],restored:['Publicado de nuevo','good']};
  function wdModerationHide(type,id,label,after){
    const {el,close}=wdOpenModal({id:'mod-hide',title:'Ocultar con un motivo',subtitle:`${MOD_TYPES[type]||''}: ${label||''}`,
      body:`<p>Nadie cambia el contenido: solo deja de verse en la web. El titular recibe el motivo tal cual, lo corrige y lo envía a revisión.</p><div class="field"><label for="mod-reason">Motivo (lo leerá el titular)</label><textarea id="mod-reason" rows="4" minlength="10" required placeholder="Qué incumple y qué tiene que corregir"></textarea></div>`,
      footer:`<button class="btn" type="button" data-modal-close>Cancelar</button><button class="btn btn-primary" type="button" id="mod-hide-ok">Ocultar</button>`});
    translateTree(el);
    $('#mod-hide-ok',el).onclick=async()=>{ try{ await postJSON('/api/admin/moderation/hide',{target_type:type,target_id:+id,reason:$('#mod-reason',el).value.trim()}); close(); toast('Oculto. El titular ha recibido el aviso.'); after?.(); }catch(e){ toast(e.message); } };
  }
  async function renderAdminModeration(id){
    const box=document.getElementById(id); if(!box) return;
    const st=new URLSearchParams(location.hash.split('?')[1]||'').get('estado')||'';
    let d; try{ d=await api('/api/admin/moderation'+(st?'?status='+encodeURIComponent(st):'')); }catch(e){ box.innerHTML=`<div class="empty">${escapeHtml(e.message)}</div>`; return; }
    const items=d.items||[];
    const row=c=>{ const s=MOD_STATUS[c.status]||[c.status,'muted'];
      return `<article class="mod-case" data-id="${c.id}"><div class="mod-head"><span class="wd-pill wd-pill-${s[1]}">${escapeHtml(s[0])}</span><strong><span>${escapeHtml(MOD_TYPES[c.target_type]||c.target_type)}</span> · <span translate="no">${escapeHtml(c.title||'')}</span></strong><small>${escapeHtml(c.owner||'')} · ${escapeHtml(wdDay((c.created_at||'').slice(0,10)))}</small></div>
        <p class="mod-reason"><b>Motivo:</b> <span translate="no">${escapeHtml(c.reason)}</span></p>
        ${c.resubmit_note?`<p class="mod-reason"><b>Lo que dice el titular:</b> <span translate="no">${escapeHtml(c.resubmit_note)}</span></p>`:''}
        ${c.decision_note?`<p class="mod-reason muted"><b>Última nota de la administración:</b> <span translate="no">${escapeHtml(c.decision_note)}</span></p>`:''}
        ${c.status!=='restored'?`<div class="mod-actions"><button class="btn btn-primary" type="button" data-mod-restore="${c.id}">Volver a publicar</button><button class="btn" type="button" data-mod-keep="${c.id}">Mantener oculto…</button></div>`:''}</article>`; };
    box.innerHTML=`<div class="notice"><strong>Moderación</strong><p>La administración no edita lo que publica un centro o un profesional: lo oculta con un motivo. Queda todo en «Actividad»: quién, cuándo y por qué.</p></div>
      <div class="cd-chips mod-filter">${[['','Todos'],['resubmitted','Enviados a revisión'],['open','Ocultos'],['restored','Publicados de nuevo']].map(([k,l])=>`<a class="cd-chip" href="#/admin?tab=moderation${k?'&estado='+k:''}" aria-pressed="${st===k}">${l}</a>`).join('')}</div>
      <div class="mod-list">${items.map(row).join('')||'<div class="empty">No hay casos.</div>'}</div>
      <details class="mod-new"><summary>Ocultar otro contenido</summary><div class="form-grid"><div class="field"><label for="mod-type">Qué</label><select id="mod-type">${Object.entries(MOD_TYPES).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div><div class="field"><label for="mod-id">Número (id)</label><input id="mod-id" type="number" min="1"></div></div><button class="btn" type="button" id="mod-new-go">Continuar</button></details>`;
    translateTree(box);
    const reload=()=>renderAdminModeration(id);
    $$('[data-mod-restore]',box).forEach(b=>b.onclick=async()=>{ const note=prompt(translateString('Nota para el titular (opcional):'))||''; try{ await postJSON('/api/admin/moderation/restore',{id:+b.dataset.modRestore,note}); toast('Publicado de nuevo.'); reload(); }catch(e){ toast(e.message); } });
    $$('[data-mod-keep]',box).forEach(b=>b.onclick=()=>{ const {el,close}=wdOpenModal({id:'mod-keep',title:'Mantener oculto',body:`<div class="field"><label for="mod-keep-note">Qué falta por corregir (lo leerá el titular)</label><textarea id="mod-keep-note" rows="4"></textarea></div>`,footer:`<button class="btn" type="button" data-modal-close>Cancelar</button><button class="btn btn-primary" type="button" id="mod-keep-ok">Enviar</button>`});
      translateTree(el); $('#mod-keep-ok',el).onclick=async()=>{ try{ await postJSON('/api/admin/moderation/keep',{id:+b.dataset.modKeep,note:$('#mod-keep-note',el).value.trim()}); close(); toast('Enviado al titular.'); reload(); }catch(e){ toast(e.message); } }; });
    $('#mod-new-go',box).onclick=()=>{ const t=$('#mod-type',box).value, n=+$('#mod-id',box).value; if(!n){ toast('Escribe el número.'); return; } wdModerationHide(t,n,'#'+n,reload); };
  }
  async function renderAdminPrivacy(id){
    const box=document.getElementById(id); if(!box) return;
    let d; try{ d=await api('/api/admin/data-permissions'); }catch(e){ box.innerHTML=`<div class="empty">${escapeHtml(e.message)}</div>`; return; }
    box.innerHTML=`<div class="notice warning"><strong>PENDIENTE DE ABOGADO</strong><p>Falta definir exactamente qué datos personales puede ver la administración según el RGPD. Mientras, solo está abierto lo que necesitan el soporte y los pagos. Cambiar estas casillas no requiere tocar el código; cada cambio y cada acceso a datos personales quedan en «Actividad» con quién, cuándo y por qué.</p></div>
      <form id="privacy-form" class="privacy-list">${(d.items||[]).map(p=>`<label class="privacy-row"><input type="checkbox" name="${escapeHtml(p.key)}" ${p.allowed?'checked':''}><span><strong>${escapeHtml(p.label)}</strong><small><span>${escapeHtml(p.help)}</span> · <span>${p.default?'abierto por defecto':'cerrado por defecto'}</span></small></span></label>`).join('')}
        <div class="field"><label for="privacy-reason">Motivo del cambio (queda en el registro)</label><input id="privacy-reason" required minlength="10"></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Guardar</button></div></form>`;
    translateTree(box);
    $('#privacy-form',box).onsubmit=async e=>{ e.preventDefault(); const allowed={}; $$('#privacy-form input[type=checkbox]',box).forEach(x=>allowed[x.name]=x.checked);
      try{ const r=await postJSON('/api/admin/data-permissions',{allowed,reason:$('#privacy-reason',box).value.trim()}); toast(Object.keys(r.changes||{}).length?'Permisos guardados.':'No había cambios.'); renderAdminPrivacy(id); }catch(err){ toast(err.message); } };
  }
  // In the panel of a centre or a freelance: what the administration has hidden, why, and «Enviar a revisión».
  async function wdModerationBanner(host){
    if(!host) return; let d; try{ d=await api('/api/provider/moderation'); }catch{ return; }
    const open=(d.items||[]).filter(c=>c.status!=='restored'); if(!open.length||!host.isConnected) return;
    host.insertAdjacentHTML('afterbegin',`<section class="mod-banner" aria-labelledby="mod-banner-h"><h2 id="mod-banner-h">${wdIcon('alert',18)} Contenido retirado por la administración</h2>
      ${open.map(c=>`<article class="mod-case" data-id="${c.id}"><div class="mod-head"><strong><span>${escapeHtml(MOD_TYPES[c.target_type]||'')}</span> · <span translate="no">${escapeHtml(c.title||'')}</span></strong><span class="wd-pill wd-pill-${c.status==='resubmitted'?'info':'warn'}">${c.status==='resubmitted'?'Enviado a revisión':'Oculto'}</span></div>
        <p class="mod-reason"><b>Motivo:</b> <span translate="no">${escapeHtml(c.reason)}</span></p>${c.decision_note?`<p class="mod-reason"><b>Nota de la administración:</b> <span translate="no">${escapeHtml(c.decision_note)}</span></p>`:''}
        ${c.status==='open'?`<p class="mod-help">Corrígelo y cuéntanos qué has cambiado. Seguirá oculto hasta que lo revisemos.</p><div class="mod-resubmit"><input type="text" data-mod-note="${c.id}" placeholder="${escapeHtml(translateString('Qué has corregido'))}"><button class="btn btn-primary" type="button" data-mod-resubmit="${c.id}">Enviar a revisión</button></div>`:'<p class="mod-help">Lo estamos revisando. Te avisaremos por correo.</p>'}</article>`).join('')}</section>`);
    const ban=host.querySelector('.mod-banner'); translateTree(ban);
    $$('[data-mod-resubmit]',ban).forEach(b=>b.onclick=async()=>{ const id=b.dataset.modResubmit; try{ await postJSON('/api/provider/moderation/resubmit',{id:+id,note:$(`[data-mod-note="${id}"]`,ban).value.trim()}); toast('Enviado a revisión.'); ban.remove(); wdModerationBanner(host); }catch(e){ toast(e.message); } });
  }
  async function renderAdmin(){
    if(!state.me){goLogin();return;}
    const d=await api('/api/me');
    if(d.account_closed){ state.me=d; setApp(`<section class="page"><div class="acc-card">${wdClosedCard()||''}<p class="adl-det">${(d.member_role||'owner')==='owner'||d.user.role==='freelance'?'Mientras está cerrada puedes ver tus reservas y descargar tus datos desde «Mi cuenta».':'El propietario del centro ha cerrado la cuenta. Solo él puede reabrirla.'}</p></div></section>`); if((d.member_role||'owner')!=='owner'&&d.user.role!=='freelance') $('#acc-reopen')?.remove(); bindAccountPrivacy(); return; }
    // v50.52 (ASVS V6.3.3): with online payments or «Cobros», the panel asks for two-step verification.
    if(d.security?.totp_blocked&&['center','freelance'].includes(d.user.role)){ state.me=d; setApp(`<section class="page"><div class="empty"><h2>Activa la verificación en dos pasos</h2><p><b>${d.security.totp_required==='cobros'?'Tu perfil tiene el permiso «Cobros».':'Tu cuenta tiene los cobros online activados.'}</b></p><p>Para proteger el dinero y los datos de pago de tus clientes, el panel pide un código de tu aplicación de verificación además de tu contraseña. Las reservas y los pagos de tus clientes siguen funcionando con normalidad.</p><a class="btn btn-primary" href="#/cuenta?seguridad=1">Activarla ahora</a></div></section>`); return; }
    const grace=()=>wdTotpGrace(d.security);
    // v50.57 (2.1): editing has its own address (#/admin?tab=points&edit=12, «edit=nuevo» for a new one): «Guardar»,
    // «← Volver», the menu and the browser's back button always know where you are and where you came from.
    { const q=new URLSearchParams(location.hash.split('?')[1]||''); const ed=q.get('edit'), pr=q.get('proponer'), tb=q.get('tab');
      const EDIT={points:editPointForm,destinations:editDestinationForm,centers:editCenterForm};
      if(pr&&tb==='points'&&['admin','center'].includes(d.user.role)) return proposePointPosition(+pr);
      if(ed!==null&&EDIT[tb]&&(d.user.role==='admin'||(d.user.role==='center'&&tb==='points'))) return EDIT[tb](ed==='nuevo'?0:(+ed||0)); }
    if(d.user.role==='center') return Promise.resolve(renderCenterWorkspace(d)).then(grace);
    if(!['admin','freelance'].includes(d.user.role)){setApp('<section class="page"><div class="empty">Tu cuenta no tiene acceso a gestión.</div></section>');return;}
    if(d.user.role==='freelance') return Promise.resolve(renderFreelancePanel(d)).then(grace);
    const isAdmin=d.user.role==='admin';
    if(isAdmin&&d.security?.totp_setup_required){ setApp(`<section class="page"><div class="empty"><h2>Activa la verificación en dos pasos</h2><p>Para usar la administración necesitas un código de tu aplicación de verificación además de tu contraseña.</p><a class="btn btn-primary" href="#/cuenta?seguridad=1">Activarla ahora</a></div></section>`); return; }
    // v50.57: everything at once (it was one request after another) and each part on its own: if one fails, the rest
    // shows and a notice says which part is missing, with «Reintentar».
    const failed=[]; const soft=(p,fallback,label)=>Promise.resolve(p).catch(e=>{ console.error(e); failed.push([label,e?.message||'']); return fallback; }); const none={items:[]};
    const [pointsR,centersR,bookingsR,suggestionsR,claimsR,mapsInfo,clientsR,usersR,travelR,marinaR,auditR,rewardsR,meta,ptCountsR,vidCountsR]=await Promise.all([
      soft(isAdmin?api('/api/dive-points'):api('/api/center-points?center_id='+d.user.center_id),none,'Puntos de buceo'),
      soft(api('/api/centers'),none,'Centros'), soft(isAdmin?api('/api/admin/bookings/summary?periodo=temporada'):api('/api/bookings'),isAdmin?{totals:{},providers:[]}:none,'Reservas'),
      soft(api(isAdmin?'/api/admin/suggestions':'/api/my/position-suggestions'),none,'Sugerencias'),
      isAdmin?soft(api('/api/admin/center-claims'),none,'Altas de centros'):none,
      isAdmin?api('/api/admin/maps').catch(()=>null):null,
      !isAdmin&&wdCan('reservas')?api('/api/center/clients').catch(()=>none):none,
      isAdmin?soft(api('/api/admin/users'),none,'Usuarios'):none,
      isAdmin?soft(api('/api/admin/travel-experiences'),none,'Experiencias'):none,
      isAdmin?api('/api/admin/marina/pendientes').catch(()=>({count:0})):{count:0},
      isAdmin?soft(api('/api/admin/audit'),none,'Actividad'):none,
      soft(api('/api/provider/reward-offers'),none,'Recompensas'),
      soft(loadMeta(),{travel:[]},'Destinos'),
      isAdmin?api('/api/admin/dive-points/summary').catch(()=>({})):{},
      isAdmin?api('/api/admin/videos/summary').catch(()=>({})):{}]);
    let points=pointsR.items||[]; let ptCounts=ptCountsR||{};
    const centers=centersR.items||[]; state.centers=centers;
    const bookSum=isAdmin?bookingsR:null;   // v50.57 (4.1): the administrator sees the bookings in figures
    const bookings=bookingsR.items||[], suggestions=suggestionsR.items||[], claims=claimsR.items||[], clients=clientsR.items||[];
    const users=usersR.items||[], travelExperiences=travelR.items||[], marinaPending=marinaR.count||0, audit=auditR.items||[], rewardOffers=rewardsR.items||[];
    const myCenter=!isAdmin?centers.find(c=>String(c.id)===String(d.user.center_id)):null;
    const centerPaid=bookings.filter(b=>b.payment_status==='paid');
    const centerPending=bookings.filter(b=>(b.status==='requested'||b.status==='pending'));
    const centerConfirmed=bookings.filter(b=>b.status==='confirmed');
    // v50.58 (2.4): the administration has the same panel as a centre: the menu on the left, grouped and folding, and the
    // section on the right. The legacy view of a centre (below) keeps its row of tabs.
    if(isAdmin){
      const nb=(k,ic,l,n)=>`<button type="button" class="cb-nav" data-tab="${k}">${wdIcon(ic,17)} <span>${l}</span>${n?`<b>${n}</b>`:''}</button>`;
      const expPending=travelExperiences.filter(e=>!['published','rejected','hidden'].includes(e.status)).length;
      setApp(`<section class="center-backoffice admin-office"><div class="cb-header provider-topbar"><div class="cb-header-id"><div><p class="eyebrow">Cuenta administrador</p><h1>Centro de control de WORLDIVES</h1><p>Control administrativo de WORLDIVES DISCOVERY. Las acciones importantes quedan registradas en «Actividad».</p></div></div></div>
        <div class="cb-layout">${wdPanelSide('admin',[
          {id:'inicio',title:'Inicio',items:[nb('overview','home','Centro de control'),nb('audit','chart','Actividad')]},
          {id:'revision',title:'Revisión',items:[nb('claims','check','Solicitudes de centros',claims.length),nb('experiences','viaje','Experiencias',expPending),nb('moderation','alert','Denuncias y moderación')]},
          {id:'puntos',title:'Puntos de buceo',items:[nb('points','pin','Todos los puntos'),nb('pointbatches','inbox','Lotes nuevos',ptCounts.batch_items),nb('pointdups','list','Posibles duplicados',ptCounts.duplicates),nb('pointprops','message','Propuestas de cambio',ptCounts.proposals),nb('pointpos','alert','Posición por revisar',ptCounts.positions),nb('pointvideos','image','Vídeos de puntos',((vidCountsR||{}).pending||0)+((vidCountsR||{}).reported||0))]},
          {id:'contenido',title:'Contenido',items:[nb('destinations','globe','Destinos'),nb('divetypes','target','Tipos de buceo'),nb('marina','fish','Especies y vídeos',marinaPending),nb('media','image','Imágenes de la web'),nb('pointtexts','file','Descripciones de puntos'),nb('maps','map','Mapas')]},
          {id:'catalogo',title:'Catálogo',items:[nb('svctemplates','tag','Plantillas de servicio'),nb('plans','star','Planes'),nb('features','sliders','Funciones'),nb('promos','megaphone','Patrocinio'),nb('rewards','gift','Recompensas')]},
          {id:'personas',title:'Centros y usuarios',items:[nb('centers','home','Centros'),nb('users','users','Usuarios')]},
          {id:'herramientas',title:'Herramientas',items:[nb('qr','qr','Códigos QR'),nb('bookings','calendar','Reservas en cifras'),nb('adminpay','receipt','Pagos, exportaciones y DAC7'),nb('emails','mail','Correos')]},
          {id:'seguros',title:'Seguros',items:[nb('seguros','shield','Aseguradoras colaboradoras')]},
          {id:'sistema',title:'Sistema',items:[nb('ops','bolt','Ajustes y estado del sistema'),nb('legal','file','Legal'),nb('privacy','lock','Datos personales y accesos')]}])}
        <div class="cb-main">${wdPanelMenuBtn('admin')}${mapsInfo&&!mapsInfo.key_configured?'<div class="notice warning" id="admin-sat-notice"><strong>Añade la clave de ArcGIS para activar el satélite.</strong><p style="margin:6px 0 0">Mientras no esté, «Satélite» aparece desactivado en los mapas. <a href="#/admin?tab=maps">Ver Mapas</a></p></div>':''}<div id="admin-content"></div></div></div></section>`);
    } else setApp(`<section class="page provider-page"><div class="provider-topbar"><div><p class="eyebrow">${isAdmin?'CUENTA ADMINISTRADOR':'PANEL PROFESIONAL · CENTRO DE BUCEO'}</p><h1>${isAdmin?'Centro de control de WORLDIVES':escapeHtml(myCenter?.name||'Panel del centro')}</h1><p class="lead">${isAdmin?'Control administrativo de WORLDIVES DISCOVERY.':'Tu centro de operaciones: reservas, salidas, clientes, pagos y catálogo.'}</p></div>${!isAdmin&&myCenter?`<div class="provider-status"><span class="status good">● Centro activo</span><a href="#/admin?tab=center">Gestionar ficha</a></div>`:''}</div>
      ${isAdmin&&mapsInfo&&!mapsInfo.key_configured?'<div class="notice warning" id="admin-sat-notice" style="margin-top:18px"><strong>Añade la clave de ArcGIS para activar el satélite.</strong><p style="margin:6px 0 0">Mientras no esté, «Satélite» aparece desactivado en los mapas. <a href="#/admin?tab=maps">Ver Mapas</a></p></div>':''}${isAdmin?'<div class="notice" style="margin-top:18px"><strong>Control total activado</strong><p style="margin:6px 0 0">Las acciones importantes quedan registradas en el historial de actividad.</p></div>':''}
      ${!isAdmin?`<div class="provider-mini-summary"><span><strong>${points.length}</strong> puntos activos</span><span><strong>${bookings.length}</strong> reservas</span><span><strong>${centerPending.length}</strong> por confirmar</span><span><strong>${centerConfirmed.length}</strong> confirmadas</span><span><strong>${centerPaid.length}</strong> pagadas</span></div>`:''}
      <div class="tabs provider-tabs">${isAdmin?'<button class="tab active" data-tab="overview">Inicio</button>':'<button class="tab active" data-tab="overview">Resumen</button><button class="tab" data-tab="bookings">Reservas</button><button class="tab" data-tab="services">Servicios y salidas</button><button class="tab" data-tab="clients">Clientes</button><button class="tab" data-tab="points">Puntos de buceo</button><button class="tab" data-tab="rewards">Recompensas</button><button class="tab" data-tab="suggestions">Correcciones</button><button class="tab" data-tab="qr">QR / Check-in</button><button class="tab" data-tab="center">Mi centro</button><button class="tab" data-tab="payments">Cobros y pagos</button>'}${isAdmin?'<button class="tab" data-tab="points">Puntos</button><button class="tab" data-tab="bookings">Reservas</button><button class="tab" data-tab="adminpay">Pagos</button><button class="tab" data-tab="emails">Correos</button><button class="tab" data-tab="legal">Legal</button><button class="tab" data-tab="pointtexts">Descripciones de puntos</button><button class="tab" data-tab="maps">Mapas</button><button class="tab" data-tab="plans">Planes</button><button class="tab" data-tab="features">Funciones</button><button class="tab" data-tab="ops">Operación</button><button class="tab" data-tab="marina">Vida marina y vídeos</button><button class="tab" data-tab="experiences">Experiencias</button><button class="tab" data-tab="destinations">Destinos</button><button class="tab" data-tab="media">Imágenes de la web</button><button class="tab" data-tab="svctemplates">Plantillas de servicios</button><button class="tab" data-tab="promos">Patrocinio</button><button class="tab" data-tab="seguros">Seguros</button><button class="tab" data-tab="users">Usuarios</button><button class="tab" data-tab="centers">Centros</button><button class="tab" data-tab="claims">Verificaciones</button><button class="tab" data-tab="moderation">Moderación</button><button class="tab" data-tab="privacy">Datos personales</button><button class="tab" data-tab="suggestions">Correcciones</button><button class="tab" data-tab="qr">QR</button><button class="tab" data-tab="audit">Actividad</button><button class="tab" data-tab="rewards">Recompensas</button>':''}</div><div id="admin-content"></div></section>`);
    const tabs=isAdmin?$$('.cb-sidebar .cb-nav[data-tab]'):$$('.tab');
    if(failed.length){ const parts=document.createElement('div'); $('#admin-content')?.before(parts); wdPartsFailed(parts,failed,()=>route()); }
    async function show(t){
      try{ await showTab(t); }catch(e){ console.error(e); const c=$('#admin-content'); if(c){ c.innerHTML=wdBlockError(e); translateTree(c); c.querySelector('[data-block-retry]').onclick=()=>show(t); } }
    }
    async function showTab(t){
      tabs.forEach(x=>x.classList.toggle('active',x.dataset.tab===t));
      const c=$('#admin-content');
      const visibleBookings=(statusFilter&&t==='bookings')?bookings.filter(b=>b.status===statusFilter):bookings;
      if(t==='overview') c.innerHTML=isAdmin?adminOverview(points,marinaPending,travelExperiences,users,centers,bookSum?.totals?.bookings||0):centerDashboard(bookings,points,clients,rewardOffers);
      if(t==='center'&&!isAdmin&&myCenter){c.innerHTML=centerProfileEditor(myCenter); bindCenterProfile(myCenter);}
      if(t==='payments'&&!isAdmin&&myCenter){c.innerHTML='<div id="center-payments-manager"></div>';renderCenterPayments(myCenter.id,'center-payments-manager');}
      if(t==='services'&&!isAdmin){c.innerHTML='<div id="center-services-manager"></div>';renderProviderServicesManager(d.user.id,'center','center-services-manager');}
      if(t==='points') c.innerHTML=isAdmin?adminPointsNav('points',ptCounts)+adminPoints(points,true):`<div id="center-points-tab"></div>`; if(t==='points'&&!isAdmin) renderCenterPointManager(d.user.center_id,'center-points-tab');
      // v50.58: the catalogue (the old «Correcciones de ubicación» address opens the proposals, where they are now)
      const PTV={pointbatches:renderAdminPointBatches,pointdups:renderAdminPointDups,pointprops:renderAdminPointProps,suggestions:renderAdminPointProps,pointpos:renderAdminPointPos};
      if(t==='pointvideos'&&isAdmin){ c.innerHTML='<div id="admin-videos"></div>';
        const vref=()=>api('/api/admin/videos/summary').then(n=>{ const b=$('.cb-sidebar .cb-nav[data-tab="pointvideos"]'); if(!b) return; let el=b.querySelector('b'); const k=(n.pending||0)+(n.reported||0); if(!k){ el?.remove(); return; } if(!el){ el=document.createElement('b'); b.append(el); } el.textContent=k; }).catch(()=>{});
        wdGuard('admin-videos',()=>renderAdminPointVideos('admin-videos',new URLSearchParams(location.hash.split('?')[1]||'').get('vtab')||'pending',vref)); }
      if(isAdmin&&PTV[t]){ const tt=t==='suggestions'?'pointprops':t; c.innerHTML=adminPointsNav(tt,ptCounts)+'<div id="admin-ptcat"></div>';
        const refresh=()=>api('/api/admin/dive-points/summary').then(n=>{ ptCounts=n; const map={pointbatches:'batch_items',pointdups:'duplicates',pointprops:'proposals',pointpos:'positions'};
          Object.entries(map).forEach(([k,f])=>{ const b=$(`.cb-sidebar .cb-nav[data-tab="${k}"]`); if(!b) return; let el=b.querySelector('b'); if(!n[f]){ el?.remove(); return; } if(!el){ el=document.createElement('b'); b.append(el); } el.textContent=n[f]; });
          $$('.pa-tab',c).forEach(x=>{ const f=map[x.dataset.paTab]; if(!f) return; let el=x.querySelector('b'); if(!n[f]){ el?.remove(); return; } if(!el){ el=document.createElement('b'); x.append(' ',el); } el.textContent=n[f]; }); }).catch(()=>{});
        wdGuard('admin-ptcat',()=>PTV[t]('admin-ptcat',refresh)); }
      if(t==='bookings'){ if(isAdmin){ c.innerHTML=adminBookingsSummary(bookSum); bindAdminBookingsSummary(c,statusFilter); } else c.innerHTML=adminBookings(visibleBookings); }
      if(t==='users') c.innerHTML=(usersR.masked?`<div class="notice wd-mask-note">${wdIcon('shield',16)} <span>Los correos se ven en parte. Verlos completos pide tu contraseña y el motivo.</span> <button type="button" class="btn btn-sm" id="users-full">Ver los correos completos</button></div>`:'')+adminUsers(users);
      if(t==='experiences') c.innerHTML=adminTravelExperiences(travelExperiences);
      if(t==='destinations') c.innerHTML=adminDestinations(meta.travel);
      if(t==='media'&&isAdmin){ c.innerHTML='<div id="site-theme-manager"></div><div id="site-media-manager"></div><div id="image-origins"></div>'; wdGuard('site-theme-manager',()=>renderThemeManager('site-theme-manager')); wdGuard('site-media-manager',()=>renderSiteMediaManager('site-media-manager')); wdGuard('image-origins',()=>renderImageOrigins('image-origins')); }
      if(t==='divetypes'&&isAdmin){ c.innerHTML='<div id="admin-divetypes"></div><div id="admin-typefields"></div>'; wdGuard('admin-typefields',()=>renderTypeFieldsAdmin('admin-typefields')); wdGuard('admin-divetypes',()=>renderSiteMediaManager('admin-divetypes',{group:'Tipos de buceo'})); }
      if(t==='svctemplates'&&isAdmin){ c.innerHTML='<div id="admin-svc-templates"></div>'; wdGuard('admin-svc-templates',()=>renderAdminServiceTemplates('admin-svc-templates')); }
      if(t==='adminpay'&&isAdmin){ c.innerHTML='<div id="admin-payments"></div>'; wdGuard('admin-payments',()=>renderAdminPayments('admin-payments')); }
      if(t==='emails'&&isAdmin){ c.innerHTML='<div id="admin-emails"></div>'; wdGuard('admin-emails',()=>renderAdminEmails('admin-emails')); }
      if(t==='legal'&&isAdmin){ c.innerHTML='<div id="admin-legal"></div>'; wdGuard('admin-legal',()=>renderAdminLegal('admin-legal')); }
      if(t==='ops'&&isAdmin){ c.innerHTML='<div id="admin-settings"></div><div id="admin-ops"></div>'; wdGuard('admin-settings',()=>renderAdminSettings('admin-settings')); wdGuard('admin-ops',()=>renderAdminOps('admin-ops')); }
      if(t==='plans'&&isAdmin){ c.innerHTML='<div id="admin-plans"></div>'; wdGuard('admin-plans',()=>renderAdminPlans('admin-plans')); }
      if(t==='features'&&isAdmin){ c.innerHTML='<div id="admin-features"></div>'; wdGuard('admin-features',()=>renderAdminFeatures('admin-features')); }
      if(t==='maps'&&isAdmin){ c.innerHTML='<div id="admin-maps"></div>'; wdGuard('admin-maps',()=>renderAdminMaps('admin-maps')); }
      if(t==='pointtexts'&&isAdmin){ c.innerHTML='<div id="admin-pointtexts"></div>'; wdGuard('admin-pointtexts',()=>renderAdminPointTexts('admin-pointtexts')); }
      if(t==='promos'&&isAdmin){ c.innerHTML='<div id="site-promos-manager"></div>'; wdGuard('site-promos-manager',()=>renderPromosManager('site-promos-manager')); }
      if(t==='seguros'&&isAdmin){ c.innerHTML='<div id="admin-insurance"></div>'; wdGuard('admin-insurance',()=>renderAdminInsurance('admin-insurance')); }
      if((t==='marina'||t==='virtual')&&isAdmin){ c.innerHTML='<div id="admin-marina"></div>'; wdGuard('admin-marina',()=>renderAdminMarina('admin-marina',t==='virtual'?'antiguos':undefined)); }
      if(t==='suggestions'&&!isAdmin) c.innerHTML=providerSuggestions(suggestions);
      if(t==='centers') c.innerHTML=adminCenters(centers);
      if(t==='claims') c.innerHTML=adminCenterClaims(claims);
      if(t==='moderation'&&isAdmin){ c.innerHTML='<div id="admin-moderation"></div>'; wdGuard('admin-moderation',()=>renderAdminModeration('admin-moderation')); }
      if(t==='privacy'&&isAdmin){ c.innerHTML='<div id="admin-privacy"></div>'; wdGuard('admin-privacy',()=>renderAdminPrivacy('admin-privacy')); }
      if(t==='qr'){ c.innerHTML='<div id="wd-short-links"></div>'; renderShortLinks('wd-short-links','admin'); }   // v50.57 (4.4)
      if(t==='audit'){ c.innerHTML='<div id="wd-counter-admin"></div>'+adminAudit(audit); renderVisitCounter('wd-counter-admin','/api/admin/contador'); }
      if(t==='clients') c.innerHTML=adminClients(clients);
      if(t==='rewards'){ c.innerHTML='<div id="admin-rewards"></div>'; wdGuard('admin-rewards',()=>renderRewardsManager('admin-rewards',{isAdmin,centers,centerId:d.user.center_id})); }
      bindAdmin(t);
    }
    tabs.forEach(t=>t.onclick=()=>show(t.dataset.tab));
    const qsAdmin=new URLSearchParams(location.hash.split('?')[1]||'');
    const requested=qsAdmin.get('tab'); const statusFilter=qsAdmin.get('status');
    const centerTabs=['overview','bookings','services','clients','points','rewards','suggestions','qr','center','payments'];
    // v50.57 (2.2): every tab of the menu can be opened by its address (before, «Plantillas» was missing from a hand-written
    // list: its address, a reload or a link to it opened «Inicio»).
    if(isAdmin){ $('.provider-topbar')?.insertAdjacentHTML('afterend','<div id="wd-conf-strip"></div>'); api('/api/admin/confirm').then(wdConfStrip).catch(()=>{}); }
    const adminTabs=$$('.cb-sidebar [data-tab]').map(b=>b.dataset.tab);
    if(isAdmin) wdPanelBind($('#app'),'admin');
    show(isAdmin&&adminTabs.includes(requested)?requested:(isAdmin?'overview':(centerTabs.includes(requested)?requested:'overview')));
  }
  // Shared by the center workspace and the legacy admin view.
  async function bindCenterProfile(c){
    const form=$('#my-center-form'); if(!form)return;
    const eqWrap=$('#center-equipment-editor');
    if(eqWrap){try{const eq=(await api('/api/center-equipment?center_id='+c.id)).items;eqWrap.innerHTML=eq.map(x=>`<div class="equipment-admin-row"><div><strong>${escapeHtml(x.label)}</strong></div><input class="center-equipment-price" data-code="${escapeHtml(x.code)}" type="number" min="0" step="0.01" value="${x.price==null?'':x.price}" placeholder="Consultar"><span>€</span><button class="btn save-equipment-price" data-code="${escapeHtml(x.code)}">Guardar</button></div>`).join('');$$('.save-equipment-price').forEach(btn=>btn.onclick=async()=>{const input=document.querySelector('.center-equipment-price[data-code="'+btn.dataset.code+'"]');try{await postJSON('/api/center-equipment',{code:btn.dataset.code,price:input.value});toast('Precio de equipo actualizado.');}catch(err){toast(err.message)}});}catch(e){eqWrap.innerHTML='<div class="empty">No se pudo cargar el catálogo de equipo.</div>';}}
    form.onsubmit=async e=>{e.preventDefault();try{await postJSON('/api/provider/center-update',{name:$('#mc-name').value,country:$('#mc-country').value,region:$('#mc-region').value,phone:$('#mc-phone').value,city:$('#mc-city').value,website:$('#mc-web').value,email:$('#mc-email').value,logo_url:$('#mc-logo').value,address:$('#mc-address').value,specialties:$('#mc-spec').value,description:$('#mc-desc').value,instagram_url:$('#mc-instagram').value,facebook_url:$('#mc-facebook').value,twitter_url:$('#mc-twitter').value,youtube_url:$('#mc-youtube').value,tiktok_url:$('#mc-tiktok').value});if($('#mc-photo').files[0]){const fd=new FormData();fd.append('file',$('#mc-photo').files[0]);await api('/api/provider/avatar',{method:'POST',body:fd});}toast('Ficha del centro actualizada.');renderAdmin();}catch(err){toast(err.message)}};
  }
  function adminOverview(points,marinaPending,experiences,users,centers,nBookings){return `<div class="cards" style="margin-top:18px"><a class="card" href="#/admin?tab=points"><span class="label">CATÁLOGO</span><h3>Gestionar puntos de buceo</h3><p>${points.length} puntos activos. Crear, editar, archivar y corregir ubicaciones.</p></a><a class="card" href="#/admin?tab=marina"><span class="label">VIDA MARINA Y VÍDEOS</span><h3>Especies y vídeos de las rutas</h3><p>${marinaPending?`<b class="status warn">${marinaPending}</b> <span>propuestas pendientes de aprobar.</span>`:'<span>Catálogo de especies, vídeos enlazados y propuestas de centros y freelance.</span>'}</p></a><a class="card" href="#/admin?tab=experiences"><span class="label">MARKETPLACE</span><h3>Gestionar experiencias</h3><p>${experiences.length} propuestas y viajes publicados o pendientes de revisión.</p></a><a class="card" href="#/admin?tab=destinations"><span class="label">DESTINOS</span><h3>Gestionar destinos</h3><p>Crea y organiza los destinos que alimentan la sección Experiencias.</p></a><a class="card" href="#/admin?tab=users"><span class="label">CUENTAS</span><h3>Usuarios y permisos</h3><p>${users.length} cuentas. Cambia roles entre administrador, centro, freelance y buceador.</p></a><a class="card" href="#/admin?tab=centers"><span class="label">PROVEEDORES</span><h3>Centros de buceo</h3><p>${centers.length} centros y sus puntos asociados.</p></a><a class="card" href="#/admin?tab=bookings"><span class="label">OPERACIÓN</span><h3>Reservas</h3><p>${Number(nBookings).toLocaleString(wdLocale())} reservas esta temporada, en cifras.</p></a><a class="card" href="#/admin?tab=audit"><span class="label">CONTROL</span><h3>Actividad administrativa</h3><p>Consulta quién creó, modificó, publicó o eliminó contenido.</p></a></div>`}

  function adminDestinations(items){return `<div class="notice"><strong>Destinos de Experiencias</strong><p>Estos destinos alimentan la sección Experiencias. Puedes crear nuevos destinos desde aquí.</p></div><div class="page-actions" style="margin-top:14px"><button class="btn btn-primary" id="new-destination">Nuevo destino</button></div><div class="table-wrap"><table><thead><tr><th>Destino</th><th>Región</th><th>Tipo</th><th></th></tr></thead><tbody>${items.map(t=>`<tr><td><span class="dst-thumb">${t.image_path?`<img src="${escapeHtml(t.image_path)}" alt="">`:''}</span>${escapeHtml(t.title)}</td><td>${escapeHtml(t.region)}</td><td>${escapeHtml(t.kind)}</td><td><button class="btn edit-destination" data-id="${t.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`}
  // v50.54: the actions of this version with a readable name (the rest keep their code, as before).
  const ADMIN_ACTION_LABELS={admin_personal_data:'Acceso a datos personales',admin_data_permissions:'Permisos de datos personales cambiados',
    moderation_hidden:'Contenido ocultado con un motivo',moderation_resubmitted:'Corrección enviada a revisión',moderation_kept:'Sigue oculto tras la revisión',
    moderation_restored:'Publicado de nuevo tras la revisión',dive_point_conditions:'Condiciones del punto cambiadas',admin_created_cli:'Administrador creado desde la consola',
    admin_password_reset_cli:'Contraseña de administración restablecida desde la consola'};
  function adminAudit(items){return `<div class="notice">Historial de las acciones administrativas y de gestión registradas por WORLDIVES.</div>${wdExportBox([['actividad','Exportar la actividad']])}<div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Elemento</th><th>Detalles</th></tr></thead><tbody>${items.map(a=>`<tr><td>${fmtDate(a.created_at)}</td><td>${escapeHtml(a.fullname||'Sistema')}</td><td>${escapeHtml(ADMIN_ACTION_LABELS[a.action]||a.action)}</td><td>${escapeHtml(a.entity_type||'')} ${a.entity_id?('#'+a.entity_id):''}</td><td>${escapeHtml(auditDetails(a.details))}</td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay actividad.</td></tr>'}</tbody></table></div>`}
  // v50.51: the details of an audit entry are stored as JSON; they are shown as «clave: valor», without empty values.
  const AUDIT_KEYS={status:'estado',reason:'motivo',mode:'modo',capacity:'capacidad',decision:'decisión',method:'método',note:'nota',center_id:'centro',rating:'valoración',booking_id:'reserva',ip:'IP (huella)',totp:'dos pasos',points:'puntos',point:'punto',species:'especies',created:'creados',skipped:'omitidos',price:'precio',effective_from:'desde',email:'email',role:'rol',name:'nombre',permissions:'permisos',recipients:'destinatarios',spots_total:'plazas',spots_available:'libres',dive_point_ids:'puntos',weekdays:'días',closures:'cierres',timezone:'zona horaria',part:'parte',kind:'tipo',added:'añadidas',requested_role:'rol pedido',amount:'importe',currency:'moneda',
    case:'caso',cambios:'cambios',what:'dato',permiso:'casilla',path:'pantalla',provider_user_id:'profesional'};
  function auditDetails(raw){
    let d; try{ d=JSON.parse(raw); }catch(e){ return String(raw||''); }
    if(!d||typeof d!=='object'||Array.isArray(d)) return String(raw||'');
    const st=v=>(typeof v==='string'&&WD_STATES[v])?WD_STATES[v][0]:v;
    const val=v=>v===true?'sí':v===false?'no':Array.isArray(v)?v.join(', '):(v&&typeof v==='object')?JSON.stringify(v):String(st(v));
    const parts=[]; const has=v=>v!==null&&v!==undefined&&v!==''&&!(Array.isArray(v)&&!v.length);
    if(has(d.from)&&has(d.to)){ parts.push(`de ${val(d.from)} a ${val(d.to)}`); delete d.from; delete d.to; }
    Object.entries(d).forEach(([k,v])=>{ if(has(v)) parts.push(`${AUDIT_KEYS[k]||k.replace(/_/g,' ')}: ${val(v)}`); });
    return parts.join(' · ');
  }
  function adminPoints(points,isAdmin){return `<div class="page-actions"><button class="btn btn-primary" id="new-point">Nuevo punto</button></div><div class="table-wrap"><table><thead><tr><th>Punto</th><th>Ubicación</th><th>Tipo</th><th>Estado</th><th></th></tr></thead><tbody>${points.map(p=>`<tr><td>${escapeHtml(p.name)}</td><td>${escapeHtml(p.country)} · ${escapeHtml(p.region||'')}<br><small>${Number(p.latitude).toFixed(5)}, ${Number(p.longitude).toFixed(5)}</small></td><td>${escapeHtml(p.dive_type)}</td><td>${escapeHtml(p.verification_status)}</td><td>${isAdmin?`<button class="btn edit-point" data-id="${p.id}">Editar</button>${p.verification_status==='pending_center'?`<button class="btn review-point" data-id="${p.id}" data-decision="approve">Aprobar</button><button class="btn review-point" data-id="${p.id}" data-decision="reject">Rechazar</button>`:''}`:`<button class="btn propose-point" data-id="${p.id}">Proponer corrección</button>`}</td></tr>`).join('')}</tbody></table></div>`}
  // v50.58 (brief of 16/10, A.3 and B.3–B.6): Administración → Puntos de buceo. Besides the list: the new batches
  // («Pendiente de verificar» until published), the possible duplicates (join or keep separate), the proposals of centres
  // and divers (accept or reject with one click) and the published sites whose position falls on land.
  const PT_ADMIN_TABS=[['points','Todos los puntos'],['pointbatches','Lotes nuevos','batch_items'],['pointdups','Posibles duplicados','duplicates'],['pointprops','Propuestas de cambio','proposals'],['pointpos','Posición por revisar','positions']];
  function adminPointsNav(active,counts){ return `<nav class="pa-nav" aria-label="Puntos de buceo">${PT_ADMIN_TABS.map(([k,l,c])=>`<button type="button" class="pa-tab${k===active?' is-active':''}" data-pa-tab="${k}" ${k===active?'aria-current="page"':''}>${escapeHtml(l)}${c&&counts?.[c]?` <b>${counts[c]}</b>`:''}</button>`).join('')}</nav>`; }
  const PT_FIELD_LABELS={latitude:'Posición',min_depth:'Profundidad mínima',max_depth:'Profundidad máxima',access:'Acceso',current:'Corriente',water_temps:'Temperatura del agua',visibility_min:'Visibilidad desde',visibility_max:'Visibilidad hasta',bottom:'Tipo de fondo',best_months:'Mejor época',warnings:'Avisos',protection:'Protección',protection_name:'Espacio protegido',permit_required:'Permiso'};
  function ptValue(k,v){
    if(v==null||v===''||(Array.isArray(v)&&!v.length)) return '—';
    if(k==='access') return PT_ACCESS[v]||v;
    if(k==='current') return PT_CURRENTS[v]||v;
    if(k==='protection') return PT_PROTECTIONS[v]||v;
    if(k==='permit_required') return Number(v)?'Hace falta permiso':'Sin permiso';
    if(k==='bottom') return (Array.isArray(v)?v:String(v).split(',')).map(x=>PT_BOTTOMS[x]||x).join(', ');
    if(k==='best_months') return (Array.isArray(v)?v:String(v).split(',')).filter(Boolean).map(m=>wdMes(+m,'short')).join(', ');
    if(k==='water_temps'){ let t=v; if(typeof t==='string'){ try{ t=JSON.parse(t); }catch{ return t; } } return Object.entries(t||{}).map(([s,r])=>`${PT_SEASONS[s]||s} ${r.filter(x=>x!=null).join('–')} °C`).join(' · ')||'—'; }
    if(/depth|visibility/.test(k)) return `${v} m`;
    return String(v);
  }
  const ptPosBadge=pc=>{ const [cls,t]=PT_CHECK[pc?.status||'unknown']||PT_CHECK.unknown; return `<span class="status ${cls==='bad'?'bad':cls==='warn'?'warn':cls==='good'?'good':''}" title="${escapeHtml(pc?.note||'')}">${escapeHtml(t)}</span>`; };

  async function renderAdminPointBatches(id,refresh){
    const host=document.getElementById(id); if(!host) return;
    const d=await api('/api/admin/dive-points/batches');
    const sum=s=>`<span>${s.pending||0} pendientes</span>${s.published?` · <span>${s.published} publicados</span>`:''}${s.merged?` · <span>${s.merged} completaron fichas</span>`:''}${s.problems?` · <span class="status bad">${s.problems} con problemas</span>`:''}${s.land?` · <span class="status bad">${s.land} en tierra</span>`:''}${s.check_pos?` · <span class="status warn">${s.check_pos} posición por revisar</span>`:''}${s.doubts?` · <span class="status warn">${s.doubts} posibles duplicados</span>`:''}${s.same?` · <span>${s.same} completan fichas que ya existen</span>`:''}`;
    host.innerHTML=`<div class="notice"><strong>Lotes nuevos</strong><p>Cada zona entra como un lote «Pendiente de verificar»: no se ve en la web hasta que lo publicas, entero o punto a punto. Un punto que cae en tierra o que puede estar repetido espera a que decidas.</p></div>
      <details class="pa-upload"><summary>Subir un lote (archivo JSON)</summary><p class="pd-hint">El archivo que preparan los scripts de <code>scripts/puntos/</code>: <code>{"zone":"…","title":"…","items":[{"name":"…","latitude":…,"longitude":…,"country":"…","sources":[…]}]}</code>.</p><input type="file" id="pa-file" accept="application/json,.json"> <button type="button" class="btn" id="pa-up">Subir el lote</button></details>
      <div class="pa-batches">${d.items.map(b=>`<article class="pa-batch" data-batch="${b.id}"><header><div><h3>${escapeHtml(b.title)}</h3><p class="muted">${escapeHtml(b.zone)} · ${escapeHtml(fmtDate(b.created_at))} · ${b.status==='published'?'<span class="status good">Publicado</span>':b.status==='partial'?'<span class="status warn">Publicado en parte</span>':'<span class="status warn">Pendiente de verificar</span>'}</p><p class="pa-sum">${sum(b.summary)}</p></div><button type="button" class="btn pa-open" data-id="${b.id}" aria-expanded="false">Ver los puntos</button></header><div class="pa-items" hidden></div></article>`).join('')||'<div class="empty">Todavía no hay lotes. Cuando se prepare una zona aparecerá aquí.</div>'}</div>`;
    translateTree(host);
    $('#pa-up',host).onclick=async()=>{ const f=$('#pa-file',host).files[0]; if(!f) return toast('Elige el archivo del lote.'); try{ const data=JSON.parse(await f.text()); const r=await postJSON('/api/admin/dive-points/batches',data); toast(`Lote subido: ${r.summary.pending} puntos pendientes.`); refresh?.(); renderAdminPointBatches(id,refresh); }catch(e){ toast(e instanceof SyntaxError?'El archivo no es un JSON válido.':e.message); } };
    $$('.pa-open',host).forEach(b=>b.onclick=()=>{ const box=b.closest('.pa-batch').querySelector('.pa-items'); const open=box.hidden; box.hidden=!open; b.setAttribute('aria-expanded',String(open)); if(open) paintBatch(+b.dataset.id,box); });
    async function paintBatch(bid,box){
      const r=await api('/api/admin/dive-points/batches/'+bid);
      const pend=r.items.filter(i=>i.status==='pending');
      box.innerHTML=`${pend.length?`<div class="pa-actions"><label class="lg-check"><input type="checkbox" class="pa-verified"> <span>Publicar como «Verificado» (si no, «Pendiente de verificar»)</span></label><button type="button" class="btn btn-primary pa-all">Publicar todos los que están bien</button></div>`:''}
        <div class="table-wrap"><table class="pa-table"><thead><tr><th>Punto</th><th>Posición</th><th>¿Ya existe?</th><th>Estado</th><th></th></tr></thead><tbody>${r.items.map(i=>{ const pos={status:i.position_status,note:i.position_note};
          const match=i.match_kind==='same'?`Completa <a href="#/admin?tab=points&edit=${i.match_point_id}">${escapeHtml(i.match_name||'')}</a> (${i.match_distance_m} m)`:i.match_kind==='doubt'?`<span class="status warn">¿Es <a href="#/admin?tab=points&edit=${i.match_point_id}">${escapeHtml(i.match_name||'')}</a>?</span> (${i.match_distance_m} m)`:'Nuevo';
          const st={pending:'Pendiente',published:'Publicado',merged:'Completó una ficha',discarded:'Descartado'}[i.status]||i.status;
          return `<tr data-item="${i.id}"><td><b>${escapeHtml(i.name)}</b><br><small>${escapeHtml([i.data.region,i.country].filter(Boolean).join(' · '))}</small>${i.problem?`<br><small class="status bad">${escapeHtml(i.problem)}</small>`:''}</td><td>${ptPosBadge(pos)}<br><small>${Number(i.latitude).toFixed(5)}, ${Number(i.longitude).toFixed(5)}</small></td><td>${match}</td><td>${escapeHtml(st)}${i.point_id&&i.status!=='pending'?` · <a href="#/punto/${i.point_id}">Ver</a>`:''}</td>
            <td class="pa-row-actions">${i.status==='pending'?(i.match_kind==='doubt'?`<button type="button" class="btn btn-sm pa-pub" data-decision="complete">Es el mismo: completar</button><button type="button" class="btn btn-sm pa-pub" data-decision="new">Es otro: publicar</button>`:`<button type="button" class="btn btn-sm pa-pub" ${pos.status==='error'||i.problem?'disabled':''}>${i.match_kind==='same'?'Completar la ficha':'Publicar'}</button>`)+`<button type="button" class="btn btn-sm pa-edit">Corregir</button><button type="button" class="btn btn-sm pa-discard">Descartar</button>`:''}</td></tr>`; }).join('')}</tbody></table></div>`;
      translateTree(box);
      const verified=()=>!!$('.pa-verified',box)?.checked;
      $('.pa-all',box)?.addEventListener('click',async()=>{ try{ const x=await postJSON('/api/admin/dive-points/batches/publish',{batch_id:bid,verified:verified()}); toast(`Publicados: ${x.done.length}. Siguen pendientes: ${x.skipped.length}.`); refresh?.(); paintBatch(bid,box); }catch(e){ toast(e.message); } });
      $$('.pa-pub',box).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/admin/dive-points/batches/publish',{item_id:+b.closest('tr').dataset.item,decision:b.dataset.decision||null,verified:verified()}); toast('Hecho.'); refresh?.(); paintBatch(bid,box); }catch(e){ toast(e.message); } });
      $$('.pa-discard',box).forEach(b=>b.onclick=async()=>{ if(!confirm(translateString('¿Descartar este punto del lote? No se publica.'))) return; try{ await postJSON('/api/admin/dive-points/batches/discard',{item_id:+b.closest('tr').dataset.item}); refresh?.(); paintBatch(bid,box); }catch(e){ toast(e.message); } });
      $$('.pa-edit',box).forEach(b=>b.onclick=()=>{ const tr=b.closest('tr'), it=r.items.find(x=>x.id===+tr.dataset.item); const ed=document.createElement('tr'); ed.className='pa-editrow';
        ed.innerHTML=`<td colspan="5"><div class="form-grid"><div class="field"><label>Nombre</label><input class="pe-n" value="${escapeHtml(it.name)}"></div><div class="field"><label>Latitud</label><input class="pe-la" type="number" step="0.000001" value="${it.latitude}"></div><div class="field"><label>Longitud</label><input class="pe-lo" type="number" step="0.000001" value="${it.longitude}"></div></div><div class="form-actions"><button type="button" class="btn btn-primary btn-sm pe-ok">Guardar y comprobar de nuevo</button><button type="button" class="btn btn-sm pe-no">Cancelar</button></div></td>`;
        tr.after(ed); translateTree(ed); $('.pe-no',ed).onclick=()=>ed.remove();
        $('.pe-ok',ed).onclick=async()=>{ try{ await postJSON('/api/admin/dive-points/batches/item',{item_id:it.id,name:$('.pe-n',ed).value,latitude:+$('.pe-la',ed).value,longitude:+$('.pe-lo',ed).value}); refresh?.(); paintBatch(bid,box); }catch(e){ toast(e.message); } }; });
    }
  }

  async function renderAdminPointDups(id,refresh){
    const host=document.getElementById(id); if(!host) return;
    const d=await api('/api/admin/dive-points/duplicates');
    const card=(k,p)=>`<div class="pa-dupcard"><h4><a href="#/admin?tab=points&edit=${p.id}">${escapeHtml(p.name)}</a></h4><p class="muted">${escapeHtml(p.country||'')}<br><small>${Number(p.lat).toFixed(5)}, ${Number(p.lon).toFixed(5)}</small></p><p><small>${p.photos} fotos · ${p.centers} centros</small></p></div>`;
    host.innerHTML=`<div class="notice"><strong>Posibles duplicados</strong><p>Fichas a menos de 300 m o con un nombre casi igual (sin tildes, sin «El» o «La», con sinónimos como «Bajo» y «Bajón»). Al unirlas, las fotos, los centros, las reseñas que llegan por ellos, la vida marina y las fuentes pasan a la ficha que se queda; la otra queda archivada, nunca se borra.</p><button type="button" class="btn btn-sm" id="pa-scan">Buscar duplicados ahora</button></div>
      <div class="pa-dups">${d.pairs.map(x=>`<article class="pa-dup" data-id="${x.id}"><p class="pa-dupmeta">${x.kind==='same'?'<span class="status bad">Parecen el mismo</span>':'<span class="status warn">Puede ser el mismo</span>'} · a ${Number(x.distance_m).toLocaleString(wdLocale())} m · nombres parecidos al ${Math.round((x.score||0)*100)} %</p>
        <div class="pa-duppair">${card('a',{id:x.a_point_id,name:x.a_name,country:x.a_country,lat:x.a_lat,lon:x.a_lon,photos:x.a_photos,centers:x.a_centers})}${card('b',{id:x.b_point_id,name:x.b_name,country:x.b_country,lat:x.b_lat,lon:x.b_lon,photos:x.b_photos,centers:x.b_centers})}</div>
        <div class="pa-actions"><button type="button" class="btn btn-sm pa-merge" data-keep="${x.a_point_id}">Unir: se queda «${escapeHtml(x.a_name)}»</button><button type="button" class="btn btn-sm pa-merge" data-keep="${x.b_point_id}">Unir: se queda «${escapeHtml(x.b_name)}»</button><button type="button" class="btn btn-sm pa-sep">Mantener separados</button></div></article>`).join('')||'<div class="empty">No hay posibles duplicados entre los puntos publicados.</div>'}</div>
      ${d.items.length?`<h3 class="pe-h">En los lotes nuevos</h3><ul class="pa-list">${d.items.map(i=>`<li><b>${escapeHtml(i.name)}</b> (${escapeHtml(i.batch_title)}) · ¿Es <a href="#/admin?tab=points&edit=${i.match_point_id}">${escapeHtml(i.match_name||'')}</a>? a ${i.match_distance_m} m · <button type="button" class="btn btn-sm" data-pa-tab="pointbatches">Decidir en «Lotes nuevos»</button></li>`).join('')}</ul>`:''}`;
    translateTree(host);
    $$('[data-pa-tab]',host).forEach(b=>b.onclick=()=>$(`.cb-sidebar .cb-nav[data-tab="${b.dataset.paTab}"]`)?.click());
    $('#pa-scan',host).onclick=async()=>{ try{ const r=await postJSON('/api/admin/dive-points/duplicates/scan',{}); toast(`Parejas nuevas: ${r.new}.`); refresh?.(); renderAdminPointDups(id,refresh); }catch(e){ toast(e.message); } };
    $$('.pa-merge',host).forEach(b=>b.onclick=async()=>{ if(!confirm(translateString('¿Unir las dos fichas? Todo pasa a la que se queda y la otra se archiva.'))) return; try{ const r=await postJSON('/api/admin/dive-points/duplicates/decide',{id:+b.closest('.pa-dup').dataset.id,decision:'merge',keep_id:+b.dataset.keep}); toast(r.filled?.length?`Unidas. La ficha recibe: ${r.filled.length} datos que le faltaban.`:'Unidas.'); refresh?.(); renderAdminPointDups(id,refresh); }catch(e){ toast(e.message); } });
    $$('.pa-sep',host).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/admin/dive-points/duplicates/decide',{id:+b.closest('.pa-dup').dataset.id,decision:'separate'}); refresh?.(); b.closest('.pa-dup').remove(); }catch(e){ toast(e.message); } });
  }

  // Encargo del 17/10 (1.2): «Datos propios de cada tipo». Adding a field to a type needs no programming; a hidden field
  // keeps its values (nothing is deleted) and stops showing in the pages.
  async function renderTypeFieldsAdmin(id){
    const host=document.getElementById(id); if(!host) return; const esc=escapeHtml; const d=await api('/api/admin/dive-type-fields');
    const KIND={number:'Número',text:'Texto',yesno:'Sí / No'};
    host.innerHTML=`<section class="mm-module tf-admin"><div class="svc-head"><div><p class="eyebrow">Ficha del punto</p><h2>Datos propios de cada tipo</h2><p>Lo que cada tipo añade a la ficha del punto: el nombre del barco de un pecio, la longitud de una cueva… Solo se enseña lo que tiene valor.</p></div></div>
      <div class="tf-types">${d.types.map(t=>`<details class="tf-type" ${t.fields.length?'':''}><summary><b>${esc(translateString(t.label))}</b> <span class="pt-n">${t.fields.filter(f=>f.active).length}</span></summary>
        <ul class="tf-list">${t.fields.map(f=>`<li class="${f.active?'':'is-off'}" data-id="${f.id}"><input class="tf-label" value="${esc(f.label)}" maxlength="80" aria-label="${esc(translateString('Nombre del dato'))}"><small>${esc(translateString(KIND[f.kind]))}${f.unit?' · '+esc(f.unit):''} · ${f.points} ${esc(translateString(f.points===1?'punto':'puntos'))}</small>
          <button type="button" class="btn btn-sm tf-save">${esc(translateString('Guardar'))}</button><button type="button" class="btn btn-sm tf-toggle">${esc(translateString(f.active?'Ocultar':'Mostrar'))}</button></li>`).join('')||`<li class="muted">${esc(translateString('Este tipo no tiene datos propios.'))}</li>`}</ul>
        <form class="tf-new" data-type="${esc(t.key)}"><input name="label" maxlength="80" placeholder="${esc(translateString('Nuevo dato, por ejemplo «Profundidad de la quilla»'))}" required><select name="kind">${Object.entries(KIND).map(([k,l])=>`<option value="${k}">${esc(translateString(l))}</option>`).join('')}</select><input name="unit" maxlength="12" placeholder="${esc(translateString('Unidad (m, nudos…)'))}"><button class="btn btn-sm btn-primary" type="submit">${esc(translateString('Añadir'))}</button></form></details>`).join('')}</div></section>`;
    const again=()=>renderTypeFieldsAdmin(id);
    $$('.tf-save',host).forEach(b=>b.onclick=()=>{ const li=b.closest('li'); postJSON('/api/admin/dive-type-fields',{id:+li.dataset.id,label:$('.tf-label',li).value}).then(()=>{ toast('Guardado.'); }).catch(e=>toast(e.message)); });
    $$('.tf-toggle',host).forEach(b=>b.onclick=()=>{ const li=b.closest('li'); postJSON('/api/admin/dive-type-fields',{id:+li.dataset.id,active:li.classList.contains('is-off')?1:0}).then(again).catch(e=>toast(e.message)); });
    $$('.tf-new',host).forEach(f=>f.onsubmit=e=>{ e.preventDefault(); const fd=new FormData(f); postJSON('/api/admin/dive-type-fields',{type_key:f.dataset.type,label:fd.get('label'),kind:fd.get('kind'),unit:fd.get('unit')}).then(()=>{ toast('Dato añadido.'); again(); }).catch(err=>toast(err.message)); });
  }
  async function renderAdminPointProps(id,refresh){
    const host=document.getElementById(id); if(!host) return;
    const d=await api('/api/admin/dive-points/proposals');
    host.innerHTML=`<div class="notice"><strong>Propuestas de cambio</strong><p>Las envían los centros que bucean en el punto (posición, corriente, visibilidad y avisos) y los buceadores (también el resto de datos). Al aceptar, la ficha cambia y la propuesta queda anotada como fuente del dato.</p></div>
      <div class="pa-props">${d.items.map(x=>{ const ch=x.changes; const rows=Object.keys(ch).filter(k=>k!=='longitude').map(k=>k==='latitude'?`<tr><th>Posición</th><td>${x.current.latitude!=null?`${Number(x.current.latitude).toFixed(5)}, ${Number(x.current.longitude).toFixed(5)}`:'—'}</td><td>${Number(ch.latitude).toFixed(5)}, ${Number(ch.longitude).toFixed(5)}${x.moved_m!=null?` <small>(${Number(x.moved_m).toLocaleString(wdLocale())} m)</small>`:''}<br>${ptPosBadge(x.position)}</td></tr>`:`<tr><th>${escapeHtml(PT_FIELD_LABELS[k]||k)}</th><td>${escapeHtml(ptValue(k,x.current[k]))}</td><td><b>${escapeHtml(ptValue(k,ch[k]))}</b></td></tr>`).join('')
            +(x.type_rows||[]).map(r=>`<tr><th>${escapeHtml(translateString(r.label))}</th><td>${r.current!=null?escapeHtml(typeValue(r,r.current)):'—'}</td><td><b>${escapeHtml(typeValue(r,r.new))}</b></td></tr>`).join('');
          return `<article class="pa-prop" data-id="${x.id}"><header><h3><a href="#/admin?tab=points&edit=${x.point_id}">${escapeHtml(x.point_name)}</a></h3><p class="muted">${x.role==='center'?`${wdIcon('home',14)} ${escapeHtml(x.center_name||'Centro')}`:`${wdIcon('user',14)} Buceador`} · ${escapeHtml(x.fullname||'')} <small>${escapeHtml(x.email||'')}</small> · ${escapeHtml(fmtDate(x.created_at))}</p></header>
            <div class="table-wrap"><table class="pa-table"><thead><tr><th>Dato</th><th>Ahora</th><th>Propuesta</th></tr></thead><tbody>${rows}</tbody></table></div>${x.note?`<p class="pa-note">«${escapeHtml(x.note)}»</p>`:''}
            <div class="pa-actions"><button type="button" class="btn btn-primary btn-sm pa-ok">Aceptar</button><button type="button" class="btn btn-sm pa-no">Rechazar</button></div></article>`; }).join('')||'<div class="empty">No hay propuestas pendientes.</div>'}</div>`;
    translateTree(host);
    const decide=(b,decision)=>postJSON('/api/admin/dive-points/proposals/review',{id:+b.closest('.pa-prop').dataset.id,decision}).then(()=>{ toast(decision==='approve'?'Aceptada: la ficha ya tiene el cambio.':'Rechazada.'); b.closest('.pa-prop').remove(); refresh?.(); }).catch(e=>toast(e.message));
    $$('.pa-ok',host).forEach(b=>b.onclick=()=>decide(b,'approve')); $$('.pa-no',host).forEach(b=>b.onclick=()=>decide(b,'reject'));
  }

  async function renderAdminPointPos(id,refresh){
    const host=document.getElementById(id); if(!host) return;
    const d=await api('/api/admin/dive-points/positions');
    host.innerHTML=`<div class="notice"><strong>Posición por revisar</strong><p>Puntos publicados que, según la línea de costa de OpenStreetMap (10 m de error), caen en tierra, o puntos de costa a más de 200 m de la orilla. Muchos tienen la posición del pueblo o de la zona: corrígelos con una fuente (el GPS de un centro, una publicación oficial), nunca «a ojo».</p><p class="muted">${d.unchecked?`${Number(d.unchecked).toLocaleString(wdLocale())} puntos están fuera de las zonas con datos de costa y no se pueden comprobar.`:''}</p><button type="button" class="btn btn-sm" id="pa-recheck">Comprobar todos de nuevo</button></div>
      <div class="table-wrap"><table class="pa-table"><thead><tr><th>Punto</th><th>Posición</th><th>Comprobación</th><th></th></tr></thead><tbody>${d.items.map(p=>`<tr><td><b>${escapeHtml(p.name)}</b><br><small>${escapeHtml([p.region,p.country].filter(Boolean).join(' · '))}</small></td><td><small>${Number(p.latitude).toFixed(5)}, ${Number(p.longitude).toFixed(5)}</small></td><td>${ptPosBadge(p.position_check)}<br><small>${escapeHtml(p.position_check?.note||'')}</small></td><td><button type="button" class="btn btn-sm edit-point" data-id="${p.id}">Editar</button></td></tr>`).join('')||'<tr><td colspan="4">Todos los puntos comprobables caen en el agua.</td></tr>'}</tbody></table></div>`;
    translateTree(host);
    $$('.edit-point',host).forEach(b=>b.onclick=()=>wdGo('#/admin?tab=points&edit='+b.dataset.id));
    $('#pa-recheck',host).onclick=async()=>{ try{ const r=await postJSON('/api/admin/dive-points/positions/recheck',{}); toast(`Comprobados: ${r.checked}.`); refresh?.(); renderAdminPointPos(id,refresh); }catch(e){ toast(e.message); } };
  }
  function adminBookings(items){
    const today=new Date().toISOString().slice(0,10);
    const ST={pending:['Pendiente','warn'],confirmed:['Confirmada','good'],completed:['Completada','good'],rejected:['Rechazada','bad'],cancelled:['Cancelada','bad']};
    const NEXT={pending:[['confirmed','Confirmar'],['rejected','Rechazar'],['cancelled','Cancelar']],confirmed:[['completed','Completar'],['cancelled','Cancelar']]};
    const shown=items.slice(0,500);
    return `<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Cliente</th><th>Centro</th><th>Servicio / punto</th><th>Estado</th><th></th></tr></thead><tbody>${shown.map(b=>{ const st=ST[b.status]||[b.status,'warn']; const acts=(NEXT[b.status]||[]).filter(([s])=>s!=='completed'||String(b.booking_date)<=today);
      return `<tr><td><strong>${escapeHtml(wdDay(b.booking_date))}</strong><br><small>${escapeHtml(b.booking_time||'')}</small></td><td>${escapeHtml(b.fullname||'')}<br><small>${escapeHtml(b.email||'')}</small></td><td>${escapeHtml(b.center_name||'')}</td><td>${escapeHtml(b.service_title||'Reserva')}<br><small>${escapeHtml(b.point_name||'Punto a concretar')} · ${Number(b.participants||1)} ${Number(b.participants||1)===1?'persona':'personas'}</small></td><td><span class="status ${st[1]}">${escapeHtml(st[0])}</span></td><td class="ab-actions"><button class="btn booking-detail" data-id="${b.id}">Ver ficha</button>${acts.map(([s,l])=>`<button class="btn booking-status" data-id="${b.id}" data-status="${s}">${l}</button>`).join('')}</td></tr>`; }).join('')||'<tr><td colspan="6">No hay reservas.</td></tr>'}</tbody></table></div>${items.length>shown.length?`<p class="muted" style="margin-top:10px">Se muestran las ${shown.length} reservas más recientes de ${items.length}.</p>`:''}`;
  }
  function adminUsers(items){ const centers=state.centers||[]; return `<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Email</th><th>Rol</th><th>Centro</th><th>Alta</th><th></th></tr></thead><tbody>${items.map(u=>`<tr><td>${escapeHtml(u.fullname)}</td><td>${escapeHtml(u.email)}</td><td><select class="user-role" data-id="${u.id}"><option value="recreational" ${u.role==='recreational'?'selected':''}>Recreativo</option><option value="center" ${u.role==='center'?'selected':''}>Centro</option><option value="freelance" ${u.role==='freelance'?'selected':''}>Freelance</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrador</option></select></td><td><select class="user-center" data-id="${u.id}"><option value="">—</option>${centers.map(c=>`<option value="${c.id}" ${String(c.id)===String(u.center_id||'')?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></td><td>${fmtDate(u.created_at)}</td><td><button class="btn save-role" data-id="${u.id}">Guardar</button> <button class="btn close-sessions" data-id="${u.id}" data-name="${escapeHtml(u.fullname||'')}" type="button">Cerrar sesiones</button></td></tr>`).join('')}</tbody></table></div>`}

  // v50.58 (A.3): from the panel, a centre proposes position, current, visibility and warnings of a site it dives (the
  // administration accepts or rejects them with one click); the same form as on the public page of the site.
  async function proposePointPosition(id){ const p=(await api('/api/dive-points/'+id)).item; const lat=p.latitude!=null?+p.latitude:'', lng=p.longitude!=null?+p.longitude:'';
    setApp(`<section class="page">${wdCrumbs([wdHomeCrumb(),['Puntos de buceo','#/admin?tab=points'],['Proponer cambios · '+(p.name||'punto')]],'#/admin?tab=points')}<p class="eyebrow">PROPUESTA</p><h1>${escapeHtml(p.name)}</h1><p class="lead">No se publica hasta que la administración la revisa.</p><div class="detail" style="margin-top:28px"><article class="detail-main" id="position-proposal">${pointProposalForm(p,{lat,lng,centre:true})}<p><a class="btn" href="#/admin?tab=points">Cancelar</a></p></article></div></section>`);
    $('#s-save').onclick=async()=>{ try{ await postJSON('/api/dive-points/'+id+'/propose',readPointProposal($('#position-proposal'),p,{lat,lng})); toast('Propuesta enviada a la administración.'); wdGo('#/admin?tab=points'); }catch(err){ toast(err.message); } }; }
  function providerSuggestions(items){return `<div class="notice"><strong>Correcciones de puntos</strong><p>Como centro o profesional puedes proponer una nueva posición para cualquier punto. La ubicación oficial solo cambia cuando el administrador la aprueba.</p></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Punto</th><th>Propuesta</th><th>Estado</th><th>Motivo</th></tr></thead><tbody>${items.map(s=>`<tr><td>${escapeHtml(s.point_name)}</td><td>${Number(s.latitude).toFixed(6)}, ${Number(s.longitude).toFixed(6)}</td><td>${escapeHtml(s.status)}</td><td>${escapeHtml(s.note||'')}</td></tr>`).join('')||'<tr><td colspan="4">Todavía no has enviado correcciones.</td></tr>'}</tbody></table></div>`}
  function adminTravelExperiences(items){return `<div class="notice"><strong>Experiencias de viaje</strong><p>Los centros y profesionales pueden proponer viajes. Desde aquí el administrador puede publicar o rechazar cada propuesta.</p></div><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Experiencia</th><th>Destino</th><th>Proveedor</th><th>Fechas</th><th>Estado</th><th></th></tr></thead><tbody>${items.map(e=>`<tr><td>${escapeHtml(e.title)}</td><td>${escapeHtml(e.destination_title)}</td><td>${escapeHtml(e.center_name||e.provider_name||'')}</td><td>${escapeHtml(e.start_date||'')}</td><td>${escapeHtml(e.status)}</td><td>${e.status==='published'?'<span class="status good">Publicada</span>':`<button class="btn experience-status" data-id="${e.id}" data-status="published">Publicar</button> <button class="btn experience-status" data-id="${e.id}" data-status="rejected">Rechazar</button>`}${e.status!=='hidden'?` <button class="btn mod-hide-btn" type="button" data-mod-type="experience" data-id="${e.id}" data-label="${escapeHtml(e.title)}">Ocultar…</button>`:' <a class="btn" href="#/admin?tab=moderation">Ver en Moderación</a>'}</td></tr>`).join('')||'<tr><td colspan="6">No hay propuestas.</td></tr>'}</tbody></table></div>`}

  function adminCenterClaims(items){ const M={email_domain:'Email del dominio del centro',phone_call:'Llamada al teléfono público del centro',document:'Documento (licencia, alta fiscal o registro)'}; return `<div class="notice"><strong>Verificación de cuentas profesionales</strong><p>Nadie obtiene el rol de centro o profesional al registrarse. Antes de aprobar, comprueba la identidad por uno de estos medios y deja una nota: <b>email del dominio del centro</b>, <b>llamada al teléfono público</b> (no al que escribió en el registro) o <b>documento</b>. Si el centro ya existe, elige tú su ficha al aprobar: el sistema no la asocia por el teléfono. Si rechazas, la persona recibe un correo (sin tu nota interna).</p></div><div class="claims-list" style="margin-top:12px">${items.map(x=>`<article class="acc-card claim-card" data-claim="${x.id}"><div class="acc-card-head"><h3>${escapeHtml(x.requested_center_name||x.fullname)} <small>· ${x.requested_role==='freelance'?'Profesional freelance':'Centro de buceo'}</small></h3><span class="status warn">Pendiente</span></div><dl class="claim-data"><dt>Cuenta</dt><dd>${escapeHtml(x.fullname)} · ${escapeHtml(x.email)} ${x.email_matches_domain?'<span class="status good">email del dominio de la web</span>':''}</dd><dt>Teléfono indicado</dt><dd>${escapeHtml(x.phone||'—')}</dd><dt>Ciudad</dt><dd>${escapeHtml(x.city||'—')}</dd><dt>Web</dt><dd>${x.website?`<a href="${escapeHtml(x.website)}" target="_blank" rel="noopener noreferrer">${escapeHtml(x.website)}</a>`:'—'}</dd>${x.suggested_center_name?`<dt>Coincidencia sugerida</dt><dd>${escapeHtml(x.suggested_center_name)} (${escapeHtml(x.suggested_center_city||'')}) · teléfono público ${escapeHtml(x.suggested_center_phone||'—')} <small>Solo es una sugerencia: llama al teléfono público para confirmar.</small></dd>`:''}${x.note?`<dt>Nota</dt><dd>${escapeHtml(x.note)}</dd>`:''}<dt>Solicitud</dt><dd>${fmtDate(x.created_at)}</dd></dl><div class="form-grid"><div class="field"><label for="cm-${x.id}">Cómo lo has verificado</label><select id="cm-${x.id}" class="claim-method"><option value="">Elige…</option>${Object.entries(M).map(([k,v])=>`<option value="${k}">${escapeHtml(v)}</option>`).join('')}</select></div><div class="field"><label for="cn-${x.id}">Nota de la verificación</label><input id="cn-${x.id}" class="claim-note" placeholder="Ej. llamada al 965 000 000 el 12/10, atendió el gerente"></div>${x.suggested_center_id&&x.requested_role!=='freelance'?`<label class="lg-check full" for="cl-${x.id}"><input type="checkbox" id="cl-${x.id}" class="claim-link" value="${x.suggested_center_id}"><span>Vincular a la ficha existente «${escapeHtml(x.suggested_center_name)}» en lugar de crear una nueva</span></label>`:''}</div><div class="form-actions"><button class="btn btn-primary review-claim" data-id="${x.id}" data-decision="approve">Aprobar</button><button class="btn review-claim" data-id="${x.id}" data-decision="reject">Rechazar</button></div></article>`).join('')||'<p class="acc-empty">No hay solicitudes pendientes.</p>'}</div>`}
  function adminCenters(items){return `<div class="page-actions"><button class="btn btn-primary" id="new-center">Nuevo centro</button></div><div class="table-wrap"><table><thead><tr><th>Centro</th><th>Ubicación</th><th>Especialidades</th><th>Puntos</th><th></th></tr></thead><tbody>${items.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.city||'')} · ${escapeHtml(c.country)}</td><td>${escapeHtml(c.specialties||'')}</td><td>${c.point_count||0}</td><td>${c.has_owner?'':`<button class="btn edit-center" data-id="${c.id}">Editar</button> `}<button class="btn mod-hide-btn" type="button" data-mod-type="center" data-id="${c.id}" data-label="${escapeHtml(c.name)}">Ocultar…</button>${c.has_owner?'<small class="muted" style="display:block">Lo gestiona su titular</small>':''}</td></tr>`).join('')||'<tr><td colspan="5">No hay centros.</td></tr>'}</tbody></table></div>`}
  function adminClients(items){ return `<div class="notice">Clientes que han escaneado el QR del centro o han quedado vinculados por una reserva.</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Cliente</th><th>Email</th><th>Primer check-in</th><th>Último</th></tr></thead><tbody>${items.map(u=>`<tr><td>${escapeHtml(u.fullname)}</td><td>${escapeHtml(u.email)}</td><td>${fmtDate(u.first_checkin)}</td><td>${fmtDate(u.last_checkin)}</td></tr>`).join('')||'<tr><td colspan="4">Todavía no hay clientes asociados.</td></tr>'}</tbody></table></div>` }
  function bindAdmin(tab){ $$('.pa-nav [data-pa-tab]').forEach(b=>b.onclick=()=>$(`.cb-sidebar .cb-nav[data-tab="${b.dataset.paTab}"]`)?.click()); if(tab==='audit') wdBindExports($('#admin-content')); if(tab==='destinations'){ $('#new-destination')?.addEventListener('click',()=>wdGo('#/admin?tab=destinations&edit=nuevo')); $$('.edit-destination').forEach(b=>b.onclick=()=>wdGo('#/admin?tab=destinations&edit='+b.dataset.id)); } if(tab==='points'){ $('#new-point')?.addEventListener('click',()=>wdGo('#/admin?tab=points&edit=nuevo')); $$('.edit-point').forEach(b=>b.onclick=()=>wdGo('#/admin?tab=points&edit='+b.dataset.id)); $$('.propose-point').forEach(b=>b.onclick=()=>wdGo('#/admin?tab=points&proponer='+b.dataset.id)); } if(tab==='centers'){ $('#new-center')?.addEventListener('click',()=>wdGo('#/admin?tab=centers&edit=nuevo')); $$('.edit-center').forEach(b=>b.onclick=()=>wdGo('#/admin?tab=centers&edit='+b.dataset.id)); } if(tab==='bookings'){ $$('.booking-detail').forEach(b=>b.onclick=()=>wdGo('#/reserva?id='+b.dataset.id)); } if(tab==='bookings') $$('.booking-status').forEach(b=>b.onclick=async()=>{try{await postJSON('/api/bookings/'+b.dataset.id+'/status',{status:b.dataset.status});toast('Estado actualizado.');renderAdmin();}catch(e){toast(e.message)}}); if(tab==='experiences') $$('.experience-status').forEach(b=>b.onclick=async()=>{try{await postJSON('/api/admin/travel-experiences/status',{id:+b.dataset.id,status:b.dataset.status});toast('Estado actualizado.');renderAdmin();}catch(e){toast(e.message)}}); if(tab==='users') $('#users-full')?.addEventListener('click',async()=>{ if(await wdAdminGate('confirm')) route(); }); if(tab==='users') $$('.save-role').forEach(b=>b.onclick=async()=>{try{const id=b.dataset.id;const role=document.querySelector('.user-role[data-id="'+id+'"]').value;const centerEl=document.querySelector('.user-center[data-id="'+id+'"]');const center_id=+(centerEl?.value||0)||null;await postJSON('/api/admin/users/role',{user_id:+id,role,center_id});toast('Rol actualizado.');}catch(e){toast(e.message)}});
    if(tab==='users') $$('.close-sessions').forEach(b=>b.onclick=()=>{ // v50.51 (ASVS V7.4.5)
      const {el,close}=wdOpenModal({id:'adm-sess',size:'sm',title:'Cerrar las sesiones de '+escapeHtml(b.dataset.name),body:'<div class="field"><label for="as-reason">Motivo (queda en el registro)</label><input id="as-reason" maxlength="300"></div>',
        footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="as-ok">Cerrar sesiones</button>'});
      $('#as-ok',el).onclick=async()=>{ try{ const r=await postJSON('/api/admin/sessions/close',{user_id:+b.dataset.id,reason:$('#as-reason',el).value}); close(); toast(`Sesiones cerradas: ${r.closed}.`); }catch(e){ toast(e.message); } }; }); if(tab==='suggestions') $$('.review-s').forEach(b=>b.onclick=async()=>{try{await postJSON('/api/admin/suggestions/review',{id:+b.dataset.id,decision:b.dataset.decision});toast('Revisión guardada.');renderAdmin();}catch(e){toast(e.message)}}); $$('.review-claim').forEach(b=>b.onclick=async()=>{ const card=b.closest('[data-claim]'); const link=card?.querySelector('.claim-link'); try{await postJSON('/api/admin/center-claims/review',{id:+b.dataset.id,decision:b.dataset.decision,verification_method:card?.querySelector('.claim-method')?.value||'',verification_note:card?.querySelector('.claim-note')?.value||'',center_id:link?.checked?+link.value:null});toast('Verificación guardada.');renderAdmin();}catch(e){toast(e.message)}}); $$('.review-point').forEach(b=>b.onclick=async()=>{try{await postJSON('/api/admin/dive-points/review',{id:+b.dataset.id,decision:b.dataset.decision});toast('Revisión del punto guardada.');renderAdmin();}catch(e){toast(e.message)}}); if(tab==='suggestions') $$('.review-s[data-decision="reject"]').forEach(b=>b.onclick=async()=>{try{await postJSON('/api/admin/suggestions/review',{id:+b.dataset.id,decision:'reject'});toast('Rechazada.');renderAdmin();}catch(e){toast(e.message)}}); }
  // v50.54: best season, water temperature and visibility of a dive site (all optional; empty = not shown on its page).
  // v50.58 (brief of 16/10, A.1 and A.3): the page of a dive site has every field of the fuller ficha. While the marker
  // moves, the server says whether it falls in the sea and which sites may be the same one; the administration also sees
  // the private register of sources (never shown on the public web).
  const PT_SOURCE_KINDS={centre:'Centro de buceo',wikidata:'Wikidata (CC0)',osm:'OpenStreetMap (ODbL)',official:'Datos oficiales',research:'Investigación propia',admin:'Administración',proposal:'Propuesta aceptada',catalogue:'Catálogo inicial'};
  const PT_SOURCE_FIELDS={'*':'Toda la ficha',name:'Nombre',position:'Posición',depth:'Profundidad',access:'Acceso',current:'Corriente',water_temps:'Temperatura del agua',visibility:'Visibilidad',bottom:'Tipo de fondo',best_months:'Mejor época',species:'Vida marina',warnings:'Avisos',protection:'Protección',description:'Descripción',type:'Tipo',level:'Nivel'};
  const PT_CHECK={ok:['good','Posición comprobada'],warn:['warn','Revisa la posición'],error:['bad','Cae en tierra'],unknown:['muted','Sin datos de costa']};
  function pointCheckHtml(pc,dups,{admin=false}={}){
    const [cls,title]=PT_CHECK[pc?.status]||PT_CHECK.unknown;
    const pos=pc?`<p class="pe-pos is-${cls}">${wdIcon(pc.status==='ok'?'check':pc.status==='error'?'alert':'pin',16)} <b>${escapeHtml(title)}</b> <span>${escapeHtml(pc.note||'')}</span></p>`:'';
    const list=(dups||[]).map(d=>`<li class="is-${d.kind}"><b>${d.kind==='same'?'Parece el mismo punto':'Puede ser el mismo punto'}:</b> <a href="${admin?`#/admin?tab=points&edit=${d.id}`:`#/punto/${d.id}`}">${escapeHtml(d.name)}</a> <span>a ${Number(d.distance_m).toLocaleString(wdLocale())} m</span></li>`).join('');
    return pos+(list?`<div class="pe-dups"><p><b>Posibles duplicados</b> · Antes de crear una ficha nueva, completa la que ya existe.</p><ul>${list}</ul></div>`:'');
  }
  async function editPointForm(id){
    const role=state.me?.user?.role, admin=role==='admin', centre=role==='center';
    let p={name:'',country:'España',region:'',dive_type:'Arrecifes',latitude:38.5,longitude:-0.13,difficulty:'Intermedio',min_depth:'',max_depth:'',description:'',access_info:'',center_id:'',data_status:'verified'}, extra=null;
    if(id){ if(admin){ extra=await api('/api/admin/dive-points/'+id); p=extra.item; } else p=(await api('/api/dive-points/'+id)).item; }
    else if(centre){ p.center_id=state.me.user.center_id; }
    const meta=await loadMeta(); const cs=(await api('/api/centers')).items;
    const lockPos=!!id&&!admin;   // a centre proposes the position of its own site, it never moves it
    const typeDefs=admin?(p.type_fields||[]):(p.type_fields_def||[]), typeVals=admin?Object.fromEntries((p.type_fields||[]).filter(f=>f.value!=null).map(f=>[f.id,f.value])):Object.fromEntries((p.type_data||[]).map(x=>[x.id,x.value]));
    const pc0=p.position_check&&typeof p.position_check==='object'?p.position_check:null;
    // the site's own type stays chosen even when it is not one of the listed types («Arrecife», «Pared»…): before, the
    // first type of the list was chosen and saving changed the type without anyone noticing. Every option carries its
    // Spanish value: with the web in another language the visible text is translated, the saved value is not.
    setApp(`<section class="page pe-page">${wdCrumbs([wdHomeCrumb(),['Puntos de buceo','#/admin?tab=points'],[id?'Editar '+(p.name||'punto'):'Nuevo punto']],'#/admin?tab=points')}<p class="eyebrow">CATÁLOGO</p><h1>${id?'Editar punto':'Nuevo punto'}</h1>
      <p class="lead">Solo datos comprobados: lo que no se sabe con seguridad se deja vacío y no aparece en la ficha.</p>
      ${extra?.duplicates?.length?`<div class="notice warning pe-dupnote"><strong>Posible duplicado</strong><p>${extra.duplicates.map(d=>`<a href="#/admin?tab=points&edit=${d.other_id}">${escapeHtml(d.other_name||'')}</a> (${Number(d.distance_m).toLocaleString(wdLocale())} m)`).join(' · ')}. <a href="#/admin?tab=pointdups">Decidir en «Posibles duplicados»</a></p></div>`:''}
      ${extra?.proposals?`<div class="notice pe-propnote"><strong>${extra.proposals===1?'1 propuesta pendiente':`${extra.proposals} propuestas pendientes`}</strong> <a href="#/admin?tab=pointprops">Revisar las propuestas</a></div>`:''}
      <form id="point-form" class="pe-form" novalidate>
      <fieldset class="pe-sec"><legend>Datos básicos</legend><div class="form-grid">
        <div class="field full"><label for="p-name">Nombre</label><input id="p-name" value="${escapeHtml(p.name)}" required maxlength="180"></div>
        <div class="field"><label for="p-country">País</label><select id="p-country">${meta.countries.map(x=>`<option value="${escapeHtml(x.name)}" ${x.name===p.country?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></div>
        <div class="field"><label for="p-region">Región / referencia</label><input id="p-region" value="${escapeHtml(p.region||'')}" maxlength="120"></div>
        <div class="field"><label for="p-type">Tipo</label><select id="p-type">${p.dive_type&&!meta.types.some(x=>x.name===p.dive_type)?`<option value="${escapeHtml(p.dive_type)}" selected>${escapeHtml(p.dive_type)}</option>`:''}${meta.types.map(x=>`<option value="${escapeHtml(x.name)}" ${x.name===p.dive_type?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></div>
        <div class="field"><label for="p-diff">Dificultad</label><select id="p-diff">${['Iniciación','Intermedio','Avanzado'].map(x=>`<option value="${escapeHtml(x)}" ${p.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div>
        <div class="field"><label for="p-cert">Titulación recomendada</label><select id="p-cert"><option value="">Automática según dificultad/tipo</option>${meta.certifications.map(c=>`<option value="${c.id}" ${String(c.id)===String(p.recommended_certification_id||'')?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div>
        <div class="field"><label for="p-center">Centro asociado</label>${centre?`<input value="${escapeHtml(cs.find(c=>String(c.id)===String(state.me.user.center_id))?.name||'Mi centro')}" disabled><input id="p-center" type="hidden" value="${state.me.user.center_id}">`:`<select id="p-center"><option value="">Sin asignar</option>${cs.map(c=>`<option value="${c.id}" ${String(c.id)===String(p.center_id||'')?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select>`}</div>
      </div></fieldset>
      <fieldset class="pe-sec"><legend>Posición</legend>
        ${lockPos?`<p class="pd-hint">La posición oficial la cambia la administración. <a href="#/admin?tab=points&proponer=${id}">Proponer otra posición</a></p>`:'<p class="pd-hint">Arrastra el marcador o haz clic en el mapa. El punto tiene que caer en el agua; uno de costa, a menos de 200 m de la orilla.</p>'}
        <div class="form-grid"><div class="field"><label for="p-lat">Latitud</label><input id="p-lat" type="number" step="0.000001" value="${p.latitude??''}" ${lockPos?'readonly':''}></div><div class="field"><label for="p-lon">Longitud</label><input id="p-lon" type="number" step="0.000001" value="${p.longitude??''}" ${lockPos?'readonly':''}></div></div>
        <div id="point-editor-map" class="map-card pe-map"></div>
        <div id="pe-check" class="pe-check" aria-live="polite">${pc0?pointCheckHtml(pc0,[],{admin}):''}</div>
      </fieldset>
      <fieldset class="pe-sec"><legend>Datos de la inmersión</legend><div class="form-grid" id="pe-data">${pointDataFields(p,{prefix:'pd',full:true})}</div></fieldset>
      ${typeDefs.length?`<fieldset class="pe-sec"><legend>Datos propios del tipo de inmersión</legend><p class="pd-hint">${escapeHtml(translateString(admin?'Según el tipo del punto. Vacío no se enseña. Los campos de cada tipo se cambian en Administración → Tipos de buceo.':'Lo que escribas aquí lo revisa la administración antes de publicarse.'))}</p><div class="form-grid" id="pe-type">${typeDataFields(typeDefs,typeVals)}</div></fieldset>`:''}
      <fieldset class="pe-sec"><legend>Descripción</legend><div class="form-grid">
        <div class="field full"><label for="p-desc">Descripción</label><textarea id="p-desc" rows="5" placeholder="Con palabras propias. Vacía, la web la escribe a partir de los datos.">${escapeHtml(p.description||'')}</textarea></div>
        <div class="field full"><label for="p-access">Acceso / notas operativas</label><textarea id="p-access" rows="2">${escapeHtml(p.access_info||'')}</textarea></div>
      </div></fieldset>
      ${admin?`<fieldset class="pe-sec"><legend>Estado del dato</legend><div class="form-grid">
        <div class="field"><label for="p-status">Estado</label><select id="p-status"><option value="verified" ${p.data_status!=='pending'?'selected':''}>Verificado</option><option value="pending" ${p.data_status==='pending'?'selected':''}>Pendiente de verificar</option></select></div>
        ${id?'':`<div class="field"><label for="p-src-ref">Fuente</label><input id="p-src-ref" maxlength="500" placeholder="Centro, publicación oficial, enlace…"></div><div class="field"><label for="p-src-date">Comprobado el</label><input id="p-src-date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field full"><label for="p-src-note">Nota de la fuente</label><input id="p-src-note" maxlength="500"></div><p class="pd-hint full">${wdIcon('lock',14)} La fuente es privada: solo la ve la administración.</p>`}
      </div></fieldset>`:''}
      <div id="pe-error" class="pe-error" aria-live="assertive"></div>
      <div class="form-actions"><a class="btn" href="#/admin?tab=points">Cancelar</a><button class="btn btn-primary" type="submit">Guardar punto</button></div></form>
      ${admin&&id?`<section class="pe-sec pe-sources" id="pe-sources"></section>`:''}
      ${id?`<div class="notice mk-notice" style="margin-top:18px"><strong>Vídeos de la ruta y vida marina</strong><div id="marina-point-editor"></div></div><div class="notice" style="margin-top:18px"><strong>Material de apoyo del punto</strong><form id="point-photo-form" data-point-id="${id}" enctype="multipart/form-data" style="margin-top:10px"><div class="field"><label>Imagen</label><input name="file" type="file" accept=".jpg,.jpeg,.png,.webp" required></div><div class="field"><label>Descripción</label><input name="caption"></div><button class="btn" type="submit">Subir fotografía</button></form></div>`:''}</section>`);
    // live check: land or sea, distance to the shore and the sites that may be the same one
    let tmr=0, seq=0;
    const check=()=>{ clearTimeout(tmr); tmr=setTimeout(async()=>{ const la=$('#p-lat')?.value, lo=$('#p-lon')?.value; if(la===''||lo===''||!$('#pe-check')) return; const my=++seq;
      const q=new URLSearchParams({lat:la,lon:lo,name:$('#p-name').value,access:$('#pd-access')?.value||'',type:$('#p-type').value,exclude:String(id||0)});
      try{ const r=await api('/api/admin/dive-points/check?'+q); if(my!==seq) return; $('#pe-check').innerHTML=pointCheckHtml(r.position,r.duplicates,{admin}); translateTree($('#pe-check')); }catch(e){} },350); };
    if(!lockPos){ ['#p-lat','#p-lon','#p-name'].forEach(s=>$(s).addEventListener('input',check)); $('#pd-access')?.addEventListener('change',check); $('#p-type').addEventListener('change',check); check(); }
    const send=async(force={})=>{
      const data={id,name:$('#p-name').value,country:$('#p-country').value,region:$('#p-region').value,dive_type:$('#p-type').value,difficulty:$('#p-diff').value,
        recommended_certification_id:$('#p-cert').value||null,description:$('#p-desc').value,access_info:$('#p-access').value,...readPointData($('#pe-data')),...force};
      if(!lockPos){ data.latitude=+$('#p-lat').value; data.longitude=+$('#p-lon').value; }
      if(!centre) data.center_id=+($('#p-center').value||0)||null; else if(!id) data.center_id=+$('#p-center').value;
      if(admin){ data.data_status=$('#p-status').value; if(!id){ data.source_ref=$('#p-src-ref').value; data.source_checked_at=$('#p-src-date').value; data.source_note=$('#p-src-note').value; } }
      if(!data.name.trim()){ $('#p-name').focus(); throw new Error('Escribe el nombre del punto.'); }
      if(id&&$('#pe-type')) data.type_fields=readTypeData($('#pe-type'));
      if(id){ const r=await postJSON('/api/dive-points/update',data,'POST'); if(r?.note) toast(translateString(r.note)); } else await postJSON('/api/dive-points',data);
    };
    const fail=err=>{ const box=$('#pe-error'); const d=err.data||{};
      // 409: on land, or a site that already exists. The administration can keep it anyway (an inland lake, two sites
      // with the same name that are not the same); a centre corrects it.
      if(err.status===409&&(d.position||d.duplicates)){
        const pos=d.position&&d.position.status==='error', dup=!pos&&(d.duplicates||[]).some(x=>x.kind==='same');
        box.innerHTML=`<div class="notice warning"><strong>${escapeHtml(err.message)}</strong>${d.duplicates?pointCheckHtml(null,d.duplicates,{admin}):''}${admin?`<p><button type="button" class="btn" id="pe-force">${pos?'Está bien así (agua interior u otro caso): guardar igualmente':'Es otro punto: crear igualmente'}</button></p>`:''}</div>`;
        translateTree(box); $('#pe-force')?.addEventListener('click',()=>send(pos?{force_position:true}:{force_new:true}).then(done).catch(fail));
        box.scrollIntoView({block:'center'}); return; }
      box.innerHTML=''; toast(err.message); };
    const done=()=>{ toast('Guardado.'); wdGo('#/admin?tab=points'); };
    $('#point-form').onsubmit=e=>{ e.preventDefault(); $('#pe-error').innerHTML=''; send().then(done).catch(fail); };
    if(id){
      renderMarinaPointEditor('marina-point-editor',id);
      $('#point-photo-form').onsubmit=async e=>{e.preventDefault(); const pid=e.target.dataset.pointId; try{await api('/api/dive-points/'+pid+'/photos',{method:'POST',body:new FormData(e.target)}); toast('Fotografía subida.'); editPointForm(+pid);}catch(err){toast(err.message)}};
      if(admin&&extra) pointSourcesSection($('#pe-sources'),id,extra.sources||[]);
    }
    if($('#point-editor-map')) wdMaps().then(()=>{ if(!window.L||!$('#point-editor-map')) return; const la=+p.latitude||38.5, lo=+p.longitude||-0.13; const emap=(wdTileDefaults(),wdLimitMap(L.map('point-editor-map',{zoomControl:true}))).setView([la,lo],15); wdLayerControl(emap); const mk=L.marker([la,lo],{draggable:!lockPos,icon:pointIcon(p,{active:true}),title:p.name||'Nuevo punto',alt:p.name||'Nuevo punto'}).addTo(emap); if(lockPos) return; const sync=ll=>{ $('#p-lat').value=ll.lat.toFixed(6); $('#p-lon').value=ll.lng.toFixed(6); mk.setLatLng(ll); check(); }; mk.on('dragend',e=>sync(e.target.getLatLng())); emap.on('click',e=>sync(e.latlng)); });
  }
  // B.3: the private register of sources of a site (only the administration: the public web never shows it)
  function pointSourcesSection(host,id,items){
    if(!host) return;
    const paint=list=>{ host.innerHTML=`<h2 class="pe-h">${wdIcon('lock',18)} Registro de fuentes <small>privado</small></h2>
      <p class="pd-hint">De dónde sale cada dato y cuándo se comprobó. Solo lo ve la administración: la web pública no lo enseña nunca (solo la línea de créditos de las licencias abiertas).</p>
      <div class="table-wrap"><table class="pe-src"><thead><tr><th>Dato</th><th>Fuente</th><th>Referencia</th><th>Licencia</th><th>Comprobado</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td>${escapeHtml(PT_SOURCE_FIELDS[s.field]||s.field)}</td><td>${escapeHtml(PT_SOURCE_KINDS[s.kind]||s.kind)}</td><td>${/^https?:\/\//i.test(s.ref||'')?`<a href="${escapeHtml(s.ref)}" target="_blank" rel="noopener noreferrer">${escapeHtml(s.ref)}</a>`:escapeHtml(s.ref||'')}${s.note?`<br><small>${escapeHtml(s.note)}</small>`:''}</td><td>${escapeHtml(s.license||'')}</td><td>${escapeHtml(s.checked_at?fmtDate(s.checked_at):'')}</td><td><button type="button" class="btn btn-sm pe-src-del" data-id="${s.id}">Quitar</button></td></tr>`).join('')||'<tr><td colspan="6">Todavía no hay ninguna fuente anotada.</td></tr>'}</tbody></table></div>
      <form class="pe-src-add form-grid" id="pe-src-add"><div class="field"><label for="ps-field">Dato</label><select id="ps-field">${Object.entries(PT_SOURCE_FIELDS).map(([k,l])=>`<option value="${escapeHtml(k)}">${escapeHtml(l)}</option>`).join('')}</select></div>
        <div class="field"><label for="ps-kind">Fuente</label><select id="ps-kind">${Object.entries(PT_SOURCE_KINDS).filter(([k])=>!['proposal','catalogue'].includes(k)).map(([k,l])=>`<option value="${k}">${escapeHtml(l)}</option>`).join('')}</select></div>
        <div class="field full"><label for="ps-ref">Referencia</label><input id="ps-ref" maxlength="500" placeholder="Enlace, publicación o persona de contacto" required></div>
        <div class="field"><label for="ps-lic">Licencia</label><input id="ps-lic" maxlength="80" placeholder="CC0, ODbL…"></div>
        <div class="field"><label for="ps-date">Comprobado el</label><input id="ps-date" type="date" value="${new Date().toISOString().slice(0,10)}"></div>
        <div class="field full"><label for="ps-note">Nota</label><input id="ps-note" maxlength="500"></div>
        <div class="form-actions full"><button class="btn" type="submit">Añadir fuente</button></div></form>`;
      translateTree(host);
      $('#pe-src-add',host).onsubmit=async e=>{ e.preventDefault(); try{ const r=await postJSON('/api/admin/dive-points/sources',{point_id:id,field:$('#ps-field').value,kind:$('#ps-kind').value,ref:$('#ps-ref').value,license:$('#ps-lic').value,checked_at:$('#ps-date').value,note:$('#ps-note').value}); toast('Fuente añadida.'); paint(r.sources); }catch(err){ toast(err.message); } };
      $$('.pe-src-del',host).forEach(b=>b.onclick=async()=>{ if(!confirm(translateString('¿Quitar esta fuente del registro?'))) return; try{ const r=await postJSON('/api/admin/dive-points/sources/delete',{id:+b.dataset.id}); paint(r.sources); }catch(err){ toast(err.message); } }); };
    paint(items);
  }
  async function editDestinationForm(id){ const meta=await loadMeta(); let t={title:'',region:'',kind:'Viaje',image_path:'',summary:'',description:''}; if(id) t=meta.travel.find(x=>x.id===id)||t; setApp(`<section class="page">${wdCrumbs([wdHomeCrumb(),['Destinos','#/admin?tab=destinations'],[id?'Editar '+(t.title||'destino'):'Nuevo destino']],'#/admin?tab=destinations')}<p class="eyebrow">EXPERIENCIAS</p><h1>${id?'Editar destino':'Nuevo destino'}</h1><form id="destination-form" style="margin-top:28px"><div class="form-grid"><div class="field full"><label>Nombre del destino</label><input id="td-title" value="${escapeHtml(t.title)}" required></div><div class="field"><label>Región / país</label><input id="td-region" value="${escapeHtml(t.region||'')}" required></div><div class="field"><label>Tipo</label><input id="td-kind" value="${escapeHtml(t.kind||'Viaje')}" required></div><div class="field full"><label>Foto del destino</label><div class="td-photo"><div class="td-photo-preview" id="td-photo-preview">${t.image_path?`<img src="${escapeHtml(t.image_path)}" alt="">`:'<span>Sin foto</span>'}</div><div><input id="td-file" type="file" accept="image/jpeg,image/png,image/webp"><small>${IMG_HINT}</small>${t.image_path?'<label class="td-remove"><input type="checkbox" id="td-remove"> Quitar la foto actual</label>':''}</div></div></div><div class="field full"><label>Resumen</label><textarea id="td-summary">${escapeHtml(t.summary||'')}</textarea></div><div class="field full"><label>Descripción</label><textarea id="td-description">${escapeHtml(t.description||'')}</textarea></div></div><div class="form-actions"><a class="btn" href="#/admin?tab=destinations">Cancelar</a><button class="btn btn-primary">Guardar destino</button></div></form></section>`); $('#td-file').onchange=e=>{ const f=e.target.files[0]; if(f) $('#td-photo-preview').innerHTML=`<img src="${URL.createObjectURL(f)}" alt="">`; }; $('#destination-form').onsubmit=async e=>{e.preventDefault();try{const r=await postJSON('/api/admin/travel-offers',{id:id||null,title:$('#td-title').value,region:$('#td-region').value,kind:$('#td-kind').value,summary:$('#td-summary').value,description:$('#td-description').value}); const tid=r.id||id; const f=$('#td-file').files[0]; if(f) await uploadForm('/api/admin/travel-offer-image',{id:tid},f); else if($('#td-remove')?.checked) await uploadForm('/api/admin/travel-offer-image',{id:tid,remove:'1'}); __travel=null; try{ state.meta=null; }catch{} toast('Guardado.');wdGo('#/admin?tab=destinations');}catch(err){toast(err.message)}}; }
  async function editCenterForm(id){ const meta=await loadMeta(); let c={name:'',country:'España',region:'',city:'',address:'',phone:'',email:'',website:'',specialties:'',latitude:38.54,longitude:-0.12,description:'',logo_url:''}; if(id){c=(await api('/api/centers/'+id)).item;} setApp(`<section class="page">${wdCrumbs([wdHomeCrumb(),['Centros','#/admin?tab=centers'],[id?'Editar '+(c.name||'centro'):'Nuevo centro']],'#/admin?tab=centers')}<p class="eyebrow">CENTROS</p><h1>${id?'Editar centro':'Nuevo centro'}</h1><form id="center-form" style="margin-top:28px"><div class="form-grid"><div class="field full"><label>Nombre</label><input id="c-name" value="${escapeHtml(c.name||'')}" required></div><div class="field"><label>País</label><select id="c-country">${meta.countries.map(x=>`<option value="${escapeHtml(x.name)}" ${x.name===c.country?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></div><div class="field"><label>Región</label><input id="c-region" value="${escapeHtml(c.region||'')}"></div><div class="field"><label>Ciudad</label><input id="c-city" value="${escapeHtml(c.city||'')}"></div><div class="field"><label>Dirección</label><input id="c-address" value="${escapeHtml(c.address||'')}"></div><div class="field"><label>Teléfono</label><input id="c-phone" value="${escapeHtml(c.phone||'')}"></div><div class="field"><label>Email</label><input id="c-email" type="email" value="${escapeHtml(c.email||'')}"></div><div class="field"><label>Web</label><input id="c-web" value="${escapeHtml(c.website||'')}"></div><div class="field full"><label>Logo URL</label><input id="c-logo" value="${escapeHtml(c.logo_url||'')}" placeholder="URL del logotipo oficial"></div><div class="field full"><label>Especialidades</label><input id="c-spec" value="${escapeHtml(c.specialties||'')}" placeholder="Cuevas, técnico, sidemount…"></div><div class="field"><label>Latitud</label><input id="c-lat" type="number" step="0.000001" value="${c.latitude||0}"></div><div class="field"><label>Longitud</label><input id="c-lon" type="number" step="0.000001" value="${c.longitude||0}"></div><div class="field full"><label>Descripción</label><textarea id="c-desc">${escapeHtml(c.description||'')}</textarea></div></div><div class="notice" style="margin-top:18px"><strong>Ubicación del centro</strong><br><small>Arrastra el marcador o haz clic en el mapa.</small><div id="center-editor-map" class="map-card" style="height:300px;margin-top:12px"></div></div><div class="form-actions"><a class="btn" href="#/admin?tab=centers">Cancelar</a><button class="btn btn-primary">Guardar centro</button></div></form></section>`); $('#center-form').onsubmit=async e=>{e.preventDefault();try{const data={id:id||null,name:$('#c-name').value,country:$('#c-country').value,region:$('#c-region').value,city:$('#c-city').value,address:$('#c-address').value,phone:$('#c-phone').value,email:$('#c-email').value,website:$('#c-web').value,specialties:$('#c-spec').value,latitude:+$('#c-lat').value,longitude:+$('#c-lon').value,description:$('#c-desc').value,logo_url:$('#c-logo').value};await postJSON(id?'/api/centers/update':'/api/centers',data);toast(id?'Centro actualizado.':'Centro creado.');wdGo('#/admin?tab=centers');}catch(err){toast(err.message)}}; if($('#center-editor-map')) wdMaps().then(()=>{ if(!window.L||!$('#center-editor-map')) return; const cm=(wdTileDefaults(),wdLimitMap(L.map('center-editor-map'))).setView([+$('#c-lat').value||38.54,+$('#c-lon').value||-0.12],13); wdLayerControl(cm); const mk=L.marker([+$('#c-lat').value||38.54,+$('#c-lon').value||-0.12],{draggable:true}).addTo(cm); const sync=ll=>{ $('#c-lat').value=ll.lat.toFixed(6); $('#c-lon').value=ll.lng.toFixed(6); mk.setLatLng(ll); }; mk.on('dragend',e=>sync(e.target.getLatLng())); cm.on('click',e=>sync(e.latlng)); }); }

  async function renderCheckin(code){ const d=await api('/api/me'); setApp(`<section class="page auth"><div class="auth-card"><p class="eyebrow">WORLDIVES DISCOVERY · CHECK-IN</p><h1 style="font-size:42px">Check-in en el centro</h1><p class="lead" style="font-size:15px">Con el check-in, el centro podrá ver tu ficha de buceador (titulación, tallas, contacto de emergencia y documentos) para prepararte la actividad. Puedes dejar de compartirla cuando quieras desde «Mi cuenta».</p>${d.authenticated?`<label class="lg-check" for="checkin-consent"><input type="checkbox" id="checkin-consent"><span id="checkin-consent-text">Compartir mis datos con este centro</span></label><div class="form-actions"><button id="checkin-btn" class="btn btn-primary" type="button" disabled>Compartir mis datos y hacer check-in</button></div>`:`<p class="notice">Primero <a href="#/login?next=/checkin/${code}" style="font-weight:800">inicia sesión</a> o <a href="#/registro?next=/checkin/${code}" style="font-weight:800">crea tu cuenta</a>.</p>`}<div id="checkin-msg" style="margin-top:16px"></div></div></section>`);
    if(!d.authenticated) return;
    // Ask the server who the centre is (it answers 409 + the centre's name until the diver consents).
    try{ await postJSON('/api/checkin/'+code,{}); }catch(e){ if(e.status===409&&e.data?.center_name){ $('#checkin-consent-text').textContent=`Compartir mis datos con ${e.data.center_name}`; } else if(e.status!==409){ toast(e.message); } }
    $('#checkin-consent').onchange=e=>{ $('#checkin-btn').disabled=!e.target.checked; };
    $('#checkin-btn').onclick=async()=>{try{const r=await postJSON('/api/checkin/'+code,{share_consent:$('#checkin-consent').checked});$('#checkin-msg').innerHTML=`<div class="notice"><strong>${escapeHtml(r.center_name)}</strong><br>Check-in hecho. El centro ya puede ver tu ficha de buceador.</div>`;}catch(e){toast(e.message)}}; }
  async function renderPaymentSuccess(params){
    const sid=params.get('session_id')||''; if(!sid){wdGo('#/area');return;}
    if(!state.me){ goLogin(); return; }
    setApp(`<section class="page pay-ok-page"><div class="pay-ok-card is-wait"><div class="pay-ok-spin" aria-hidden="true"></div><h1>Confirmando tu pago…</h1><p>Estamos comprobándolo con el banco. No cierres esta ventana.</p></div></section>`);
    let d=null, tries=0;
    while(tries<6){ try{ d=await api('/api/payments/session/'+encodeURIComponent(sid)); }catch(err){ d={error:err.message}; break; } if(d.payment?.status!=='pending') break; tries++; await new Promise(r=>setTimeout(r,1500)); if(!location.hash.startsWith('#/pago-ok')) return; }
    if(!d||d.error){ setApp(`<section class="page pay-ok-page"><div class="pay-ok-card is-warn"><div class="pay-ok-icon">${wdIcon('alert',30)}</div><h1>No podemos mostrar este pago</h1><p>${escapeHtml(d?.error||'')}</p><p>Si se ha hecho el cargo, lo verás en tu reserva en unos minutos.</p><div class="page-actions"><a class="btn btn-primary" href="#/area">Ir a Mi área</a></div></div></section>`); return; }
    const p=d.payment, esc=escapeHtml, paid=p.status==='paid';
    const when=p.paid_at?new Date(p.paid_at).toLocaleString(wdLocale(),{dateStyle:'long',timeStyle:'short'}):'';
    const card=p.card_last4?`${CARD_BRANDS[p.card_brand]||esc(p.card_brand||'Tarjeta')} ···· ${esc(p.card_last4)}`:'Tarjeta';
    const head=paid?`<div class="pay-ok-icon">${wdIcon('check',34)}</div><p class="eyebrow">PAGO COMPLETADO</p><h1>¡Reserva confirmada!</h1><p class="lead">Hemos recibido tu pago y tu plaza está asegurada. Te hemos dejado el justificante en tu reserva.</p>`
      :p.status==='review'?`<div class="pay-ok-icon is-warn">${wdIcon('alert',30)}</div><p class="eyebrow">PAGO EN REVISIÓN</p><h1>Estamos revisando tu pago</h1><p class="lead">El importe recibido no coincide con la reserva. No pagues otra vez: te escribiremos en breve.</p>`
      :`<div class="pay-ok-icon is-warn">${wdIcon('clock',30)}</div><p class="eyebrow">PAGO PENDIENTE</p><h1>Todavía no tenemos la confirmación</h1><p class="lead">Algunos bancos tardan unos minutos. Te avisaremos en cuanto llegue; no hace falta que pagues de nuevo.</p>`;
    setApp(`<section class="page pay-ok-page"><div class="pay-ok-card ${paid?'is-ok':'is-warn'}">${head}
      <div class="pay-ok-ticket"><div class="pay-ok-row"><span>Actividad</span><strong>${esc(p.service_title||'Reserva')}</strong></div><div class="pay-ok-row"><span>Centro</span><strong>${esc(p.center_name||'—')}</strong></div>
        ${p.booking_date?`<div class="pay-ok-row"><span>Fecha</span><strong>${esc(wdLongDay?wdLongDay(p.booking_date):p.booking_date)}${p.booking_time?' · '+esc(p.booking_time):''}</strong></div>`:''}${p.participants?`<div class="pay-ok-row"><span>Buceadores</span><strong>${esc(p.participants)}</strong></div>`:''}
        <div class="pay-ok-row is-total"><span>Importe</span><strong>${wdMoney(p.amount_received||p.amount,p.currency)}</strong></div>
        ${paid?`<div class="pay-ok-row"><span>Pagado con</span><strong>${card}</strong></div>${when?`<div class="pay-ok-row"><span>Fecha del pago</span><strong>${esc(when)}</strong></div>`:''}`:''}${p.booking_ref?`<div class="pay-ok-row"><span>Nº de reserva</span><strong>${esc(p.booking_ref)}</strong></div>`:''}<div class="pay-ok-row"><span>Ref. del pago</span><strong>${esc(p.reference||'')}</strong></div></div>
      <div class="page-actions">${p.booking_id?`<a class="btn btn-primary" href="#/reserva?id=${p.booking_id}">Ver mi reserva y el QR</a><a class="btn" href="/api/bookings/${p.booking_id}/receipt.pdf" target="_blank" rel="noopener">${wdIcon('download',15)} Justificante PDF</a>`:''}${p.receipt_url?`<a class="btn" href="${esc(p.receipt_url)}" target="_blank" rel="noopener">Recibo de Stripe</a>`:''}<a class="btn" href="#/area">Mi área</a></div>
      <p class="pay-ok-foot">${wdIcon('lock',14)} Pago procesado por Stripe. WORLDIVES no guarda los datos de tu tarjeta.</p></div></section>`);
  }

  // ---------------------------------------------------------------- v50.30 · Legal, cookies, password recovery
  let LEGAL_INFO=null;
  async function legalInfo(){ if(!LEGAL_INFO){ try{ LEGAL_INFO=await api('/api/legal/info'); }catch{ LEGAL_INFO={version:'',docs:{},owner:{},reasons:{}}; } } return LEGAL_INFO; }
  // Small, safe Markdown renderer for the legal documents (headings, lists, tables, quotes, bold, links).
  function wdMd(md){
    const esc=escapeHtml; const slug=s=>wdFold?wdFold(s).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''):s;
    const inline=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
      .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g,(m,txt,url)=>{ const safe=/^(#\/|https?:\/\/|mailto:)/.test(url)?url:'#'; return `<a href="${safe}"${/^https?:/.test(safe)?' target="_blank" rel="noopener"':''}>${txt}</a>`; })
      .replace(/(^|[\s(])(www\.[a-z0-9.-]+\.[a-z]{2,})/gi,'$1<a href="https://$2" target="_blank" rel="noopener">$2</a>')
      .replace(/\[(pendiente de completar|to be completed)\]/g,'<mark class="lg-pending">$1</mark>');
    const out=[]; let list=null, para=[], table=null, first=true;
    const flushP=()=>{ if(para.length){ out.push('<p>'+inline(para.join(' '))+'</p>'); para=[]; } };
    const flushL=()=>{ if(list){ out.push(`<${list.t}>`+list.items.map(i=>'<li>'+inline(i)+'</li>').join('')+`</${list.t}>`); list=null; } };
    const cells=r=>r.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
    const flushT=()=>{ if(table){ const rows=table.filter(r=>!/^\|?\s*:?-{2,}/.test(r.trim())); const [h,...body]=rows;
      const head=cells(h), label=i=>esc(String(head[i]||'').replace(/\*\*/g,''));   // v50.46: each cell knows its column (cards on phones)
      out.push('<div class="lg-table"><table><thead><tr>'+head.map(c=>'<th scope="col">'+inline(c)+'</th>').join('')+'</tr></thead><tbody>'+body.map(r=>'<tr>'+cells(r).map((c,i)=>`<td data-label="${label(i)}">`+inline(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'); table=null; } };
    const flush=()=>{ flushP(); flushL(); flushT(); };
    for(const raw of String(md||'').replace(/\r/g,'').split('\n')){ const l=raw.trimEnd(); let m;
      if(!l.trim()){ flush(); continue; }
      if(l.trim().startsWith('|')){ flushP(); flushL(); (table??=[]).push(l); continue; } flushT();
      if((m=l.match(/^(#{1,3})\s+(.*)$/))){ flush(); if(m[1].length===1&&first){ first=false; continue; } const n=Math.min(3,m[1].length); out.push(`<h${n} id="${slug(m[2])}">${inline(m[2])}</h${n}>`); continue; }
      if((m=l.match(/^\s*[-*]\s+(.*)$/))){ flushP(); if(list?.t!=='ul'){ flushL(); list={t:'ul',items:[]}; } list.items.push(m[1]); continue; }
      if((m=l.match(/^\s*\d+\.\s+(.*)$/))){ flushP(); if(list?.t!=='ol'){ flushL(); list={t:'ol',items:[]}; } list.items.push(m[1]); continue; }
      if((m=l.match(/^>\s?(.*)$/))){ flush(); out.push('<blockquote>'+inline(m[1])+'</blockquote>'); continue; }
      flushL(); para.push(l.trim());
    }
    flush(); return out.join('\n');
  }
  async function renderLegal(slug){
    slug=slug||'aviso-legal'; const esc=escapeHtml; const qs=new URLSearchParams(location.hash.split('?')[1]||'');
    let doc, info;
    try{ [doc,info]=await Promise.all([api('/api/legal/doc?slug='+encodeURIComponent(slug)+'&lang='+currentLanguage()),legalInfo()]); }
    catch(e){ setApp(`<section class="page"><div class="empty"><h2>Documento no encontrado</h2><p>Consulta el resto de la información legal.</p><a class="btn btn-primary" href="#/legal/aviso-legal">Aviso legal</a></div></section>`); return; }
    const route=doc.route||slug, toc=[...String(doc.markdown).matchAll(/^##\s+(.*)$/gm)].map(m=>m[1]);
    const slugOf=s=>wdFold(s).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
    const up=doc.upcoming;
    setApp(`<section class="lg-page">
      <header class="lg-hero"><div class="lg-hero-in"><p class="eyebrow">${wdIcon('file',14)} Información legal</p><h1 translate="no">${esc(doc.title)}</h1>
        <p class="lg-meta">Versión vigente: <span translate="no">${esc(doc.version)}</span> · En vigor desde el <span translate="no">${esc(wdLegalDate(doc.effective_at))}</span></p></div></header>
      <div class="lg-wrap">
        <nav class="lg-nav" aria-label="Documentos legales"><p class="lg-nav-t">Documentos</p>${Object.entries(info.docs||{}).map(([k,v])=>`<a href="#/legal/${k}" ${k===route?'aria-current="page"':''}>${esc(v)}</a>`).join('')}</nav>
        <div class="lg-main">
          ${doc.prevails_note?`<div class="notice lg-prevails" translate="no" lang="${esc(doc.lang)}">${wdIcon('info',16)} ${esc(doc.prevails_note)}</div>`:''}
          ${doc.lang!==currentLanguage()&&!doc.prevails_note?`<div class="notice lg-prevails">${wdIcon('info',16)} Este documento todavía no está traducido a tu idioma. Se muestra la versión oficial.</div>`:''}
          ${up?`<div class="notice warning lg-upcoming" id="lg-upcoming"><strong>Nueva versión anunciada.</strong> Entra en vigor el <span translate="no">${esc(wdLegalDate(up.effective_at))}</span>.${up.summary?` <span translate="no">${esc(up.summary)}</span>`:''} <button type="button" class="btn-link" id="lg-up-read">Leer la nueva versión</button></div>`:''}
          <article class="lg-doc" translate="no" lang="${esc(doc.lang)}">${wdMd(doc.markdown)}${slug==='denuncias'?'<div id="lg-report"></div>':''}${slug==='contacto'?'<div id="lg-contact"></div>':''}</article>
          <section class="lg-history" aria-labelledby="lg-hist-t"><h2 id="lg-hist-t">Versiones de este documento</h2><div id="lg-hist"><p class="muted">Cargando…</p></div></section>
        </div>
        <aside class="lg-side">${toc.length>2?`<div class="lg-toc"><p class="lg-nav-t">En esta página</p>${toc.map(h=>`<a href="#${slugOf(h)}" data-to="${slugOf(h)}" translate="no">${esc(h)}</a>`).join('')}</div>`:''}
          <div class="lg-actions"><button type="button" class="btn" id="lg-print">${wdIcon('download',15)} Imprimir o guardar en PDF</button><a class="btn" href="#/legal/denuncias">${wdIcon('alert',15)} Denunciar contenido</a></div></aside>
      </div></section>`);
    $('#lg-print').onclick=()=>window.print();
    $$('.lg-toc a').forEach(a=>a.onclick=e=>{ e.preventDefault(); const t=document.getElementById(a.dataset.to); if(t){ t.setAttribute('tabindex','-1'); t.scrollIntoView({behavior:'smooth',block:'start'}); t.focus({preventScroll:true}); } });
    if(slug==='denuncias') renderReportForm($('#lg-report'),info,qs.get('url')||'');
    if(slug==='contacto') renderContactForm($('#lg-contact'),qs.get('asunto')||'');
    let hist=[]; try{ hist=(await api('/api/legal/history?slug='+encodeURIComponent(doc.slug))).items||[]; }catch{}
    const hm=$('#lg-hist'); if(!hm) return;
    hm.innerHTML=hist.length?`<ul class="lg-hist-list">${hist.map(h=>`<li><div><b translate="no">${esc(h.version)}</b> · <span>${h.effective_at>new Date().toISOString().slice(0,10)?'Entra en vigor el':'En vigor desde el'}</span> <span translate="no">${esc(wdLegalDate(h.effective_at))}</span>${h.version===doc.version?' <span class="status good">Vigente</span>':''}${h.summary?`<p translate="no">${esc(h.summary)}</p>`:''}</div><button type="button" class="btn" data-ver="${h.id}">Leer</button></li>`).join('')}</ul>`:'<p class="muted">Esta es la primera versión.</p>';
    translateTree(hm);
    $$('[data-ver]',hm).forEach(b=>b.onclick=()=>openLegalVersion(+b.dataset.ver));
    const upRow=up&&hist.find(h=>h.version===up.version); if(upRow&&$('#lg-up-read')) $('#lg-up-read').onclick=()=>openLegalVersion(upRow.id);
    else $('#lg-up-read')?.remove();
  }
  function wdLegalDate(d){ if(!d) return ''; try{ return new Date(String(d).slice(0,10)+'T12:00:00').toLocaleDateString(currentLanguage(),{day:'numeric',month:'long',year:'numeric'}); }catch{ return String(d).slice(0,10); } }
  async function openLegalVersion(id){
    let v; try{ v=await api('/api/legal/version?id='+id); }catch(err){ toast(err.message); return; }
    const text=String(v.markdown);
    wdOpenModal({id:'legal-version',size:'lg',title:escapeHtml(v.title),subtitle:`Versión ${escapeHtml(v.version)} · ${escapeHtml(wdLegalDate(v.effective_at))}`,
      body:`<article class="lg-doc" translate="no" lang="${escapeHtml(v.lang)}">${wdMd(text)}</article>`,footer:'<button type="button" class="btn" data-modal-close>Cerrar</button>'});
  }
  // A new version in force of a document the user must accept: one window asks for it (once per visit if postponed).
  function legalAcceptGate(){
    const pend=state.me?.legal?.pending||[]; if(!pend.length||$('#legal-accept')) return;
    if((location.hash||'').startsWith('#/legal/')) return;
    try{ if(sessionStorage.getItem('wd_legal_later')===pend.map(p=>p.slug+p.version).join(',')) return; }catch{}
    const esc=escapeHtml;
    const {el,close}=wdOpenModal({id:'legal-accept',title:'Hemos actualizado nuestras condiciones',subtitle:'Para seguir usando tu cuenta, revisa y acepta las nuevas versiones.',
      body:`<ul class="lg-accept-list">${pend.map(p=>`<li>${wdIcon('file',16)} <a href="#/legal/${esc(p.route)}" target="_blank" rel="noopener">${esc(p.title)}</a> <small>· versión <span translate="no">${esc(p.version)}</span></small></li>`).join('')}</ul>
        <label class="lg-check"><input type="checkbox" id="la-ok"> <span>He leído y acepto estas versiones.</span></label>`,
      footer:'<button type="button" class="btn" id="la-later">Más tarde</button><button type="button" class="btn btn-primary" id="la-accept" disabled>Aceptar</button>'});
    translateTree(el);
    $('#la-ok',el).onchange=e=>{ $('#la-accept',el).disabled=!e.target.checked; };
    $('#la-later',el).onclick=()=>{ try{ sessionStorage.setItem('wd_legal_later',pend.map(p=>p.slug+p.version).join(',')); }catch{} close(); };
    $('#la-accept',el).onclick=async()=>{ try{ const r=await postJSON('/api/legal/accept',{docs:pend.map(p=>p.slug)}); if(state.me) state.me.legal={pending:r.pending,upcoming:r.upcoming}; close(); toast('Gracias. Condiciones aceptadas.'); }catch(err){ toast(err.message); } };
  }
  function renderReportForm(mount,info,url){
    if(!mount) return; const me=state.me?.user; const esc=escapeHtml;
    mount.innerHTML=`<form class="lg-form" id="report-form" translate="yes"><h2>Formulario de denuncia</h2>
      <div class="form-grid">
        <div class="field full"><label for="rp-reason">Motivo</label><select id="rp-reason" required><option value="">Elige un motivo…</option>${Object.entries(info.reasons||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div>
        <div class="field full"><label for="rp-url">Dirección (URL) del contenido</label><input id="rp-url" type="url" placeholder="https://…" value="${esc(url)}"><small>Abre la página del contenido y copia la dirección de la barra del navegador.</small></div>
        <div class="field full"><label for="rp-details">Explica por qué es ilegal o incumple las condiciones</label><textarea id="rp-details" minlength="20" maxlength="3000" required rows="5"></textarea></div>
        <div class="field"><label for="rp-name">Tu nombre</label><input id="rp-name" minlength="2" maxlength="120" required autocomplete="name" value="${esc(me?.fullname||'')}"></div>
        <div class="field"><label for="rp-email">Tu email</label><input id="rp-email" type="email" maxlength="160" required autocomplete="email" value="${esc(me?.email&&!/\.local$/.test(me.email)?me.email:'')}"></div>
        <label class="lg-check full"><input type="checkbox" id="rp-faith" required><span>Declaro que la información de esta denuncia es exacta y completa, y que la envío de buena fe.</span></label>
      </div><div class="form-actions"><button class="btn btn-primary" type="submit">Enviar denuncia</button></div></form>`;
    $('#report-form').onsubmit=async e=>{ e.preventDefault(); const btn=e.submitter||$('#report-form button[type=submit]'); btn.disabled=true;
      try{ const r=await postJSON('/api/reports',{reason:$('#rp-reason').value,target_url:$('#rp-url').value,details:$('#rp-details').value,name:$('#rp-name').value,email:$('#rp-email').value,lang:currentLanguage(),good_faith:$('#rp-faith').checked});
        mount.innerHTML=`<div class="lg-done">${wdIcon('check',22)}<div><h2>Denuncia recibida</h2><p>Referencia <b>${esc(r.ref)}</b>. La revisaremos con diligencia${$('#rp-email')?.value?' y te escribiremos con la decisión':''}. Gracias por ayudarnos.</p></div></div>`; translateTree(mount);
      }catch(err){ toast(err.message); btn.disabled=false; } };
  }
  // «Contacto» form (v50.46): same fields, labels, button and messages as the rest of the site.
  const CONTACT_TOPICS={web:'Dudas sobre la web o tu cuenta',booking:'Un problema con una reserva',privacy:'Protección de datos y tus derechos',accessibility:'Accesibilidad',center:'Centros que quieren unirse',other:'Otro asunto'};
  function renderContactForm(mount,topic){
    if(!mount) return; const me=state.me?.user; const esc=escapeHtml;
    mount.innerHTML=`<form class="lg-form" id="contact-form" translate="yes" novalidate><h2>Escríbenos</h2>
      <p class="lg-form-alt"><span>¿Quieres denunciar un contenido?</span> <a href="#/legal/denuncias">Ve a «Denunciar contenido»</a></p>
      <div class="form-grid">
        <div class="field full"><label for="ct-topic">Asunto</label><select id="ct-topic" required><option value="">Elige un asunto…</option>${Object.entries(CONTACT_TOPICS).map(([k,v])=>`<option value="${k}" ${k===topic?'selected':''}>${esc(v)}</option>`).join('')}</select></div>
        <div class="field full" id="ct-ref-f" hidden><label for="ct-ref">Número de reserva (si lo tienes)</label><input id="ct-ref" maxlength="40" placeholder="WOD-…" autocapitalize="characters"></div>
        <div class="field"><label for="ct-name">Tu nombre</label><input id="ct-name" minlength="2" maxlength="120" required autocomplete="name" value="${esc(me?.fullname||'')}"></div>
        <div class="field"><label for="ct-email">Tu email</label><input id="ct-email" type="email" maxlength="160" required autocomplete="email" value="${esc(me?.email&&!/\.local$/.test(me.email)?me.email:'')}"></div>
        <div class="field full"><label for="ct-msg">Mensaje</label><textarea id="ct-msg" minlength="10" maxlength="4000" required rows="6"></textarea></div>
        <label class="lg-check full"><input type="checkbox" id="ct-privacy" required><span><span>Acepto que WORLDIVES use estos datos solo para responderme.</span> <a href="#/legal/privacidad" target="_blank" rel="noopener">Política de privacidad</a></span></label>
      </div><div class="form-actions"><button class="btn btn-primary" type="submit">Enviar mensaje</button></div></form>`;
    const sync=()=>{ $('#ct-ref-f').hidden=$('#ct-topic').value!=='booking'; }; $('#ct-topic').onchange=sync; sync();
    $('#contact-form').onsubmit=async e=>{ e.preventDefault(); const f=e.target; if(!f.reportValidity()) return; const btn=$('#contact-form button[type=submit]'); btn.disabled=true;
      try{ const r=await postJSON('/api/contact',{topic:$('#ct-topic').value,booking_ref:$('#ct-ref').value,name:$('#ct-name').value,email:$('#ct-email').value,message:$('#ct-msg').value,privacy:$('#ct-privacy').checked,lang:currentLanguage()});
        mount.innerHTML=`<div class="lg-done" role="status">${wdIcon('check',22)}<div><h2>Mensaje enviado</h2><p>Te responderemos por email, normalmente en menos de 48 horas en días laborables.</p><p><span>Referencia:</span> <b translate="no">${esc(r.ref)}</b></p></div></div>`; translateTree(mount);
      }catch(err){ toast(err.message); btn.disabled=false; } };
    translateTree(mount);
  }
  // Accessibility (v50.36): every <label> is tied to its field. Labels written without «for» (about a hundred in the
  // panels) are linked at render time to the only control of their field; controls without any label get the
  // placeholder or the nearby text as their accessible name.
  let wdLabelSeq=0;
  function wdLinkLabels(root){
    if(!root?.querySelectorAll) return;
    root.querySelectorAll('label:not([for])').forEach(l=>{ if(l.querySelector('input,select,textarea')) return;
      let c=l.nextElementSibling; if(!(c&&c.matches('input,select,textarea'))){ const box=l.closest('.field,.svc-field,.bk-field,.form-row,.cd-field'); const all=box?box.querySelectorAll('input:not([type=hidden]),select,textarea'):[]; c=all.length===1?all[0]:null; }
      if(!c) return; if(!c.id) c.id='wdf-'+(++wdLabelSeq); l.htmlFor=c.id; });
    root.querySelectorAll('input:not([type=hidden]):not([aria-label]):not([aria-labelledby]),select:not([aria-label]):not([aria-labelledby]),textarea:not([aria-label]):not([aria-labelledby])').forEach(c=>{
      if(c.closest('label')||(c.id&&root.querySelector(`label[for="${CSS.escape(c.id)}"]`))||(c.id&&document.querySelector(`label[for="${CSS.escape(c.id)}"]`))) return;
      const name=c.getAttribute('placeholder')||c.getAttribute('title'); if(name) c.setAttribute('aria-label',name); });
  }
  try{ let t=null; new MutationObserver(()=>{ clearTimeout(t); t=setTimeout(()=>wdLinkLabels(document.body),60); }).observe(document.documentElement,{childList:true,subtree:true}); }catch{}
  // Maintenance or incident banner (Administración → Operación).
  function siteBanner(){ const b=state.meta?.banner; $('#site-banner')?.remove(); if(!b) return;
    document.body.insertAdjacentHTML('afterbegin',`<div class="site-banner is-${escapeHtml(b.level||'info')}" id="site-banner" role="status">${wdIcon(b.level==='incident'?'alert':'info',16)} <span>${escapeHtml(b.text)}</span></div>`);
    translateTree($('#site-banner')); }
  // Administración → Funciones: what is switched off disappears from menus and pages (the server refuses it too).
  function applyFeatureSwitches(){ const f=state.meta?.features||{}; Object.keys(f).forEach(k=>document.body.classList.toggle('feat-off-'+k,f[k]===false)); }
  // Demo deployments (WOD_DEMO_MODE=1): a fixed ribbon on every page.
  async function demoRibbon(){ const sent=$('#demo-ribbon'); if(sent){ document.body.classList.add('is-demo'); translateTree(sent); return; }   // v50.53: the server already puts it in the page
    let st; try{ st=await api('/api/setup/status'); }catch{ return; } if(!st.demo||$('#demo-ribbon')) return;
    document.body.classList.add('is-demo');
    document.body.insertAdjacentHTML('afterbegin','<div class="demo-ribbon" id="demo-ribbon" role="note"><strong>Versión de demostración</strong> <span>Centros, personas y reservas inventados. Pagos de prueba; los correos no salen.</span></div>');
    translateTree($('#demo-ribbon')); }
  // Footer: the owner's identification (LSSI-CE art. 10) as soon as it is filled in at Administración → Legal.
  async function footerOwner(){ const el=$('#footer-owner'); if(!el) return; const o=(await legalInfo()).owner||{};
    const parts=[o.owner_name,o.nif&&('NIF '+o.nif),o.address,o.email].filter(Boolean); if(!parts.length) return;
    el.setAttribute('translate','no'); el.textContent=`© ${new Date().getFullYear()} ${o.trade_name||'WORLDIVES DISCOVERY'} · ${parts.join(' · ')}`; }
  function cookieNotice(){
    let seen=null; try{ seen=Number(localStorage.getItem('wd_cookie_notice')||0); }catch{ return; }
    if(seen&&Date.now()-seen<365*864e5) return; if($('#ck-bar')) return;
    document.body.insertAdjacentHTML('beforeend',`<div class="ck-bar" id="ck-bar" role="region" aria-label="Aviso de cookies"><p>${wdIcon('shield',16)}<span>Solo usamos cookies técnicas, necesarias para que la web funcione (por ejemplo, para mantener tu sesión). No usamos cookies de publicidad ni de analítica. <a href="#/legal/cookies">Más información</a></span></p><button type="button" class="btn btn-primary" id="ck-ok">Entendido</button></div>`);
    $('#ck-ok').onclick=()=>{ try{ localStorage.setItem('wd_cookie_notice',String(Date.now())); }catch{} $('#ck-bar')?.remove(); };
    translateTree($('#ck-bar'));
  }
  // Link from the «Confirma la eliminación de tu cuenta» email.
  function renderConfirmDeletion(params){
    const token=params?.get?.('token')||new URLSearchParams(location.hash.split('?')[1]||'').get('token')||'';
    setApp(authCard('Eliminar mi cuenta',token?`<div class="cx-summary is-late">${wdIcon('alert',20)}<p>Al confirmar borraremos tu ficha, tus documentos, tu Log Book y tus puntos. Las reservas y los pagos se conservan sin tu nombre el tiempo que exige la ley. No se puede deshacer.</p></div>
      <p><a href="/api/account/export?format=zip" download>Descarga antes una copia de tus datos</a> (necesitas haber iniciado sesión).</p>
      <div class="form-actions"><a class="btn" href="#/">Cancelar</a><button class="btn danger" type="button" id="cd-ok">Eliminar definitivamente</button></div>`
      :`<div class="notice warning">El enlace no es válido.</div>`));
    $('#cd-ok')?.addEventListener('click',async e=>{ e.target.disabled=true;
      try{ await postJSON('/api/account/delete/confirm',{token}); state.me=null; renderAccount(); setApp(authCard('Cuenta eliminada','<p class="lead" style="font-size:15px">Hemos eliminado tu cuenta y tus datos personales. Gracias por haber buceado con nosotros.</p><div class="form-actions"><a class="btn btn-primary" href="#/">Ir al inicio</a></div>')); }
      catch(err){ toast(err.message); e.target.disabled=false; } });
  }
  async function renderForgot(){
    setApp(authCard('¿Has olvidado tu contraseña?',`<p class="lead" style="font-size:15px">Escribe el email de tu cuenta y te enviaremos un enlace para elegir una contraseña nueva.</p>
      <form id="forgot-form"><div class="field"><label for="fg-email">Email o usuario</label><input id="fg-email" required autocomplete="email"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Enviar enlace</button></div></form>
      <p style="margin-top:18px;font-size:13px;color:var(--muted)"><a href="#/login" style="color:var(--sea);font-weight:800">Volver a iniciar sesión</a></p>`));
    $('#forgot-form').onsubmit=async e=>{ e.preventDefault(); const b=$('#forgot-form button'); b.disabled=true;
      try{ await postJSON('/api/auth/forgot',{email:$('#fg-email').value}); $('#forgot-form').outerHTML=`<div class="notice good" style="margin-top:6px"><strong>Revisa tu correo.</strong><p style="margin:6px 0 0">Si existe una cuenta con esos datos, te hemos enviado un enlace para cambiar la contraseña. Caduca en 1 hora. Mira también en la carpeta de spam.</p></div>`; translateTree($('#app')); }
      catch(err){ toast(err.message); b.disabled=false; } };
  }
  async function renderReset(params){
    const token=params?.get?.('token')||'';
    setApp(authCard('Elige una contraseña nueva',token?`<form id="reset-form"><div class="field"><label for="rs-1">Nueva contraseña</label><input id="rs-1" type="password" minlength="10" required autocomplete="new-password"><small>Mínimo 10 caracteres.</small></div><div class="field"><label for="rs-2">Repite la contraseña</label><input id="rs-2" type="password" minlength="10" required autocomplete="new-password"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Guardar contraseña</button></div></form>`
      :`<div class="notice warning">El enlace no es válido. <a href="#/recuperar">Pide uno nuevo</a>.</div>`));
    $('#reset-form')?.addEventListener('submit',async e=>{ e.preventDefault(); if($('#rs-1').value!==$('#rs-2').value){ toast('Las contraseñas no coinciden.'); return; }
      try{ await postJSON('/api/auth/reset',{token,password:$('#rs-1').value}); toast('Contraseña cambiada. Ya puedes iniciar sesión.'); wdGo('#/login'); }catch(err){ toast(err.message); } });
  }
  // Centres and professionals: the terms for centres change with 15 days of notice. The banner announces the new
  // version (with its summary) and lets them accept it now; a version already in force is asked in legalAcceptGate.
  async function proTermsBanner(user){
    if(!user||!['center','freelance'].includes(user.role)) return; const esc=escapeHtml;
    const lg=state.me?.legal||{}; const up=(lg.upcoming||[]).find(u=>u.slug==='centros'); const pend=(lg.pending||[]).find(p=>p.slug==='centros');
    if(!up&&!pend) return;
    const host=$('#app .cb-main')||$('#app > section'); if(!host||$('#pro-terms-bar')) return;
    const msg=pend?`<strong>Condiciones para centros y profesionales</strong> Hay una nueva versión en vigor (<span translate="no">${esc(pend.version)}</span>). Revísala y acéptala para seguir publicando.`
      :`<strong>Cambios en las condiciones para centros</strong> La nueva versión entra en vigor el <span translate="no">${esc(wdLegalDate(up.effective_at))}</span>.${up.summary?` <span translate="no">${esc(up.summary)}</span>`:''} Si no estás de acuerdo, puedes darte de baja antes de esa fecha.`;
    host.insertAdjacentHTML('afterbegin',`<div class="pro-terms-bar" id="pro-terms-bar" role="status">${wdIcon('file',18)}<p>${msg}</p><a class="btn" href="#/legal/condiciones-centros" target="_blank" rel="noopener">Leer</a><button type="button" class="btn btn-primary" id="pro-terms-ok">Aceptar</button></div>`);
    translateTree($('#pro-terms-bar'));
    $('#pro-terms-ok').onclick=async()=>{ try{ const r=await postJSON('/api/legal/accept',{docs:['centros'],upcoming:!pend}); if(state.me) state.me.legal={pending:r.pending,upcoming:r.upcoming}; $('#pro-terms-bar').remove(); toast('Condiciones aceptadas.'); }catch(err){ toast(err.message); } };
  }

  // ---------------------------------------------------------------- v50.30 · Cancelling a booking
  // v50.55: a booking paid in person to the professional: the published price, the notice, the professional's policy
  // and, once he has accepted, «Hablar por WhatsApp». For the professional, his private marks.
  function inPersonBookingCard(b,own){ const esc=escapeHtml, live=!['cancelled','rejected','expired'].includes(b.status);
    const pdf=`<a class="btn" href="/api/bookings/${b.id}/receipt.pdf" target="_blank" rel="noopener">${wdIcon('download',15)} Justificante PDF</a>`;
    return `<section class="pay-card is-person"><div class="pay-card-icon">${wdIcon('wallet',22)}</div><div class="pay-card-main"><p class="eyebrow">${esc(translateString('Pago en persona al profesional').toUpperCase())}</p>
      <h3>${esc(translateString('Precio publicado'))} · ${esc(wdMoney(b.price,b.currency))}</h3>
      ${wdInPersonBox(b,{ack:false})}
      ${live&&own?(b.pro_whatsapp?`<p>${esc(translateString('Acuerda con el profesional la forma de pago y los detalles.'))}</p>`:b.status==='requested'?`<p class="muted">${esc(translateString('El botón «Hablar por WhatsApp» aparece cuando el profesional acepta tu solicitud.'))}</p>`:''):''}
      ${wdProPolicy(b)}
      <div class="page-actions">${live&&own?wdWhatsAppBtn(b.pro_whatsapp):''}${pdf}</div></div></section>`; }
  function proMarkCard(b){ if(!wdInPerson(b)||!['confirmed','completed'].includes(b.status)) return ''; const esc=escapeHtml;
    return `<section class="pay-card is-person pro-mark" id="pro-mark"><div class="pay-card-icon">${wdIcon('check',22)}</div><div class="pay-card-main"><p class="eyebrow">${esc(translateString('SOLO PARA TU CONTROL'))}</p>
      <h3>${esc(translateString(b.pro_mark?WD_PRO_MARKS[b.pro_mark]:'Sin marcar'))}</h3><p class="muted">${esc(translateString('El cliente no ve esta marca y no mueve dinero.'))}</p>
      <div class="page-actions">${Object.entries(WD_PRO_MARKS).map(([k,l])=>`<button type="button" class="btn ${b.pro_mark===k?'btn-primary':''}" data-pro-mark="${k}" aria-pressed="${b.pro_mark===k}">${esc(translateString(l))}</button>`).join('')}${b.pro_mark?`<button type="button" class="btn" data-pro-mark="">${esc(translateString('Quitar la marca'))}</button>`:''}</div></div></section>`; }
  function bindProMark(b,id,again){ $$('[data-pro-mark]').forEach(x=>x.onclick=async()=>{ x.disabled=true; try{ const r=await postJSON('/api/pro-mark',{kind:'booking',id,mark:x.dataset.proMark}); toast(r.mark?translateString(WD_PRO_MARKS[r.mark])+'.':translateString('Marca quitada.')); again(); }catch(err){ toast(err.message); x.disabled=false; } }); }
  function bookingCancelCard(b){
    const c=b.cancel; if(!c||!['pending','requested','accepted_pending_payment','confirmed'].includes(b.status)||c.started) return '';
    if(c.in_person) return `<section class="cx-card"><div class="cx-icon">${wdIcon('calendar',20)}</div><div class="cx-main"><p class="eyebrow">CANCELACIÓN</p><h3>¿No puedes ir?</h3>
      <p>${escapeHtml(translateString('Si cancelas, se libera tu plaza y avisamos al profesional. WORLDIVES no gestiona pagos ni devoluciones en este servicio: si le has pagado algo, resuélvelo directamente con él.'))}</p>
      <p class="cx-policy"><b>${escapeHtml(translateString('Política del profesional'))}:</b> ${escapeHtml(c.policy_text||translateString(WD_IP_NO_POLICY))} <a href="#/legal/pago-en-persona">${escapeHtml(translateString('Cómo funciona el pago en persona'))}</a></p>
      <button type="button" class="btn cx-btn" id="booking-cancel">Cancelar reserva</button></div></section>`;
    const amount=wdMoney(c.refund_amount,b.currency), paidAmount=wdMoney(c.paid_amount,b.currency);
    const until=c.deadline?new Date(c.deadline).toLocaleString(wdLocale(),{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}):'';
    const msg=!c.paid_online?'Puedes cancelar sin coste: no has pagado nada online.'
      :c.free?`Cancelación gratuita hasta el ${until}. Si cancelas ahora te corresponde una devolución de ${amount}.`
      :c.refund_amount>0?`El plazo de cancelación gratuita terminó el ${until}. Si cancelas ahora, según la política del centro, te corresponde una devolución de ${amount} (de ${paidAmount} pagados).`
      :`El plazo de cancelación gratuita terminó el ${until}. Si cancelas ahora, según la política del centro, no hay reembolso de los ${paidAmount} pagados.`;
    return `<section class="cx-card ${c.paid_online&&!c.free?'is-late':''}"><div class="cx-icon">${wdIcon('calendar',20)}</div><div class="cx-main"><p class="eyebrow">CANCELACIÓN</p><h3>¿No puedes ir?</h3><p>${escapeHtml(msg)}</p>
      <p class="cx-policy">${escapeHtml(b.cancellation_text||c.policy_text||'')}${b.cancellation_note?' '+escapeHtml(b.cancellation_note):''} <a href="#/legal/condiciones-reserva">Condiciones de reserva</a></p>
      <button type="button" class="btn cx-btn" id="booking-cancel">Cancelar reserva</button></div></section>`;
  }
  function bindBookingCancel(b,id){
    const btn=$('#booking-cancel'); if(!btn) return;
    btn.onclick=async()=>{
      let terms; try{ terms=(await postJSON(`/api/bookings/${id}/cancel`,{preview:true})).terms; }catch(err){ toast(err.message); return; }
      const refund=terms.paid_online?(terms.refund_amount>0?`Según la política del centro te corresponde una devolución de <b>${wdMoney(terms.refund_amount,b.currency)}</b>. La hace el centro a la misma tarjeta y te avisamos por email (después, 5–10 días hábiles según tu banco).`:'<b>No hay reembolso</b> porque estás fuera del plazo de cancelación gratuita.'):'No se te cobrará nada.';
      const {el,close}=wdOpenModal({id:'cancel-modal',title:'Cancelar la reserva',subtitle:`${escapeHtml(b.center_name)} · ${escapeHtml(areaDate(b.booking_date,b.booking_time))}`,
        body:`<div class="cx-summary ${terms.paid_online&&!terms.refund_amount?'is-late':''}">${wdIcon(terms.refund_amount>0||!terms.paid_online?'check':'alert',20)}<p>${refund}</p></div>
          <div class="field"><label for="cx-reason">Motivo (opcional, lo verá el centro)</label><textarea id="cx-reason" rows="3" maxlength="300" placeholder="Por ejemplo: me he resfriado, cambio de planes…"></textarea></div>`,
        footer:'<button type="button" class="btn" data-modal-close>No, mantener la reserva</button><button type="button" class="btn danger" id="cx-ok">Sí, cancelar la reserva</button>'});
      $('#cx-ok',el).onclick=async e=>{ e.currentTarget.disabled=true; try{ const r=await postJSON(`/api/bookings/${id}/cancel`,{reason:$('#cx-reason',el).value}); close();
        toast(r.refund==='proposed'?`Reserva cancelada. Hemos pedido al centro que te devuelva ${wdMoney(r.refund_amount,b.currency)}.`:r.refund==='refunded'?`Reserva cancelada. Te devolvemos ${wdMoney(r.refund_amount,b.currency)}.`:'Reserva cancelada.');
        renderBookingDetail(new URLSearchParams('id='+id)); }catch(err){ toast(err.message); e.currentTarget.disabled=false; } };
    };
  }
  function accountPrivacyCard(u){
    return `<section class="acc-card" id="acc-privacy"><div class="acc-card-head"><h2>${wdIcon('shield',18)} Privacidad y datos</h2></div>
      <p class="acc-help">Descarga una copia de todos tus datos o elimina tu cuenta cuando quieras.</p>
      ${wdClosedCard()}
      <div class="acc-privacy-actions"><a class="btn" href="/api/account/export?format=zip" download>${wdIcon('download',15)} Descargar mis datos (ZIP)</a>${u.role==='recreational'?'<button type="button" class="btn danger" id="acc-delete">Eliminar mi cuenta</button>':''}${wdOwnsProvider()&&!state.me?.account_closed?'<button type="button" class="btn danger" id="acc-close">Borrar mi cuenta para siempre</button>':''}</div>
      <p class="acc-legal-links"><a href="#/legal/privacidad">Privacidad</a> · <a href="#/legal/condiciones-buceadores">Condiciones de uso</a> · <a href="#/legal/condiciones-reserva">Condiciones de reserva</a> · <a href="#/legal/cookies">Cookies</a></p></section>`;
  }
  // v50.49: centres (owner) and freelance close their account: six months to come back with everything, then deleted.
  function wdOwnsProvider(){ const m=state.me; return !!m&&(m.user?.role==='freelance'||(m.user?.role==='center'&&(m.member_role||'owner')==='owner')); }
  function wdClosedCard(){ const c=state.me?.account_closed; if(!c) return '';
    return `<div class="cx-summary is-late" id="acc-closed">${wdIcon('alert',20)}<div><p><b>Tu cuenta está cerrada</b> <span>desde el</span> <span translate="no">${escapeHtml(wdLegalDate(c.closed_at))}</span>. <span>Nadie la ve ni puede reservar.</span></p>
      <p><span>La guardamos hasta el</span> <b translate="no">${escapeHtml(wdLegalDate(c.purge_after))}</b> (<span class="num">${c.days_left}</span> <span>${c.days_left===1?'día':'días'}</span>). <span>Después la borraremos para siempre.</span></p>
      <button type="button" class="btn btn-primary" id="acc-reopen">Reabrir mi cuenta</button></div></div>`; }
  async function wdCloseAccountFlow(){
    const esc=escapeHtml; let st; try{ st=await api('/api/provider/cuenta'); }catch(err){ toast(err.message); return; }
    const money=(v,c)=>wdMoney(v,c||'EUR');
    const futureHtml=()=>`<div class="cx-summary is-late">${wdIcon('alert',20)}<p><span>Tienes</span> <b class="num">${st.future_count}</b> <span>${st.future_count===1?'reserva próxima. Antes de cerrar hay que resolverla.':'reservas próximas. Antes de cerrar hay que resolverlas.'}</span> <span>Cámbialas o cancélalas desde tus reservas, o cancélalas todas aquí.</span></p></div>
      <ul class="acc-close-list" translate="no">${st.future.slice(0,12).map(b=>`<li><b>${esc(wdLegalDate(b.booking_date))}${b.booking_time?' · '+esc(b.booking_time):''}</b> · ${esc(b.service_title||'')} · ${esc(b.name||'')} · ${b.participants} · ${b.paid>0?esc(money(b.paid,b.currency)):''}</li>`).join('')}${st.future.length>12?`<li>… +${st.future.length-12}</li>`:''}</ul>
      <p class="adl-det"><span>«Cancelar y avisar a todos» cancela todas, devuelve lo pagado completo</span>${st.refund_total>0?` (<span class="num" translate="no">${esc(money(st.refund_total))}</span>)`:''} <span>y avisa a cada buceador por email y en la app, en su idioma.</span></p>`;
    const closeHtml=()=>`<div class="cx-summary">${wdIcon('info',20)}<p><span>Tu cuenta se cierra ahora: deja de verse y nadie puede reservar.</span> <b>Guardamos todo durante 6 meses</b>: <span>si en ese tiempo entras y pulsas «Reabrir mi cuenta», lo recuperas tal como estaba. Pasados los 6 meses lo borramos todo, salvo los pagos y los datos fiscales que la ley obliga a guardar.</span></p></div>
      <p style="margin:0 0 10px"><a href="/api/center/export?kind=bookings" download>Descarga antes tus reservas (CSV)</a></p>
      <div class="field"><label for="close-pw">Escribe tu contraseña para confirmar</label><input id="close-pw" type="password" autocomplete="current-password" required></div>`;
    const {el,close}=wdOpenModal({id:'close-account',title:'Borrar mi cuenta para siempre',subtitle:esc(st.name||''),
      body:`<div id="close-body">${st.future_count?futureHtml():closeHtml()}</div>`,
      footer:`<button type="button" class="btn" data-modal-close>No, volver</button>${st.future_count?'<button type="button" class="btn danger" id="close-cancel-all">Cancelar y avisar a todos</button>':'<button type="button" class="btn danger" id="close-ok">Cerrar mi cuenta</button>'}`});
    $('#close-cancel-all',el)?.addEventListener('click',async e=>{ if(!confirm(translateString('¿Cancelar todas las reservas? Se devuelve todo lo pagado y no se puede deshacer.'))) return; e.target.disabled=true;
      try{ const r=await postJSON('/api/provider/cuenta/cancelar-todo',{confirm:true}); close(); toast(`${r.result.cancelled} · ${translateString('reservas canceladas. Hemos avisado a todos.')}`); wdCloseAccountFlow(); }catch(err){ e.target.disabled=false; toast(err.message); } });
    $('#close-ok',el)?.addEventListener('click',async e=>{ e.target.disabled=true;
      try{ const r=await postJSON('/api/provider/cuenta/cerrar',{password:$('#close-pw',el).value}); close(); state.me=null; renderAccount();
        toast(`${translateString('Tu cuenta se ha cerrado. Puedes reabrirla hasta el')} ${wdLegalDate(r.purge_after)}.`); wdGo('#/'); }
      catch(err){ e.target.disabled=false; toast(err.message); } });
  }
  function bindAccountPrivacy(){
    $('#acc-close')?.addEventListener('click',wdCloseAccountFlow);
    $('#acc-reopen')?.addEventListener('click',async e=>{ e.target.disabled=true; try{ await postJSON('/api/provider/cuenta/reabrir',{}); await loadMe(); toast('Tu cuenta vuelve a estar abierta, con todo como estaba.'); route(); }catch(err){ e.target.disabled=false; toast(err.message); } });
    $('#acc-delete')?.addEventListener('click',()=>{
      const {el,close}=wdOpenModal({id:'delete-account',title:'Eliminar mi cuenta',subtitle:'Esta acción no se puede deshacer',
        body:`<div class="cx-summary is-late">${wdIcon('alert',20)}<p>Borraremos tu ficha, tu documentación, tu Log Book, tus mensajes y tus recompensas. Las reservas pasadas se conservan sin tu nombre, porque la ley obliga a guardar los datos de los pagos. Si tienes reservas próximas, cancélalas antes.</p></div>
          <p style="margin:0 0 10px"><a href="/api/account/export?format=zip" download>Descarga antes una copia de tus datos</a></p>
          <div class="field"><label for="del-pw">Escribe tu contraseña para confirmar</label><input id="del-pw" type="password" autocomplete="current-password" required></div>`,
        footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn danger" id="del-ok">Eliminar definitivamente</button>'});
      $('#del-ok',el).onclick=async()=>{ try{ const r=await postJSON('/api/account/delete',{password:$('#del-pw',el).value}); close();
        if(r&&r.email_sent){ toast('Te hemos enviado un email para confirmar la eliminación. El enlace caduca en 24 horas.'); return; }
        state.me=null; renderAccount(); toast('Tu cuenta se ha eliminado.'); wdGo('#/'); }catch(err){ toast(err.message); } };
    });
  }

  // ---------------------------------------------------------------- v50.31 · Account: email, shared data, professional request, security
  function accountEmailCard(u){
    const verified=!!u.email_verified_at;
    return `<section class="acc-card" id="acc-email"><div class="acc-card-head"><h2>${wdIcon('message',18)} Email</h2>${verified?'<span class="status good">Verificado</span>':'<span class="status warn">Sin verificar</span>'}</div>
      <p class="acc-help"><strong>${escapeHtml(u.email)}</strong></p>${verified?'':'<p class="acc-help">Confirma tu email desde el enlace que te enviamos para recibir los avisos de tus reservas y poder recuperar la cuenta.</p><button type="button" class="btn" id="acc-email-resend">Reenviar el correo de verificación</button>'}
      <details class="acc-upload"><summary>Cambiar mi email</summary><form id="acc-email-form"><div class="field"><label for="acc-new-email">Nuevo email</label><input id="acc-new-email" type="email" required autocomplete="email"></div><div class="field"><label for="acc-email-pw">Tu contraseña</label><input id="acc-email-pw" type="password" required autocomplete="current-password"></div>${state.me?.security?.totp_enabled?'<div class="field"><label for="acc-email-code">Código de verificación (o de recuperación)</label><input id="acc-email-code" inputmode="text" autocomplete="one-time-code" maxlength="32" required></div>':''}<button class="btn" type="submit">Enviar confirmación al nuevo email</button><small>El cambio se aplica cuando confirmes desde el nuevo email.</small></form></details></section>`;
  }
  function accountSharesCard(){ return `<section class="acc-card" id="acc-shares"><div class="acc-card-head"><h2>${wdIcon('shield',18)} Centros que ven tu ficha</h2></div><p class="acc-help">Un centro ve tu ficha de buceador y tus documentos cuando reservas tú con él o cuando compartes tus datos al hacer check-in con su QR.</p><div id="acc-shares-list"><p class="acc-empty">Cargando…</p></div></section>`; }
  function proRequestCard(u){
    const req=u.requested_role; if(!['center','freelance'].includes(req)||['center','freelance','admin'].includes(u.role)) return '';
    const st=state.me?.pro_request?.status||'pending';
    return `<section class="acc-card"><div class="acc-card-head"><h2>${wdIcon('chart',18)} Cuenta profesional</h2><span class="status ${st==='rejected'?'bad':'warn'}">${st==='rejected'?'No aprobada':'Pendiente de verificación'}</span></div><p class="acc-help">${st==='rejected'?'No hemos podido verificar tu solicitud. Escríbenos si crees que es un error.':`Estamos verificando tu ${req==='center'?'centro':'perfil profesional'}. Te avisaremos por email en cuanto esté aprobado; mientras tanto puedes usar WORLDIVES como buceador.`}</p></section>`;
  }
  function accountSecurityCard(u){ return (typeof totpCard==='function'?totpCard(u):'')+sessionsCard(); }
  // v50.51 (ASVS V7.5.2): where the account is open, and closing every other session.
  // v50.55 (encargo 2): «Dispositivos conectados»: the web sessions and the app's devices, each with «Cerrar sesión».
  function sessionsCard(){
    return `<section class="acc-card" id="acc-sessions"><div class="acc-card-head"><h2>${wdIcon('lock',18)} Dispositivos conectados</h2></div>
      <p class="acc-help">Dónde está abierta tu cuenta ahora: navegadores y la app. Si ves algo que no reconoces, cierra ese dispositivo y cambia tu contraseña.</p>
      <div id="acc-sessions-list"><p class="acc-empty">Cargando…</p></div>
      <div class="acc-privacy-actions"><button type="button" class="btn" id="acc-sessions-close">Cerrar todas menos esta</button></div></section>`;
  }
  async function bindSessionsCard(){
    const box=$('#acc-sessions-list'); if(!box) return;
    const esc=escapeHtml;
    const load=async()=>{ try{ const d=await api('/api/account/devices');
      box.innerHTML=(d.items||[]).map(x=>`<div class="acc-doc acc-device"><span class="acc-device-ic">${wdIcon(x.kind==='app'?'bell':'globe',18)}</span><span><span><strong>${esc(x.device)}</strong>${x.system?` · ${esc(x.system)}`:''} ${x.current?`<span class="status good">${esc(translateString('Este dispositivo'))}</span>`:''}
          <small>${esc(translateString('Última actividad'))}: ${esc(wdDeadline(x.last_seen))}${x.city?` · ${esc(translateString('Ciudad aproximada'))}: ${esc(x.city)}`:''}${x.kind==='app'&&x.expires_at?` · ${esc(translateString('Pide la contraseña de nuevo el'))} ${esc(wdDeadline(x.expires_at))}`:''}</small></span></span>
          ${x.current?'':`<button type="button" class="btn btn-sm" data-close-dev="${esc(x.id)}">${esc(translateString('Cerrar sesión'))}</button>`}</div>`).join('')||'<p class="acc-empty">Solo esta sesión.</p>';
      if(!d.city_source) box.insertAdjacentHTML('beforeend',`<p class="acc-help"><small>${esc(translateString('La ciudad aproximada aparecerá cuando el servidor la reciba de su proxy (pendiente de configurar).'))}</small></p>`);
      $$('[data-close-dev]',box).forEach(b=>b.onclick=async()=>{ if(!await wdConfirm({title:translateString('Cerrar la sesión de ese dispositivo'),text:translateString('Tendrá que volver a entrar con la contraseña. Si es un móvil, borrará sus datos guardados al conectarse.'),ok:translateString('Cerrar sesión')})) return;
        try{ await postJSON('/api/account/devices/close',{id:b.dataset.closeDev}); toast(translateString('Sesión cerrada en ese dispositivo.')); load(); }catch(err){ toast(err.message); } });
    }catch(e){ box.innerHTML=`<p class="acc-empty">${escapeHtml(e.message)}</p>`; } };
    await load();
    if(/dispositivos=1/.test(location.hash)) setTimeout(()=>$('#acc-sessions')?.scrollIntoView({block:'start'}),400);   // after the rest of «Mi cuenta» is drawn
    $('#acc-sessions-close')?.addEventListener('click',()=>{ const two=!!state.me?.security?.totp_enabled;
      const {el,close}=wdOpenModal({id:'sess-close',size:'sm',title:'Cerrar las demás sesiones',body:`<div class="field"><label for="sc-pw">Tu contraseña</label><input id="sc-pw" type="password" autocomplete="current-password"></div>${two?'<div class="field"><label for="sc-code">Código de verificación (o de recuperación)</label><input id="sc-code" autocomplete="one-time-code" maxlength="32"></div>':''}`,
        footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="sc-ok">Cerrar sesiones</button>'});
      $('#sc-ok',el).onclick=async()=>{ try{ const r=await postJSON('/api/account/sessions/close',{password:$('#sc-pw',el).value,totp_code:$('#sc-code',el)?.value||''}); close(); toast(r.closed===1?'Se ha cerrado 1 sesión.':`Se han cerrado ${r.closed} sesiones.`); load(); }catch(err){ toast(err.message); } }; });
  }
  async function bindAccountExtras(d){
    $('#acc-email-resend')?.addEventListener('click',async()=>{ try{ await postJSON('/api/account/verify-email/resend',{}); toast('Te hemos enviado el correo de verificación.'); }catch(e){ toast(e.message); } });
    $('#acc-email-form')?.addEventListener('submit',async e=>{ e.preventDefault(); try{ await postJSON('/api/account/email',{email:$('#acc-new-email').value,password:$('#acc-email-pw').value,totp_code:$('#acc-email-code')?.value||''}); toast('Revisa el nuevo email y confirma el cambio.'); e.target.reset(); }catch(err){ toast(err.message); } });
    const list=$('#acc-shares-list'); if(list){ try{ const s=await api('/api/account/shares'); list.innerHTML=(s.items||[]).length?s.items.map(x=>`<div class="acc-doc"><span><span><strong>${escapeHtml(x.center_name)}</strong><small>${escapeHtml(x.city||'')} · desde ${fmtDate(x.granted_at)}</small></span></span><button type="button" class="btn" data-unshare="${x.center_id}">Dejar de compartir</button></div>`).join(''):'<p class="acc-empty">No compartes tu ficha con ningún centro (aparte de los centros en los que reservas tú).</p>';
      $$('[data-unshare]',list).forEach(b=>b.onclick=async()=>{ if(!confirm('¿Dejar de compartir tu ficha con este centro? Seguirá viendo los datos de las reservas que hagas tú.')) return; try{ await postJSON('/api/account/shares/revoke',{center_id:+b.dataset.unshare}); toast('Has dejado de compartir tus datos con el centro.'); bindAccountExtras(d); }catch(e){ toast(e.message); } }); }catch{ list.innerHTML=''; } }
    if(typeof bindTotpCard==='function') bindTotpCard(d);
    bindSessionsCard();
  }
  async function renderVerifyEmail(params){
    const token=params.get('token')||''; setApp(authCard('Verificar email','<p class="lead">Comprobando el enlace…</p>'));
    try{ const r=await postJSON('/api/auth/verify-email',{token}); setApp(authCard(r.changed?'Email cambiado':'Email verificado',`<div class="notice success">${r.changed?'Tu email se ha cambiado. Vuelve a iniciar sesión con la nueva dirección.':'Gracias: tu email está verificado.'}</div><p><a class="btn btn-primary" href="${r.changed?'#/login':'#/cuenta'}">${r.changed?'Iniciar sesión':'Ir a mi cuenta'}</a></p>`)); await loadMe(); }
    catch(e){ setApp(authCard('Enlace no válido',`<div class="notice warn">${escapeHtml(e.message)}</div><p><a class="btn" href="#/cuenta">Ir a mi cuenta</a></p>`)); }
  }

  // ---------------------------------------------------------------- v50.30 · Administration: Legal and Emails
  const EMAIL_STATUS={queued:['En cola','warn'],sending:['Enviando','warn'],sent:['Enviado','good'],failed:['Fallido','bad'],skipped:['Sin email real','muted'],expired:['Caducado','muted']};
  async function renderAdminLegal(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/admin/legal'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const missing=['owner_name','nif','address','email'].filter(k=>!d.settings[k]);
    const RS={open:['Abierta','warn'],actioned:['Contenido retirado','good'],dismissed:['Desestimada','muted']};
    mount.innerHTML=`<section class="mm-module adl"><div class="svc-head"><div><p class="eyebrow">Legal</p><h2>Datos del titular y documentos legales</h2><p>Estos datos se insertan en el aviso legal, la privacidad, las condiciones y el pie de todos los correos. Los textos son plantillas completas: haz que los revise un abogado antes de publicar la web.</p></div></div>
      ${missing.length?`<div class="notice warning"><strong>Faltan datos obligatorios.</strong> Mientras no los completes, los documentos muestran «pendiente de completar».</div>`:'<div class="notice good"><strong>Datos del titular completos.</strong></div>'}
      <form id="adl-form" class="form-grid adl-form">${Object.entries(d.fields).map(([k,l])=>`<div class="field ${['address','registry'].includes(k)?'full':''}"><label for="adl-${k}">${esc(l)}</label><input id="adl-${k}" data-k="${k}" maxlength="300" value="${esc(d.settings[k]||'')}" ${k==='fee_percent'?'inputmode="decimal" placeholder="10"':''}></div>`).join('')}
        <div class="form-actions full"><button class="btn btn-primary" type="submit">Guardar datos legales</button></div></form>
      <div id="adl-retention"></div>
      <h3 class="adl-h">Documentos legales</h3>
      <p class="muted">Cada cambio crea una versión nueva con su fecha de entrada en vigor y queda en el historial público. El castellano es la versión de referencia; el inglés también es oficial y el resto de idiomas muestran «prevalece el castellano».</p>
      <div class="table-wrap"><table class="data-table adl-doctable"><thead><tr><th>Documento</th><th>Versión vigente</th><th>Idiomas</th><th>Próxima versión</th><th></th></tr></thead><tbody>${(d.documents||[]).map(x=>`<tr><td><a href="#/legal/${esc(x.route)}" target="_blank" rel="noopener">${esc(x.title)}</a>${x.acceptance?`<div class="adl-det">${x.acceptance==='pro'?'Lo aceptan centros y profesionales':'Lo acepta cada usuario'}${x.notice_days?` · aviso de ${x.notice_days} días`:''}</div>`:''}</td><td>${esc(x.version)}</td><td>${x.langs.map(l=>`<span class="adl-lang">${esc(l)}</span>`).join(' ')}</td><td>${x.upcoming?`${esc(x.upcoming.version)} · ${esc(wdLegalDate(x.upcoming.effective_at))}`:'—'}</td><td><button type="button" class="btn adl-edit" data-slug="${esc(x.slug)}">Editar</button></td></tr>`).join('')}</tbody></table></div>
      <h3 class="adl-h">Mensajes de contacto ${(d.contacts||[]).filter(c=>c.status==='open').length?`<b class="adl-badge">${(d.contacts||[]).filter(c=>c.status==='open').length} sin atender</b>`:''}</h3>
      ${(d.contacts||[]).length?`<div class="table-wrap"><table class="data-table adl-contacts"><thead><tr><th>Ref.</th><th>Fecha</th><th>Asunto</th><th>Remitente</th><th>Mensaje</th><th>Estado</th><th></th></tr></thead><tbody>${d.contacts.map(c=>`<tr><td>CON-${String(c.id).padStart(5,'0')}</td><td>${esc((c.created_at||'').slice(0,10))}</td><td>${esc((d.contact_topics||{})[c.topic]||c.topic)}${c.booking_ref?`<div class="adl-det">${esc(c.booking_ref)}</div>`:''}</td><td>${esc(c.name)}<div class="adl-det"><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></div></td><td class="adl-msg">${esc(c.message)}</td><td>${c.status==='open'?'<span class="status warn">Sin atender</span>':'<span class="status good">Atendido</span>'}</td><td><button type="button" class="btn adl-contact" data-id="${c.id}" data-done="${c.status==='open'?1:0}">${c.status==='open'?'Marcar atendido':'Reabrir'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Todavía no hay mensajes del formulario de contacto.</p>'}
      <h3 class="adl-h">Denuncias de contenido ${d.open_reports?`<b class="adl-badge">${d.open_reports} abiertas</b>`:''}</h3>
      ${d.reports.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Ref.</th><th>Fecha</th><th>Motivo</th><th>Contenido</th><th>Remitente</th><th>Estado</th><th></th></tr></thead><tbody>${d.reports.map(r=>`<tr><td>DEN-${String(r.id).padStart(5,'0')}</td><td>${esc((r.created_at||'').slice(0,10))}</td><td>${esc(d.reasons[r.reason]||r.reason)}</td><td>${r.target_type?`<b>${esc({review:'Reseña',center:'Centro',point:'Punto de buceo',experience:'Experiencia',photo:'Foto',promotion:'Promoción',profile:'Perfil'}[r.target_type]||r.target_type)}</b> `:''}${r.target_url?`<a href="${esc(r.target_url)}" target="_blank" rel="noopener">Abrir</a>`:'—'}<div class="adl-det">${esc(r.details)}</div></td><td>${esc([r.reporter_name,r.reporter_email].filter(Boolean).join(' · ')||'Anónimo')}</td><td><span class="status ${RS[r.status]?.[1]||''}">${esc(RS[r.status]?.[0]||r.status)}</span>${r.resolution?`<div class="adl-det">${esc(r.resolution)}</div>`:''}</td><td>${r.status==='open'?`<button type="button" class="btn adl-resolve" data-id="${r.id}" data-type="${esc(r.target_type||'')}">Resolver</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay denuncias.</div>'}
    </section>`;
    $('#adl-form').onsubmit=async e=>{ e.preventDefault(); const data={}; $$('#adl-form input[data-k]').forEach(i=>data[i.dataset.k]=i.value); try{ await postJSON('/api/admin/legal',data); LEGAL_INFO=null; toast('Datos legales guardados.'); renderAdminLegal(mountId); }catch(err){ toast(err.message); } };
    $$('.adl-edit',mount).forEach(b=>b.onclick=()=>openLegalEditor(b.dataset.slug,'es',()=>renderAdminLegal(mountId)));
    renderRetentionCard($('#adl-retention',mount));
    $$('.adl-contact',mount).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/admin/contact/done',{id:+b.dataset.id,done:b.dataset.done==='1'}); toast(b.dataset.done==='1'?'Mensaje marcado como atendido.':'Mensaje reabierto.'); renderAdminLegal(mountId); }catch(err){ toast(err.message); } });
    $$('.adl-resolve',mount).forEach(b=>b.onclick=()=>{
      const {el,close}=wdOpenModal({id:'report-resolve',title:'Resolver denuncia',subtitle:'Se enviará la decisión, con los motivos, a quien la presentó y a quien publicó el contenido',
        body:`<div class="field"><label for="rr-st">Decisión</label><select id="rr-st"><option value="actioned">Retirar o corregir el contenido</option><option value="dismissed">Desestimar: el contenido se mantiene</option></select></div><div class="field"><label for="rr-txt">Explicación de los motivos</label>${b.dataset.type==='review'?'':'<p class="muted small full">«Retirar o corregir» solo oculta automáticamente las reseñas. Para fichas, fotos, promociones o perfiles, corrige o retira primero el contenido desde su pestaña y después guarda aquí la decisión.</p>'}<textarea id="rr-txt" rows="4" minlength="10" maxlength="2000" required placeholder="Explica brevemente qué has comprobado y qué has decidido."></textarea><small>Si retiras contenido de un usuario o centro, infórmale también de los motivos.</small></div>`,
        footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="rr-ok">Guardar decisión</button>'});
      $('#rr-ok',el).onclick=async()=>{ if(($('#rr-txt',el).value||'').trim().length<10){ toast('Explica los motivos de la decisión (se envían a las dos partes).'); return; } try{ await postJSON('/api/admin/reports/resolve',{id:+b.dataset.id,status:$('#rr-st',el).value,resolution:$('#rr-txt',el).value}); close(); toast('Denuncia resuelta.'); renderAdminLegal(mountId); }catch(err){ toast(err.message); } };
    });
  }
  // Administración → Legal: retention periods of the privacy policy (a daily job applies them).
  async function renderRetentionCard(mount){
    if(!mount) return; const esc=escapeHtml; let d; try{ d=await api('/api/admin/retention'); }catch(err){ mount.innerHTML=''; return; }
    const F=[['inactive_months','Cuentas de buceador sin actividad','meses',`Se avisa por email y se elimina ${d.warn_days} días después si no entra.`],
      ['expired_docs_months','Documentos caducados','meses','Se borran después de su fecha de caducidad.'],
      ['notices_months','Avisos de los centros','meses',''],['audit_months','Registro de actividad','meses',''],['audit_keep','Entradas del registro que se conservan siempre','entradas','']];
    const L=d.last;
    mount.innerHTML=`<h3 class="adl-h">Conservación de datos</h3><p class="muted">Plazos de la política de privacidad. Cada día se aplican automáticamente. Las reservas y los pagos se conservan 6 años y no se borran aquí. Los registros del servidor se conservan ${d.log_days} días (variable WOD_LOG_RETENTION_DAYS).</p>
      <form id="ret-form" class="form-grid">${F.map(([k,l,u,h])=>`<div class="field"><label for="ret-${k}">${esc(l)} (${u})</label><input id="ret-${k}" data-k="${k}" type="number" min="${d.limits[k][0]}" max="${d.limits[k][1]}" value="${d.settings[k]}" required>${h?`<small>${esc(h)}</small>`:`<small>Por defecto: ${d.defaults[k]}</small>`}</div>`).join('')}
        <div class="form-actions full"><button class="btn" type="button" id="ret-run">Guardar y aplicar ahora</button><button class="btn btn-primary" type="submit">Guardar plazos</button></div></form>
      ${L?`<p class="adl-det" id="ret-last">Última ejecución ${esc(L.date)}: ${L.warned} avisos de inactividad, ${L.accounts_deleted} cuentas eliminadas, ${L.documents_deleted} documentos, ${L.notices_deleted} avisos y ${L.audit_deleted} entradas del registro borradas.</p>`:'<p class="adl-det">Todavía no se ha ejecutado.</p>'}`;
    const send=async run=>{ const data={run_now:run}; $$('#ret-form input[data-k]').forEach(i=>data[i.dataset.k]=i.value);
      try{ await postJSON('/api/admin/retention',data); toast(run?'Plazos guardados y aplicados.':'Plazos guardados.'); renderRetentionCard(mount); }catch(err){ toast(err.message); } };
    $('#ret-form').onsubmit=e=>{ e.preventDefault(); send(false); };
    $('#ret-run').onclick=()=>{ if($('#ret-form').reportValidity()&&confirm('Se borrarán ahora los datos que hayan superado los plazos. ¿Continuar?')) send(true); };
  }
  // Administración → Descripciones de puntos: the own texts written from the data of each point, to review one by one.
  // Administración → Medios: credit and origin/licence of every image the platform publishes.
  // ---------------------------------------------------------------- v50.37 · Fase 6: plans, tools and team
  const PLAN_STATUS={trial:['Prueba gratuita','warn'],active:['Activo','good'],expired:['Terminado','bad'],free:['Ficha gratuita','muted']};
  function openInfoRequest({center_id=null,provider_user_id=null,name=''}){
    const me=state.me?.user; const esc=escapeHtml;
    const {el,close}=wdOpenModal({id:'info-request',title:'Solicitar información',subtitle:esc(name),
      body:`<p class="muted" style="margin-top:0">Este centro todavía no tiene reserva online en WORLDIVES. Le enviamos tu mensaje y te contestará directamente.</p>
        <form id="ir-form" class="form-grid"><div class="field"><label for="ir-name">Tu nombre</label><input id="ir-name" required maxlength="120" value="${esc(me?.fullname||'')}" autocomplete="name"></div>
        <div class="field"><label for="ir-email">Tu email</label><input id="ir-email" type="email" required maxlength="160" value="${esc(me?.email&&!/\.local$/.test(me.email)?me.email:'')}" autocomplete="email"></div>
        <div class="field"><label for="ir-phone">Teléfono (opcional)</label><input id="ir-phone" type="tel" maxlength="40" autocomplete="tel"></div>
        <div class="field"><label for="ir-date">Fecha deseada (opcional)</label><input id="ir-date" type="date" min="${new Date().toISOString().slice(0,10)}"></div>
        <div class="field"><label for="ir-pax">Personas</label><input id="ir-pax" type="number" min="1" max="99" value="1"></div>
        <div class="field full"><label for="ir-msg">¿Qué necesitas?</label><textarea id="ir-msg" rows="4" minlength="10" maxlength="2000" required placeholder="Actividad, nivel, dudas…"></textarea></div>
        <label class="lg-check full"><input type="checkbox" id="ir-ok" required> <span>Acepto que WORLDIVES envíe estos datos al centro para que me conteste (<a href="#/legal/privacidad" target="_blank" rel="noopener">privacidad</a>).</span></label></form>`,
      footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="ir-send">Enviar solicitud</button>'});
    translateTree(el);
    $('#ir-send',el).onclick=async()=>{ if(!$('#ir-form',el).reportValidity()) return; const b=$('#ir-send',el); b.disabled=true;
      try{ await postJSON('/api/info-requests',{center_id,provider_user_id,name:$('#ir-name',el).value,email:$('#ir-email',el).value,phone:$('#ir-phone',el).value,wanted_date:$('#ir-date',el).value,
          participants:$('#ir-pax',el).value,message:$('#ir-msg',el).value,accept_privacy:$('#ir-ok',el).checked,lang:currentLanguage()});
        delete el.dataset.dirty; close(); toast('Solicitud enviada. El centro te contestará directamente.'); }
      catch(err){ toast(err.message); b.disabled=false; } };
  }
  function planFeatureList(p,labels,limits){ const esc=escapeHtml;
    return `<ul class="pl-feats">${Object.entries(labels).map(([k,l])=>`<li class="${p.features[k]?'is-on':'is-off'}">${wdIcon(p.features[k]?'check':'extra',14)} ${esc(l)}</li>`).join('')}
      ${Object.entries(limits||{}).map(([k,l])=>`<li class="is-on">${wdIcon('check',14)} ${esc(l)}: ${Number(p.limits?.[k]||0)?Number(p.limits[k]):'sin límite'}</li>`).join('')}</ul>`; }
  async function renderPlans(){
    let d; try{ d=await api('/api/plans'); }catch(err){ setApp(`<section class="page"><div class="empty">${escapeHtml(err.message)}</div></section>`); return; }
    const esc=escapeHtml; const mine=state.me?.plan;
    setApp(`<section class="page pl-page"><p class="eyebrow">Para centros y profesionales</p><h1>Planes de WORLDIVES</h1>
      <p class="lead">Sin comisión por reserva: cobras directamente en tu cuenta de Stripe. Solo pagas, si quieres, la cuota anual de tu plan.${d.trial_days?` Al aprobar tu alta tienes ${d.trial_days} días de prueba gratuita.`:''}</p>
      <div class="pl-grid">${d.items.map(p=>`<article class="pl-card ${mine?.code===p.code?'is-current':''}"><h2>${esc(p.name)}</h2><p class="pl-price">${p.code==='free'?'Gratis':(p.price_year?`${wdMoney(p.price_year,p.currency)} <small>/ año</small>`:'<small>Precio a consultar</small>')}</p>
        <p class="muted">${esc(p.description||'')}</p>${planFeatureList(p,d.features,d.limits)}${mine?.code===p.code?'<span class="status good">Tu plan</span>':''}</article>`).join('')}</div>
      <div class="notice"><strong>Siempre, en cualquier plan:</strong> tus reservas actuales se atienden con normalidad y puedes exportar tus datos. Si un plan termina, tu ficha sigue publicada como ficha gratuita.</div>
      ${state.me?.user&&['center','freelance'].includes(state.me.user.role)?'<p><a class="btn btn-primary" href="#/admin?tab=plan">Gestionar mi plan</a></p>':'<p><a class="btn btn-primary" href="#/registro">Dar de alta mi centro</a></p>'}</section>`);
  }
  async function renderMyPlanRoute(params){
    const sid=params?.get?.('pago'); if(sid){ try{ await postJSON('/api/provider/plan/sync',{session_id:sid}); toast('Pago recibido. Tu plan está activo.'); }catch(err){ toast(err.message); } }
    wdGo('#/admin?tab=plan');
  }
  async function renderMyPlan(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d,pl; try{ [d,pl]=await Promise.all([api('/api/provider/plan'),api('/api/plans')]); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const p=d.plan; const st=PLAN_STATUS[p.status]||[p.status,''];
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Mi plan</p><h2>${esc(p.name)} <span class="status ${st[1]}">${esc(st[0])}</span></h2>
      <p>${p.expires_at?`${p.status==='trial'?'La prueba gratuita termina':'Activo hasta'} el <b>${esc(wdLegalDate(p.expires_at))}</b>.`:'Ficha gratuita: tu centro aparece en el catálogo y recibe solicitudes de información.'} Las reservas que ya tienes se atienden siempre y puedes exportar tus datos en cualquier plan.</p></div><a class="btn" href="#/planes">Comparar planes</a></div>
      ${planFeatureList(p,pl.features,pl.limits)}
      ${p.exceptions.length?`<p class="adl-det">Excepciones de la administración: ${p.exceptions.map(e=>`${esc(pl.features[e.feature]||e.feature)} ${e.enabled?'activada':'desactivada'} (${esc(e.reason)})`).join(' · ')}</p>`:''}
      <h3 class="adl-h">Renovar o cambiar de plan</h3>
      <div class="pl-grid is-compact">${pl.items.filter(x=>x.code!=='free').map(x=>`<article class="pl-card"><h3>${esc(x.name)}</h3><p class="pl-price">${x.price_year?`${wdMoney(x.price_year,x.currency)} <small>/ año</small>`:'<small>Precio a consultar</small>'}</p>
        ${x.price_year&&d.online_payment&&d.role==='owner'?`<button type="button" class="btn btn-primary pl-pay" data-plan="${esc(x.code)}">${p.code===x.code?'Renovar 12 meses':'Contratar 12 meses'}</button>`:`<p class="adl-det">${d.role!=='owner'?'Solo el propietario puede contratar.':'Escríbenos para activarlo por transferencia.'}</p>`}</article>`).join('')}</div>
      ${d.payments.length?`<h3 class="adl-h">Pagos de la cuota</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Plan</th><th>Importe</th><th>Forma</th><th>Periodo</th><th>Estado</th></tr></thead><tbody>${d.payments.map(x=>`<tr><td>${esc((x.paid_at||x.created_at||'').slice(0,10))}</td><td>${esc(x.plan_code)}</td><td>${wdMoney(x.amount,x.currency)}</td><td>${x.method==='stripe'?'Tarjeta':'Manual'}</td><td>${esc([x.period_start,x.period_end].filter(Boolean).join(' → '))}</td><td>${esc({paid:'Pagado',pending:'En curso',failed:'No completado'}[x.status]||x.status)}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;
    $$('.pl-pay',mount).forEach(b=>b.onclick=async()=>{ b.disabled=true; try{ const r=await postJSON('/api/provider/plan/checkout',{plan:b.dataset.plan}); location.href=r.checkout_url; }catch(err){ toast(err.message); b.disabled=false; } });
  }
  async function renderFiscalCard(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let f; try{ f=await api('/api/provider/fiscal'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const v=k=>esc(f[k]||''); const miss=new Set(f.missing);
    const exp=f.insurance_expires_at; const days=exp?Math.round((new Date(exp+'T12:00:00')-new Date())/864e5):null;
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Datos fiscales y verificación</p><h2>Datos del prestador (DAC7) y seguro</h2>
      <p>La normativa europea DAC7 obliga a las plataformas a identificar a los prestadores que cobran a través de ellas. Estos datos solo los ve la administración de WORLDIVES y se usan para la declaración anual y para tus justificantes.</p></div></div>
      ${f.missing.length?`<div class="notice warning"><strong>Faltan datos:</strong> completa los campos marcados.</div>`:'<div class="notice good"><strong>Datos completos.</strong></div>'}
      ${days!==null&&days<0?'<div class="notice warning"><strong>Tu seguro de responsabilidad civil ha caducado.</strong> Actualiza la póliza.</div>':days!==null&&days<=30?`<div class="notice warning"><strong>Tu seguro caduca en ${days} días.</strong></div>`:''}
      <form id="fi-form" class="form-grid">
        <div class="field"><label for="fi-type">Tipo de prestador</label><select id="fi-type"><option value="">Elige…</option><option value="company" ${f.entity_type==='company'?'selected':''}>Empresa (persona jurídica)</option><option value="individual" ${f.entity_type==='individual'?'selected':''}>Autónomo (persona física)</option></select></div>
        <div class="field"><label for="fi-legal">Razón social o nombre completo</label><input id="fi-legal" maxlength="160" value="${v('legal_name')}" ${miss.has('legal_name')?'aria-invalid="true"':''}></div>
        <div class="field"><label for="fi-tax">NIF / TIN</label><input id="fi-tax" maxlength="40" value="${v('tax_id')}" ${miss.has('tax_id')?'aria-invalid="true"':''}></div>
        <div class="field"><label for="fi-country">País emisor del NIF</label><input id="fi-country" maxlength="2" placeholder="ES" value="${v('tax_id_country')}" style="text-transform:uppercase" ${miss.has('tax_id_country')?'aria-invalid="true"':''}></div>
        <div class="field" data-for="company"><label for="fi-reg">Número de registro mercantil</label><input id="fi-reg" maxlength="160" value="${v('registration_number')}"></div>
        <div class="field" data-for="individual"><label for="fi-birth">Fecha de nacimiento</label><input id="fi-birth" type="date" value="${v('birth_date')}"></div>
        <div class="field full"><label for="fi-addr">Dirección fiscal</label><input id="fi-addr" maxlength="300" value="${v('fiscal_address')}"></div>
        <div class="field full"><p class="adl-det"><b>Cuenta de cobro:</b> ${f.payout_account?`Stripe · ${esc(f.payout_account)}`:'Sin cuenta de cobro conectada (Cobros y pagos).'}</p></div>
        <label class="lg-check full"><input type="checkbox" id="fi-lic" ${f.declares_licences?'checked':''}> <span>Declaro que el centro tiene las licencias y autorizaciones necesarias para su actividad.</span></label>
        <label class="lg-check full"><input type="checkbox" id="fi-staff" ${f.declares_qualified_staff?'checked':''}> <span>Declaro que el personal que guía y enseña tiene la titulación profesional exigida.</span></label>
        <div class="field full"><label for="fi-licnote">Licencias y titulaciones (opcional)</label><input id="fi-licnote" maxlength="300" value="${v('licences_note')}" placeholder="Ej.: autorización de la Capitanía, centro PADI 5 estrellas…"></div>
        <h3 class="adl-h full ins-rc-head"><span>Seguro de responsabilidad civil</span><button type="button" class="btn btn-sm" id="fi-rc-buy">Contratar o renovar seguro de RC del centro</button></h3>
        <div class="field"><label for="fi-ins">Aseguradora</label><input id="fi-ins" maxlength="160" value="${v('insurance_company')}"></div>
        <div class="field"><label for="fi-pol">Número de póliza</label><input id="fi-pol" maxlength="160" value="${v('insurance_policy')}"></div>
        <div class="field"><label for="fi-exp">Caduca el</label><input id="fi-exp" type="date" value="${v('insurance_expires_at')}" ${miss.has('insurance_expires_at')?'aria-invalid="true"':''}></div>
        <div class="field"><label for="fi-doc">Certificado de la póliza (PDF o imagen)</label><input id="fi-doc" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"><small>${f.has_insurance_doc?'Ya hay un certificado subido. Si subes otro, lo sustituye.':'Opcional. Solo lo ve la administración.'}</small></div>
        <div class="form-actions full"><button class="btn btn-primary" type="submit">Guardar</button></div></form></section>`;
    const sync=()=>{ const t=$('#fi-type').value; $$('#fi-form [data-for]').forEach(x=>x.hidden=x.dataset.for!==t); }; $('#fi-type').onchange=sync; sync();
    $('#fi-rc-buy').onclick=()=>openInsuranceOffers({kind:'rc_centro',audience:'centro'});
    $('#fi-form').onsubmit=async e=>{ e.preventDefault();
      try{ await postJSON('/api/provider/fiscal',{entity_type:$('#fi-type').value,legal_name:$('#fi-legal').value,tax_id:$('#fi-tax').value,tax_id_country:$('#fi-country').value,
          registration_number:$('#fi-reg').value,birth_date:$('#fi-birth').value,fiscal_address:$('#fi-addr').value,declares_licences:$('#fi-lic').checked,
          declares_qualified_staff:$('#fi-staff').checked,licences_note:$('#fi-licnote').value,insurance_company:$('#fi-ins').value,insurance_policy:$('#fi-pol').value,insurance_expires_at:$('#fi-exp').value});
        const file=$('#fi-doc').files[0]; if(file) await upload('/api/provider/insurance-doc',file);
        toast('Datos guardados.'); renderFiscalCard(mountId); }catch(err){ toast(err.message); } };
  }
  async function renderInfoRequests(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/center/info-requests'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Solicitudes de información</p><h2>Mensajes de buceadores interesados</h2><p>Contesta directamente por email o teléfono. Te llegan también por email.</p></div></div>
      ${d.items.length?`<div class="ir-list">${d.items.map(r=>`<article class="ir-item ${r.read_at?'':'is-new'}" data-id="${r.id}"><header><b>${esc(r.name)}</b> <small>${esc((r.created_at||'').slice(0,16).replace('T',' '))}</small>${r.read_at?'':'<span class="status warn">Nueva</span>'}${r.status==='answered'?'<span class="status good">Contestada</span>':''}</header>
        <p>${esc(r.message)}</p><p class="adl-det"><a href="mailto:${esc(r.email)}">${esc(r.email)}</a>${r.phone?` · <a href="tel:${esc(r.phone.replace(/\s+/g,''))}">${esc(r.phone)}</a>`:''}${r.wanted_date?` · ${esc(wdLegalDate(r.wanted_date))}`:''}${r.participants?` · ${r.participants} pax`:''}</p>
        <div class="form-actions"><button type="button" class="btn ir-read" data-answered="0">Marcar como leída</button><button type="button" class="btn ir-read" data-answered="1">Marcar como contestada</button></div></article>`).join('')}</div>`:'<div class="empty">Todavía no hay solicitudes.</div>'}</section>`;
    $$('.ir-read',mount).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/center/info-requests/read',{id:+b.closest('.ir-item').dataset.id,answered:b.dataset.answered==='1'}); renderInfoRequests(mountId); }catch(err){ toast(err.message); } });
  }
  async function renderProviderStats(mountId,days=30){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/provider/stats?days='+days); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const t=d.totals, z=d.zone; const max=Math.max(1,...d.series.map(x=>x.views));
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Estadísticas</p><h2>Cómo te encuentran los buceadores</h2><p>Datos agregados, sin datos personales. Disponibles en todos los planes.</p></div>
      <label class="field" style="min-width:160px"><span>Periodo</span><select id="ps-days">${[30,90,365].map(n=>`<option value="${n}" ${n===days?'selected':''}>Últimos ${n} días</option>`).join('')}</select></label></div>
      <div class="acc-kpis">${accKpi('eye',t.views,'visitas a tu ficha')}${accKpi('calendar',t.book_clicks,'clics en «Reservar»')}${accKpi('message',t.info_requests,'solicitudes de información')}</div>
      ${z?`<div class="notice">Media de los ${z.providers} centros de ${esc(z.name)}: <b>${z.views}</b> visitas, <b>${z.book_clicks}</b> clics en «Reservar» y <b>${z.info_requests}</b> solicitudes.</div>`:'<p class="adl-det">La comparación con tu zona aparece cuando hay al menos 3 centros más en ella.</p>'}
      ${d.series.length?`<div class="ps-chart" role="img" aria-label="Visitas por día">${d.series.map(x=>`<span style="height:${Math.round(x.views*100/max)}%" title="${esc(x.day)}: ${x.views}"></span>`).join('')}</div>`:''}<div id="${mountId}-vc" class="ps-counter"></div></section>`;
    $('#ps-days').onchange=e=>renderProviderStats(mountId,+e.target.value);
    renderVisitCounter(mountId+'-vc','/api/provider/contador');   // v50.57 (4.2): season, month and since the beginning
  }
  async function renderProviderTools(mountId,isCenter){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    // v50.51 (ASVS V8): each profile sees the exports and the calendar it may read.
    const owner=wdCan('centro'), cobros=wdCan('cobros'), reservas=wdCan('reservas');
    const [ical,widget]=await Promise.all([owner?api('/api/provider/ical').catch(e=>({error:e.message,plan:e.data?.plan_required})):Promise.resolve(null),api('/api/provider/widget').catch(()=>null)]);
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Herramientas</p><h2>Exportar, calendario, widget e importación</h2></div></div>
      <h3 class="adl-h">Exportar mis datos</h3><p class="adl-det">Disponible siempre, en cualquier plan. En Excel o en CSV, con el periodo que elijas; si no hay datos en ese periodo, el archivo sale con las columnas y el aviso «Sin datos en este periodo».</p>
      ${wdExportBox([...(reservas?[['reservas','Reservas'],['clientes','Clientes']]:[]),['servicios','Servicios'],['agenda','Agenda'],...(cobros?[['pagos','Pagos']]:[]),...(isCenter&&owner?[['actividad','Actividad']]:[])])}
      ${!ical?'':`<h3 class="adl-h">Calendario (iCal)</h3>`}
      ${!ical?'':ical.error?`<p class="adl-det">${esc(ical.error)} ${ical.plan?'<a href="#/planes">Ver planes</a>':''}</p>`:`<p class="adl-det">Suscríbete desde Google Calendar, Apple Calendar u Outlook con esta dirección privada. Quien la tenga ve tu agenda: si la compartes por error, genera otra.</p>
        <div class="tl-row"><input id="tl-ical" readonly value="${esc(ical.url||'')}" placeholder="Genera tu dirección privada" aria-label="Dirección del calendario"><button type="button" class="btn" id="tl-ical-copy" ${ical.url?'':'hidden'}>Copiar</button>${owner?`<button type="button" class="btn" id="tl-ical-new">${ical.url?'Generar otra':'Generar dirección'}</button>`:''}</div>`}
      ${widget?`<h3 class="adl-h">Reservas desde tu web y redes</h3>
        <div class="field"><label for="tl-link">Enlace directo (Instagram, Google, tu web)</label><div class="tl-row"><input id="tl-link" readonly value="${esc(widget.link)}"><button type="button" class="btn tl-copy" data-src="tl-link">Copiar</button><a class="btn" href="${esc(widget.whatsapp)}" target="_blank" rel="noopener">Compartir por WhatsApp</a></div></div>
        ${widget.widget?`<div class="field"><label for="tl-iframe">Widget para pegar en tu web</label><div class="tl-row"><textarea id="tl-iframe" rows="3" readonly>${esc(widget.iframe)}</textarea><button type="button" class="btn tl-copy" data-src="tl-iframe">Copiar</button></div></div>`:'<p class="adl-det">El widget para tu web está incluido en los planes con motor de reservas. <a href="#/planes">Ver planes</a></p>'}`:''}
      ${isCenter&&owner?`<h3 class="adl-h">Importar clientes (CSV)</h3><p class="adl-det">Usa la <a href="/api/center/import/template" download>plantilla</a> (nombre, email, teléfono, titulación, notas). Antes de importar verás una vista previa con los duplicados. Los clientes importados son solo tuyos: no reciben correos de WORLDIVES.</p>
        <div class="tl-row"><input type="file" id="tl-csv" accept=".csv,text/csv" aria-label="Archivo CSV de clientes"><button type="button" class="btn" id="tl-preview">Vista previa</button></div><div id="tl-import"></div>`:''}</section>`;
    wdBindExports(mount);
    $$('.tl-copy',mount).forEach(b=>b.onclick=()=>{ const el=$('#'+b.dataset.src); el.select(); navigator.clipboard?.writeText(el.value).catch(()=>{}); toast('Copiado.'); });
    $('#tl-ical-copy')?.addEventListener('click',()=>{ navigator.clipboard?.writeText($('#tl-ical').value).catch(()=>{}); toast('Copiado.'); });
    $('#tl-ical-new')?.addEventListener('click',async()=>{ if($('#tl-ical').value&&!confirm('La dirección actual dejará de funcionar. ¿Generar otra?')) return; try{ await postJSON('/api/provider/ical/regenerate',{}); renderProviderTools(mountId,isCenter); }catch(err){ toast(err.message); } });
    let csvText='';
    $('#tl-preview')?.addEventListener('click',async()=>{ const f=$('#tl-csv').files[0]; if(!f){ toast('Elige el archivo CSV.'); return; } csvText=await f.text();
      try{ const r=await postJSON('/api/center/import',{csv:csvText}); const S={new:['Nuevo','good'],duplicate:['Duplicado','warn'],error:['Error','bad']};
        $('#tl-import').innerHTML=`<p><b>${r.summary.new}</b> nuevos · <b>${r.summary.duplicate}</b> duplicados · <b>${r.summary.error}</b> con errores</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Línea</th><th>Nombre</th><th>Email</th><th>Teléfono</th><th>Estado</th></tr></thead><tbody>${r.rows.slice(0,300).map(x=>`<tr><td>${x.line}</td><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.phone)}</td><td><span class="status ${S[x.status][1]}">${S[x.status][0]}</span> ${esc(x.note)}</td></tr>`).join('')}</tbody></table></div>
          ${r.summary.new?`<div class="form-actions"><button type="button" class="btn btn-primary" id="tl-confirm">Importar ${r.summary.new} clientes</button></div>`:''}`;
        $('#tl-confirm')?.addEventListener('click',async()=>{ try{ const c=await postJSON('/api/center/import',{csv:csvText,confirm:true}); toast(`${c.created} clientes importados.`); $('#tl-import').innerHTML=''; }catch(err){ toast(err.message); } });
      }catch(err){ toast(err.message); } });
  }
  // v50.49: what the person signed in can do in the panel (permissions of their role in this centre).
  function wdCan(p){ const m=state.me; if(!m) return false; if(Array.isArray(m.permissions)&&m.permissions.length) return m.permissions.includes(p); return (m.member_role||'owner')==='owner'; }
  async function renderTeam(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/center/team'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const me=state.me?.user?.id; const R=d.roles, RL=d.role_list||[], PERM=d.permissions||[];
    const opts=(sel)=>RL.map(r=>`<option value="${esc(r.key)}" ${r.key===sel?'selected':''}>${esc(r.name)}</option>`).join('');
    const checks=(r,pre)=>PERM.map(p=>`<label class="tr-perm"><input type="checkbox" value="${esc(p.key)}" ${r.permissions.includes(p.key)?'checked':''} ${r.owner?'disabled':''} aria-describedby="${pre}-h-${esc(p.key)}"> <span><b>${esc(p.name)}</b><small id="${pre}-h-${esc(p.key)}">${esc(p.help)}</small></span></label>`).join('');
    const rules=d.rules||{};
    mount.innerHTML=`<section class="mm-module tq-links-module" id="tq-links-mount"></section><section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Equipo del centro</p><h2>Cuentas del centro</h2>
      <p>Cada persona tiene un perfil. Abajo puedes cambiar lo que puede hacer cada perfil y crear los tuyos (por ejemplo, «Instructor máster»). La app del móvil muestra a cada persona solo lo que su perfil permite.</p></div></div>
      <div class="table-wrap"><table class="data-table"><thead><tr><th>Persona</th><th>Perfil</th><th></th></tr></thead><tbody>${d.members.map(m=>`<tr><td><b>${esc(m.fullname)}</b><div class="adl-det">${esc(m.email)}</div></td>
        <td><label class="sr-only" for="tm-r-${m.id}">Perfil de ${esc(m.fullname)}</label><select id="tm-r-${m.id}" class="tm-role" data-id="${m.id}" ${m.id===me?'disabled':''}>${opts(m.member_role)}${R[m.member_role]?'':`<option value="" selected>Perfil borrado</option>`}</select></td>
        <td>${m.id===me?'<small>Tú</small>':`${m.member_role!=='owner'?`<button type="button" class="btn tm-sessions" data-id="${m.id}" data-name="${esc(m.fullname||'')}">Sesiones</button> `:''}<button type="button" class="btn tm-remove" data-id="${m.id}">Quitar</button>`}</td></tr>`).join('')}</tbody></table></div>
      ${d.invites.length?`<h3 class="adl-h">Invitaciones pendientes</h3><ul class="tm-inv">${d.invites.map(i=>`<li>${esc(i.email)} · ${esc(R[i.member_role]||'Perfil borrado')} · caduca ${esc(wdLegalDate(i.expires_at))} <button type="button" class="btn-link tm-revoke" data-id="${i.id}">Anular</button></li>`).join('')}</ul>`:''}
      <h3 class="adl-h" id="tr-h">Perfiles y lo que puede hacer cada uno</h3>
      <p class="adl-det"><span>Solo tú, como propietario, puedes:</span> ${(d.owner_only||[]).map(x=>`<span>${esc(x)}</span>`).join(' · ')}.</p>
      <div class="tr-list">${RL.map(r=>`<details class="tr-role" data-key="${esc(r.key)}"><summary><b>${esc(r.name)}</b> <small><span class="num">${r.members}</span> <span>${r.members===1?'persona':'personas'}</span>${r.builtin?'':' · <span>perfil de tu centro</span>'}${r.builtin&&r.changed?' · <span>cambiado</span>':''}</small></summary>
        ${r.owner?'<p class="adl-det">El propietario siempre puede hacerlo todo.</p>':`<p class="tq-role-link">${rules.blocked||(rules.only_reception&&r.key!=='reception')?`<button type="button" class="btn btn-sm" disabled>${wdIcon('lock',14)} <span>Enlazar persona</span></button> <small>${esc(translateString(rules.blocked?'Disponible en el plan Motor de reservas':'Disponible en el plan Pro'))}</small>`:`<button type="button" class="btn btn-sm tq-link-role" data-role="${esc(r.key)}">${wdIcon('qr',14)} <span>Enlazar persona</span></button>`}</p><form class="tr-form" data-key="${esc(r.key)}">${r.builtin?'':`<div class="field"><label for="tr-n-${esc(r.key)}">Nombre del perfil</label><input id="tr-n-${esc(r.key)}" class="tr-name" maxlength="40" value="${esc(r.name)}" required></div>`}
          <fieldset class="tr-perms"><legend class="sr-only">Qué puede hacer ${esc(r.name)}</legend>${checks(r,'tr-'+r.key)}</fieldset>
          <div class="form-actions"><button type="submit" class="btn btn-primary">Guardar</button>${r.builtin&&r.changed?`<button type="button" class="btn tr-reset">Volver a lo de siempre</button>`:''}${r.builtin?'':`<button type="button" class="btn tr-del">Borrar perfil</button>`}</div></form>`}</details>`).join('')}
        ${rules.custom_profiles===false?`<div class="tr-role tq-locked"><b>+ Crear un perfil</b>${tqPlans('Disponible en el plan Pro')}</div>`:`<details class="tr-role" id="tr-new"><summary><b>+ Crear un perfil</b></summary><form class="tr-form" data-key=""><div class="field"><label for="tr-n-new">Nombre del perfil</label><input id="tr-n-new" class="tr-name" maxlength="40" placeholder="Instructor máster" required></div>
          <fieldset class="tr-perms"><legend class="sr-only">Qué puede hacer el perfil nuevo</legend>${checks({permissions:['checkin'],owner:false},'tr-new')}</fieldset>
          <div class="form-actions"><button type="submit" class="btn btn-primary">Crear perfil</button></div></form></details>`}</div></section>`;
    renderTeamLinks($('#tq-links-mount',mount),d,()=>renderTeam(mountId));
    $$('.tq-link-role',mount).forEach(b=>b.onclick=()=>tqOpenLink(d,{onDone:()=>renderTeam(mountId),role:b.dataset.role}));
    $$('.tm-role',mount).forEach(x=>x.onchange=async()=>{ if(!x.value) return; try{ await postJSON('/api/center/team/role',{user_id:+x.dataset.id,member_role:x.value}); toast('Perfil cambiado.'); }catch(err){ toast(err.message); renderTeam(mountId); } });
    $$('.tm-remove',mount).forEach(b=>b.onclick=async()=>{ if(!confirm('Esta persona dejará de tener acceso al centro. ¿Continuar?')) return; try{ await postJSON('/api/center/team/remove',{user_id:+b.dataset.id}); renderTeam(mountId); }catch(err){ toast(err.message); } });
    // v50.55 (encargo 2): the owner sees where each person of his team is signed in and can close all their sessions.
    $$('.tm-sessions',mount).forEach(b=>b.onclick=async()=>{ let d2; try{ d2=await api('/api/center/team/sessions'); }catch(err){ toast(err.message); return; }
      const m=(d2.items||[]).find(x=>x.user_id===+b.dataset.id)||{devices:[]};
      const {el,close}=wdOpenModal({id:'tm-sess',size:'sm',title:translateString('Sesiones de')+' '+b.dataset.name,
        body:(m.devices.length?m.devices.map(x=>`<div class="acc-doc"><span><strong>${esc(x.device)}</strong>${x.system?` · ${esc(x.system)}`:''}<small>${esc(translateString('Última actividad'))}: ${esc(wdDeadline(x.last_seen))}</small></span></div>`).join(''):`<p class="acc-empty">${esc(translateString('No tiene ninguna sesión abierta.'))}</p>`)
          +`<p class="acc-help">${esc(translateString('Al cerrarlas tendrá que volver a entrar con su contraseña; en el móvil se borran los datos guardados.'))}</p>`,
        footer:`<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="tm-sess-ok" ${m.devices.length?'':'disabled'}>${esc(translateString('Cerrar todas sus sesiones'))}</button>`});
      $('#tm-sess-ok',el).onclick=async()=>{ try{ const r=await postJSON('/api/center/team/sessions/close',{user_id:+b.dataset.id}); close(); toast(translateString('Sesiones cerradas')+`: ${r.closed}`); }catch(err){ toast(err.message); } }; });
    $$('.tm-revoke',mount).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/center/team/invite/revoke',{id:+b.dataset.id}); renderTeam(mountId); }catch(err){ toast(err.message); } });
    const reopen=async(key)=>{ await renderTeam(mountId); const el=key&&document.querySelector(`#${mountId} .tr-role[data-key="${key}"]`); if(el){ el.open=true; el.scrollIntoView({block:'nearest'}); } };
    $$('.tr-form',mount).forEach(f=>{
      f.onsubmit=async e=>{ e.preventDefault(); const body={key:f.dataset.key||undefined,permissions:$$('input[type=checkbox]:checked',f).map(x=>x.value)}; const n=$('.tr-name',f); if(n) body.name=n.value;
        try{ const r=await postJSON('/api/center/team/roles/save',body); toast(f.dataset.key?'Perfil guardado.':'Perfil creado.'); reopen(r.key); }catch(err){ toast(err.message); } };
      $('.tr-reset',f)?.addEventListener('click',async()=>{ try{ await postJSON('/api/center/team/roles/save',{key:f.dataset.key,reset:true}); toast('Perfil como siempre.'); reopen(f.dataset.key); }catch(err){ toast(err.message); } });
      $('.tr-del',f)?.addEventListener('click',async()=>{ if(!confirm('¿Borrar este perfil?')) return; try{ await postJSON('/api/center/team/roles/delete',{key:f.dataset.key}); toast('Perfil borrado.'); renderTeam(mountId); }catch(err){ toast(err.message); } });
    });
  }
  const ACTIVITY_LABELS={booking_created:'Reserva creada',booking_status_changed:'Estado de reserva cambiado',service_created:'Servicio creado',service_updated:'Servicio modificado',slot_created:'Salida creada',
    center_profile_updated:'Datos del centro modificados',provider_fiscal_data_updated:'Datos fiscales modificados',team_invited:'Invitación al equipo',team_role_changed:'Perfil del equipo cambiado',
    team_member_removed:'Persona quitada del equipo',team_joined:'Se une al equipo',clients_imported:'Clientes importados',provider_export:'Exportación de datos',ical_regenerated:'Nueva dirección de calendario',
    review_reply_saved:'Respuesta a una reseña',team_link_requested:'Petición para unirse al equipo',team_link_accepted:'Acepta unirse al equipo',team_link_declined:'Rechaza unirse al equipo',
    team_link_ended:'Sale del equipo',team_link_paused:'Equipo: en pausa',team_link_reactivated:'Equipo: reactivado',team_person_scanned:'QR personal escaneado',team_transfer_requested:'Transferencia de la propiedad pedida',
    team_transfer_confirmed:'Propiedad transferida',team_context_switch:'Cambio de centro',phones_viewed:'Teléfonos de clientes vistos',new_device_login:'Entrada desde un dispositivo nuevo',
    login:'Inicio de sesión',service_slot_updated:'Salida modificada',team_sessions_closed:'Sesiones del equipo cerradas',team_invite_revoked:'Invitación anulada',team_role_saved:'Perfil guardado',
    team_role_deleted:'Perfil borrado',booking_rescheduled:'Reserva cambiada de salida',refund_issued:'Devolución',points_granted:'Puntos concedidos'};
  // v50.57 (4.4): QR codes with a short, stable address (…/q/abc234) that lead to a page of WORLDIVES chosen from a
  // list: the administration (registrations, dive sites, centres, experiences…) and each centre from its panel (its
  // pages). Nobody types an address. «Probar enlace» opens the real destination without counting a scan.
  async function renderShortLinks(mountId,scope){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml, admin=scope==='admin';
    const base=admin?'/api/admin/short-links':'/api/center/short-links';
    let d; try{ d=await api(base); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const canEdit=admin||wdCan('centro'), refresh=()=>renderShortLinks(mountId,scope);
    const when=v=>{ try{ return new Date(v).toLocaleDateString(wdLocale(),{day:'numeric',month:'short',year:'numeric'}); }catch{ return ''; } };
    const card=q=>`<article class="sl-card" data-id="${q.id}">
      <img class="sl-qr" src="/api/short-links/${q.id}/qr.svg" alt="${esc(translateString('Código QR'))}" width="128" height="128" loading="lazy">
      <div class="sl-body"><h3>${esc(q.name)}</h3>
        <p class="sl-dest">${wdIcon('arrow',14)} <span>${esc(q.dest_label)}</span>${q.ref_name?` · <b translate="no">${esc(q.ref_name)}</b>`:''}</p>
        ${q.broken?`<p class="sl-warn">${wdIcon('alert',14)} <span>El destino ya no existe: lleva a su lista. Edítalo para elegir otro.</span></p>`:''}
        ${q.caption?`<p class="sl-cap" translate="no">«${esc(q.caption)}»</p>`:''}
        <p class="sl-url"><code translate="no">${esc(q.short_url.replace(/^https?:\/\//,''))}</code> <button type="button" class="btn-link sl-copy">Copiar</button></p>
        <p class="sl-scans"><b>${Number(q.scans||0).toLocaleString(wdLocale())}</b> <span>${q.scans===1?'escaneo':'escaneos'}</span>${q.last_scan_at?` · <span>último:</span> ${esc(when(q.last_scan_at))}`:''}</p>
        <div class="sl-actions"><a class="btn btn-sm sl-try" href="/q/${esc(q.code)}?prueba=1" target="_blank" rel="noopener">Probar enlace</a>
          <a class="btn btn-sm" href="/api/short-links/${q.id}/qr.png?descargar=1" download>PNG</a><a class="btn btn-sm" href="/api/short-links/${q.id}/qr.svg?descargar=1" download>SVG</a>
          <a class="btn btn-sm" href="/api/short-links/${q.id}/qr.pdf?descargar=1&lang=${currentLanguage()}" download>PDF</a>
          ${canEdit?'<button type="button" class="btn btn-sm sl-edit">Editar</button><button type="button" class="btn btn-sm danger sl-del">Borrar</button>':''}</div></div></article>`;
    mount.innerHTML=`<section class="mm-module sl-module"><div class="svc-head"><div><p class="eyebrow">${admin?'Códigos QR':'QR para imprimir'}</p><h2>${admin?'Códigos QR de WORLDIVES':'Los QR de tu centro'}</h2>
      <p>Elige a dónde lleva cada QR de la lista. Su dirección corta no cambia aunque cambie la web: los QR ya impresos siguen funcionando. Solo se cuenta cuántas veces se escanea, sin datos de nadie.</p></div>
      ${canEdit?'<button type="button" class="btn btn-primary" id="sl-new">+ Nuevo QR</button>':''}</div>
      ${d.items.length?`<div class="sl-grid">${d.items.map(card).join('')}</div>`:'<div class="empty"><p>Aún no hay ningún QR. Crea el primero: elige a dónde lleva y descárgalo en PNG, SVG o PDF.</p></div>'}</section>`;
    translateTree(mount);
    $('#sl-new',mount)?.addEventListener('click',()=>openForm(null));
    $$('.sl-card',mount).forEach(c=>{ const q=d.items.find(x=>x.id===Number(c.dataset.id));
      $('.sl-copy',c).onclick=async()=>{ try{ await navigator.clipboard.writeText(q.short_url); toast('Dirección copiada.'); }catch{ toast(q.short_url); } };
      $('.sl-edit',c)?.addEventListener('click',()=>openForm(q));
      $('.sl-del',c)?.addEventListener('click',async()=>{
        if(!await wdConfirm({title:`¿Borrar «${q.name}»?`,text:'Si ya está impreso, al escanearlo llevará a la portada de WORLDIVES. No se puede deshacer.',ok:'Borrar',danger:true})) return;
        try{ await postJSON(base+'/delete',{id:q.id}); toast('QR borrado.'); refresh(); }catch(err){ toast(err.message); } }); });
    function openForm(q){
      const v=q||{name:'',dest:'',ref_id:null,ref_name:'',caption:''}; let chosen=v.ref_id?{id:v.ref_id,name:v.ref_name||translateString('(ya no existe)')}:null;
      const opts=d.dests.map(x=>`<option value="${x.key}" ${x.key===v.dest?'selected':''} ${x.not_yet?'disabled':''}>${esc(x.label)}${x.not_yet?' '+esc(translateString('(cuando exista)')):''}</option>`).join('');
      const {el,close}=wdOpenModal({id:'sl-form',title:q?'Editar QR':'Nuevo QR',subtitle:'El destino se elige de la lista: no se puede escribir una dirección.',
        body:`<form id="slf" class="sl-form"><div class="field"><label for="slf-name">Nombre interno</label><input id="slf-name" maxlength="80" required value="${esc(v.name)}" placeholder="${esc(translateString('Por ejemplo: Recepción feria Madrid'))}"><small>Solo lo ves tú; no sale en el QR.</small></div>
          <div class="field"><label for="slf-dest">A dónde lleva</label><select id="slf-dest" required><option value="">${esc(translateString('Elige un destino'))}</option>${opts}</select></div>
          <div class="field" id="slf-item" hidden><label for="slf-q" id="slf-item-l"></label>
            ${admin?'<input id="slf-q" type="search" autocomplete="off" placeholder=""><div id="slf-results" class="sl-results" role="listbox"></div>':`<select id="slf-svc">${(d.services||[]).map(x=>`<option value="${x.id}" ${x.id===v.ref_id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>`}
            <p id="slf-chosen" class="sl-chosen" hidden></p></div>
          <div class="field"><label for="slf-cap">Texto del PDF (opcional)</label><input id="slf-cap" maxlength="80" value="${esc(v.caption||'')}" placeholder="${esc(translateString('Por ejemplo: Regístrate como centro'))}"><small>Sale encima del QR en el PDF para imprimir.</small></div></form>`,
        footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="submit" form="slf" class="btn btn-primary">Guardar QR</button>'});
      translateTree(el);
      const need=()=>(d.dests.find(x=>x.key===$('#slf-dest',el).value)||{}).needs;
      const ITEM={punto:'Busca el punto de buceo',centro:'Busca el centro',experiencia:'Busca la experiencia',servicio:'Elige el servicio'};
      const showChosen=()=>{ const p=$('#slf-chosen',el); if(!admin) return; p.hidden=!chosen; p.innerHTML=chosen?`${wdIcon('check',14)} <b translate="no">${esc(chosen.name)}</b> <button type="button" class="btn-link" id="slf-clear">${esc(translateString('Cambiar'))}</button>`:'';
        $('#slf-clear',el)?.addEventListener('click',()=>{ chosen=null; showChosen(); $('#slf-q',el)?.focus(); }); };
      const showItem=()=>{ const n=need(); $('#slf-item',el).hidden=!n; if(!n) return; $('#slf-item-l',el).textContent=translateString(ITEM[n]||'');
        if(admin){ $('#slf-q',el).placeholder=translateString('Escribe parte del nombre'); if(chosen&&q&&q.dest!==$('#slf-dest',el).value) chosen=null; showChosen(); } };
      let t0=0;
      $('#slf-q',el)?.addEventListener('input',e=>{ clearTimeout(t0); const text=e.target.value.trim(); t0=setTimeout(async()=>{
        const box=$('#slf-results',el); if(text.length<2){ box.innerHTML=''; return; }
        try{ const r=await api(`/api/admin/short-links/search?tipo=${need()}&q=${encodeURIComponent(text)}`);
          box.innerHTML=r.items.length?r.items.map(x=>`<button type="button" class="sl-hit" role="option" data-id="${x.id}" data-name="${esc(x.name)}"><b translate="no">${esc(x.name)}</b>${x.sub?` <small translate="no">${esc(x.sub)}</small>`:''}</button>`).join(''):`<p class="muted">${esc(translateString('Nada con ese nombre.'))}</p>`;
          $$('.sl-hit',box).forEach(b=>b.onclick=()=>{ chosen={id:Number(b.dataset.id),name:b.dataset.name}; box.innerHTML=''; $('#slf-q',el).value=''; showChosen(); });
        }catch(err){ box.innerHTML=`<p class="muted">${esc(err.message)}</p>`; } },250); });
      $('#slf-dest',el).addEventListener('change',showItem); showItem();
      $('#slf',el).onsubmit=async e=>{ e.preventDefault(); const n=need();
        const ref=n?(admin?chosen?.id:Number($('#slf-svc',el)?.value||0)):null;
        try{ await postJSON(base+'/save',{id:q?.id,name:$('#slf-name',el).value,dest:$('#slf-dest',el).value,ref_id:ref||null,caption:$('#slf-cap',el).value});
          close(); toast('QR guardado.'); refresh(); }catch(err){ toast(err.message); } };
    }
  }
  // v50.57 (4.2): visits (pages seen and visitors of each day) and bookings (total, by mode, amount) of the season, the
  // month and since the beginning.
  async function renderVisitCounter(mountId,url){
    const el=document.getElementById(mountId); if(!el) return; const esc=escapeHtml;
    let d; try{ d=await api(url); }catch(err){ el.innerHTML=''; return; }
    const P=d.periods, n=v=>Number(v||0).toLocaleString(wdLocale()), dm=v=>{ const [y,m,dd]=String(v).split('-'); return `${dd}/${m}`; };
    const head=p=>p.key==='temporada'?`Temporada <small>${esc(dm(p.from))}–${esc(dm(p.to))}</small>`:p.key==='mes'?'Este mes':'Desde el inicio';
    const money=p=>p.amounts.length?p.amounts.map(a=>esc(wdMoney(a.amount,a.currency))).join(' · '):'—';
    const modes=[...new Map(P.flatMap(p=>p.by_mode).map(m=>[m.mode,m.label])).entries()];
    const row=(label,f,cls='')=>`<tr class="${cls}"><th scope="row">${label}</th>${P.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`;
    el.innerHTML=`<section class="vc-block" aria-labelledby="${mountId}-t"><h3 id="${mountId}-t">Visitas y reservas</h3><div class="table-wrap"><table class="vc-table">
      <thead><tr><th></th>${P.map(p=>`<th scope="col">${head(p)}</th>`).join('')}</tr></thead><tbody>
      ${row('Páginas vistas',p=>n(p.views))}${row('Visitantes únicos <small>(de cada día)</small>',p=>n(p.uniques))}
      ${row('Reservas',p=>n(p.bookings))}${modes.map(([k,l])=>row(`<span>${esc(l)}</span>`,p=>n(p.by_mode.find(m=>m.mode===k)?.bookings),'vc-sub')).join('')}
      ${row('Importe reservado <small>(confirmadas)</small>',money)}</tbody></table></div>
      <p class="vc-note">Sin cookies ni datos de nadie: el servidor solo suma. Cada visitante cuenta una vez al día; no se cuentan los robots ni la administración.</p></section>`;
    translateTree(el);
  }
  async function renderActivity(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/center/activity'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Registro de actividad</p><h2>Quién ha hecho qué en el centro</h2></div></div>
      ${wdExportBox([['actividad','Exportar la actividad']])}
      ${d.items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Persona</th><th>Acción</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc((x.created_at||'').slice(0,16).replace('T',' '))}</td><td><span translate="no">${esc(x.actor_name||x.fullname||'—')}</span>${x.actor_role?` <small>(${esc(x.actor_role)})</small>`:''}</td><td>${esc(ACTIVITY_LABELS[x.action]||x.action.replace(/_/g,' '))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Todavía no hay actividad.</div>'}</section>`;
    wdBindExports(mount);
  }
  // ---------------------------------------------------------------- v50.58 · equipo enlazado por QR (encargo del 16/10/2026)
  // Cada persona tiene su QR personal («Mi QR»: cambia cada minuto y sirve una vez), un código corto de 10 minutos y
  // «Compartir para enlazar» (un enlace de 24 horas y un uso). El centro la enlaza en «Equipo → Enlazar persona» (cámara,
  // código o correo); la persona dice que sí en «Mi equipo» y elige el centro en el selector de perfil del menú. «Mi
  // agenda» junta su trabajo propio y lo que le asigna cada centro, cada centro con su color. El servidor decide todo.
  const TQ_STATE={pending:['Pendiente de aceptar','warn'],active:['Activo','good'],paused:['En pausa','warn'],ended:['Terminado',''],cancelled:['Anulado',''],declined:['Rechazado','bad']};
  const tqChip=x=>{ const s=TQ_STATE[x.status]||[x.status_name||x.status,'']; return `<span class="status ${s[1]}">${escapeHtml(s[0])}</span>`; };
  const tqDay=d=>{ try{ return new Date(String(d).slice(0,10)+'T12:00:00').toLocaleDateString(wdLocale(),{day:'numeric',month:'short'}); }catch{ return String(d||''); } };
  const tqWhen=v=>{ try{ return new Date(typeof v==='number'?v*1000:v).toLocaleString(wdLocale(),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}); }catch{ return ''; } };
  const tqHere=name=>location.hash.replace(/^#\/?/,'').split('?')[0]===name;
  const tqCode=c=>String(c||'').replace(/^(.{3})/,'$1 ');
  const tqMMSS=s=>{ s=Math.max(0,Math.round(s)); return Math.floor(s/60)+':'+String(s%60).padStart(2,'0'); };
  const tqAvatar=(photo,name,size=40)=>photo?`<img class="tq-avatar" src="${escapeHtml(photo)}" alt="" width="${size}" height="${size}" loading="lazy">`:`<span class="avatar tq-avatar" aria-hidden="true">${escapeHtml(initials(name||''))}</span>`;
  const tqLogo=x=>x.logo?`<img class="tq-logo" src="${escapeHtml(x.logo)}" alt="" width="44" height="44" loading="lazy">`:`<span class="tq-logo" aria-hidden="true">${escapeHtml(initials(x.center_name||''))}</span>`;
  const tqIso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const tqPlans=msg=>`<p class="tq-lock">${wdIcon('lock',16)} <span>${escapeHtml(msg)}</span> <a href="#/admin?tab=plan">Ver planes</a></p>`;
  // The QR of a person is read with the camera: inside the app with its own scanner, in the browser with BarcodeDetector.
  async function tqReadCamera(video){
    const S=window.Capacitor?.Plugins?.CapacitorBarcodeScanner;
    if(S){ const r=await S.scanBarcode({hint:0,scanInstructions:translateString('Apunta al QR de la persona'),scanButton:false,cameraDirection:1}); return r?.ScanResult||r?.scanResult||''; }
    if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia) throw new Error('Este navegador no puede usar la cámara aquí: escribe el código de 6 letras que la persona ve debajo de su QR.');
    let det, stream;
    try{ det=new BarcodeDetector({formats:['qr_code']}); stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}}); }
    catch{ throw new Error('No se ha podido abrir la cámara: escribe el código de 6 letras que la persona ve debajo de su QR.'); }
    video.srcObject=stream; video.hidden=false; await video.play();
    return new Promise((ok,ko)=>{ let done=false;
      const stop=v=>{ if(done) return; done=true; stream.getTracks().forEach(t=>t.stop()); video.hidden=true; v instanceof Error?ko(v):ok(v); };
      const tick=async()=>{ if(done) return; if(!video.isConnected){ stop(''); return; } try{ const f=await det.detect(video); if(f[0]){ stop(f[0].rawValue); return; } }catch{} requestAnimationFrame(tick); };
      tick(); setTimeout(()=>stop(new Error('No se ha leído ningún QR. Vuelve a probar o escribe el código.')),30000); });
  }

  // «Mi QR»: el QR de este minuto, el código corto de estos 10 minutos y «Compartir para enlazar».
  let tqTimer=0, tqLoad=null;
  document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&tqLoad&&tqHere('mi-qr')) tqLoad(); });
  async function renderMyQR(){
    if(!state.me){ goLogin(); return; } const esc=escapeHtml; clearInterval(tqTimer);
    setApp(`<section class="page tq-page">${wdCrumbs([['Mi área','#/area'],['Mi QR','']])}
      ${wdIsDiver()&&!((state.me.profiles||[]).length>1||(state.me.team_requests||0)>0)
        ?`<header class="tq-head"><p class="eyebrow">Mi QR</p><h1>Mi QR</h1><p class="lead">Enséñalo en el centro para el check-in o para añadir un Buddy. No lleva tus datos, cambia cada minuto y sirve una sola vez.</p></header>`
        :`<header class="tq-head"><p class="eyebrow">Mi QR</p><h1>Tu QR para unirte a un equipo</h1>
        <p class="lead">Enséñalo en el centro: lo escanean en «Equipo → Enlazar persona» y te llega una petición que tú aceptas. No lleva tus datos, cambia cada minuto y sirve una sola vez.</p></header>`}
      <div class="tq-grid"><div class="tq-card" id="tq-card"><div class="tq-skel" aria-hidden="true"></div></div>
        ${wdIsDiver()&&!((state.me.profiles||[]).length>1||(state.me.team_requests||0)>0)?`<div class="tq-side"><section class="tq-box"><h2>Buddies</h2><p>Si tu compañero lo escanea con su móvil, te llega su petición de Buddy en «Buddies».</p><div class="tq-actions"><a class="btn" href="#/buddies">${wdIcon('users',16)} <span>Mis Buddies</span></a></div></section></div></div></section>`:''}
        <div class="tq-side" ${wdIsDiver()&&!((state.me.profiles||[]).length>1||(state.me.team_requests||0)>0)?'hidden':''}><section class="tq-box"><h2>¿No estás en el centro?</h2><p>Crea un enlace de un solo uso y mándalo por WhatsApp o por correo. Dura 24 horas y lo puedes anular.</p>
            <button type="button" class="btn btn-primary" id="tq-share">${wdIcon('link',16)} <span>Compartir para enlazar</span></button><div id="tq-share-out"></div><div id="tq-shares"></div></section>
          <section class="tq-box"><h2>Tus equipos</h2><p>Las peticiones de los centros, los equipos donde estás y lo que te toca cada día.</p>
            <div class="tq-actions"><a class="btn" href="#/mi-equipo">${wdIcon('users',16)} <span>Mi equipo</span></a><a class="btn" href="#/mi-agenda">${wdIcon('calendar',16)} <span>Mi agenda</span></a></div></section></div></div></section>`);
    const card=$('#tq-card'); let left=0, period=60, codeLeft=0, busy=false;
    const load=tqLoad=async()=>{ if(busy||!card.isConnected) return; busy=true;
      try{ const d=await api('/api/my/qr'); left=period=d.refresh_in||60; codeLeft=d.code_expires_in;
        card.innerHTML=`<div class="tq-person">${tqAvatar(d.photo,d.name,48)}<div><b translate="no">${esc(d.name||'')}</b><small>${esc(d.account_label||'')}</small></div></div>
          <div class="tq-qr" role="img" aria-label="${esc(translateString('Tu QR personal'))}">${d.svg}</div>
          <div class="tq-timer"><span class="tq-bar" aria-hidden="true"><i id="tq-bar"></i></span><span><span>Cambia en</span> <b id="tq-left" class="num">${left}</b> <span>s</span></span></div>
          <div class="tq-code"><span>¿No pueden escanearlo? Diles este código:</span><b id="tq-code" translate="no">${esc(tqCode(d.code))}</b>
            <small><span>Caduca en</span> <span id="tq-code-left" class="num">${tqMMSS(codeLeft)}</span> · <span>sirve una vez</span></small></div>`;
        translateTree(card);
      }catch(err){ card.innerHTML=wdBlockError(err); translateTree(card); card.querySelector('[data-block-retry]').onclick=load; }
      finally{ busy=false; } };
    await load();
    tqTimer=setInterval(()=>{ if(!tqHere('mi-qr')||!card.isConnected){ clearInterval(tqTimer); return; } if(document.hidden) return;
      left--; codeLeft--;
      const l=$('#tq-left'), b=$('#tq-bar'), c=$('#tq-code-left');
      if(l) l.textContent=Math.max(0,left); if(b) b.style.width=Math.max(0,left/period*100)+'%'; if(c) c.textContent=tqMMSS(codeLeft);
      if(left<=0||codeLeft<=0) load(); },1000);
    const shares=async()=>{ const box=$('#tq-shares'); if(!box) return; let r; try{ r=await api('/api/my/qr/shares'); }catch{ return; }
      const open=r.items.filter(x=>x.state==='open');
      box.innerHTML=open.length?`<h3 class="tq-h3">Enlaces sin usar</h3><ul class="tq-share-list">${open.map(x=>`<li><span><span>Caduca</span> <span class="num">${esc(tqWhen(x.expires_at))}</span></span><button type="button" class="btn-link" data-revoke="${x.id}">Anular</button></li>`).join('')}</ul>`:'';
      translateTree(box);
      $$('[data-revoke]',box).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/my/qr/share/revoke',{id:+b.dataset.revoke}); toast('Enlace anulado: ya no sirve.'); $('#tq-share-out').innerHTML=''; shares(); }catch(err){ toast(err.message); } }); };
    shares();
    $('#tq-share').onclick=async()=>{ try{ const r=await postJSON('/api/my/qr/share',{}); const out=$('#tq-share-out');
        const msg=translateString('Para añadirme a tu equipo en WORLDIVES, abre este enlace (sirve una vez y dura 24 horas):')+' '+r.url;
        out.innerHTML=`<div class="tq-share-new"><label for="tq-share-url">Tu enlace</label><input id="tq-share-url" readonly value="${esc(r.url)}" translate="no">
          <div class="tq-actions"><button type="button" class="btn btn-sm" id="tq-copy">Copiar</button>${navigator.share?'<button type="button" class="btn btn-sm" id="tq-native">Compartir…</button>':''}
            <a class="btn btn-sm" href="https://wa.me/?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener">WhatsApp</a><a class="btn btn-sm" href="mailto:?subject=${encodeURIComponent(translateString('Mi enlace para tu equipo'))}&amp;body=${encodeURIComponent(msg)}">Correo</a></div></div>`;
        translateTree(out);
        $('#tq-copy').onclick=async()=>{ try{ await navigator.clipboard.writeText(r.url); toast('Enlace copiado.'); }catch{ $('#tq-share-url').select(); } };
        $('#tq-native')?.addEventListener('click',()=>navigator.share({text:msg}).catch(()=>{}));
        shares(); }catch(err){ toast(err.message); } };
  }

  // «Mi equipo»: las peticiones de los centros (aceptar o rechazar) y los centros donde la persona está.
  async function tqActivateFreelance(roleName){
    return new Promise(res=>{ const {el,close}=wdOpenModal({id:'tq-free',size:'sm',title:escapeHtml(translateString('Activa tu perfil de freelance')),
      body:`<p><span>Perfil en el equipo</span>: <b>${escapeHtml(roleName)}</b></p><p>Para este perfil necesitas tu perfil de freelance. Es gratis: sigues teniendo todo lo de tu cuenta y, además, estás en los equipos de los centros y ves en tu agenda lo que te asignan.</p>
        <p class="adl-det">Con el plan gratuito no tienes servicios, reservas ni cobros propios.</p>
        <label class="lg-check"><input type="checkbox" id="tq-free-ok"> <span>Acepto las <a href="#/legal/condiciones-centros" target="_blank" rel="noopener">condiciones para profesionales</a>.</span></label>`,
      footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="tq-free-go" disabled>Activar y aceptar</button>'});
      translateTree(el); let done=false; const fin=v=>{ if(done) return; done=true; res(v); };
      $('#tq-free-ok',el).onchange=e=>{ $('#tq-free-go',el).disabled=!e.target.checked; };
      $('#tq-free-go',el).onclick=()=>{ fin(true); close(); };
      new MutationObserver((m,o)=>{ if(!el.isConnected){ o.disconnect(); fin(false); } }).observe(document.body,{childList:true}); });
  }
  async function tqSwitch(centerId,label){
    try{ await postJSON('/api/team/switch',{center:+centerId||0}); await loadMe();
      toast(centerId?translateString('Ahora trabajas en')+' '+label:translateString('Has vuelto a tu perfil.')); wdGo(centerId?'#/admin':'#/area'); }
    catch(err){ toast(err.message); }
  }
  async function renderMyTeams(){
    if(!state.me){ goLogin(); return; } const esc=escapeHtml;
    let d; try{ d=await api('/api/my/teams'); }catch(err){ setApp(`<section class="page">${wdBlockError(err)}</section>`); $('[data-block-retry]')?.addEventListener('click',renderMyTeams); return; }
    const req=x=>`<article class="tq-item" style="--c:${esc(x.color)}">${tqLogo(x)}<div class="tq-item-body"><h3 translate="no">${esc(x.center_name)}</h3>
        <p><span>Quiere añadirte a su equipo como</span> <b>${esc(x.role_name)}</b> · <span>${esc(x.dates)}</span></p>
        ${x.needs_freelance?'<p class="tq-note">Para este perfil tienes que activar tu perfil de freelance. Es gratis y lo haces al aceptar.</p>':''}
        <div class="tq-actions"><button type="button" class="btn btn-primary" data-accept="${x.id}">Aceptar</button><button type="button" class="btn" data-decline="${x.id}">Rechazar</button></div></div></article>`;
    const link=x=>`<article class="tq-item" style="--c:${esc(x.color)}">${tqLogo(x)}<div class="tq-item-body"><h3><span translate="no">${esc(x.center_name)}</span> ${tqChip(x)}</h3>
        <p><b>${esc(x.role_name)}</b> · <span>${esc(x.dates)}</span>${x.status==='active'&&!x.in_force?' · <span>Aún no ha empezado</span>':''}</p>
        <div class="tq-actions">${x.status==='active'&&x.in_force?`<button type="button" class="btn btn-sm" data-work="${x.center_id}" data-name="${esc(x.center_name)}">Trabajar en este centro</button>`:''}
          ${['active','paused'].includes(x.status)?`<button type="button" class="btn btn-sm" data-leave="${x.id}" data-name="${esc(x.center_name)}">Salir de este centro</button>`:''}</div></div></article>`;
    setApp(`<section class="page tq-page">${wdCrumbs([['Mi área','#/area'],['Mi equipo','']])}
      <header class="tq-head"><p class="eyebrow">Mi equipo</p><h1>Los centros donde trabajas</h1>
        <p class="lead">Nadie te añade a un equipo sin tu «sí». Puedes salir de un centro cuando quieras: lo que hiciste sigue en tu agenda, sin datos de sus clientes.</p>
        <div class="tq-actions"><a class="btn" href="#/mi-qr">${wdIcon('qr',16)} <span>Mi QR</span></a><a class="btn" href="#/mi-agenda">${wdIcon('calendar',16)} <span>Mi agenda</span></a></div></header>
      ${d.requests.length?`<h2 class="adl-h">Peticiones pendientes</h2><div class="tq-list" id="tq-requests">${d.requests.map(req).join('')}</div>`:''}
      <h2 class="adl-h">Tus equipos</h2>${d.links.length?`<div class="tq-list" id="tq-links">${d.links.map(link).join('')}</div>`:'<div class="empty"><p>Aún no estás en ningún equipo. Enseña tu QR en el centro para que te añadan.</p><p><a class="btn" href="#/mi-qr">Mi QR</a></p></div>'}</section>`);
    $$('[data-accept]').forEach(b=>b.onclick=async()=>{ const x=d.requests.find(r=>r.id===+b.dataset.accept); const body={id:x.id,accept:true};
      if(x.needs_freelance){ if(!await tqActivateFreelance(x.role_name)) return; body.activate_freelance=true; body.accept_terms=true; }
      b.disabled=true;
      try{ await postJSON('/api/my/teams/respond',body); await loadMe(); toast(translateString('Ya estás en el equipo de')+' '+x.center_name+'.'); renderMyTeams(); }
      catch(err){ b.disabled=false; toast(err.message); } });
    $$('[data-decline]').forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/my/teams/respond',{id:+b.dataset.decline,accept:false}); await loadMe(); toast('Petición rechazada.'); renderMyTeams(); }catch(err){ toast(err.message); } });
    $$('[data-work]').forEach(b=>b.onclick=()=>tqSwitch(+b.dataset.work,b.dataset.name));
    $$('[data-leave]').forEach(b=>b.onclick=async()=>{
      if(!await wdConfirm({title:translateString('Salir de')+' '+b.dataset.name,text:'Dejarás de ver lo de este centro al momento. Tus trabajos pasados siguen en tu agenda.',ok:'Salir del equipo',danger:true})) return;
      try{ await postJSON('/api/my/teams/leave',{id:+b.dataset.leave}); await loadMe(); toast('Has salido del equipo.'); renderMyTeams(); }catch(err){ toast(err.message); } });
  }

  // «Mi agenda»: dos semanas, día a día; cada centro con su color y el trabajo propio aparte. Sin datos de los clientes.
  async function renderMyAgenda(params){
    if(!state.me){ goLogin(); return; } const esc=escapeHtml;
    const want=params?.get?.('desde')||''; const from=/^\d{4}-\d{2}-\d{2}$/.test(want)?want:tqIso(new Date());
    const f=new Date(from+'T12:00:00'), shift=n=>tqIso(new Date(f.getTime()+n*864e5)), to=shift(13);
    let d; try{ d=await api(`/api/my/agenda?from=${from}&to=${to}`); }catch(err){ setApp(`<section class="page">${wdBlockError(err)}</section>`); $('[data-block-retry]')?.addEventListener('click',()=>renderMyAgenda(params)); return; }
    const days=new Map(); d.items.forEach(i=>{ if(!days.has(i.date)) days.set(i.date,[]); days.get(i.date).push(i); });
    const legend=[...new Map(d.items.map(i=>[i.center,[i.color,i.kind]])).entries()];
    const dayName=s=>{ try{ return new Date(s+'T12:00:00').toLocaleDateString(wdLocale(),{weekday:'long',day:'numeric',month:'long'}); }catch{ return s; } };
    const who=i=>i.kind==='own'?`<span class="tq-ag-center">${esc(i.center)}</span>`:`<span class="tq-ag-center" translate="no">${esc(i.center)}</span>`;
    setApp(`<section class="page tq-page">${wdCrumbs([['Mi área','#/area'],['Mi agenda','']])}
      <header class="tq-head"><p class="eyebrow">Mi agenda</p><h1>Lo que te toca, de todos tus centros</h1>
        <p class="lead">Tu trabajo de freelance y lo que te asigna cada centro, en una sola agenda. Cada centro tiene su color.</p></header>
      <nav class="tq-ag-nav" aria-label="Semanas"><a class="btn btn-sm" href="#/mi-agenda?desde=${shift(-14)}">← <span>Anteriores</span></a>
        <b class="num">${esc(tqDay(from))} – ${esc(tqDay(to))}</b><a class="btn btn-sm" href="#/mi-agenda?desde=${shift(14)}"><span>Siguientes</span> →</a></nav>
      ${legend.length?`<ul class="tq-legend">${legend.map(([n,[c,k]])=>`<li style="--c:${esc(c)}"><i aria-hidden="true"></i><span ${k==='own'?'':'translate="no"'}>${esc(n)}</span></li>`).join('')}</ul>`:''}
      <div id="tq-agenda">${days.size?[...days].map(([day,items])=>`<section class="tq-day"><h2>${esc(dayName(day))}</h2><ul>${items.map(i=>`<li class="tq-ag-item" style="--c:${esc(i.color)}">${who(i)}<span class="tq-ag-what">${esc(i.what||i.line)}</span></li>`).join('')}</ul></section>`).join('')
        :'<div class="empty"><p>No tienes nada asignado en estas dos semanas.</p></div>'}</div></section>`);
  }

  // The personal QR scanned with the phone's own camera (/p/…), and the link a person shares (/e/… → #/enlazar?i=…):
  // a centre signed in goes straight to «Enlazar persona» with it; anybody else sees how it works, without data.
  // Encargo del 17/10 (1.7) · «Buddies»: compañeros de buceo, no una red social. Peticiones que se aceptan o se rechazan,
  // la lista, y «¿Buceamos?»: una fecha, si se quiere un punto, y uno o varios Buddies. Al aceptar se abre WhatsApp entre
  // los dos; dentro de WORLDIVES no hay chat, ni muro, ni publicaciones, ni seguidores.
  async function renderBuddies(){
    if(!(await loadMe(),state.me)){ goLogin(); return; } const esc=escapeHtml;
    let d; try{ d=await api('/api/buddies'); }catch(err){ setApp(`<section class="page">${wdBlockError(err)}</section>`); return; }
    const when=x=>esc(wdLongDay(x.date));
    const row=(x,actions)=>`<li class="bd-row"><span class="bd-avatar" translate="no">${esc(initials(x.name))}</span><span class="bd-main"><b translate="no">${esc(x.name)}</b>${x.date?`<small>${when(x)}${x.point?` · <span translate="no">${esc(x.point)}</span>`:''}</small>`:''}</span><span class="bd-actions">${actions}</span></li>`;
    setApp(accountShell('buddies',{eyebrow:'BUDDIES',title:'Tus compañeros de buceo',lead:'Añade a tus Buddies con su QR y proponles bucear juntos. Al aceptar, os escribís por WhatsApp para organizaros.'},`
      <div class="acc-grid"><div class="acc-col">
        ${d.incoming.length?`<section class="acc-card bd-card"><div class="acc-card-head"><h2>${wdIcon('bell',18)} Peticiones para ti</h2></div><ul class="bd-list">${d.incoming.map(x=>row(x,`<button type="button" class="btn btn-sm btn-primary" data-req-ok="${x.id}">Aceptar</button><button type="button" class="btn btn-sm" data-req-no="${x.id}">Rechazar</button>`)).join('')}</ul></section>`:''}
        ${d.invites_in.length?`<section class="acc-card bd-card"><div class="acc-card-head"><h2>${wdIcon('calendar',18)} ¿Buceamos?</h2></div><ul class="bd-list">${d.invites_in.map(x=>row(x,x.status==='pending'?`<button type="button" class="btn btn-sm btn-primary" data-inv-ok="${x.id}">${wdIcon('whatsapp',15)} Aceptar</button><button type="button" class="btn btn-sm" data-inv-no="${x.id}">No puedo</button>`:`<span class="status good">${esc(translateString('Aceptada'))}</span>`)).join('')}</ul></section>`:''}
        <section class="acc-card bd-card"><div class="acc-card-head"><h2>${wdIcon('users',18)} Mis Buddies</h2><span class="pt-n">${d.buddies.length}</span></div>
          ${d.buddies.length?`<ul class="bd-list">${d.buddies.map(x=>row(x,`<label class="bd-pick"><input type="checkbox" data-pick="${esc(x.id)}"> <span>${esc(translateString('Invitar'))}</span></label><button type="button" class="btn-link bd-remove" data-remove="${esc(x.id)}" data-name="${esc(x.name)}">Quitar</button>`)).join('')}</ul>`
            :'<p class="acc-empty">Todavía no tienes Buddies. Enséñale tu QR a tu compañero o escanea el suyo.</p>'}
          ${d.outgoing.length?`<p class="bd-sub">Esperando respuesta</p><ul class="bd-list is-muted">${d.outgoing.map(x=>row(x,`<button type="button" class="btn-link" data-req-cancel="${x.id}">Anular</button>`)).join('')}</ul>`:''}</section>
        ${d.buddies.length?`<section class="acc-card bd-card" id="bd-dive"><div class="acc-card-head"><h2>${wdIcon('inmersion',18)} Proponer una inmersión</h2></div>
          <form id="bd-dive-form" class="form-grid"><p class="field full pd-hint">Marca «Invitar» en uno o varios Buddies, elige la fecha y, si quieres, el punto.</p>
            <div class="field"><label for="bd-date">Fecha</label><input id="bd-date" type="date" min="${wdToday()}" required></div>
            <div class="field"><label for="bd-point">Punto (opcional)</label><input id="bd-point" list="bd-points" autocomplete="off" placeholder="${esc(translateString('Busca un punto de buceo'))}"><datalist id="bd-points"></datalist></div>
            <div class="field full"><label for="bd-note">Nota (opcional)</label><input id="bd-note" maxlength="200"></div>
            <div class="form-actions full"><button class="btn btn-primary" type="submit">¿Buceamos?</button></div></form>
          ${d.invites_out.length?`<p class="bd-sub">Tus propuestas</p><ul class="bd-list is-muted">${d.invites_out.map(x=>row(x,`<span class="status ${x.status==='accepted'?'good':x.status==='rejected'?'bad':'warn'}">${esc(translateString(x.status==='accepted'?'Aceptada':x.status==='rejected'?'No puede':'Pendiente'))}</span>${x.status==='pending'?`<button type="button" class="btn-link" data-inv-cancel="${x.id}">Anular</button>`:''}`)).join('')}</ul>`:''}</section>`:''}
      </div><aside class="acc-col">
        <section class="acc-card bd-qr"><div class="acc-card-head"><h2>${wdIcon('qr',18)} Mi QR de Buddy</h2></div><img src="${esc(d.qr.svg)}" alt="${esc(translateString('Tu QR de Buddy'))}" width="200" height="200"><p class="acc-help">Que tu compañero lo escanee con su móvil: le pedirá ser tu Buddy.</p>
          <div class="page-actions"><button type="button" class="btn btn-sm" id="bd-copy">${wdIcon('link',15)} Copiar mi enlace</button></div></section>
        ${d.has_phone?'':`<div class="notice"><p>${esc(translateString('Para organizaros por WhatsApp, añade tu teléfono en «Ajustes».'))}</p></div>`}
      </aside></div>`));
    const again=()=>renderBuddies(), fail=err=>toast(err.message);
    $$('[data-req-ok],[data-req-no]').forEach(b=>b.onclick=()=>postJSON('/api/buddies/answer',{id:+(b.dataset.reqOk||b.dataset.reqNo),accept:!!b.dataset.reqOk}).then(()=>{ toast(b.dataset.reqOk?'Ya sois Buddies.':'Petición rechazada.'); again(); }).catch(fail));
    $$('[data-req-cancel]').forEach(b=>b.onclick=()=>postJSON('/api/buddies/cancel',{id:+b.dataset.reqCancel}).then(again).catch(fail));
    $$('[data-remove]').forEach(b=>b.onclick=async()=>{ if(!await wdConfirm({title:'Quitar Buddy',text:translateString('¿Quitar a {n} de tus Buddies?').replace('{n}',b.dataset.name),ok:'Quitar'})) return; postJSON('/api/buddies/remove',{ref:b.dataset.remove}).then(again).catch(fail); });
    $$('[data-inv-cancel]').forEach(b=>b.onclick=()=>postJSON('/api/buddies/dive/cancel',{id:+b.dataset.invCancel}).then(again).catch(fail));
    $$('[data-inv-no]').forEach(b=>b.onclick=()=>postJSON('/api/buddies/dive/answer',{id:+b.dataset.invNo,accept:false}).then(again).catch(fail));
    $$('[data-inv-ok]').forEach(b=>b.onclick=async()=>{ try{ const r=await postJSON('/api/buddies/dive/answer',{id:+b.dataset.invOk,accept:true});
        if(r.whatsapp){ window.open(r.whatsapp,'_blank','noopener'); toast('Aceptada: se abre WhatsApp para organizaros.'); } else toast(translateString('Aceptada. {n} no tiene teléfono en su perfil: organizaos en persona.').replace('{n}',r.name||''));
        again(); }catch(err){ fail(err); } });
    $('#bd-copy').onclick=async()=>{ try{ await navigator.clipboard.writeText(d.qr.url); toast('Enlace copiado.'); }catch{ toast(d.qr.url); } };
    const pin=$('#bd-point'); let pts=[], tmr=0;
    pin?.addEventListener('input',()=>{ clearTimeout(tmr); const q=pin.value.trim(); if(q.length<2) return; tmr=setTimeout(async()=>{ try{ const r=await api('/api/dive-points?limit=8&q='+encodeURIComponent(q)); pts=(r.items||r||[]).slice(0,8); $('#bd-points').innerHTML=pts.map(x=>`<option value="${esc(x.name)}">`).join(''); }catch{} },250); });
    $('#bd-dive-form')?.addEventListener('submit',async e=>{ e.preventDefault(); const picked=$$('[data-pick]:checked').map(x=>x.dataset.pick);
      if(!picked.length){ toast('Marca «Invitar» en al menos un Buddy.'); return; }
      const point=pts.find(x=>x.name===pin.value.trim());
      try{ const r=await postJSON('/api/buddies/dive',{buddies:picked,date:$('#bd-date').value,point_id:point?.id||null,note:$('#bd-note').value}); toast(translateString(r.sent===1?'Propuesta enviada.':'Propuestas enviadas: {n}.').replace('{n}',r.sent)); again(); }catch(err){ fail(err); } });
  }
  async function renderPersonalQRLanding(code){
    const me=state.me?.user;
    if(me&&me.role==='recreational'){   // 17/10 (1.7): «Mi QR» of another diver, scanned with the phone
      setApp(authCard('Añadir un Buddy',`<p class="lead auth-lead">Es el QR de otro buceador de WORLDIVES. ¿Le pides ser tu Buddy?</p><div class="form-actions"><button class="btn btn-primary" type="button" id="bq-ask">Pedir ser Buddies</button><a class="btn" href="#/buddies">Ahora no</a></div>`));
      $('#bq-ask').onclick=async()=>{ try{ const r=await postJSON('/api/buddies/qr',{code:code.replace(/^#\/enlazar\?i=/,'')}); toast(r.status==='pending'?translateString('Petición enviada. Cuando la acepte, seréis Buddies.'):translateString('Ya sois Buddies.')); wdGo('#/buddies'); }catch(err){ toast(err.message); } };
      return; }
    if(me&&me.role==='center'&&(state.me?.member_role||'owner')==='owner'){ sessionStorage.setItem('wd-tq-code',code); wdGo('#/admin?tab=team'); return; }
    setApp(authCard('Enlazar a una persona',`<p class="lead auth-lead">Es el QR o el enlace de una persona de WORLDIVES para unirse al equipo de un centro. No lleva sus datos.</p>
      <ol class="tq-steps"><li>Entra con la cuenta del centro.</li><li>Abre «Equipo → Enlazar persona».</li><li>Escanea el QR, escribe su código o abre su enlace.</li></ol>
      ${me?'<p class="adl-det">Solo el propietario del centro puede enlazar personas, desde su panel.</p>':`<div class="form-actions"><a class="btn btn-primary" href="#/login?next=${encodeURIComponent(location.hash)}">Iniciar sesión</a></div>`}`));
  }

  // The centre: «Enlazar persona» (camera, code or email), the people linked, their profile, pause, remove and
  // «Transferir la propiedad». What the plan does not allow is shown locked with «Ver planes».
  function tqRoleOptions(roleList,rules,selected){
    return roleList.filter(r=>r.key!=='owner').map(r=>{ const locked=rules.only_reception&&r.key!=='reception';
      return `<option value="${escapeHtml(r.key)}" ${r.key===selected?'selected':''} ${locked?'disabled':''}>${escapeHtml(translateString(r.name))}${locked?' — '+escapeHtml(translateString('Disponible en el plan Pro')):''}</option>`; }).join('');
  }
  function tqDurationFields(pre){
    return `<fieldset class="tq-dur"><legend>Duración</legend><label class="tq-radio"><input type="radio" name="${pre}-kind" value="fixed" checked> <span><b>Fijo</b><small>Hasta que lo quites del equipo.</small></span></label>
      <label class="tq-radio"><input type="radio" name="${pre}-kind" value="days"> <span><b>Por días</b><small>Solo esos días; después sale solo.</small></span></label>
      <div class="tq-dates" id="${pre}-dates" hidden><div class="field"><label for="${pre}-from">Desde</label><input type="date" id="${pre}-from" value="${tqIso(new Date())}"></div>
        <div class="field"><label for="${pre}-to">Hasta</label><input type="date" id="${pre}-to" value="${tqIso(new Date())}"></div></div></fieldset>`;
  }
  function tqDurationBind(el,pre){ $$(`input[name="${pre}-kind"]`,el).forEach(r=>r.onchange=()=>{ $(`#${pre}-dates`,el).hidden=$(`input[name="${pre}-kind"]:checked`,el).value!=='days'; }); }
  const tqDurationValue=(el,pre)=>{ const kind=$(`input[name="${pre}-kind"]:checked`,el).value; return kind==='days'?{kind,starts_on:$(`#${pre}-from`,el).value,ends_on:$(`#${pre}-to`,el).value}:{kind}; };
  function tqOpenLink(d,{onDone,code,role}={}){
    const esc=escapeHtml, rules=d.rules||{};
    const firstRole=role||(rules.only_reception?'reception':'instructor');
    const {el,close}=wdOpenModal({id:'tq-link',title:escapeHtml(translateString('Enlazar persona')),subtitle:escapeHtml(translateString('La persona recibe la petición y tiene que aceptarla. Nadie queda enlazado sin su «sí».')),
      body:`<div class="pr-tabs" role="tablist"><button type="button" class="pr-tab is-on" data-tqt="scan" role="tab" aria-selected="true">${wdIcon('camera',16)} <span>Escanear QR</span></button><button type="button" class="pr-tab" data-tqt="code" role="tab" aria-selected="false">${wdIcon('qr',16)} <span>Escribir el código</span></button><button type="button" class="pr-tab" data-tqt="email" role="tab" aria-selected="false">${wdIcon('message',16)} <span>Por correo</span></button></div>
        <div id="tq-step1">
          <div data-tqp="scan"><p class="adl-det">Pide a la persona que abra «Mi QR» en su móvil (en su menú, arriba a la derecha) y apunta la cámara.</p>
            <video id="tq-video" playsinline muted hidden class="tq-video"></video><button type="button" class="btn btn-primary" id="tq-cam">${wdIcon('camera',16)} <span>Abrir la cámara</span></button></div>
          <form data-tqp="code" hidden id="tq-code-form"><div class="field"><label for="tq-code-i">Código de 6 letras o enlace</label><input id="tq-code-i" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="600" placeholder="ABC 123" translate="no"><small>Lo ve debajo de su QR (dura 10 minutos), o pega el enlace que te ha enviado.</small></div>
            <div class="form-actions"><button type="submit" class="btn btn-primary">Buscar</button></div></form>
          <form data-tqp="email" hidden id="tq-mail-form"><div class="field"><label for="tq-mail">Email de la persona</label><input id="tq-mail" type="email" maxlength="160" required></div>
            <div class="field"><label for="tq-mail-role">Perfil</label><select id="tq-mail-role">${tqRoleOptions(d.role_list||[],rules,firstRole)}</select></div>${tqDurationFields('tq-m')}
            <p class="adl-det">Si aún no tiene cuenta, el correo le lleva a crearla (de freelance o normal) y queda enlazada al terminar.</p>
            <div class="form-actions"><button type="submit" class="btn btn-primary">Enviar invitación</button></div></form>
          <div id="tq-err" class="tq-err" role="alert"></div></div>
        <div id="tq-step2" hidden></div>`,
      footer:'<button type="button" class="btn" data-modal-close>Cerrar</button>'});
    translateTree(el); tqDurationBind(el,'tq-m');
    const tab=t=>{ $$('[data-tqt]',el).forEach(b=>{ const on=b.dataset.tqt===t; b.classList.toggle('is-on',on); b.setAttribute('aria-selected',on?'true':'false'); }); $$('[data-tqp]',el).forEach(p=>p.hidden=p.dataset.tqp!==t); $('#tq-err',el).textContent=''; };
    $$('[data-tqt]',el).forEach(b=>b.onclick=()=>tab(b.dataset.tqt));
    const err=m=>{ const e=$('#tq-err',el); e.textContent=translateString(m||''); };
    const lookup=async code=>{ err(''); let r; try{ r=await postJSON('/api/center/team/scan',{code}); }catch(e){ err(e.message); return; }
      const p=r.person, s2=$('#tq-step2',el);
      $('#tq-step1',el).hidden=true; $('.pr-tabs',el).hidden=true; s2.hidden=false;
      s2.innerHTML=`<div class="tq-found">${tqAvatar(p.photo,p.name,56)}<div><b translate="no">${esc(p.name)}</b><small>${esc(p.account_label)}</small>
          ${p.certifications.length?`<ul class="tq-certs">${p.certifications.map(c=>`<li translate="no">${esc(c)}</li>`).join('')}</ul>`:'<small class="tq-nocert">Sin titulaciones en su cuenta.</small>'}</div></div>
        ${p.self?'<p class="notice warning">Esa eres tú: ya estás en el equipo.</p>':p.already?'<p class="notice warning">Esa persona ya está en tu equipo o tiene una petición pendiente.</p>':`<form id="tq-req" class="tq-req-form">
          <div class="field"><label for="tq-role">Perfil</label><select id="tq-role">${tqRoleOptions(d.role_list||[],r.rules,firstRole)}</select>
            ${r.rules.only_reception?tqPlans('Con tu plan, la persona del equipo solo puede ser Recepción. Los demás perfiles: Disponible en el plan Pro.'):''}</div>
          ${tqDurationFields('tq-r')}
          ${p.account==='recreational'?'<p class="adl-det">Su cuenta es de buceador: para los perfiles de trabajo tendrá que activar su perfil de freelance (es gratis) al aceptar.</p>':''}
          <div class="form-actions"><button type="button" class="btn" id="tq-back">Otra persona</button><button type="submit" class="btn btn-primary">Enviar petición</button></div></form>`}`;
      translateTree(s2); tqDurationBind(s2,'tq-r');
      $('#tq-back',s2)?.addEventListener('click',()=>{ s2.hidden=true; s2.innerHTML=''; $('#tq-step1',el).hidden=false; $('.pr-tabs',el).hidden=false; });
      $('#tq-req',s2)?.addEventListener('submit',async e=>{ e.preventDefault(); const btn=$('button[type=submit]',e.target); btn.disabled=true;
        try{ const x=await postJSON('/api/center/team/link',{ref:r.ref,member_role:$('#tq-role',s2).value,...tqDurationValue(s2,'tq-r')});
          s2.innerHTML=`<div class="notice success"><strong>${esc(translateString(x.message))}</strong></div>`; onDone?.(); }
        catch(e2){ btn.disabled=false; toast(e2.message); } }); };
    $('#tq-cam',el).onclick=async()=>{ err(''); try{ const v=await tqReadCamera($('#tq-video',el)); if(v) lookup(v); }catch(e){ tab('code'); err(e.message); $('#tq-code-i',el).focus(); } };
    $('#tq-code-form',el).onsubmit=e=>{ e.preventDefault(); const v=$('#tq-code-i',el).value.trim(); if(v) lookup(v); };
    $('#tq-mail-form',el).onsubmit=async e=>{ e.preventDefault(); err(''); const btn=$('button[type=submit]',e.target); btn.disabled=true;
      try{ await postJSON('/api/center/team/link-email',{email:$('#tq-mail',el).value.trim(),member_role:$('#tq-mail-role',el).value,...tqDurationValue(el,'tq-m')});
        $('#tq-mail-form',el).innerHTML=`<div class="notice success"><strong>${esc(translateString('Invitación enviada. Cuando la acepte, aparecerá en tu equipo.'))}</strong></div>`; onDone?.(); }
      catch(e2){ btn.disabled=false; err(e2.message); } };
    if(code){ tab('code'); $('#tq-code-i',el).value=code.length>40?code:tqCode(code); lookup(code); }
    return {el,close};
  }
  async function renderTeamLinks(mount,d,refresh){
    const esc=escapeHtml, rules=d.rules||{}, owner=(state.me?.member_role||'owner')==='owner';
    const RL=d.role_list||[];
    const row=x=>{ const done=['ended','cancelled','declined'].includes(x.status);
      return `<tr data-link="${x.id}"><td><div class="tq-who">${tqAvatar(x.photo,x.name,36)}<span><b translate="no">${esc(x.name)}</b><small>${esc(x.account_label)}</small></span></div></td>
        <td>${done?esc(x.role_name):`<label class="sr-only" for="tl-r-${x.id}">Perfil</label><select id="tl-r-${x.id}" class="tl-role" data-id="${x.id}">${tqRoleOptions(RL,rules,x.member_role)}</select>`}</td>
        <td>${esc(x.dates)}</td><td>${tqChip(x)}${x.waiting_start?` <small class="tq-start"><span>Empieza el</span> ${esc(tqDay(x.starts_on))}</small>`:''}</td>
        <td class="tq-row-act">${x.status==='active'?`<button type="button" class="btn btn-sm" data-tl="pause" data-id="${x.id}">Pausar</button>`:''}${x.status==='paused'?`<button type="button" class="btn btn-sm" data-tl="reactivate" data-id="${x.id}">Reactivar</button>`:''}${done?'':`<button type="button" class="btn btn-sm danger" data-tl="end" data-id="${x.id}" data-name="${esc(x.name)}">${x.status==='pending'?'Anular':'Quitar'}</button>`}</td></tr>`; };
    const active=(d.links||[]).filter(x=>x.status==='active'&&!x.waiting_start);
    mount.innerHTML=`<div class="svc-head tq-team-head"><div><p class="eyebrow">Enlazar persona</p><h2>Personas enlazadas a tu centro</h2>
        <p>Cada persona entra con su propia cuenta y elige tu centro en su menú. Ve solo lo que permite su perfil, y solo mientras está en tu equipo.</p>
        ${rules.cap?`<p class="tq-seats">${rules.used} de ${rules.cap} personas además del propietario</p>`:''}</div>
      ${rules.blocked?`<button type="button" class="btn btn-primary" id="tq-open" disabled aria-describedby="tq-lockmsg">${wdIcon('lock',16)} <span>Enlazar persona</span></button>`:`<button type="button" class="btn btn-primary" id="tq-open">${wdIcon('qr',16)} <span>Enlazar persona</span></button>`}</div>
      ${rules.blocked?`<div id="tq-lockmsg">${tqPlans('Disponible en el plan Motor de reservas')}</div>`:''}
      ${(d.links||[]).length?`<div class="table-wrap"><table class="data-table tq-table"><thead><tr><th>Persona</th><th>Perfil</th><th>Duración</th><th>Estado</th><th></th></tr></thead><tbody>${d.links.map(row).join('')}</tbody></table></div>`
        :(rules.blocked?'':'<div class="empty"><p>Aún no has enlazado a nadie. Pulsa «Enlazar persona» y escanea su QR.</p></div>')}
      ${owner&&active.length?`<details class="tq-transfer"><summary>Transferir la propiedad</summary><form id="tq-tr" class="tq-req-form"><p class="adl-det">La nueva persona pasa a ser la propietaria y tú quedas como Encargado. Te enviamos un correo para confirmarlo.</p>
        <div class="field"><label for="tq-tr-who">Nueva persona propietaria</label><select id="tq-tr-who">${active.map(x=>`<option value="${x.user_id}">${esc(x.name)}</option>`).join('')}</select></div>
        <div class="form-actions"><button type="submit" class="btn">Enviar el correo de confirmación</button></div></form></details>`:''}`;
    translateTree(mount);
    $('#tq-open',mount)?.addEventListener('click',()=>tqOpenLink(d,{onDone:refresh}));
    $$('.tl-role',mount).forEach(s=>s.onchange=async()=>{ try{ await postJSON('/api/center/team/link/role',{id:+s.dataset.id,member_role:s.value}); toast('Perfil cambiado.'); }catch(err){ toast(err.message); refresh(); } });
    $$('[data-tl]',mount).forEach(b=>b.onclick=async()=>{ const act=b.dataset.tl;
      if(act==='end'&&!await wdConfirm({title:translateString('Quitar del equipo a')+' '+b.dataset.name,text:'Pierde el acceso al momento, también si tiene la sesión abierta. Su historial de trabajos se queda.',ok:'Quitar del equipo',danger:true})) return;
      try{ await postJSON('/api/center/team/link/'+act,{id:+b.dataset.id}); toast(act==='end'?'Ya no está en tu equipo.':act==='pause'?'En pausa: no tiene acceso hasta que lo reactives.':'Reactivado.'); refresh(); }catch(err){ toast(err.message); } });
    $('#tq-tr',mount)?.addEventListener('submit',async e=>{ e.preventDefault(); try{ await postJSON('/api/center/team/transfer',{user_id:+$('#tq-tr-who',mount).value}); toast('Te hemos enviado un correo para confirmar la transferencia.'); }catch(err){ toast(err.message); } });
    // An address opened from a QR or a shared link (#/p/…, #/enlazar?i=…) opens «Enlazar persona» with it.
    const pending=sessionStorage.getItem('wd-tq-code'); if(pending&&!rules.blocked){ sessionStorage.removeItem('wd-tq-code'); tqOpenLink(d,{onDone:refresh,code:pending}); }
  }
  async function renderTransferConfirm(params){
    const token=params?.get?.('token')||'';
    if(!state.me){ goLogin(); return; }
    setApp(authCard('Transferir la propiedad',`<p class="lead auth-lead">Confirma que la propiedad del centro pasa a la persona que elegiste. Tú quedas en el equipo como Encargado.</p>
      <div class="form-actions"><button class="btn btn-primary" id="tq-tr-ok" type="button">Confirmar la transferencia</button><a class="btn" href="#/admin?tab=team">Cancelar</a></div>`));
    $('#tq-tr-ok').onclick=async()=>{ try{ await postJSON('/api/team/transfer/confirm',{token}); await loadMe(); toast('Hecho: la propiedad ha cambiado.'); wdGo('#/admin?tab=team'); }catch(err){ toast(err.message); } };
  }
  async function renderTeamJoin(params){
    const token=params?.get?.('token')||''; const esc=escapeHtml;
    let inv; try{ inv=await api('/api/team/invite?token='+encodeURIComponent(token)); }catch(err){ setApp(authCard('Invitación al equipo',`<div class="notice warning">${esc(err.message)}</div>`)); return; }
    const me=state.me?.user, own=state.me?.own_role||me?.role;
    // v50.58: «Enlazar persona» por correo: la persona entra con su propia cuenta (de freelance, o normal para Recepción)
    const fresh=!!inv.account, needFree=fresh&&inv.needs_freelance;
    const freeBox=`<label class="lg-check"><input type="checkbox" id="tj-free"> <span>Activo mi perfil de freelance (es gratis) y acepto las <a href="#/legal/condiciones-centros" target="_blank" rel="noopener">condiciones para profesionales</a>.</span></label>`;
    const choice=!fresh?'':needFree?'<p class="adl-det">Se crea tu cuenta de freelance (es gratis): con ella puedes estar en los equipos de varios centros.</p>'
      :`<fieldset class="tq-dur"><legend>Tu cuenta</legend><label class="tq-radio"><input type="radio" name="tj-as" value="recreational" checked> <span><b>Cuenta normal</b><small>Para Recepción. También puedes reservar y llevar tu Log Book.</small></span></label>
        <label class="tq-radio"><input type="radio" name="tj-as" value="freelance"> <span><b>Cuenta de freelance</b><small>Gratis. Para trabajar con varios centros.</small></span></label></fieldset>`;
    const terms=fresh?`Acepto los <a href="#/legal/terminos" target="_blank" rel="noopener">términos</a>${needFree?', las <a href="#/legal/condiciones-centros" target="_blank" rel="noopener">condiciones para profesionales</a>':''} y la <a href="#/legal/privacidad" target="_blank" rel="noopener">política de privacidad</a>.`
      :'Acepto las <a href="#/legal/condiciones-centros" target="_blank" rel="noopener">condiciones para centros</a> y la <a href="#/legal/privacidad" target="_blank" rel="noopener">política de privacidad</a>.';
    setApp(authCard('Únete al equipo de '+esc(inv.center),`<p class="lead" style="font-size:15px">Te han invitado con el perfil de <b>${esc(inv.role_label)}</b> (${esc(inv.email)}).${fresh&&inv.dates?` <span>${esc(inv.dates)}</span>.`:''}</p>
      ${me?`${fresh&&own==='recreational'&&needFree?freeBox:''}<div class="form-actions"><button class="btn btn-primary" id="tj-ok" type="button">Aceptar con mi cuenta</button></div>`:`<form id="tj-form"><div class="field"><label for="tj-name">Nombre y apellidos</label><input id="tj-name" required maxlength="120" autocomplete="name"></div>
        <div class="field"><label for="tj-user">Usuario</label><input id="tj-user" required maxlength="40" autocomplete="username"></div>
        <div class="field"><label for="tj-pass">Contraseña</label><input id="tj-pass" type="password" minlength="10" required autocomplete="new-password"><small>Mínimo 10 caracteres.</small></div>
        ${choice}<label class="lg-check"><input type="checkbox" id="tj-terms" required> <span>${terms}</span></label>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Crear mi cuenta y unirme</button></div></form><p style="font-size:13px">¿Ya tienes cuenta con ese email? <a href="#/login?next=${encodeURIComponent(location.hash)}">Inicia sesión</a>.</p>`}`));
    const done=async()=>{ await loadMe(); toast('Ya formas parte del equipo.'); wdGo(fresh?'#/mi-equipo':'#/admin'); };
    $('#tj-ok')?.addEventListener('click',async()=>{ const free=$('#tj-free'); if(free&&!free.checked){ toast('Para este perfil tienes que activar tu perfil de freelance (es gratis).'); free.focus(); return; }
      try{ await postJSON('/api/team/join',{token,...(free?{activate_freelance:true,accept_terms:true}:{})}); done(); }catch(err){ toast(err.message); } });
    $('#tj-form')?.addEventListener('submit',async e=>{ e.preventDefault(); try{ await postJSON('/api/team/join',{token,fullname:$('#tj-name').value,username:$('#tj-user').value,password:$('#tj-pass').value,accept_terms:$('#tj-terms').checked,as:$('input[name="tj-as"]:checked')?.value}); done(); }catch(err){ toast(err.message); } });
  }
  // Administración → Planes
  async function renderAdminOps(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let h; try{ h=await api('/api/admin/health'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const ago=t=>t?esc(t.replace('T',' ').slice(0,16)):'—'; const mb=b=>b?(b/1048576).toLocaleString(wdLocale(),{maximumFractionDigits:1})+' MB':'';
    const q=h.email_queue||{};
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Operación</p><h2>Estado del servidor, copias y avisos</h2><p>Versión ${esc(h.version)} · en marcha desde hace ${Math.round(h.uptime_s/3600)} h · ${h.workers} proceso(s) · base de ${h.db_size_mb} MB.</p></div><button type="button" class="btn" id="ops-refresh">Actualizar</button></div>
      ${h.demo?`<div class="notice"><strong>Entorno de pruebas.</strong> Restaurar la demo borra lo que hayas cambiado aquí y vuelve a crear las cuentas de prueba y los datos de ejemplo con fechas a partir de hoy. <button type="button" class="btn btn-secondary" id="ops-demo-reset">Restaurar demo</button></div>`:''}
      ${h.warnings.length?`<div class="notice warning"><strong>Ajustes pendientes:</strong><ul>${h.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}
      <div class="acc-kpis">${accKpi('shield',h.quick_check?esc(h.quick_check.result):'—','Integridad de la base (quick_check diario) · '+ago(h.quick_check?.at))}
        ${accKpi('download',h.backup_db?ago(h.backup_db.at):(h.backup_enabled?'Pendiente':'Desactivadas'),'Última copia de la base '+(h.backup_db?mb(h.backup_db.size):'')+(h.backup_external?' · con copia externa':' · sin copia externa'))}
        ${accKpi('image',h.backup_files?ago(h.backup_files.at):'—','Última copia de fotos y documentos')}
        ${accKpi('mail',(q.queued||0)+(q.retry||0),'Correos en cola · '+(q.failed||0)+' fallidos')}
        ${accKpi('alert',h.errors_recent,'Errores 500 recientes')}
        ${h.disk?accKpi('chart',h.disk.free_gb+' GB','Disco libre ('+h.disk.used_pct+' % usado)',null,h.disk.used_pct>85):''}</div>
      ${(h.services||[]).length?`<h3 class="adl-h" id="ops-status">Estado del sistema</h3>
      <p class="adl-det">Si falta una clave, solo se desactiva esa función; el resto de la web sigue funcionando. Las claves van en el archivo <code>.env</code> del servidor y se aplican al reiniciarlo.</p>
      <div class="table-wrap"><table class="ops-status"><thead><tr><th>Servicio</th><th>Estado</th><th>Detalle</th><th>Variable del .env</th></tr></thead><tbody>${h.services.map(x=>`<tr data-service="${esc(x.key)}">
        <td><strong>${esc(x.name)}</strong>${x.effect?`<small>${esc(x.effect)}</small>`:''}</td>
        <td><span class="status ${x.state==='ok'?'good':x.state==='error'?'bad':'warn'}">${x.state==='ok'?'Configurado':x.state==='error'?'Error':'Pendiente'}</span></td>
        <td>${esc(x.detail)}</td><td translate="no">${x.env.map(v=>`<code>${esc(v)}</code>`).join(' ')||'—'}</td></tr>`).join('')}</tbody></table></div>`:''}
      <h3 class="adl-h">Aviso de mantenimiento o incidencia</h3>
      ${h.banner?`<div class="notice">Aviso activo hasta ${ago(h.banner.until)}: «${esc(h.banner.text)}» <button type="button" class="btn-link" id="ops-off">Quitar</button></div>`:''}
      <form id="ops-banner" class="form-grid"><div class="field full"><label for="ops-text">Texto que verá todo el mundo arriba de la web</label><input id="ops-text" maxlength="300" placeholder="Ej.: El domingo de 7:00 a 8:00 haremos mantenimiento; las reservas pueden tardar en confirmarse."></div>
        <div class="field"><label for="ops-level">Tipo</label><select id="ops-level"><option value="maintenance">Mantenimiento</option><option value="incident">Incidencia</option><option value="info">Información</option></select></div>
        <div class="field"><label for="ops-hours">Durante (horas)</label><input id="ops-hours" type="number" min="1" max="336" value="24"></div>
        <label class="lg-check full"><input type="checkbox" id="ops-notify"> <span>Avisar también por email a todos los centros y profesionales</span></label>
        <div class="form-actions full"><button class="btn btn-primary" type="submit">Publicar aviso</button></div></form>
      <p class="adl-det">Monitor externo: configura un servicio de uptime (UptimeRobot, Better Stack, Uptime Kuma…) contra <code>${esc(location.origin)}/api/health</code>. Si se repiten errores 500, se avisa por email a los administradores.</p></section>`;
    $('#ops-refresh').onclick=()=>renderAdminOps(mountId);
    $('#ops-demo-reset')?.addEventListener('click',async e=>{ if(!confirm('Se borrarán los cambios hechos en el entorno de pruebas y se volverán a crear los datos de ejemplo. ¿Continuar?')) return;
      e.target.disabled=true; e.target.textContent='Restaurando…';
      try{ const r=await postJSON('/api/admin/demo/reset',{}); toast(r.message); state.me=null; setTimeout(()=>{ wdGo('#/login'); location.reload(); },1200); }catch(err){ toast(err.message); e.target.disabled=false; e.target.textContent='Restaurar demo'; } });
    $('#ops-off')?.addEventListener('click',async()=>{ try{ await postJSON('/api/admin/banner',{text:''}); state.meta=null; await loadMeta().catch(()=>{}); siteBanner(); toast('Aviso quitado.'); renderAdminOps(mountId); }catch(err){ toast(err.message); } });
    $('#ops-banner').onsubmit=async e=>{ e.preventDefault(); if(!$('#ops-text').value.trim()){ toast('Escribe el texto del aviso.'); return; }
      if($('#ops-notify').checked&&!confirm('Se enviará un email a todos los centros y profesionales. ¿Continuar?')) return;
      try{ const r=await postJSON('/api/admin/banner',{text:$('#ops-text').value,level:$('#ops-level').value,hours:$('#ops-hours').value,notify_centers:$('#ops-notify').checked}); state.meta=null; await loadMeta().catch(()=>{}); siteBanner(); toast(r.emails?`Aviso publicado y ${r.emails} emails en cola.`:'Aviso publicado.'); renderAdminOps(mountId); }catch(err){ toast(err.message); } };
  }
  async function renderAdminPlans(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/admin/plans'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const y=new Date().getFullYear();
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Planes</p><h2>Planes, cuotas y excepciones</h2><p>El precio es la cuota anual (pendiente de confirmar con la gestoría si se muestra con IVA incluido). Los cambios valen desde ya para las funciones; los precios, para los pagos nuevos.</p></div></div>
      <div class="ap-plans">${d.plans.map(p=>`<form class="ap-plan pl-card" data-code="${esc(p.code)}"><h3>${esc(p.code)}</h3>
        <div class="field"><label for="ap-n-${p.code}">Nombre</label><input id="ap-n-${p.code}" name="name" value="${esc(p.name)}" maxlength="80" required></div>
        <div class="field"><label for="ap-p-${p.code}">Precio anual</label><input id="ap-p-${p.code}" name="price" inputmode="decimal" value="${p.price_year??''}" ${p.code==='free'?'disabled':''} placeholder="Sin definir"></div>
        <div class="field"><label for="ap-c-${p.code}">Moneda</label><input id="ap-c-${p.code}" name="currency" value="${esc(p.currency)}" maxlength="3"></div>
        <div class="field"><label for="ap-d-${p.code}">Descripción</label><textarea id="ap-d-${p.code}" name="description" rows="2" maxlength="500">${esc(p.description||'')}</textarea></div>
        <fieldset><legend>Funciones</legend>${Object.entries(d.features).map(([k,l])=>`<label class="lg-check"><input type="checkbox" name="f_${k}" ${p.features[k]?'checked':''} ${p.code==='free'&&['online_bookings','online_payments'].includes(k)?'disabled':''}> <span>${esc(l)}</span></label>`).join('')}</fieldset>
        ${Object.entries(d.limits).map(([k,l])=>`<div class="field"><label for="ap-l-${p.code}-${k}">${esc(l)} (0 = sin límite)</label><input id="ap-l-${p.code}-${k}" name="l_${k}" type="number" min="0" value="${Number(p.limits[k]||0)}"></div>`).join('')}
        ${p.code!=='free'?`<label class="lg-check"><input type="checkbox" name="active" ${p.active?'checked':''}> <span>Plan disponible</span></label>`:''}
        <button class="btn btn-primary" type="submit">Guardar</button></form>`).join('')}</div>
      <h3 class="adl-h">Prueba gratuita</h3><form id="ap-trial" class="form-grid"><div class="field"><label for="ap-td">Días de prueba al aprobar un alta</label><input id="ap-td" type="number" min="0" max="365" value="${d.settings.trial_days}"></div>
        <div class="field"><label for="ap-tp">Plan de la prueba</label><select id="ap-tp">${d.plans.filter(p=>p.code!=='free').map(p=>`<option value="${esc(p.code)}" ${p.code===d.settings.trial_plan?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>
        <div class="form-actions full"><button class="btn btn-primary" type="submit">Guardar</button></div></form>
      <h3 class="adl-h">Informe DAC7</h3><p class="adl-det">Por ejercicio fiscal: identificación fiscal, país, importes cobrados a través de la web por cada prestador y trimestre, número de actividades y comisiones (0). Si a un centro le faltan datos fiscales, el informe sale igualmente y la pestaña «Datos incompletos» del Excel los lista. Revísalo con la gestoría antes de presentar el modelo 238.</p>
      ${wdExportBox([['dac7','Informe DAC7'],['dac7_pago_en_persona','DAC7 · pago en persona (pendiente de gestoría)']],{period:false,year:true})}
      <h3 class="adl-h">Centros y profesionales</h3>
      <div class="table-wrap"><table class="data-table"><thead><tr><th>Prestador</th><th>Plan</th><th>Hasta</th><th>Datos fiscales</th><th></th></tr></thead><tbody>${d.providers.map((p,i)=>`<tr><td><b>${esc(p.name)}</b><div class="adl-det">${p.type==='center'?'Centro':'Profesional'}${p.place?' · '+esc(p.place):''}</div></td>
        <td>${esc(p.plan.name)} <span class="status ${(PLAN_STATUS[p.plan.status]||[])[1]||''}">${esc((PLAN_STATUS[p.plan.status]||[p.plan.status])[0])}</span>${p.plan.exceptions.length?`<div class="adl-det">${p.plan.exceptions.length} excepciones</div>`:''}</td>
        <td>${esc(p.plan.expires_at||'—')}</td><td>${p.fiscal_missing.length?`<span class="status warn">Faltan ${p.fiscal_missing.length}</span>`:'<span class="status good">Completos</span>'}</td>
        <td><button type="button" class="btn ap-manage" data-i="${i}">Gestionar</button></td></tr>`).join('')}</tbody></table></div>
      ${d.payments.length?`<h3 class="adl-h">Últimos pagos de cuotas</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Prestador</th><th>Plan</th><th>Importe</th><th>Forma</th><th>Estado</th></tr></thead><tbody>${d.payments.map(x=>`<tr><td>${esc((x.paid_at||x.created_at||'').slice(0,10))}</td><td>${esc(x.provider_type)} #${x.provider_id}</td><td>${esc(x.plan_code)}</td><td>${wdMoney(x.amount,x.currency)}</td><td>${esc(x.method)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;
    $$('.ap-plan',mount).forEach(f=>f.onsubmit=async e=>{ e.preventDefault(); const code=f.dataset.code; const g=n=>f.elements[n];
      const data={code,name:g('name').value,price_year:g('price').value,currency:g('currency').value,description:g('description').value,features:{},limits:{},active:g('active')?g('active').checked:true};
      Object.keys(d.features).forEach(k=>data.features[k]=g('f_'+k).checked); Object.keys(d.limits).forEach(k=>data.limits[k]=g('l_'+k).value);
      try{ await postJSON('/api/admin/plans/save',data); toast('Plan guardado.'); }catch(err){ toast(err.message); } });
    $('#ap-trial').onsubmit=async e=>{ e.preventDefault(); try{ await postJSON('/api/admin/plans/settings',{trial_days:$('#ap-td').value,trial_plan:$('#ap-tp').value}); toast('Prueba gratuita guardada.'); }catch(err){ toast(err.message); } };
    wdBindExports(mount);
    $$('.ap-manage',mount).forEach(b=>b.onclick=()=>{ const p=d.providers[+b.dataset.i];
      const {el,close}=wdOpenModal({id:'plan-manage',title:esc(p.name),subtitle:`Plan actual: ${esc(p.plan.name)}${p.plan.expires_at?' hasta '+esc(p.plan.expires_at):''}`,
        body:`<h3 class="adl-h">Activar un plan (pago manual)</h3><div class="form-grid"><div class="field"><label for="pm-plan">Plan</label><select id="pm-plan">${d.plans.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('')}</select></div>
          <div class="field"><label for="pm-months">Meses</label><input id="pm-months" type="number" min="1" max="36" value="12"></div><div class="field"><label for="pm-amount">Importe cobrado</label><input id="pm-amount" inputmode="decimal" placeholder="Precio del plan"></div>
          <div class="field full"><label for="pm-note">Nota (obligatoria)</label><input id="pm-note" maxlength="500" placeholder="Ej.: transferencia del 12/10, factura 2026-031"></div>
          <div class="form-actions full"><button type="button" class="btn btn-primary" id="pm-assign">Guardar</button></div></div>
          <h3 class="adl-h">Excepciones</h3>${p.plan.exceptions.length?`<ul>${p.plan.exceptions.map(x=>`<li>${esc(d.features[x.feature]||x.feature)}: ${x.enabled?'activada':'desactivada'} — ${esc(x.reason)} <button type="button" class="btn-link pm-unexc" data-id="${x.id}">Quitar</button></li>`).join('')}</ul>`:'<p class="adl-det">Ninguna.</p>'}
          <div class="form-grid"><div class="field"><label for="pm-feat">Función</label><select id="pm-feat">${Object.entries(d.features).map(([k,l])=>`<option value="${k}">${esc(l)}</option>`).join('')}</select></div>
          <div class="field"><label for="pm-en">Valor</label><select id="pm-en"><option value="1">Activar</option><option value="0">Desactivar</option></select></div>
          <div class="field full"><label for="pm-why">Motivo (obligatorio)</label><input id="pm-why" maxlength="500"></div>
          <div class="form-actions full"><button type="button" class="btn" id="pm-exc">Añadir excepción</button></div></div>`,
        footer:'<button type="button" class="btn" data-modal-close>Cerrar</button>'});
      const after=()=>{ delete el.dataset.dirty; close(); renderAdminPlans(mountId); };
      $('#pm-assign',el).onclick=async()=>{ try{ await postJSON('/api/admin/plans/assign',{type:p.type,id:p.id,plan:$('#pm-plan',el).value,months:$('#pm-months',el).value,amount:$('#pm-amount',el).value,note:$('#pm-note',el).value}); toast('Plan guardado.'); after(); }catch(err){ toast(err.message); } };
      $('#pm-exc',el).onclick=async()=>{ try{ await postJSON('/api/admin/plans/exception',{type:p.type,id:p.id,feature:$('#pm-feat',el).value,enabled:$('#pm-en',el).value==='1',reason:$('#pm-why',el).value}); toast('Excepción añadida.'); after(); }catch(err){ toast(err.message); } };
      $$('.pm-unexc',el).forEach(x=>x.onclick=async()=>{ try{ await postJSON('/api/admin/plans/exception/remove',{id:+x.dataset.id}); after(); }catch(err){ toast(err.message); } });
    });
  }
  // Administración → Funciones
  async function renderAdminFeatures(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/admin/features'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Funciones</p><h2>Activar u ocultar funciones de la web</h2><p>Al desactivar una función desaparece de la web y el servidor rechaza su uso. Los datos se conservan y vuelven al activarla.</p></div></div>
      <form id="af-form" class="af-list">${Object.entries(d.labels).map(([k,l])=>`<label class="lg-check"><input type="checkbox" data-k="${k}" ${d.switches[k]?'checked':''}> <span>${esc(l)}</span></label>`).join('')}
        <label class="lg-check"><input type="checkbox" id="af-pilot" ${d.pilot_mode?'checked':''}> <span><b>Modo piloto:</b> solo pueden darse de alta centros y profesionales con invitación</span></label>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Guardar</button></div></form>
      <h3 class="adl-h">Invitaciones para el piloto</h3><form id="af-inv" class="form-grid"><div class="field"><label for="af-note">Para quién (nota)</label><input id="af-note" maxlength="200"></div><div class="field"><label for="af-days">Válida (días)</label><input id="af-days" type="number" min="1" max="365" value="30"></div><div class="form-actions full"><button class="btn" type="submit">Crear invitación</button></div></form>
      ${d.invites.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Nota</th><th>Caduca</th><th>Estado</th><th></th></tr></thead><tbody>${d.invites.map(i=>`<tr><td><code>${esc(i.code)}</code></td><td>${esc(i.note||'')}</td><td>${esc(i.expires_at||'—')}</td><td>${i.used_at?'Usada':'Disponible'}</td><td>${i.used_at?'':`<button type="button" class="btn-link af-revoke" data-id="${i.id}">Anular</button>`}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;
    $('#af-form').onsubmit=async e=>{ e.preventDefault(); const sw={}; $$('#af-form [data-k]').forEach(x=>sw[x.dataset.k]=x.checked);
      try{ await postJSON('/api/admin/features',{switches:sw,pilot_mode:$('#af-pilot').checked}); state.meta=null; toast('Funciones guardadas.'); }catch(err){ toast(err.message); } };
    $('#af-inv').onsubmit=async e=>{ e.preventDefault(); try{ const r=await postJSON('/api/admin/invites',{note:$('#af-note').value,days:$('#af-days').value}); toast('Invitación '+r.code+' creada.'); renderAdminFeatures(mountId); }catch(err){ toast(err.message); } };
    $$('.af-revoke',mount).forEach(b=>b.onclick=async()=>{ try{ await postJSON('/api/admin/invites',{revoke:+b.dataset.id}); renderAdminFeatures(mountId); }catch(err){ toast(err.message); } });
  }
  async function renderImageOrigins(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/admin/images'); }catch(err){ mount.innerHTML=''; return; }
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Imágenes</p><h2>Origen y licencia de las imágenes</h2><p>Indica de dónde sale cada imagen (foto propia, banco de imágenes con su licencia, cesión del autor…) además del crédito que se muestra. Las imágenes sin origen hay que comprobarlas o sustituirlas antes del lanzamiento.</p></div></div>
      ${d.missing?`<div class="notice warning"><strong>${d.missing} ${d.missing===1?'imagen sin origen':'imágenes sin origen'}.</strong></div>`:'<div class="notice good"><strong>Todas las imágenes tienen origen.</strong></div>'}
      <div class="table-wrap"><table class="data-table"><thead><tr><th>Imagen</th><th>Dónde se usa</th><th>Crédito</th><th>Origen / licencia</th><th></th></tr></thead><tbody>${d.items.map((x,i)=>`<tr${x.missing?' class="is-warn"':''}><td><img src="${esc(x.path)}" alt="" loading="lazy" style="width:72px;height:48px;object-fit:cover;border-radius:6px"><div class="adl-det">${esc(x.path.split('/').pop())}</div></td><td class="adl-det">${x.where.map(esc).join('<br>')}</td>
        <td><label class="sr-only" for="io-c-${i}">Crédito</label><input id="io-c-${i}" maxlength="200" value="${esc(x.credit)}"></td><td><label class="sr-only" for="io-o-${i}">Origen o licencia</label><input id="io-o-${i}" maxlength="300" value="${esc(x.origin)}" placeholder="Ej.: foto propia; Unsplash License; cedida por…"></td>
        <td><button type="button" class="btn io-save" data-i="${i}">Guardar</button></td></tr>`).join('')}</tbody></table></div></section>`;
    $$('.io-save',mount).forEach(b=>b.onclick=async()=>{ const i=+b.dataset.i; try{ await postJSON('/api/admin/images',{path:d.items[i].path,credit:$('#io-c-'+i).value,origin:$('#io-o-'+i).value}); toast('Guardado.'); renderImageOrigins(mountId); }catch(err){ toast(err.message); } });
  }
  async function renderAdminMaps(mountId){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/admin/maps'); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const n=x=>Number(x||0).toLocaleString(wdLocale()); const pct=d.limit?Math.min(100,Math.round(d.used*100/d.limit)):0;
    const mb=x=>(x/1048576).toLocaleString(wdLocale(),{maximumFractionDigits:0})+' MB';
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Mapas</p><h2>Mapa base, satélite y batimetría</h2><p>El mapa base se sirve desde nuestro servidor. La vista satélite pasa por nuestro servidor con la clave de ArcGIS, que nunca llega al navegador; aquí controlas cuántas teselas se sirven al mes para no salir de la cuota gratuita.</p></div></div>
      <div class="acc-kpis">${accKpi('map',d.pmtiles.exists?mb(d.pmtiles.size):(d.pmtiles.local?'Falta el archivo':'Externo'),'Mapa base (PMTiles) · '+esc(d.pmtiles.url))}
        ${accKpi('globe',d.key_configured?(d.available?'Activa':'Oculta: límite alcanzado'):'Sin clave','Vista satélite (ARCGIS_API_KEY)')}
        ${accKpi('chart',`${n(d.used)} / ${n(d.limit)}`,`Teselas satélite en ${esc(d.month)} (${pct} %)`)}</div>
      ${!d.pmtiles.exists&&d.pmtiles.local?'<div class="notice warning"><strong>Falta el mapa base.</strong> Sigue los pasos de docs/mapas.md para descargar el archivo PMTiles.</div>':''}
      ${!d.key_configured?'<div class="notice warning" id="maps-sat-notice"><strong>Añade la clave de ArcGIS para activar el satélite.</strong> Ponla en ARCGIS_API_KEY, en el archivo .env del servidor (nunca en el código), y reinicia. Mientras tanto, los visitantes ven «Satélite» desactivado con «Disponible próximamente».</div>':''}
      <form id="maps-form" class="form-grid"><div class="field"><label for="maps-limit">Límite mensual de teselas satélite</label><input id="maps-limit" type="number" min="0" max="50000000" step="1000" value="${d.limit}" required><small>Por defecto ${n(d.default_limit)}, por debajo de las 2.000.000 gratuitas. Al 80 % se avisa por email; al llegar al límite la capa se oculta hasta el mes siguiente.</small></div>
        <div class="form-actions full"><button class="btn btn-primary" type="submit">Guardar límite</button></div></form>
      ${d.history.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Mes</th><th>Teselas satélite</th></tr></thead><tbody>${d.history.map(h=>`<tr><td>${esc(h.month)}</td><td>${n(h.tiles)}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;
    $('#maps-form').onsubmit=async e=>{ e.preventDefault(); try{ await postJSON('/api/admin/maps',{limit:$('#maps-limit').value}); toast('Límite guardado.'); renderAdminMaps(mountId); }catch(err){ toast(err.message); } };
  }
  async function renderAdminPointTexts(mountId,pending=true){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    let d; try{ d=await api('/api/admin/point-texts?pending='+(pending?1:0)); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    mount.innerHTML=`<section class="mm-module"><div class="svc-head"><div><p class="eyebrow">Catálogo</p><h2>Descripciones de los puntos de buceo</h2>
      <p>Todas las descripciones se han reescrito con texto propio a partir de los datos de cada punto (lugar, tipo, profundidad, nivel y acceso), en los 9 idiomas. No se inventa ningún dato: lo que falta aparece en «Datos que faltan». El texto anterior se guarda aquí hasta que marques el punto como revisado.</p></div></div>
      <p class="adl-det"><b>${d.reviewed}</b> de <b>${d.total}</b> puntos revisados. <label class="lg-check" style="display:inline-flex"><input type="checkbox" id="apt-all" ${pending?'':'checked'}> <span>Mostrar también los revisados</span></label></p>
      ${d.items.length?`<div class="apt-list">${d.items.map(p=>`<article class="apt-item" data-id="${p.id}"><header><h3>${esc(p.name)}</h3><span class="adl-det">${esc([p.region,p.country].filter(Boolean).join(', '))}</span>${p.description_reviewed?'<span class="status good">Descripción revisada</span>':'<span class="status warn">Pendiente de revisar</span>'}</header>
        <div class="field"><label for="apt-t-${p.id}">Descripción nueva (castellano)</label><textarea id="apt-t-${p.id}" rows="5" maxlength="4000">${esc(p.description||'')}</textarea></div>
        ${p.description_missing.length?`<p class="adl-det"><b>Datos que faltan:</b> ${p.description_missing.map(esc).join(', ')}</p>`:''}
        ${p.description_legacy&&p.description_legacy!==p.description?`<details><summary>Texto anterior</summary><p class="adl-det">${esc(p.description_legacy)}</p></details>`:''}
        <div class="form-actions"><button type="button" class="btn apt-regen">Regenerar desde los datos</button><button type="button" class="btn btn-primary apt-ok">Guardar y marcar como revisada</button></div></article>`).join('')}</div>`:'<div class="empty">No hay descripciones pendientes de revisar.</div>'}</section>`;
    $('#apt-all').onchange=e=>renderAdminPointTexts(mountId,!e.target.checked);
    $$('.apt-item',mount).forEach(el=>{ const id=+el.dataset.id;
      $('.apt-ok',el).onclick=async()=>{ try{ await postJSON('/api/admin/point-texts/review',{id,description:$('textarea',el).value,lang:'es'}); toast('Descripción revisada.'); renderAdminPointTexts(mountId,pending); }catch(err){ toast(err.message); } };
      $('.apt-regen',el).onclick=async()=>{ try{ await postJSON('/api/admin/point-texts/review',{id,regenerate:true}); toast('Descripción regenerada.'); renderAdminPointTexts(mountId,pending); }catch(err){ toast(err.message); } }; });
  }
  async function openLegalEditor(slug,lang,done){
    const esc=escapeHtml; let d; try{ d=await api(`/api/admin/legal/doc?slug=${encodeURIComponent(slug)}&lang=${lang}`); }catch(err){ toast(err.message); return; }
    const today=new Date(), minDays=lang==='es'&&d.version?d.notice_days:0;
    const iso=x=>new Date(x.getTime()-x.getTimezoneOffset()*6e4).toISOString().slice(0,10);
    const minDate=iso(new Date(today.getTime()+minDays*864e5));
    const LANGS=['es','en','fr','de','it','pt','nl','pl','zh'];
    const {el,close}=wdOpenModal({id:'legal-editor',size:'lg',title:'Editar «'+esc(d.title)+'»',subtitle:'Se publica como una versión nueva. Las anteriores se conservan en el historial.',
      body:`<div class="form-grid">
        <div class="field"><label for="le-lang">Idioma</label><select id="le-lang">${LANGS.map(l=>`<option value="${l}" ${l===lang?'selected':''}>${l.toUpperCase()}${l==='es'?' · referencia':l==='en'?' · oficial':''}</option>`).join('')}</select></div>
        <div class="field"><label for="le-eff">Entra en vigor el</label><input id="le-eff" type="date" min="${minDate}" value="${minDate}" required>${minDays?`<small>Los cambios de este documento se anuncian con ${minDays} días de antelación.</small>`:''}</div>
        <div class="field full"><label for="le-title">Título</label><input id="le-title" maxlength="200" value="${esc(d.title)}"></div>
        <div class="field full"><label for="le-md">Texto (Markdown)</label><textarea id="le-md" rows="18" class="le-md" spellcheck="true">${esc(d.markdown||d.base_markdown||'')}</textarea>
          <small>${!d.markdown&&lang!=='es'?'<b>No hay versión en este idioma:</b> se muestra el texto en castellano para que lo traduzcas. ':''}Campos que se rellenan solos: ${d.placeholders.map(p=>`<code>{{${esc(p)}}}</code>`).join(' ')||'—'}</small></div>
        <div class="field full"><label for="le-sum">Resumen de los cambios</label><textarea id="le-sum" rows="2" maxlength="1000" placeholder="Por ejemplo: añadimos el plazo de devolución de la señal."></textarea><small>Aparece en el historial y en el email a los usuarios.</small></div>
        ${lang==='es'&&d.acceptance?`<label class="lg-check full"><input type="checkbox" id="le-notify" checked> <span>Avisar por email a ${d.acceptance==='pro'?'los centros y profesionales':'todos los usuarios'} y pedirles que la acepten cuando entre en vigor</span></label>`:''}
      </div>
      <details class="le-hist"><summary>Historial (${d.history.length})</summary><ul>${d.history.map(h=>`<li><b>${esc(h.version)}</b> · ${esc(h.lang)} · ${esc(wdLegalDate(h.effective_at))}${h.summary?' — '+esc(h.summary):''} <small>(${h.source==='file'?'texto inicial':'publicado '+esc((h.published_at||'').slice(0,10))})</small></li>`).join('')}</ul></details>`,
      footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn" id="le-preview">Vista previa</button><button type="button" class="btn btn-primary" id="le-pub">Publicar versión</button>'});
    $('#le-lang',el).onchange=e=>{ close(); openLegalEditor(slug,e.target.value,done); };
    $('#le-preview',el).onclick=()=>wdOpenModal({id:'legal-preview',size:'lg',title:'Vista previa',body:`<article class="lg-doc" translate="no">${wdMd($('#le-md',el).value)}</article>`,footer:'<button type="button" class="btn" data-modal-close>Cerrar</button>'});
    $('#le-pub',el).onclick=async()=>{ const b=$('#le-pub',el); b.disabled=true;
      try{ const r=await postJSON('/api/admin/legal/publish',{slug,lang,title:$('#le-title',el).value,markdown:$('#le-md',el).value,summary:$('#le-sum',el).value,effective_at:$('#le-eff',el).value,notify:$('#le-notify',el)?$('#le-notify',el).checked:false});
        delete el.dataset.dirty; close(); LEGAL_INFO=null; toast(`Versión ${r.version} publicada. Entra en vigor el ${wdLegalDate(r.effective_at)}.`); done&&done(); }
      catch(err){ toast(err.message); b.disabled=false; } };
  }
  async function renderAdminEmails(mountId,opts={}){
    const mount=document.getElementById(mountId); if(!mount) return; const esc=escapeHtml;
    const q=new URLSearchParams({status:opts.status||'',q:opts.q||'',page:opts.page||0});
    let d; try{ d=await api('/api/admin/emails?'+q); }catch(err){ mount.innerHTML=`<div class="empty">${esc(err.message)}</div>`; return; }
    const s=d.smtp, total=Object.values(d.counts).reduce((a,b)=>a+b,0);
    mount.innerHTML=`<section class="mm-module em">
      <div class="svc-head"><div><p class="eyebrow">Correos automáticos</p><h2>Correos de la plataforma</h2><p>Cada reserva, pago, cancelación o aviso genera su correo en el idioma del destinatario. Aquí ves todos los envíos y una vista previa de cada plantilla.</p></div></div>
      <div class="em-smtp ${s.enabled?'is-on':'is-off'}">${wdIcon('mail',22)}<div><strong>${s.enabled?'Envío activado':'Envío pendiente de configurar'}</strong>
        <p>${s.enabled?`Servidor ${esc(s.host)}:${esc(String(s.port))} (${esc(s.security)}) · remitente «${esc(s.from_name)}» &lt;${esc(s.from)}&gt;${s.reply_to?' · respuestas a '+esc(s.reply_to):''}`:'Los correos se guardan en la cola y se enviarán en cuanto configures el correo corporativo. En el servidor, define <code>WOD_SMTP_HOST</code>, <code>WOD_SMTP_PORT</code>, <code>WOD_SMTP_USER</code>, <code>WOD_SMTP_PASSWORD</code> y <code>WOD_MAIL_FROM</code>, y reinicia.'}</p></div>
        <form id="em-test" class="em-test"><input id="em-test-to" type="email" placeholder="tu@email.com" value="${esc(state.me?.user?.email&&!/\.(local|test)$/.test(state.me.user.email)?state.me.user.email:'')}" required><button class="btn" type="submit">Enviar prueba</button></form></div>
      <div class="em-kpis">${Object.entries(EMAIL_STATUS).map(([k,[l,c]])=>`<button type="button" class="em-kpi ${opts.status===k?'is-on':''}" data-st="${k}"><b>${(d.counts[k]||0).toLocaleString(wdLocale())}</b><span class="status ${c}">${l}</span></button>`).join('')}<button type="button" class="em-kpi ${!opts.status?'is-on':''}" data-st=""><b>${total.toLocaleString(wdLocale())}</b><span class="status">Todos</span></button></div>
      <div class="em-grid"><div>
        <div class="em-tools"><label class="cd-field">${wdIcon('search',16)}<input id="em-q" type="search" placeholder="Buscar por email o asunto" value="${esc(opts.q||'')}"></label></div>
        <div class="table-wrap"><table class="data-table em-table"><thead><tr><th>Fecha</th><th>Para</th><th>Asunto</th><th>Plantilla</th><th>Estado</th></tr></thead><tbody>
        ${d.items.length?d.items.map(r=>`<tr class="em-row" data-id="${r.id}" tabindex="0"><td>${esc(new Date(r.created_at).toLocaleString(wdLocale(),{dateStyle:'short',timeStyle:'short'}))}</td><td>${esc(r.to_email)}<small>${esc(r.lang.toUpperCase())}</small></td><td translate="no">${esc(r.subject)}</td><td>${esc(d.templates.find(t=>t.key===r.template)?.label||r.template)}</td><td><span class="status ${EMAIL_STATUS[r.status]?.[1]||''}">${esc(EMAIL_STATUS[r.status]?.[0]||r.status)}</span>${r.last_error?`<small class="em-err">${esc(r.last_error)}</small>`:''}</td></tr>`).join(''):'<tr><td colspan="5">No hay correos con este filtro.</td></tr>'}
        </tbody></table></div>
        <div class="em-pager">${d.page>0?'<button type="button" class="btn" id="em-prev">Anteriores</button>':''}<span>${d.total?`${d.page*50+1}–${Math.min(d.total,(d.page+1)*50)} de ${d.total.toLocaleString(wdLocale())}`:''}</span>${(d.page+1)*50<d.total?'<button type="button" class="btn" id="em-next">Siguientes</button>':''}</div>
      </div>
      <aside class="em-preview"><h3>Plantillas</h3><p>Vista previa con datos de ejemplo.</p>
        <div class="form-grid"><div class="field full"><label for="em-tpl">Plantilla</label><select id="em-tpl">${['diver','pro','center','admin','any'].map(a=>{ const list=d.templates.filter(t=>EMAIL_AUD[a]===t.audience); return list.length?`<optgroup label="${esc(list[0].audience)}">${list.map(t=>`<option value="${t.key}">${esc(t.label)}</option>`).join('')}</optgroup>`:''; }).join('')}</select></div>
        <div class="field full"><label for="em-lang">Idioma</label><select id="em-lang">${d.langs.map(l=>`<option value="${l}">${esc(LANGS[l]||l)}</option>`).join('')}</select></div></div>
        <p class="em-subject" id="em-subject" translate="no"></p><iframe id="em-frame" class="em-frame" sandbox="" title="Vista previa del correo"></iframe></aside></div>
    </section>`;
    const reload=o=>renderAdminEmails(mountId,{...opts,...o});
    $$('.em-kpi',mount).forEach(b=>b.onclick=()=>reload({status:b.dataset.st,page:0}));
    let t=null; $('#em-q',mount).oninput=e=>{ clearTimeout(t); t=setTimeout(()=>reload({q:e.target.value,page:0}),400); };
    $('#em-prev',mount)?.addEventListener('click',()=>reload({page:d.page-1})); $('#em-next',mount)?.addEventListener('click',()=>reload({page:d.page+1}));
    $('#em-test',mount).onsubmit=async e=>{ e.preventDefault(); try{ const r=await postJSON('/api/admin/emails/test',{to:$('#em-test-to',mount).value}); toast(r.message||'Correo de prueba enviado.'); reload({}); }catch(err){ toast(err.message); } };
    const preview=async()=>{ try{ const p=await api(`/api/admin/email-preview?template=${encodeURIComponent($('#em-tpl',mount).value)}&lang=${$('#em-lang',mount).value}`); $('#em-subject',mount).textContent=p.subject; $('#em-frame',mount).srcdoc=p.html; }catch(err){ toast(err.message); } };
    $('#em-tpl',mount).onchange=preview; $('#em-lang',mount).onchange=preview; preview();
    $$('.em-row',mount).forEach(r=>{ const open=async()=>{ try{ const it=(await api('/api/admin/emails/'+r.dataset.id)).item;
      const {el,close}=wdOpenModal({id:'email-view',size:'lg',title:esc(it.subject),subtitle:`Para ${esc(it.to_name?it.to_name+' · ':'')}${esc(it.to_email)} · ${esc(EMAIL_STATUS[it.status]?.[0]||it.status)}${it.sent_at?' · enviado '+esc(new Date(it.sent_at).toLocaleString(wdLocale())):''}`,
        body:`<iframe class="em-frame em-frame-lg" sandbox="" title="Correo"></iframe>${it.last_error?`<p class="em-err">Último error: ${esc(it.last_error)}</p>`:''}`,
        footer:`<button type="button" class="btn" data-modal-close>Cerrar</button>${it.status!=='skipped'?'<button type="button" class="btn btn-primary" id="em-resend">Reenviar</button>':''}`});
      $('.em-frame',el).srcdoc=it.html||'';
      $('#em-resend',el)?.addEventListener('click',async()=>{ try{ await postJSON('/api/admin/emails/resend',{id:it.id}); close(); toast('Correo puesto de nuevo en la cola.'); reload({}); }catch(err){ toast(err.message); } });
    }catch(err){ toast(err.message); } }; r.onclick=open; r.onkeydown=e=>{ if(e.key==='Enter') open(); }; });
    marketingComposer(mount.querySelector('.em'));
  }
  const EMAIL_AUD={diver:'Buceador',pro:'Profesional',center:'Centro',admin:'Administración',any:'Cualquier usuario',marketing:'Con consentimiento comercial'};
  // ---------------------------------------------------------------- v50.35 · Fase 4: two-step verification, marketing consent
  // v50.52: the days left to turn on two-step verification, on top of the panel (centres and freelance with online payments).
  const wdLongDate=s=>s?wdParseDate(String(s).slice(0,10)).toLocaleDateString(wdLocale(),{day:'numeric',month:'long',year:'numeric'}):'';
  function wdTotpGrace(sec){
    if(!sec||sec.totp_enabled||sec.totp_blocked||!sec.totp_deadline||$('#totp-grace')) return;
    const page=$('#app .page')||$('#app'); if(!page) return;
    const box=document.createElement('div'); box.className='notice warn'; box.id='totp-grace';
    box.innerHTML=`<strong>${escapeHtml(translateString('Activa la verificación en dos pasos antes del {fecha}').replace('{fecha}',wdLongDate(sec.totp_deadline)))}</strong><p>${escapeHtml(translateString('Es obligatoria en las cuentas con cobros online. Después de esa fecha, mientras no la actives, solo podrás entrar en «Mi cuenta». Las reservas y los pagos de tus clientes seguirán funcionando.'))}</p><a class="btn btn-primary" href="#/cuenta?seguridad=1">${escapeHtml(translateString('Activarla ahora'))}</a>`;
    page.prepend(box);
  }
  function totpCard(u){
    const sec=state.me?.security||{}; const on=!!sec.totp_enabled; const forced=!!sec.totp_required;
    return `<section class="acc-card" id="acc-totp"><div class="acc-card-head"><h2>${wdIcon('lock',18)} Verificación en dos pasos</h2>${on?'<span class="status good">Activada</span>':sec.totp_setup_required||forced?'<span class="status bad">Obligatoria</span>':'<span class="status warn">Desactivada</span>'}</div>
      <p class="acc-help">${on?`Al iniciar sesión te pedimos además un código de tu aplicación de verificación. Te quedan ${Number(sec.recovery_left||0)} códigos de recuperación.`:'Protege tu cuenta con un código de 6 cifras de una aplicación como Google Authenticator, Microsoft Authenticator o Aegis.'}${u.role==='admin'&&sec.totp_setup_required?' <b>Los administradores deben activarla para usar la administración.</b>':''}${forced?` <b>${sec.totp_required==='cobros'?'Es obligatoria porque tu perfil tiene el permiso «Cobros».':'Es obligatoria porque tu cuenta tiene cobros online.'}</b>${!on&&sec.totp_deadline&&!sec.totp_blocked?' <b>'+escapeHtml(translateString('Tienes hasta el {fecha}.').replace('{fecha}',wdLongDate(sec.totp_deadline)))+'</b>':''}`:''}</p>
      <div id="totp-box">${on?`<div class="acc-privacy-actions"><button type="button" class="btn" id="totp-recovery">Nuevos códigos de recuperación</button>${u.role==='admin'||forced?'':'<button type="button" class="btn danger" id="totp-off">Desactivar</button>'}</div>`
        :`<form id="totp-start" class="acc-pw"><div class="field"><label for="totp-pw">Tu contraseña</label><input id="totp-pw" type="password" autocomplete="current-password" required></div><button class="btn btn-primary">Activar</button></form>`}</div></section>`;
  }
  function bindTotpCard(d){
    const box=$('#totp-box'); if(!box) return;
    if(new URLSearchParams(location.hash.split('?')[1]||'').get('seguridad')) setTimeout(()=>$('#acc-totp')?.scrollIntoView({behavior:'smooth'}),200);
    const showCodes=codes=>{ box.innerHTML=`<div class="notice warn"><strong>Guarda estos códigos de recuperación</strong><p>Cada uno sirve una sola vez para entrar si pierdes el móvil. No los volveremos a mostrar.</p><pre class="totp-codes">${codes.map(escapeHtml).join('\n')}</pre><button type="button" class="btn" id="totp-copy">Copiar</button> <button type="button" class="btn btn-primary" id="totp-done">Ya los he guardado</button></div>`;
      $('#totp-copy').onclick=()=>navigator.clipboard?.writeText(codes.join('\n')).then(()=>toast('Códigos copiados.')).catch(()=>{}); $('#totp-done').onclick=async()=>{ await loadMe(); renderAccountPage(); }; };
    $('#totp-start')?.addEventListener('submit',async e=>{ e.preventDefault(); try{ const r=await postJSON('/api/account/totp/setup',{password:$('#totp-pw').value});
      box.innerHTML=`<ol class="totp-steps"><li>Abre tu aplicación de verificación y escanea este código:<div class="totp-qr">${r.qr_svg}</div><small>¿No puedes escanear? Escribe esta clave: <code>${escapeHtml(r.secret.replace(/(.{4})/g,'$1 ').trim())}</code></small></li>
        <li><form id="totp-confirm" class="acc-pw"><div class="field"><label for="totp-code">Escribe el código de 6 cifras que muestra</label><input id="totp-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></div><button class="btn btn-primary">Confirmar y activar</button></form></li></ol>`;
      $('#totp-confirm').onsubmit=async ev=>{ ev.preventDefault(); try{ const x=await postJSON('/api/account/totp/enable',{code:$('#totp-code').value}); toast('Verificación en dos pasos activada.'); showCodes(x.recovery_codes); }catch(err){ toast(err.message); } };
    }catch(err){ toast(err.message); } });
    const ask=(title,action,done)=>{ const {el,close}=wdOpenModal({id:'totp-ask',size:'sm',title,body:`<div class="field"><label for="ta-pw">Contraseña</label><input id="ta-pw" type="password" autocomplete="current-password"></div><div class="field"><label for="ta-code">Código de verificación o de recuperación</label><input id="ta-code" inputmode="numeric" autocomplete="one-time-code" maxlength="20"></div>`,
      footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="ta-ok">Continuar</button>'});
      $('#ta-ok',el).onclick=async()=>{ try{ const r=await postJSON('/api/account/totp/'+action,{password:$('#ta-pw',el).value,code:$('#ta-code',el).value}); close(); done(r); }catch(err){ toast(err.message); } }; };
    $('#totp-recovery')?.addEventListener('click',()=>ask('Nuevos códigos de recuperación','recovery',r=>showCodes(r.recovery_codes)));
    $('#totp-off')?.addEventListener('click',()=>ask('Desactivar la verificación en dos pasos','disable',async()=>{ toast('Verificación en dos pasos desactivada.'); await loadMe(); renderAccountPage(); }));
  }
  function marketingCard(u){
    return `<section class="acc-card" id="acc-marketing"><div class="acc-card-head"><h2>${wdIcon('message',18)} Novedades y ofertas</h2></div>
      <label class="svc-check"><input type="checkbox" id="acc-mkt" ${u.marketing_consent?'checked':''}><span><strong>Quiero recibir novedades y ofertas de WORLDIVES por email</strong><small>Opcional. Puedes darte de baja cuando quieras, también desde el enlace de cada correo. Los avisos de tus reservas te llegan siempre.</small></span></label></section>`;
  }
  function bindMarketingCard(){ $('#acc-mkt')?.addEventListener('change',async e=>{ try{ await postJSON('/api/account/marketing',{consent:e.target.checked}); toast(e.target.checked?'Te enviaremos novedades y ofertas.':'Ya no recibirás comunicaciones comerciales.'); }catch(err){ toast(err.message); e.target.checked=!e.target.checked; } }); }
  async function renderUnsubscribe(params){
    const t=params.get('t')||'';
    setApp(`<section class="page auth"><div class="auth-card" style="max-width:560px"><p class="eyebrow">WORLDIVES DISCOVERY</p><h1>Darse de baja</h1><div id="unsub-box"><p class="lead">Un momento…</p></div></div></section>`);
    try{ await postJSON('/api/marketing/unsubscribe',{t}); $('#unsub-box').innerHTML='<p class="lead">Listo: ya no recibirás comunicaciones comerciales de WORLDIVES DISCOVERY.</p><p>Los avisos de tus reservas y de tu cuenta te seguirán llegando. Puedes volver a apuntarte en «Mi cuenta».</p><a class="btn btn-primary" href="#/">Ir a la portada</a>'; }
    catch(err){ $('#unsub-box').innerHTML=`<p class="lead">${escapeHtml(err.message)}</p><p>Si el enlace no funciona, entra en «Mi cuenta» y desmarca «Novedades y ofertas».</p>`; }
    translateTree($('#unsub-box'));
  }
  // Provider: move a booking to another departure of the same service (the diver gets an email).
  async function openRescheduleModal(b,after){
    let svc; try{ svc=(await api('/api/provider-services/'+b.service_id)); }catch(e){ toast(e.message); return; }
    const today=wdToday(); const slots=(svc.slots||[]).filter(s=>s.id!==b.slot_id&&s.slot_date>=today&&['open','full'].includes(s.status));
    if(!slots.length){ toast('No hay otras salidas de este servicio. Programa una nueva salida antes de cambiar la reserva.'); return; }
    const {el,close}=wdOpenModal({id:'reschedule',title:'Cambiar fecha u hora',subtitle:'Se mueve a otra salida del mismo servicio. El cliente recibe un email con el cambio.',
      body:`<div class="field"><label for="rs-slot">Nueva salida</label><select id="rs-slot">${slots.map(s=>`<option value="${s.id}" ${Number(s.spots_available)<Number(b.participants||1)?'disabled':''}>${escapeHtml(wdLongDay(s.slot_date))} · ${escapeHtml(s.slot_time)} · ${s.spots_available} plazas libres</option>`).join('')}</select></div>
        <div class="field"><label for="rs-reason">Motivo (lo verá el cliente)</label><input id="rs-reason" maxlength="300" placeholder="Ej.: el estado del mar obliga a cambiar la salida"></div>`,
      footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="rs-ok">Cambiar</button>'});
    $('#rs-ok',el).onclick=async()=>{ try{ await postJSON(`/api/bookings/${b.id}/reschedule`,{slot_id:+$('#rs-slot',el).value,reason:$('#rs-reason',el).value}); close(); toast('Reserva cambiada. El cliente recibe un email.'); after&&after(); }catch(err){ toast(err.message); } };
  }
  // Administration: commercial email, only to users who agreed (Fase 4.3).
  function marketingComposer(mount){
    if(!mount) return;
    mount.insertAdjacentHTML('beforeend',`<section class="cb-panel" id="mkt-panel"><div class="cb-panel-head"><div><h3>Comunicación comercial</h3><p>Solo llega a quien dio su consentimiento y tiene el email verificado. Cada correo lleva baja en un clic. Envía antes una prueba a tu email.</p></div></div>
      <form id="mkt-form" class="form-grid"><div class="field full"><label for="mkt-subject">Asunto</label><input id="mkt-subject" maxlength="150" required></div><div class="field full"><label for="mkt-title">Título</label><input id="mkt-title" maxlength="150"></div>
        <div class="field full"><label for="mkt-body">Texto</label><textarea id="mkt-body" rows="5" maxlength="5000" required></textarea></div><div class="field"><label for="mkt-button">Texto del botón</label><input id="mkt-button" maxlength="60" placeholder="Ver en WORLDIVES"></div><div class="field"><label for="mkt-url">Enlace del botón</label><input id="mkt-url" maxlength="500" placeholder="#/experiencias o https://…"></div>
        <div class="form-actions full"><button type="button" class="btn" id="mkt-test">Enviarme una prueba</button><button class="btn btn-primary">Enviar a los suscritos</button></div></form></section>`);
    const f=$('#mkt-form'); const body=test=>({subject:$('#mkt-subject').value,title:$('#mkt-title').value,body:$('#mkt-body').value,button:$('#mkt-button').value,url:$('#mkt-url').value,test});
    $('#mkt-test').onclick=async()=>{ try{ const r=await postJSON('/api/admin/marketing/send',body(true)); toast(`Prueba enviada (${r.recipients}).`); }catch(e){ toast(e.message); } };
    f.onsubmit=async e=>{ e.preventDefault(); if(!confirm('¿Enviar este correo a todas las personas suscritas?')) return; try{ const r=await postJSON('/api/admin/marketing/send',body(false)); toast(`En cola para ${r.recipients} personas.`); }catch(err){ toast(err.message); } };
  }


  // ---------------------------------------------------------------- v50.30 · Top 10: precise location
  async function wdPickOnMap({start,onPick}){
    const {el,close}=wdOpenModal({id:'tt-map',size:'lg',title:'Elige tu ubicación',subtitle:'Toca el mapa donde estás (o donde quieres bucear) y pulsa «Ver el Top 10 aquí».',
      body:'<div id="tt-pick-map" class="tt-pick-map"></div><p class="tt-pick-coords" id="tt-pick-coords">Todavía no has elegido ningún punto.</p>',
      footer:'<button type="button" class="btn" data-modal-close>Cancelar</button><button type="button" class="btn btn-primary" id="tt-pick-ok" disabled>Ver el Top 10 aquí</button>'});
    await wdMaps(); if(!el.isConnected) return;
    if(!window.L){ $('#tt-pick-map',el).innerHTML='<div class="map-fallback"><strong>El mapa no está disponible ahora mismo</strong><span>Busca tu localidad en el buscador.</span></div>'; return; }
    wdTileDefaults(); const m=L.map($('#tt-pick-map',el),{zoomControl:true,attributionControl:true}).setView(start?[start.lat,start.lon]:[39.4,-0.4],start?9:6);
    wdLayerControl(m);
    const icon=L.divIcon({className:'tt-me-wrap',html:'<span class="tt-me"></span>',iconSize:[22,22],iconAnchor:[11,11]});
    // Dive sites as context (same round markers and clusters as every other map; tapping one picks its position).
    loadMapLayer().then(layer=>{ const grp=wdMarkerLayer(); const ms=(layer.items||[]).filter(p=>p.latitude!=null).map(p=>{ const x=L.marker([p.latitude,p.longitude],{icon:pointIcon(p),title:p.name,alt:p.name}); x.on('click',()=>m.fire('click',{latlng:x.getLatLng()})); return x; }); grp.addLayers?grp.addLayers(ms):ms.forEach(x=>x.addTo(grp)); grp.addTo(m); }).catch(()=>{});
    let mk=null, sel=null;
    m.on('click',e=>{ sel=e.latlng; if(mk) mk.setLatLng(sel); else mk=L.marker(sel,{icon}).addTo(m); $('#tt-pick-ok',el).disabled=false; $('#tt-pick-coords',el).textContent=`${sel.lat.toFixed(4)}, ${sel.lng.toFixed(4)}`; });
    setTimeout(()=>m.invalidateSize(),160);
    $('#tt-pick-ok',el).onclick=()=>{ close(); onPick(sel.lat,sel.lng); };
  }
  async function wdGeocode(q){
    // Through our own server (/api/geocode): the visitor's IP is not sent to a third party and the provider's usage policy is respected.
    const d=await api('/api/geocode?'+new URLSearchParams({q,lang:currentLanguage()})); if(d.unavailable) throw new Error(d.error||'No se ha podido buscar.');
    const it=(d.items||[])[0]; if(!it) return null;
    return {lat:+it.lat,lon:+it.lon,label:String(it.name||q).split(',')[0]};
  }


